def _call_sports_live_intelligence(function_name, bot, *args, **kwargs):
    if sports_live_intelligence is None:
        raise RuntimeError("sports.live_intelligence unavailable")
    if hasattr(sports_live_intelligence, "bind_runtime_globals"):
        sports_live_intelligence.bind_runtime_globals(globals())
    return getattr(sports_live_intelligence, function_name)(bot, *args, **kwargs)

def _aion_env_bool(name, default=False):
    raw = os.environ.get(name)
    if raw is None:
        return bool(default)
    return str(raw).strip().lower() in {"1", "true", "yes", "on", "y"}


def _aion_env_float(name, default):
    raw = os.environ.get(name)
    if raw in (None, ""):
        return float(default)
    try:
        return float(raw)
    except (TypeError, ValueError):
        return float(default)


