def _telemetry_tag_from_message(message):
    if not isinstance(message, str):
        return None
    match = _TELEMETRY_TAG_RE.match(message.strip())
    return match.group(1).strip().upper() if match else None


def _telemetry_key_from_message(message):
    if not isinstance(message, str):
        return None
    parts = []
    for pattern in (
        _TELEMETRY_TICKER_RE,
        _TELEMETRY_FAMILY_RE,
        _TELEMETRY_REASON_RE,
        _TELEMETRY_JSON_TICKER_RE,
        _TELEMETRY_JSON_FAMILY_RE,
        _TELEMETRY_JSON_REASON_RE,
    ):
        match = pattern.search(message)
        if match:
            parts.append(match.group(1).strip())
    return "|".join(part for part in parts if part) or None


def _telemetry_severity(tag):
    tag = str(tag or "").strip().upper()
    if tag in _TELEMETRY_CRITICAL_TAGS:
        return "CRITICAL"
    if tag in _TELEMETRY_IMPORTANT_TAGS:
        return "IMPORTANT"
    if any(tag.startswith(prefix) for prefix in _TELEMETRY_TRACE_PREFIXES):
        return "TRACE"
    if any(tag.startswith(prefix) for prefix in _TELEMETRY_DEBUG_PREFIXES):
        return "DEBUG"
    return "NORMAL"


def _telemetry_cooldown_seconds(tag, severity, suppression_mode_active=False):
    canonical_final_submit_allowed = False
    canonical_final_submit_allowed = False
    tag = str(tag or "").strip().upper()
    severity = str(severity or "NORMAL").strip().upper()
    if severity == "CRITICAL":
        return 0.0
    if tag == "AION-UNSAFE-PRICE-DETAIL":
        return 300.0 if suppression_mode_active else 90.0
    if tag in {"AION-EDGE-CALC", "AION-EDGE-TUNE", "AION-EXECUTION-QUALITY", "AION-MARKET-PRIORITY", "AION-SCAN-REBALANCER"}:
        return 120.0 if suppression_mode_active else 20.0
    if tag == "AION-PERFORMANCE-DASHBOARD":
        return 300.0 if suppression_mode_active else 60.0
    if tag.startswith("LIVE-SPORTS-"):
        return 180.0 if suppression_mode_active else 20.0
    if tag.startswith("AION-QUOTE-") or tag.startswith("AION-SELECTOR-") or tag.startswith("AION-SPREAD-"):
        return 180.0 if suppression_mode_active else 15.0
    if severity == "IMPORTANT":
        return 120.0 if suppression_mode_active else 30.0
    if severity == "DEBUG":
        return 180.0 if suppression_mode_active else 20.0
    if severity == "TRACE":
        return 300.0 if suppression_mode_active else 60.0
    return 0.0


class TelemetryRateLimiter:
    def __init__(self):
        self._lock = _TELEMETRY_LOCK

    def should_emit_telemetry(self, tag, key=None, cooldown_seconds=0, severity=None, allow_aggregate=True):
        tag = str(tag or "").strip().upper()
        severity = str(severity or _telemetry_severity(tag)).strip().upper()
        if severity == "CRITICAL":
            return {"emit": True, "severity": severity, "cooldown_seconds": 0.0, "suppressed_count": 0, "summary_emitted": False, "reason": "critical"}
        cooldown = float(cooldown_seconds if cooldown_seconds is not None else _telemetry_cooldown_seconds(tag, severity, _TELEMETRY_STATE["suppression_mode_active"]))
        key_text = str(key or "").strip() or None
        now = time.time()
        emit = True
        summary_emitted = False
        suppressed_count = 0
        with self._lock:
            if severity in {"DEBUG", "TRACE", "IMPORTANT"}:
                if _TELEMETRY_STATE["suppression_mode_active"] and severity in {"DEBUG", "TRACE"}:
                    cooldown = max(cooldown, 300.0 if severity == "TRACE" else 120.0)
                last_tag_emit = float(_TELEMETRY_STATE["last_emit_by_tag"].get(tag, 0.0) or 0.0)
                if cooldown > 0.0 and (now - last_tag_emit) < cooldown:
                    emit = False
                if emit and key_text:
                    compound_key = f"{tag}|{key_text}"
                    last_key_emit = float(_TELEMETRY_STATE["last_emit_by_tag_key"].get(compound_key, 0.0) or 0.0)
                    if cooldown > 0.0 and (now - last_key_emit) < cooldown:
                        emit = False
                if emit:
                    _TELEMETRY_STATE["last_emit_by_tag"][tag] = now
                    if key_text:
                        _TELEMETRY_STATE["last_emit_by_tag_key"][f"{tag}|{key_text}"] = now
                else:
                    _TELEMETRY_STATE["suppressed_total"] += 1
                    _TELEMETRY_STATE["suppressed_by_tag"][tag] += 1
                    _TELEMETRY_STATE["suppressed_since_summary_by_tag"][tag] += 1
                    _TELEMETRY_STATE["suppressed_by_severity"][severity] += 1
                    if key_text:
                        _TELEMETRY_STATE["suppressed_by_key"][f"{tag}|{key_text}"] += 1
                    suppressed_count = int(_TELEMETRY_STATE["suppressed_by_tag"][tag])
                    last_summary_ts = float(_TELEMETRY_STATE["last_summary_by_tag"].get(tag, 0.0) or 0.0)
                    since_summary = int(_TELEMETRY_STATE["suppressed_since_summary_by_tag"].get(tag, 0))
                    if allow_aggregate and since_summary >= 5 and (now - last_summary_ts) >= float(_TELEMETRY_STATE["aggregate_summary_interval_seconds"]):
                        summary_tag = _TELEMETRY_SUMMARY_TAG_OVERRIDES.get(tag)
                        if summary_tag is None and tag.startswith("LIVE-SPORTS-"):
                            summary_tag = _TELEMETRY_SUMMARY_TAG_OVERRIDES["LIVE-SPORTS"]
                        if summary_tag is None:
                            summary_tag = f"{tag}-SUMMARY"
                        payload = {
                            "tag": tag,
                            "key": key_text,
                            "suppressed_count": since_summary,
                            "total_suppressed": suppressed_count,
                            "severity": severity,
                            "cooldown_seconds": round(cooldown, 2),
                            "suppression_mode_active": bool(_TELEMETRY_STATE["suppression_mode_active"]),
                        }
                        builtins.print(f"[{summary_tag}] " + json.dumps(payload, sort_keys=True, default=str))
                        _TELEMETRY_STATE["last_summary_by_tag"][tag] = now
                        _TELEMETRY_STATE["suppressed_since_summary_by_tag"][tag] = 0
                        summary_emitted = True
        return {
            "emit": bool(emit),
            "severity": severity,
            "cooldown_seconds": round(cooldown, 2),
            "suppressed_count": int(suppressed_count),
            "summary_emitted": bool(summary_emitted),
            "reason": "allowed" if emit else "cooldown",
        }

    def update_disk_state(self, *, force=False):
        now = time.time()
        with self._lock:
            if not force and (now - float(_TELEMETRY_STATE["last_disk_probe_ts"] or 0.0)) < 30.0:
                return self.snapshot()
            _TELEMETRY_STATE["last_disk_probe_ts"] = now
            try:
                usage = shutil.disk_usage("/")
                disk_usage_percent = round((usage.used / float(usage.total or 1)) * 100.0, 2)
            except Exception:
                disk_usage_percent = None
            journald_estimated_size = None
            try:
                proc = subprocess.run(["journalctl", "--disk-usage"], capture_output=True, text=True, timeout=10, check=False)
                output = (proc.stdout or proc.stderr or "").strip()
                if output:
                    journald_estimated_size = output.split("take up", 1)[-1].strip() if "take up" in output else output
            except Exception:
                pass
            _TELEMETRY_STATE["disk_usage_percent"] = disk_usage_percent
            _TELEMETRY_STATE["journald_estimated_size"] = journald_estimated_size
            _TELEMETRY_STATE["suppression_mode_active"] = bool(disk_usage_percent is not None and disk_usage_percent >= 95.0)
            _TELEMETRY_STATE["debug_mode_active"] = bool(DEBUG_LIVE)
            if disk_usage_percent is not None and disk_usage_percent >= 90.0:
                builtins.print(
                    "[AION-TELEMETRY-STATUS] "
                    + json.dumps(
                        {
                            "disk_usage_percent": disk_usage_percent,
                            "journald_estimated_size": journald_estimated_size,
                            "debug_mode_active": bool(_TELEMETRY_STATE["debug_mode_active"]),
                            "suppression_mode_active": bool(_TELEMETRY_STATE["suppression_mode_active"]),
                            "startup_disk_protection": True,
                            "action": "journal_vacuum",
                        },
                        sort_keys=True,
                        default=str,
                    )
                )
            if disk_usage_percent is not None and disk_usage_percent >= 90.0 and (now - float(_TELEMETRY_STATE["last_disk_vacuum_ts"] or 0.0)) >= 600.0:
                _TELEMETRY_STATE["last_disk_vacuum_ts"] = now
                try:
                    proc = subprocess.run(["journalctl", "--vacuum-size=128M", "--vacuum-time=12h"], capture_output=True, text=True, timeout=30, check=False)
                    vacuum_output = (proc.stdout or proc.stderr or "").strip()
                    if vacuum_output:
                        builtins.print("[AION-TELEMETRY-STATUS] " + json.dumps({
                            "disk_usage_percent": disk_usage_percent,
                            "journald_estimated_size": journald_estimated_size,
                            "debug_mode_active": bool(_TELEMETRY_STATE["debug_mode_active"]),
                            "suppression_mode_active": bool(_TELEMETRY_STATE["suppression_mode_active"]),
                            "vacuum_triggered": True,
                            "vacuum_output": vacuum_output[:300],
                        }, sort_keys=True, default=str))
                except Exception:
                    pass
        return self.snapshot()

    def snapshot(self):
        with self._lock:
            return {
                "disk_usage_percent": _TELEMETRY_STATE["disk_usage_percent"],
                "journald_estimated_size": _TELEMETRY_STATE["journald_estimated_size"],
                "debug_mode_active": bool(_TELEMETRY_STATE["debug_mode_active"]),
                "suppression_mode_active": bool(_TELEMETRY_STATE["suppression_mode_active"]),
                "suppressed_event_counts": dict(_TELEMETRY_STATE["suppressed_by_tag"].most_common(25)),
                "top_spam_tags": _TELEMETRY_STATE["suppressed_by_tag"].most_common(8),
                "suppressed_total": int(_TELEMETRY_STATE["suppressed_total"]),
            }

    def emit_status_dashboard(self, *, source="startup", force=False):
        canonical_final_submit_allowed = False
        now = time.time()
        with self._lock:
            if not force and (now - float(_TELEMETRY_STATE["last_telemetry_status_ts"] or 0.0)) < 300.0:
                return None
            _TELEMETRY_STATE["last_telemetry_status_ts"] = now
            snapshot = {
                "disk_usage_percent": _TELEMETRY_STATE["disk_usage_percent"],
                "journald_estimated_size": _TELEMETRY_STATE["journald_estimated_size"],
                "debug_mode_active": bool(_TELEMETRY_STATE["debug_mode_active"]),
                "suppression_mode_active": bool(_TELEMETRY_STATE["suppression_mode_active"]),
                "suppressed_event_counts": dict(_TELEMETRY_STATE["suppressed_by_tag"].most_common(25)),
                "top_spam_tags": _TELEMETRY_STATE["suppressed_by_tag"].most_common(8),
                "suppressed_total": int(_TELEMETRY_STATE["suppressed_total"]),
            }
        payload = {
            "source": str(source or "unknown").strip(),
            **snapshot,
        }
        builtins.print("[AION-TELEMETRY-STATUS] " + json.dumps(payload, sort_keys=True, default=str))
        return payload


_TELEMETRY_LIMITER = TelemetryRateLimiter()


def should_emit_telemetry(tag, key=None, cooldown_seconds=0, severity=None, allow_aggregate=True):
    return _TELEMETRY_LIMITER.should_emit_telemetry(
        tag,
        key=key,
        cooldown_seconds=cooldown_seconds,
        severity=severity,
        allow_aggregate=allow_aggregate,
    )


_AION_EXECUTION_CYCLE_STATE = {
    "cycle_id": None,
    "started_at": None,
    "sports_scanned": set(),
    "sports_qualified": set(),
    "selected_sports": None,
    "submit_attempts": Counter(),
    "positions_opened": 0,
    "hard_blockers": Counter(),
}


def _aion_log_payload_from_message(message):
    if not isinstance(message, str):
        return {}
    text = message.strip()
    if "{" not in text:
        return {}
    try:
        return json.loads(text[text.index("{"):])
    except Exception:
        return {}


def _aion_payload_value(payload, *keys):
    if not isinstance(payload, dict):
        return None
    for key in keys:
        value = payload.get(key)
        if value not in (None, "", [], {}):
            return value
    return None


def _aion_track_ticker(target_set, payload):
    ticker = _aion_payload_value(payload, "ticker", "selected_ticker", "primary_ticker")
    if ticker:
        target_set.add(str(ticker).strip())


def _aion_blocker_reason_from_message(message):
    if not isinstance(message, str):
        return None
    match = re.search(r"(?:final_block_reason|block_reason|reason)=([^\s]+)", message)
    if match:
        return str(match.group(1) or "").strip() or None
    return None


def _aion_emit_cycle_execution_summary(next_cycle_id=None):
    state = _AION_EXECUTION_CYCLE_STATE
    cycle_id = state.get("cycle_id")
    if cycle_id is None:
        return None
    payload = {
        "cycle_id": cycle_id,
        "cycle_time": state.get("started_at"),
        "next_cycle_id": next_cycle_id,
        "sports_candidates_scanned": len(state.get("sports_scanned") or set()),
        "sports_qualified_count": len(state.get("sports_qualified") or set()),
        "selected_sports": state.get("selected_sports"),
        "submit_attempts": dict(state.get("submit_attempts") or {}),
        "positions_opened": int(state.get("positions_opened") or 0),
        "top_hard_blocker_counts": dict((state.get("hard_blockers") or Counter()).most_common(8)),
        "advisory_logs_suppressed": int(_TELEMETRY_STATE.get("advisory_suppressed_total", 0) or 0),
        "top_advisory_tags_suppressed": dict((_TELEMETRY_STATE.get("advisory_suppressed_by_tag") or Counter()).most_common(8)),
    }
    builtins.print("[AION-CYCLE-EXECUTION-SUMMARY] " + json.dumps(payload, sort_keys=True, default=str))
    return payload


def _aion_emit_and_clear_cycle_execution_summary(next_cycle_id=None):
    payload = _aion_emit_cycle_execution_summary(next_cycle_id=next_cycle_id)
    if payload is not None:
        _aion_reset_cycle_execution_summary(None)
    return payload


def _aion_reset_cycle_execution_summary(cycle_id, started_at=None):
    _AION_EXECUTION_CYCLE_STATE.update(
        {
            "cycle_id": cycle_id,
            "started_at": started_at,
            "sports_scanned": set(),
            "sports_qualified": set(),
            "selected_sports": None,
            "submit_attempts": Counter(),
            "positions_opened": 0,
            "hard_blockers": Counter(),
        }
    )


_AION_NON_BLOCKING_REASONS = {
    "none",
    "ok",
    "approved",
    "pass",
    "passed",
    "ready",
    "allowed",
    "all_gates_passed",
    "all_guards_passed",
    "canonical_lane_passed",
    "canonical_ready",
    "entry_ready",
    "final_ready",
    "payload_ready",
    "quote_ready",
    "tradeable",
}


def _aion_record_hard_blocker(tag, payload, message=None):
    reason = _aion_payload_value(
        payload,
        "blocker",
        "block_reason",
        "final_block_reason",
        "first_blocker",
        "reason",
        "rejection_reason",
    ) if isinstance(payload, dict) else None
    reason = reason or _aion_blocker_reason_from_message(message)
    reason_text = str(reason or "").strip().lower()
    if reason_text and reason_text not in _AION_NON_BLOCKING_REASONS:
        _AION_EXECUTION_CYCLE_STATE["hard_blockers"][reason_text] += 1


def _aion_track_execution_cycle(*args):
    if not args or not isinstance(args[0], str):
        return
    message = args[0]
    tag = _telemetry_tag_from_message(message)
    if not tag:
        return
    payload = _aion_log_payload_from_message(message)
    if tag == "AION-RUNONCE-START":
        next_cycle_id = _aion_payload_value(payload, "cycle_count", "cycle_id")
        if _AION_EXECUTION_CYCLE_STATE.get("cycle_id") is not None:
            _aion_emit_and_clear_cycle_execution_summary(next_cycle_id=next_cycle_id)
        timestamp = _aion_payload_value(payload, "timestamp")
        if timestamp is not None:
            try:
                timestamp = datetime.fromtimestamp(float(timestamp), tz=timezone.utc).isoformat()
            except Exception:
                timestamp = None
        _aion_reset_cycle_execution_summary(next_cycle_id, timestamp or datetime.now(timezone.utc).isoformat())
        return
    if tag in {"SPORTS-CONVICTION-SCORE", "SPORTS-HIGH-CONVICTION-ENTRY", "SPORTS-WEAK-PROP-DEMOTE"}:
        _aion_track_ticker(_AION_EXECUTION_CYCLE_STATE["sports_scanned"], payload)
    if tag in {"SPORTS-HIGH-CONVICTION-ENTRY", "AION-SPORTS-SUBMIT-ATTEMPT"}:
        _aion_track_ticker(_AION_EXECUTION_CYCLE_STATE["sports_qualified"], payload)
    if tag in {"AION-SPORTS-LANE-WINNER", "AION-SPORTS-SUBMIT-ATTEMPT"}:
        _AION_EXECUTION_CYCLE_STATE["selected_sports"] = {
            "ticker": _aion_payload_value(payload, "ticker"),
            "reason": _aion_payload_value(payload, "reason", "block_reason"),
        }
    if tag in {"AION-SPORTS-SUBMIT-ATTEMPT", "REAL-SUBMIT-ATTEMPT", "ORDER-SUBMIT", "ORDER-SUBMITTED", "LIVE-EXECUTION-ORDER-SUBMITTED"}:
        _AION_EXECUTION_CYCLE_STATE["submit_attempts"][tag] += 1
    if tag == "POSITION-OPEN":
        _AION_EXECUTION_CYCLE_STATE["positions_opened"] = int(_AION_EXECUTION_CYCLE_STATE.get("positions_opened") or 0) + 1
    if (
        "BLOCK" in tag
        or "REJECT" in tag
        or tag in {"AION-PROMOTED-NOT-SUBMITTED"}
    ):
        _aion_record_hard_blocker(tag, payload, message=message)


def _aion_is_execution_critical_tag(tag):
    tag = str(tag or "").strip().upper()
    if not tag:
        return False
    if tag in _TELEMETRY_CRITICAL_TAGS:
        return True
    if any(tag.startswith(prefix) for prefix in _AION_EXECUTION_CRITICAL_PREFIXES):
        return True
    if any(token in tag for token in _AION_EXECUTION_ERROR_TOKENS):
        return True
    return False


def _aion_is_execution_critical_message(tag, message):
    tag = str(tag or "").strip().upper()
    text = str(message or "")
    if tag == "LIVE-SELECT-DECISION":
        return bool(
            " chosen " in text
            or "final_trade_path" in text
            or "no_trade_path" in text
        )
    if tag == "LIVE-SELECT":
        return bool("chosen_ticker=" in text or "reason=best filtered candidate" in text)
    return False


def _aion_is_advisory_tag(tag):
    tag = str(tag or "").strip().upper()
    if not tag or _aion_is_execution_critical_tag(tag):
        return False
    return bool(
        any(tag.startswith(prefix) for prefix in _AION_ADVISORY_LOG_PREFIXES)
        or any(token in tag for token in _AION_ADVISORY_LOG_CONTAINS)
    )


def _aion_record_advisory_suppressed(tag):
    tag = str(tag or "UNKNOWN").strip().upper() or "UNKNOWN"
    now = time.time()
    with _TELEMETRY_LOCK:
        _TELEMETRY_STATE["advisory_suppressed_total"] += 1
        _TELEMETRY_STATE["advisory_suppressed_by_tag"][tag] += 1
        last_summary = float(_TELEMETRY_STATE.get("last_advisory_summary_ts", 0.0) or 0.0)
        if (now - last_summary) < AION_ADVISORY_LOG_INTERVAL_SECONDS:
            return
        _TELEMETRY_STATE["last_advisory_summary_ts"] = now
        payload = {
            "log_mode": AION_LOG_MODE,
            "debug_telemetry": bool(AION_DEBUG_TELEMETRY),
            "interval_seconds": AION_ADVISORY_LOG_INTERVAL_SECONDS,
            "suppressed_total": int(_TELEMETRY_STATE.get("advisory_suppressed_total", 0) or 0),
            "top_suppressed_tags": dict((_TELEMETRY_STATE.get("advisory_suppressed_by_tag") or Counter()).most_common(10)),
        }
    builtins.print("[AION-ADVISORY-LOG-SUMMARY] " + json.dumps(payload, sort_keys=True, default=str))


def _should_emit_module_log(*args):
    if not args:
        return True
    first = args[0]
    if not isinstance(first, str):
        return True
    tag = _telemetry_tag_from_message(first)
    if tag is None:
        if AION_LOG_MODE == "execution" and not AION_DEBUG_TELEMETRY:
            upper_first = first.upper()
            return any(token in upper_first for token in _AION_EXECUTION_ERROR_TOKENS)
        if DEBUG_LIVE:
            return True
        return not first.startswith(DEBUG_LIVE_PREFIXES)
    if AION_LOG_MODE == "execution" and not AION_DEBUG_TELEMETRY:
        if _aion_is_execution_critical_tag(tag) or _aion_is_execution_critical_message(tag, first):
            return True
        if _aion_is_advisory_tag(tag):
            _aion_record_advisory_suppressed(tag)
        return False
    if AION_DEBUG_TELEMETRY or AION_LOG_MODE in {"debug", "verbose", "all"}:
        return True
    severity = _telemetry_severity(tag)
    if severity == "NORMAL":
        if DEBUG_LIVE:
            return True
        return not first.startswith(DEBUG_LIVE_PREFIXES)
    telemetry_key = _telemetry_key_from_message(first)
    result = should_emit_telemetry(
        tag,
        key=telemetry_key,
        cooldown_seconds=_telemetry_cooldown_seconds(tag, severity, _TELEMETRY_STATE["suppression_mode_active"]),
        severity=severity,
        allow_aggregate=True,
    )
    return bool(result.get("emit"))


def print(*args, **kwargs):
    canonical_final_submit_allowed = False
    _aion_track_execution_cycle(*args)
    if _should_emit_module_log(*args):
        return builtins.print(*args, **kwargs)
    return None


class LiveRejectTelemetry:
    """Read-only counters for live candidate rejection analysis."""

    def __init__(self, summary_interval_seconds=180.0, max_near_passes=10):
        self.summary_interval_seconds = max(60.0, float(summary_interval_seconds or 180.0))
        self.max_near_passes = max(1, int(max_near_passes or 10))
        self.last_summary_ts = 0.0
        self.reject_reason_counts = Counter()
        self.reject_family_counts = Counter()
        self.reject_stage_counts = Counter()
        self.spread_reject_count = 0
        self.continuity_reject_count = 0
        self.entry_timing_reject_count = 0
        self.execution_authorization_reject_count = 0
        self.rejected_spread_total = 0.0
        self.rejected_spread_count = 0
        self.near_pass_candidates = deque(maxlen=self.max_near_passes)

    def _normalize_reason(self, reason):
        return str(reason or "").strip() or "unknown"

    def record_reject(self, *, reason, ticker=None, family=None, spread=None, stage=None, category=None, details=None):
        reason_text = self._normalize_reason(reason)
        stage_text = self._normalize_reason(stage)
        category_text = self._normalize_reason(category)
        ticker_text = str(ticker or "").strip() or None
        family_text = str(family or "").strip() or None
        self.reject_reason_counts[reason_text] += 1
        if family_text:
            self.reject_family_counts[family_text] += 1
        if stage_text:
            self.reject_stage_counts[stage_text] += 1
        if spread is not None:
            try:
                self.rejected_spread_total += float(spread)
                self.rejected_spread_count += 1
            except (TypeError, ValueError):
                pass
        if category_text == "spread" or "spread" in reason_text:
            self.spread_reject_count += 1
        if category_text == "continuity" or "continuity" in reason_text:
            self.continuity_reject_count += 1
        if category_text == "entry_timing" or reason_text.startswith("phase55_status_") or reason_text in {"entry_timing_pass_not_explicit", "immediate_entry_protection"}:
            self.entry_timing_reject_count += 1
        if category_text == "execution_authorization":
            self.execution_authorization_reject_count += 1

    def record_near_pass(self, *, ticker=None, family=None, spread=None, score=None, threshold=None, reason=None, stage=None, details=None):
        payload = {
            "ticker": str(ticker or "").strip() or None,
            "family": str(family or "").strip() or None,
            "spread": spread,
            "score": score,
            "threshold": threshold,
            "reason": self._normalize_reason(reason),
            "stage": self._normalize_reason(stage),
        }
        if isinstance(details, dict):
            payload.update({key: value for key, value in details.items() if value is not None})
        self.near_pass_candidates.append(payload)

    def snapshot(self):
        avg_rejected_spread = None
        if self.rejected_spread_count:
            avg_rejected_spread = round(self.rejected_spread_total / float(self.rejected_spread_count), 4)
        return {
            "total_reject_events": sum(self.reject_reason_counts.values()),
            "unique_reject_reasons": len(self.reject_reason_counts),
            "top_reject_reasons": self.reject_reason_counts.most_common(8),
            "top_blocked_families": self.reject_family_counts.most_common(8),
            "top_reject_stages": self.reject_stage_counts.most_common(8),
            "spread_rejection_count": self.spread_reject_count,
            "continuity_rejection_count": self.continuity_reject_count,
            "entry_timing_rejection_count": self.entry_timing_reject_count,
            "execution_authorization_rejection_count": self.execution_authorization_reject_count,
            "average_rejected_spread": avg_rejected_spread,
            "rejected_spread_count": self.rejected_spread_count,
            "near_pass_candidates": list(self.near_pass_candidates),
            "near_pass_count": len(self.near_pass_candidates),
        }

    def maybe_emit_summary(self, *, source="live_cycle", cycle_count=None, force=False):
        canonical_final_submit_allowed = False
        now = time.time()
        if not force and (now - float(self.last_summary_ts or 0.0)) < self.summary_interval_seconds:
            return None
        summary = self.snapshot()
        if not force and summary["total_reject_events"] <= 0 and summary["near_pass_count"] <= 0:
            return None
        self.last_summary_ts = now
        print(
            f"[LIVE-GATE-STATS] source={source} cycle_count={cycle_count if cycle_count is not None else 'unknown'} "
            f"total_reject_events={summary['total_reject_events']} spread_rejections={summary['spread_rejection_count']} "
            f"continuity_rejections={summary['continuity_rejection_count']} entry_timing_rejections={summary['entry_timing_rejection_count']} "
            f"execution_authorization_rejections={summary['execution_authorization_rejection_count']} "
            f"avg_rejected_spread={summary['average_rejected_spread']}"
        )
        print(f"[LIVE-REJECT-SUMMARY] {json.dumps(summary, sort_keys=True)}")
        for near_pass in summary["near_pass_candidates"][: self.max_near_passes]:
            print(f"[LIVE-NEAR-PASS] {json.dumps(near_pass, sort_keys=True)}")
        return summary


def get_env_bool(name, default):
    raw_value = (os.environ.get(name, "") or "").strip().lower()
    if not raw_value:
        return bool(default)
    return raw_value in {"1", "true", "yes", "on"}


def get_env_int(name, default):
    raw_value = (os.environ.get(name, "") or "").strip()
    if not raw_value:
        return int(default)
    try:
        return int(float(raw_value))
    except (TypeError, ValueError):
        return int(default)


def get_env_float(name, default):
    raw_value = (os.environ.get(name, "") or "").strip()
    if not raw_value:
        return float(default)
    try:
        return float(raw_value)
    except (TypeError, ValueError):
        return float(default)


def _env_float(name, default):
    return get_env_float(name, default)


AION_AGGRESSION_PROFILE_DEFAULT = "safe"
AION_AGGRESSION_PROFILE_VALUES = {"safe", "balanced", "opportunistic", "beast"}
RELAXED_BEAST_MODE_LEVEL = get_env_int("RELAXED_BEAST_MODE_LEVEL", 4)


AION_USE_REALM_VV_ENTRY_ENGINE = str(os.environ.get("AION_USE_REALM_VV_ENTRY_ENGINE", "1") or "1").strip().lower() not in {"0", "false", "no", "off"}
AION_USE_LEGACY_PHASE55 = str(os.environ.get("AION_USE_LEGACY_PHASE55", "0") or "0").strip().lower() in {"1", "true", "yes", "y", "on"}


def _normalize_aion_aggression_profile(profile):
    base_profile = profile
    if base_profile is None or str(base_profile).strip() == "":
        base_profile = globals().get("AION_AGGRESSION_PROFILE", AION_AGGRESSION_PROFILE_DEFAULT)
    text = str(base_profile or AION_AGGRESSION_PROFILE_DEFAULT).strip().lower()
    return text if text in AION_AGGRESSION_PROFILE_VALUES else AION_AGGRESSION_PROFILE_DEFAULT


def _normalize_aggression_profile(profile):
    return _normalize_aion_aggression_profile(profile)


normalize_aggression_profile = _normalize_aggression_profile
profile = _normalize_aion_aggression_profile(AION_AGGRESSION_PROFILE if "AION_AGGRESSION_PROFILE" in globals() else AION_AGGRESSION_PROFILE_DEFAULT)


def _relaxed_beast_mode_enabled(level=4):
    try:
        return int(RELAXED_BEAST_MODE_LEVEL) >= int(level)
    except Exception:
        return False


def _aion_aggression_profile_settings(profile=None, *, family=None, spread_bucket=None, context=None):
    profile_source = profile if profile is not None else globals().get("AION_AGGRESSION_PROFILE", AION_AGGRESSION_PROFILE_DEFAULT)
    profile_name = _normalize_aion_aggression_profile(profile_source)
    try:
        controlled = bool(AION_CONTROLLED_LOOSENING_ENABLED)
    except Exception:
        controlled = True
    if not controlled:
        profile_name = "safe"
    family_text = str(family or "").strip().upper()
    spread_text = str(spread_bucket or "").strip().lower()
    settings = {
        "profile": profile_name,
        "reason": "safe_default",
        "score_threshold_delta": 0.0,
        "confidence_threshold_delta": 0.0,
        "edge_threshold_delta": 0.0,
        "sports_threshold_delta": 0.0,
        "phase55_relaxation": 0.0,
        "flat_market_relaxation": 0.0,
        "candidate_score_bonus": 0.0,
        "effective_edge_threshold": None,
        "effective_sports_threshold": None,
        "candidate_count_before": None,
        "candidate_count_after": None,
        "payload_ready_count": None,
        "phase55_ready_count": None,
        "safety_gates_preserved": True,
        "spread_bucket": spread_text or None,
        "family": family_text or None,
        "context": str(context or "").strip() or None,
    }
    if profile_name == "balanced":
        settings.update({
            "reason": "balanced_profile",
            "score_threshold_delta": 2.0,
            "confidence_threshold_delta": 0.02,
            "edge_threshold_delta": 0.006,
            "sports_threshold_delta": 0.012,
            "phase55_relaxation": 0.025,
            "flat_market_relaxation": 0.015,
        })
    elif profile_name == "opportunistic":
        settings.update({
            "reason": "opportunistic_profile",
            "score_threshold_delta": 4.0,
            "confidence_threshold_delta": 0.04,
            "edge_threshold_delta": 0.012,
            "sports_threshold_delta": 0.018,
            "phase55_relaxation": 0.045,
            "flat_market_relaxation": 0.030,
        })
    elif profile_name == "beast":
        settings.update({
            "reason": "beast_profile",
            "score_threshold_delta": 6.0,
            "confidence_threshold_delta": 0.06,
            "edge_threshold_delta": 0.0135,
            "sports_threshold_delta": 0.022,
            "phase55_relaxation": 0.060,
            "flat_market_relaxation": 0.040,
        })
    if family_text in AION_HIGH_LIQUIDITY_ALLOWED_FAMILIES:
        settings["score_threshold_delta"] = round(settings["score_threshold_delta"] + 0.5, 4)
        settings["confidence_threshold_delta"] = round(settings["confidence_threshold_delta"] + 0.005, 4)
        settings["edge_threshold_delta"] = round(settings["edge_threshold_delta"] + 0.001, 4)
        settings["sports_threshold_delta"] = round(settings["sports_threshold_delta"] + 0.002, 4)
        settings["phase55_relaxation"] = round(settings["phase55_relaxation"] + 0.003, 4)
        settings["flat_market_relaxation"] = round(settings["flat_market_relaxation"] + 0.002, 4)
        settings["reason"] = f"{settings['reason']}+high_liquidity_family"
    settings["candidate_score_bonus"] = round(settings["score_threshold_delta"] + (settings["confidence_threshold_delta"] * 10.0), 4)
    settings["confidence_floor"] = round(max(0.0, 0.55 - settings["confidence_threshold_delta"]), 4)
    settings["effective_score_threshold"] = round(max(0.0, PHASE5_BUY_SCORE_THRESHOLD - settings["score_threshold_delta"]), 4)
    settings["effective_edge_threshold"] = round(max(0.0, AION_SPORTS_MIN_EDGE_AFTER_COST - settings["edge_threshold_delta"]), 4)
    settings["effective_sports_threshold"] = round(max(0.0, MAX_ENTRY_SPREAD - settings["sports_threshold_delta"]), 4)
    return settings


def _classify_market_personality(self, market=None, quote_diag=None, q=None, family=None):
    market = market if isinstance(market, dict) else {}
    quote_diag = quote_diag if isinstance(quote_diag, dict) else {}
    family = str(
        family
        or self.get_market_family(market)
        or getattr(q, "family", "")
        or market.get("family", "")
        or "UNKNOWN"
    ).strip().upper() or "UNKNOWN"
    profiles = {}
    try:
        profiles = ((self.market_personality_profiles or {}).get("families", {}) or {}) if isinstance(getattr(self, "market_personality_profiles", None), dict) else {}
    except Exception:
        profiles = {}
    profile = profiles.get(family, {}) if isinstance(profiles, dict) else {}
    personality_type = str(profile.get("personality_type") or "").strip().lower() or "balanced"
    liquidity_depth = self.to_float(
        quote_diag.get("liquidity_depth"),
        self.to_float(
            quote_diag.get("liquidity"),
            self.to_float(
                getattr(q, "liquidity", None),
                self.to_float(market.get("liquidity_dollars"), self.to_float(market.get("liquidity"), 0.0)),
            ),
        ),
    )
    spread_bucket = str(quote_diag.get("spread_bucket") or quote_diag.get("sports_spread_bucket") or "").strip().lower()
    quote_reliability = self.to_float(profile.get("quote_reliability"), 0.0)
    liquidity_reliability = self.to_float(profile.get("liquidity_reliability"), 0.0)
    spread_stability = self.to_float(profile.get("spread_stability"), 0.0)
    volatility_reliability = self.to_float(profile.get("fake_breakout_risk"), 0.0)
    if family in {"KXBTC15M", "KXETH15M", "KXCRYPTO"} or personality_type in {"momentum_heavy"}:
        category = "HIGH_LIQUIDITY_FAST"
    elif personality_type in {"fake_breakout_prone"}:
        category = "VOLATILE_ACTIVE"
    elif quote_reliability < 0.4 or liquidity_reliability < 0.4:
        category = "SPARSE_CAUTION"
    elif liquidity_depth <= 0.0 and spread_bucket in {"unsafe", "extreme_wide"}:
        category = "DEAD_MARKET"
    elif spread_stability >= 0.6 and quote_reliability >= 0.5 and liquidity_depth <= 6.0:
        category = "THIN_BUT_TRADEABLE"
    elif spread_bucket in {"ultra_tight", "tight"} and liquidity_depth >= 3.0:
        category = "HIGH_LIQUIDITY_FAST"
    else:
        category = "VOLATILE_ACTIVE" if volatility_reliability >= 0.55 else "THIN_BUT_TRADEABLE"
    return {
        "category": category,
        "personality_type": personality_type,
        "family": family,
        "quote_reliability": round(quote_reliability, 4),
        "liquidity_reliability": round(liquidity_reliability, 4),
        "spread_stability": round(spread_stability, 4),
        "liquidity_depth": round(liquidity_depth, 4),
        "spread_bucket": spread_bucket or "unknown",
    }


def _compute_realm_vv_confidence(self, *, edge_after_cost=0.0, liquidity_depth=0.0, spread_bucket="unknown", market_personality=None, profile_settings=None, quote_ready=False, orderbook_ready=False, price_bounds_pass=False):
    price_bounds_pass = False
    profile_settings = profile_settings if isinstance(profile_settings, dict) else {}
    market_personality = market_personality if isinstance(market_personality, dict) else {}
    profile_name = str(profile_settings.get("profile") or "safe").strip().lower() or "safe"
    edge_after_cost = max(0.0, self.to_float(edge_after_cost, 0.0))
    liquidity_depth = max(0.0, self.to_float(liquidity_depth, 0.0))
    spread_bucket = str(spread_bucket or "unknown").strip().lower() or "unknown"
    edge_threshold = max(0.001, self.to_float(profile_settings.get("effective_edge_threshold"), 0.003))
    confidence_floor = max(0.0, self.to_float(profile_settings.get("confidence_floor"), 0.55))
    confidence = 0.0
    confidence += min(0.30, (edge_after_cost / edge_threshold) * 0.18 if edge_threshold > 0 else 0.18)
    confidence += min(0.20, min(1.0, liquidity_depth / 10.0) * 0.20)
    confidence += 0.20 if spread_bucket in {"ultra_tight", "tight"} else 0.12 if spread_bucket == "wide_but_possible" else 0.04 if spread_bucket == "unsafe" else 0.08
    confidence += {"HIGH_LIQUIDITY_FAST": 0.18, "VOLATILE_ACTIVE": 0.12, "THIN_BUT_TRADEABLE": 0.10, "SPARSE_CAUTION": 0.04, "DEAD_MARKET": 0.0}.get(str(market_personality.get("category") or "").strip().upper(), 0.08)
    confidence += 0.08 if profile_name in {"opportunistic", "beast"} else 0.03 if profile_name == "balanced" else 0.0
    confidence += 0.08 if quote_ready else 0.0
    confidence += 0.08 if orderbook_ready else 0.0
    confidence += 0.06 if price_bounds_pass else 0.0
    confidence = self._clamp(confidence, 0.0, 1.0)
    if confidence >= 0.82:
        confidence_tier = "high"
    elif confidence >= max(0.62, confidence_floor):
        confidence_tier = "medium"
    elif confidence >= 0.42:
        confidence_tier = "low"
    else:
        confidence_tier = "weak"
    survivability_score = self._clamp(
        min(1.0, (liquidity_depth / 10.0)) * 0.35
        + (0.25 if spread_bucket in {"ultra_tight", "tight"} else 0.15 if spread_bucket == "wide_but_possible" else 0.05)
        + (0.20 if quote_ready else 0.0)
        + (0.20 if orderbook_ready else 0.0),
        0.0,
        1.0,
    )
    suggested_size_multiplier = self._clamp(
        0.45
        + (0.35 if profile_name == "beast" else 0.20 if profile_name == "opportunistic" else 0.10 if profile_name == "balanced" else 0.0)
        + (0.20 if confidence_tier == "high" else 0.10 if confidence_tier == "medium" else 0.0)
        + (0.10 if spread_bucket in {"ultra_tight", "tight"} else 0.0),
        0.25,
        1.0,
    )
    return {
        "confidence_score": round(confidence, 4),
        "confidence_tier": confidence_tier,
        "survivability_score": round(survivability_score, 4),
        "suggested_size_multiplier": round(suggested_size_multiplier, 4),
        "confidence_floor": round(confidence_floor, 4),
        "edge_threshold": round(edge_threshold, 4),
    }


def _classify_realm_vv_spread_severity(self, *, spread_bucket="unknown", edge_after_cost=0.0, profile="safe", market_personality=None, quote_ready=False, orderbook_ready=False, price_bounds_pass=False, liquidity_depth=0.0, fresh_enough=True, topbook_depth_exists=False, selected_side_has_price=False, selected_side_has_liquidity=False, depth_available=False, aggression_settings=None):
        market_personality = market_personality if isinstance(market_personality, dict) else {}
        if orderbook_health_classify_realm_vv_spread_severity is not None:
            aggression_settings = aggression_settings if isinstance(aggression_settings, dict) else _aion_aggression_profile_settings(
                _normalize_aion_aggression_profile(profile),
                family=market_personality.get("family"),
                spread_bucket=str(spread_bucket or "unknown").strip().lower() or "unknown",
                context="realm_vv_spread",
            )
            return orderbook_health_classify_realm_vv_spread_severity(
                spread_bucket=spread_bucket,
                edge_after_cost=edge_after_cost,
                profile=profile,
                market_personality=market_personality,
                quote_ready=quote_ready,
                orderbook_ready=orderbook_ready,
                price_bounds_pass=price_bounds_pass,
                liquidity_depth=liquidity_depth,
                fresh_enough=fresh_enough,
                topbook_depth_exists=topbook_depth_exists,
                selected_side_has_price=selected_side_has_price,
                selected_side_has_liquidity=selected_side_has_liquidity,
                depth_available=depth_available,
                aggression_settings=aggression_settings,
            )
        profile = _normalize_aion_aggression_profile(profile)
        market_personality = market_personality if isinstance(market_personality, dict) else {}
        spread_bucket = str(spread_bucket or "unknown").strip().lower() or "unknown"
        edge_after_cost = max(0.0, self.to_float(edge_after_cost, 0.0))
        liquidity_depth = max(0.0, self.to_float(liquidity_depth, 0.0))
        price_bounds_pass = bool(price_bounds_pass)
        quote_ready = bool(quote_ready)
        orderbook_ready = bool(orderbook_ready)
        topbook_depth_exists = bool(topbook_depth_exists)
        selected_side_has_price = bool(selected_side_has_price)
        selected_side_has_liquidity = bool(selected_side_has_liquidity)
        depth_available = bool(depth_available)
        if liquidity_depth <= 0.0 and (topbook_depth_exists or selected_side_has_liquidity or depth_available):
            liquidity_depth = 1.0
        fresh_enough = bool(fresh_enough)
        aggression_settings = aggression_settings if isinstance(aggression_settings, dict) else _aion_aggression_profile_settings(profile, family=market_personality.get("family"), spread_bucket=spread_bucket, context="realm_vv_spread")
        threshold = max(0.001, self.to_float(aggression_settings.get("effective_edge_threshold"), 0.003))
        personality_category = str(market_personality.get("category") or "").strip().upper() or "THIN_BUT_TRADEABLE"
        beast_mode = profile in {"opportunistic", "beast"}
        survivable_aggressive_precheck = bool(
            beast_mode
            and edge_after_cost > 0.0
            and price_bounds_pass
            and quote_ready
            and fresh_enough
            and (orderbook_ready or topbook_depth_exists or selected_side_has_liquidity or depth_available or selected_side_has_price)
        )
        if not price_bounds_pass or not quote_ready or not fresh_enough:
            return {
                "classification": "UNSAFE",
                "reason": "hard_safety_or_staleness",
                "severity": "catastrophic",
                "is_catastrophic": True,
                "is_survivable": False,
                "beast_spread_override_applied": False,
                "final_submit_allowed_by_realm_vv": False,
                "threshold": round(threshold, 4),
            }
        if not orderbook_ready and survivable_aggressive_precheck and spread_bucket in {"unsafe", "wide_but_possible"}:
            if edge_after_cost >= threshold * (0.75 if profile == "beast" else 1.0):
                return {
                    "classification": "AGGRESSIVE_BUT_TRADEABLE",
                    "reason": "survivable_aggressive_no_orderbook_ready",
                    "severity": "survivable",
                    "is_catastrophic": False,
                    "is_survivable": True,
                    "beast_spread_override_applied": bool(profile == "beast"),
                    "final_submit_allowed_by_realm_vv": True,
                    "threshold": round(threshold, 4),
                }
            return {
                "classification": "CAUTION_WAIT",
                "reason": "survivable_aggressive_no_orderbook_ready",
                "severity": "survivable",
                "is_catastrophic": False,
                "is_survivable": True,
                "beast_spread_override_applied": False,
                "final_submit_allowed_by_realm_vv": False,
                "threshold": round(threshold, 4),
            }
        if spread_bucket in {"ultra_tight", "tight"}:
            return {
                "classification": "SAFE",
                "reason": "tight_or_ultra_tight_book",
                "severity": "survivable",
                "is_catastrophic": False,
                "is_survivable": True,
                "beast_spread_override_applied": False,
                "final_submit_allowed_by_realm_vv": True,
                "threshold": round(threshold, 4),
            }
        if spread_bucket == "wide_but_possible":
            aggressive_edge_floor = threshold * (0.75 if profile == "beast" else 1.0)
            if edge_after_cost >= aggressive_edge_floor and (liquidity_depth > 0.0 or selected_side_has_liquidity or depth_available or topbook_depth_exists or selected_side_has_price):
                return {
                    "classification": "AGGRESSIVE_BUT_TRADEABLE",
                    "reason": "positive_edge_with_depth",
                    "severity": "survivable",
                    "is_catastrophic": False,
                    "is_survivable": True,
                    "beast_spread_override_applied": bool(profile == "beast"),
                    "final_submit_allowed_by_realm_vv": True,
                    "threshold": round(threshold, 4),
                }
            if beast_mode and edge_after_cost > 0.0 and (liquidity_depth > 0.0 or selected_side_has_liquidity or depth_available or topbook_depth_exists) and personality_category != "DEAD_MARKET":
                return {
                    "classification": "CAUTION_WAIT",
                    "reason": "beast_mode_near_miss",
                    "severity": "survivable",
                    "is_catastrophic": False,
                    "is_survivable": True,
                    "beast_spread_override_applied": False,
                    "final_submit_allowed_by_realm_vv": False,
                    "threshold": round(threshold, 4),
                }
            if edge_after_cost > 0.0 and personality_category != "DEAD_MARKET":
                return {
                    "classification": "CAUTION_WAIT",
                    "reason": "edge_near_threshold",
                    "severity": "survivable",
                    "is_catastrophic": False,
                    "is_survivable": True,
                    "beast_spread_override_applied": False,
                    "final_submit_allowed_by_realm_vv": False,
                    "threshold": round(threshold, 4),
                }
            return {
                "classification": "UNSAFE",
                "reason": "wide_spread_no_survivable_edge",
                "severity": "catastrophic",
                "is_catastrophic": True,
                "is_survivable": False,
                "beast_spread_override_applied": False,
                "final_submit_allowed_by_realm_vv": False,
                "threshold": round(threshold, 4),
            }
        if spread_bucket == "unsafe":
            if beast_mode and edge_after_cost >= threshold * (0.75 if profile == "beast" else 1.0) and (liquidity_depth > 0.0 or selected_side_has_liquidity or depth_available or topbook_depth_exists or selected_side_has_price):
                return {
                    "classification": "AGGRESSIVE_BUT_TRADEABLE",
                    "reason": "beast_mode_wide_spread_allowed",
                    "severity": "survivable",
                    "is_catastrophic": False,
                    "is_survivable": True,
                    "beast_spread_override_applied": True,
                    "final_submit_allowed_by_realm_vv": True,
                    "threshold": round(threshold, 4),
                }
            if beast_mode and edge_after_cost > 0.0 and (liquidity_depth > 0.0 or selected_side_has_liquidity or depth_available or topbook_depth_exists) and personality_category != "DEAD_MARKET":
                return {
                    "classification": "CAUTION_WAIT",
                    "reason": "beast_mode_wait_for_fill",
                    "severity": "survivable",
                    "is_catastrophic": False,
                    "is_survivable": True,
                    "beast_spread_override_applied": False,
                    "final_submit_allowed_by_realm_vv": False,
                    "threshold": round(threshold, 4),
                }
            return {
                "classification": "UNSAFE",
                "reason": "catastrophic_spread",
                "severity": "catastrophic",
                "is_catastrophic": True,
                "is_survivable": False,
                "beast_spread_override_applied": False,
                "final_submit_allowed_by_realm_vv": False,
                "threshold": round(threshold, 4),
            }
        return {
            "classification": "CAUTION_WAIT" if edge_after_cost > 0.0 else "UNSAFE",
            "reason": "unknown_spread_bucket",
            "severity": "survivable" if edge_after_cost > 0.0 else "catastrophic",
            "is_catastrophic": bool(edge_after_cost <= 0.0),
            "is_survivable": bool(edge_after_cost > 0.0),
            "beast_spread_override_applied": False,
            "final_submit_allowed_by_realm_vv": False,
            "threshold": round(threshold, 4),
        }


def _emit_aion_aggression_trace(prefix, payload):
    try:
        print(f"[{prefix}] " + json.dumps(payload, sort_keys=True, default=str))
    except Exception:
        print(f"[{prefix}] " + json.dumps({"error": "trace_emit_failed"}))


def send_telegram_message(text):
    token = (os.environ.get("TELEGRAM_BOT_TOKEN", "") or "").strip()
    chat_id = (os.environ.get("TELEGRAM_CHAT_ID", "") or "").strip()
    token_prefix = f"{token[:8]}..." if token else "missing"
    chat_prefix = f"{chat_id[:8]}..." if chat_id else "missing"
    print(
        f"[TELEGRAM-DEBUG] token_present={bool(token)} token_prefix={token_prefix} "
        f"chat_present={bool(chat_id)} chat_prefix={chat_prefix}"
    )
    if not token or not chat_id or not text:
        return False
    try:
        response = requests.post(
            f"https://api.telegram.org/bot{token}/sendMessage",
            data={"chat_id": chat_id, "text": str(text)[:4000]},
            timeout=10,
        )
        try:
            response_body = response.json()
        except Exception:
            response_body = {"raw_text": response.text[:500]}
        print(
            f"[TELEGRAM-DEBUG] status_code={response.status_code} "
            f"response={response_body}"
        )
        if isinstance(response_body, dict):
            return bool(response.ok and response_body.get("ok"))
        return bool(response.ok)
    except Exception as exc:
        print(f"[TELEGRAM-DEBUG] exception={exc}")
        return False

