    def get_markets(self, limit=25, status="open", cursor=None, return_cursor=False, extra_params=None):
        if globals().get("LIVE_MODE", False):
            base_url = self.get_live_base_url()
            url = self.build_live_request_url("/trade-api/v2/markets")
            print(f"[LIVE-MARKETS-DEBUG] base_url={base_url}")
            print(f"[LIVE-MARKETS-DEBUG] url={url}")
        else:
            url = f"{BASE_URL}/markets"
        params = {
            "limit": limit,
            "status": status,
        }
        if cursor:
            params["cursor"] = cursor
        if extra_params:
            params.update(extra_params)
        if globals().get("LIVE_MODE", False):
            params.setdefault("mve_filter", "exclude")
        if globals().get("LIVE_MODE", False):
            print(f"[LIVE-MARKETS-DEBUG] params={params}")
        response = requests.get(url, params=params, timeout=15)
        response.raise_for_status()
        response_data = response.json()
        markets = response_data.get("markets", [])
        if return_cursor:
            next_cursor = response_data.get("cursor") or response_data.get("next_cursor")
            return markets, next_cursor
        return markets

    def to_float(self, value, default=0.0):
        try:
            if value is None:
                return default
            return float(value)
        except (TypeError, ValueError):
            return default

    def get_market_quote_values(self, market):
        return {
            "yes_bid": self.to_float(market.get("yes_bid_dollars", market.get("yes_bid")), None),
            "yes_ask": self.to_float(market.get("yes_ask_dollars", market.get("yes_ask")), None),
            "no_bid": self.to_float(market.get("no_bid_dollars", market.get("no_bid")), None),
            "no_ask": self.to_float(market.get("no_ask_dollars", market.get("no_ask")), None),
        }

    def has_complete_quote_side(self, bid_value, ask_value):
        return bid_value is not None and ask_value is not None

    def has_complete_numeric_quotes(self, market):
        quote_values = self.get_market_quote_values(market)
        return all(value is not None for value in quote_values.values())

    def _safe_payload_keys(self, payload):
        if not isinstance(payload, dict):
            return []
        return sorted(str(key) for key in payload.keys())[:30]

    def _is_sports_market_or_family(self, market_or_family):
        return self.get_market_discovery_category(market_or_family) == "sports"

    def is_sports_family(self, family, ticker=None):
        family = str(family or "").strip().upper()
        if not family and ticker:
            family = str(self.get_market_family({"ticker": str(ticker).strip()}) or "").strip().upper()
        sports_prefixes = (
            "KXNBA", "KXWNBA", "KXMLB", "KXNFL", "KXNHL", "KXNCAA", "KXNCAAB", "KXNCAAF",
            "KXCFB", "KXCBB", "KXATP", "KXWTA", "KXITF", "KXTENNIS", "KXGOLF", "KXEPL",
            "KXSOCCER", "KXSQUASH", "KXUFC", "KXMMA", "KXBOX",
        )
        explicit_sports_families = {
            "KXNBA", "KXNBA1H", "KXNBA1HTOTAL", "KXNBA1HSPREAD", "KXNBASPREAD", "KXNBATOTAL",
            "KXMLB", "KXMLBSPREAD", "KXMLBTOTAL", "KXMLBHRR", "KXMLBMONEYLINE", "KXMLBHR", "KXMLBTB", "KXMLBHIT",
            "KXNFL", "KXNFLSPREAD", "KXNFLTOTAL",
            "KXNHL", "KXNHLGOAL",
            "KXNCAAB", "KXNCAAF",
            "KXCFB", "KXCBB", "KXATP", "KXWTA", "KXITF", "KXTENNISMATCH", "KXATPCHALLENGERMATCH",
            "KXGOLF", "KXEPL", "KXSOCCER", "KXSQUASHMATCH", "KXUFC", "KXMMA", "KXBOX",
        }
        if family in explicit_sports_families or any(family.startswith(prefix) for prefix in sports_prefixes):
            return True
        if ticker:
            ticker_family = str(self.get_market_family({"ticker": str(ticker).strip()}) or "").strip().upper()
            if ticker_family and (ticker_family in explicit_sports_families or any(ticker_family.startswith(prefix) for prefix in sports_prefixes)):
                return True
        return self.get_market_discovery_category(family or ticker or "") == "sports"

    def _classify_sports_liquidity_market_type(self, family=None, ticker=None, title=None):
        family = str(family or "").strip().upper()
        ticker = str(ticker or "").strip().upper()
        code = family if family and family != "UNKNOWN" else ticker
        text = " ".join(str(value or "").strip().upper() for value in (family, ticker, title) if value)
        if code.startswith("KXMLBHR") or "HOME RUN" in text or " HR" in text:
            return "mlb_hr_longshot"
        if (
            code.startswith(("KXMLBTB", "KXMLBHIT"))
            or "HIT" in text
            or "TOTAL BASE" in text
            or "RBI" in text
            or "STRIKEOUT" in text
            or "PLAYER PROP" in text
        ):
            return "mlb_player_prop"
        if code.startswith(("KXMLBSPREAD", "KXMLBTOTAL", "KXMLBMONEYLINE", "KXMLB")):
            return "mlb_core"
        if code.startswith(("KXATP", "KXTENNIS", "KXWTA", "KXITF")) or "ATP" in text or "TENNIS" in text:
            return "tennis_atp"
        if code.startswith(("KXNBA", "KXNFL", "KXNHL", "KXNCAA", "KXCFB", "KXCBB", "KXSQUASH")):
            return "sports_core"
        return "sports_default"

    def _sports_liquidity_relaxation_thresholds(self, market_type):
        market_type = str(market_type or "sports_default").strip().lower()
        defaults = {
            "spread_cap": max(AION_SPORTS_MAX_SPREAD_SOFT, 0.35),
            "edge_floor": max(0.0025, AION_SPORTS_MIN_EDGE_AFTER_COST * 0.30),
            "stale_seconds": 240.0,
        }
        by_type = {
            "mlb_core": {"spread_cap": max(AION_SPORTS_MAX_SPREAD_SOFT, 0.32), "edge_floor": max(0.002, AION_SPORTS_MIN_EDGE_AFTER_COST * 0.25), "stale_seconds": 240.0},
            "mlb_player_prop": {"spread_cap": max(AION_SPORTS_MAX_SPREAD_SOFT, 0.48), "edge_floor": max(0.004, AION_SPORTS_MIN_EDGE_AFTER_COST * 0.35), "stale_seconds": 240.0},
            "mlb_hr_longshot": {"spread_cap": max(AION_SPORTS_MAX_SPREAD_HARD, 0.65), "edge_floor": max(0.008, AION_SPORTS_MIN_EDGE_AFTER_COST * 0.55), "stale_seconds": 240.0},
            "tennis_atp": {"spread_cap": max(AION_SPORTS_MAX_SPREAD_SOFT, 0.42), "edge_floor": max(0.0035, AION_SPORTS_MIN_EDGE_AFTER_COST * 0.35), "stale_seconds": 180.0},
            "sports_core": {"spread_cap": max(AION_SPORTS_MAX_SPREAD_SOFT, 0.28), "edge_floor": max(0.0025, AION_SPORTS_MIN_EDGE_AFTER_COST * 0.30), "stale_seconds": 240.0},
        }
        return {**defaults, **by_type.get(market_type, {})}

    def _sports_liquidity_relaxation_decision(
        self,
        *,
        ticker=None,
        family=None,
        market_title=None,
        market=None,
        selected_side=None,
        selected_price=None,
        spread=None,
        yes_top_size=None,
        no_top_size=None,
        liquidity=None,
        edge_after_cost=None,
        profitability_score=None,
        blocker_reason=None,
        unsafe_price_status=None,
        unsafe_resolution_reason=None,
        orderbook_age_seconds=None,
        market_lifecycle_state=None,
        final_submit_allowed=False,
        quote_ready=False,
        orderbook_ready=False,
    ):
        family = str(family or self.get_market_family(market or {}) or "").strip().upper()
        ticker = str(ticker or (market or {}).get("ticker") or "").strip()
        market_title = str(market_title or (market or {}).get("title") or (market or {}).get("market_title") or "").strip()
        selected_side = str(selected_side or "").strip().lower()
        market_type = self._classify_sports_liquidity_market_type(family=family, ticker=ticker, title=market_title)
        thresholds = self._sports_liquidity_relaxation_thresholds(market_type)
        selected_price_value = self.to_float(selected_price, None)
        spread_value = self.to_float(spread, None)
        yes_top = self.to_float(yes_top_size, 0.0) or 0.0
        no_top = self.to_float(no_top_size, 0.0) or 0.0
        liquidity_value = self.to_float(liquidity, 0.0) or 0.0
        edge_value = self.to_float(edge_after_cost, None)
        profitability_value = self.to_float(profitability_score, None)
        orderbook_age = self.to_float(orderbook_age_seconds, None)
        blocker = str(blocker_reason or "").strip().lower()
        unsafe_status = str(unsafe_price_status or "").strip().lower()
        unsafe_reason = str(unsafe_resolution_reason or "").strip().lower()
        lifecycle = str(market_lifecycle_state or "").strip().lower()
        weak_liquidity_blockers = {
            "insufficient_liquidity",
            "orderbook_not_usable",
            "quote_not_usable",
            "unsafe_spread",
            "spread_wait",
            "spread_above_threshold",
            "thin_book_without_depth",
            "thin_top_book",
            "low_liquidity",
            "selected_side_liquidity_missing",
            "missing_selected_side_liquidity",
            "topbook_size_too_small",
        }
        hard_unsafe_statuses = {
            "unexecutable_price",
            "both_sides_unexecutable",
            "invalid_price",
            "malformed_price",
            "inverted_book",
            "crossed_book",
            "corrupt_orderbook",
            "fake_orderbook",
            "dead_market",
            "empty_book",
        }
        executable_price = bool(selected_side in {"yes", "no"} and selected_price_value is not None and KALSHI_CONTRACT_MIN_PRICE <= selected_price_value <= KALSHI_CONTRACT_MAX_PRICE)
        explicit_fake_or_corrupt = bool(
            unsafe_status in hard_unsafe_statuses
            or unsafe_reason in hard_unsafe_statuses
            or blocker in {"selected_price_missing", "selected_price_below_0_01", "selected_price_above_0_99", "selected_price_unit_mismatch", "missing_selected_side_price"}
        )
        stale_timing = bool(
            lifecycle in {"closed", "settled", "expired", "halted", "cancelled"}
            or (orderbook_age is not None and orderbook_age > float(thresholds.get("stale_seconds", 240.0)))
        )
        spread_absurd = bool(spread_value is not None and (spread_value < 0.0 or spread_value > float(thresholds.get("spread_cap", AION_SPORTS_MAX_SPREAD_HARD))))
        edge_ok = bool(
            final_submit_allowed
            or (edge_value is not None and edge_value >= float(thresholds.get("edge_floor", 0.004)))
            or (
                edge_value is not None
                and edge_value > 0.0
                and profitability_value is not None
                and (
                    profitability_value >= 65.0
                    or (0.0 < profitability_value <= 1.0 and profitability_value >= 0.55)
                )
            )
        )
        true_book_block = bool(explicit_fake_or_corrupt or stale_timing or spread_absurd or not executable_price)
        reason = "sports_thin_liquidity_warning"
        allowed = bool(
            self.is_sports_family(family, ticker=ticker)
            and family != "KXBTC15M"
            and (blocker in weak_liquidity_blockers or not quote_ready or not orderbook_ready)
            and executable_price
            and not true_book_block
        )
        if not self.is_sports_family(family, ticker=ticker) or family == "KXBTC15M":
            reason = "not_relaxable_sports_family"
        elif blocker not in weak_liquidity_blockers and quote_ready and orderbook_ready:
            reason = "no_liquidity_relaxation_needed"
        elif not executable_price:
            reason = "missing_executable_selected_price"
        elif explicit_fake_or_corrupt:
            reason = "hard_book_or_price_integrity_block"
        elif stale_timing:
            reason = "stale_or_closed_sports_market"
        elif spread_absurd:
            reason = "sports_spread_absurd_for_family"
        elif not edge_ok:
            reason = "thin_book_without_confirmed_edge_demoted_to_size"
        return {
            "allowed": bool(allowed),
            "reason": reason,
            "market_type": market_type,
            "spread_cap": round(float(thresholds.get("spread_cap", AION_SPORTS_MAX_SPREAD_HARD)), 4),
            "edge_floor": round(float(thresholds.get("edge_floor", 0.004)), 4),
            "selected_price_executable": bool(executable_price),
            "selected_price": selected_price_value,
            "spread": spread_value,
            "yes_top_size": yes_top,
            "no_top_size": no_top,
            "liquidity": liquidity_value,
            "edge_after_cost": edge_value,
            "profitability_score": profitability_value,
            "edge_ok": bool(edge_ok),
            "true_book_block": bool(true_book_block),
            "blocker_reason": blocker or None,
            "unsafe_price_status": unsafe_status or None,
            "unsafe_resolution_reason": unsafe_reason or None,
            "orderbook_age_seconds": orderbook_age,
            "market_lifecycle_state": lifecycle or None,
            "final_effect": "sports_thin_liquidity_warning" if allowed else "hard_block",
        }

    def _emit_sports_liquidity_decision_log(self, tag, *, ticker=None, family=None, selected_side=None, decision=None, reason=None):
        decision = decision if isinstance(decision, dict) else {}
        payload = {
            "ticker": ticker or None,
            "family": family or None,
            "market_type": decision.get("market_type"),
            "selected_side": selected_side or None,
            "selected_price": decision.get("selected_price"),
            "spread": decision.get("spread"),
            "yes_top_size": decision.get("yes_top_size"),
            "no_top_size": decision.get("no_top_size"),
            "liquidity": decision.get("liquidity"),
            "edge_after_cost": decision.get("edge_after_cost"),
            "profitability_score": decision.get("profitability_score"),
            "reason": reason or decision.get("reason"),
            "final_effect": decision.get("final_effect"),
        }
        try:
            print(f"[{tag}] " + json.dumps(payload, sort_keys=True, default=str))
        except Exception:
            pass

    def _get_sports_market_lifecycle_state(self, *args, **kwargs):
        if sports_calibration is None or not hasattr(sports_calibration, "get_sports_market_lifecycle_state"):
            raise RuntimeError("sports.calibration.get_sports_market_lifecycle_state unavailable")
        return sports_calibration.get_sports_market_lifecycle_state(bot=self, *args, **kwargs)

    def _sports_live_state_field(self, sources, *names):
        for source in sources:
            if source is None:
                continue
            for name in names:
                try:
                    value = source.get(name) if isinstance(source, dict) else getattr(source, name, None)
                except Exception:
                    value = None
                if value not in (None, ""):
                    return value, name
        return None, None

    def _sports_live_state_bool(self, value):
        if isinstance(value, bool):
            return value
        text = str(value or "").strip().lower()
        if text in {"1", "true", "yes", "y", "on", "live", "in_play", "inplay", "in-play"}:
            return True
        if text in {"0", "false", "no", "n", "off", "scheduled", "pregame", "not_started", "upcoming"}:
            return False
        return False

    def _sports_live_state_timestamp_from_keys(self, sources, keys):
        for source in sources:
            if source is None:
                continue
            for key in keys:
                try:
                    raw = source.get(key) if isinstance(source, dict) else getattr(source, key, None)
                except Exception:
                    raw = None
                ts = self._parse_market_timestamp(raw)
                if ts is not None:
                    return ts, key, raw
        return None, None, None

    def _sports_live_state_timestamp(self, sources):
        keys = (
            "event_start_time",
            "event_start_time_ts",
            "occurrence_datetime",
            "occurrence_datetime_ts",
            "start_time",
            "start_time_ts",
            "scheduled_start_time",
            "scheduled_start_time_ts",
            "game_start_time",
            "game_start_time_ts",
            "match_start_time",
            "match_start_time_ts",
        )
        return self._sports_live_state_timestamp_from_keys(sources, keys)

    def _sports_live_state_hard_start_timestamp(self, sources):
        keys = (
            "event_start_time",
            "event_start_time_ts",
            "start_time",
            "start_time_ts",
            "scheduled_start_time",
            "scheduled_start_time_ts",
            "game_start_time",
            "game_start_time_ts",
            "match_start_time",
            "match_start_time_ts",
        )
        return self._sports_live_state_timestamp_from_keys(sources, keys)

    def _sports_live_state_occurrence_timestamp(self, sources):
        keys = (
            "occurrence_datetime",
            "occurrence_datetime_ts",
            "expected_expiration_time",
            "expected_expiration_time_ts",
        )
        return self._sports_live_state_timestamp_from_keys(sources, keys)

    def _sports_live_state_has_scoreboard(self, sources):
        live_values = {"live", "in_play", "inplay", "in-play", "started", "in_progress", "running", "midgame", "halftime", "intermission", "between_periods", "top", "bottom"}
        non_live_values = {"scheduled", "pregame", "pre_game", "not_started", "not started", "upcoming", "preview", "created"}
        scoreboard_keys = (
            "scoreboard",
            "box_score",
            "game",
            "match",
            "live_context",
            "sports_live_context",
        )
        state_keys = (
            "live_state",
            "game_state",
            "game_status",
            "event_status",
            "match_status",
            "period",
            "current_period",
            "quarter",
            "inning",
            "current_inning",
            "half",
            "set",
            "current_set",
            "clock",
            "game_clock",
            "time_remaining",
        )
        for source in sources:
            if source is None:
                continue
            containers = [source]
            if isinstance(source, dict):
                for key in scoreboard_keys:
                    value = source.get(key)
                    if isinstance(value, dict):
                        containers.append(value)
            for container in containers:
                for key in state_keys:
                    try:
                        value = container.get(key) if isinstance(container, dict) else getattr(container, key, None)
                    except Exception:
                        value = None
                    if value in (None, ""):
                        continue
                    text = str(value).strip().lower()
                    if text in non_live_values:
                        continue
                    if key in {"clock", "game_clock", "time_remaining"} and text in {"0", "00:00", "0:00"}:
                        continue
                    if text in live_values or key not in {"event_status", "game_status", "match_status", "live_state", "game_state"}:
                        return True, key, value
        return False, None, None

    def _sports_live_state_has_executable_orderbook(self, sources, side=None):
        side = self._normalize_live_side(side)

        def _get(container, key):
            try:
                return container.get(key) if isinstance(container, dict) else getattr(container, key, None)
            except Exception:
                return None

        def _price(value):
            value = self.to_float(value, None)
            if value is None:
                return None
            if value > 1.0:
                value = value / 100.0
            if KALSHI_CONTRACT_MIN_PRICE <= value <= KALSHI_CONTRACT_MAX_PRICE:
                return value
            return None

        def _positive(value):
            value = self.to_float(value, None)
            return value is not None and value > 0.0

        def _containers(source):
            containers = [source]
            if isinstance(source, dict):
                for key in ("orderbook", "order_book", "top_book", "book", "quote", "quote_diag", "canonical_tradeability"):
                    value = source.get(key)
                    if isinstance(value, dict):
                        containers.append(value)
            return containers

        for source in sources:
            if source is None:
                continue
            for container in _containers(source):
                orderbook_ready = bool(
                    _get(container, "orderbook_ready")
                    or _get(container, "orderbook_exists")
                    or _get(container, "topbook_depth_exists")
                    or _get(container, "topbook_snapshot_present")
                    or _get(container, "normalized_orderbook_present")
                    or _get(container, "selected_side_has_liquidity")
                    or _get(container, "depth_available")
                )
                selected_price = _price(
                    _get(container, "selected_price_dollars")
                    if _get(container, "selected_price_dollars") is not None
                    else _get(container, "selected_price")
                    if _get(container, "selected_price") is not None
                    else _get(container, "selected_price_cents")
                )
                if orderbook_ready and selected_price is not None:
                    return True, "orderbook_ready", True

                yes_price = _price(_get(container, "yes_ask") if _get(container, "yes_ask") is not None else _get(container, "yes_price"))
                no_price = _price(_get(container, "no_ask") if _get(container, "no_ask") is not None else _get(container, "no_price"))
                yes_bid = _price(_get(container, "yes_bid"))
                no_bid = _price(_get(container, "no_bid"))
                yes_depth = any(_positive(_get(container, key)) for key in ("yes_top_size", "yes_ask_size", "yes_size", "liquidity", "liquidity_depth", "volume", "open_interest", "open_interest_fp"))
                no_depth = any(_positive(_get(container, key)) for key in ("no_top_size", "no_ask_size", "no_size", "liquidity", "liquidity_depth", "volume", "open_interest", "open_interest_fp"))
                if side == "yes" and yes_price is not None and (orderbook_ready or yes_depth or yes_bid is not None):
                    return True, "yes_executable_orderbook", yes_price
                if side == "no" and no_price is not None and (orderbook_ready or no_depth or no_bid is not None):
                    return True, "no_executable_orderbook", no_price
                if side not in {"yes", "no"} and (
                    (yes_price is not None and (orderbook_ready or yes_depth or yes_bid is not None))
                    or (no_price is not None and (orderbook_ready or no_depth or no_bid is not None))
                ):
                    return True, "executable_orderbook", selected_price or yes_price or no_price
        return False, None, None

    def _sports_live_state_has_visible_liquidity(self, sources):
        def _get(container, key):
            try:
                return container.get(key) if isinstance(container, dict) else getattr(container, key, None)
            except Exception:
                return None

        def _positive(value):
            value = self.to_float(value, None)
            return value is not None and value > 0.0

        def _containers(source):
            containers = [source]
            if isinstance(source, dict):
                for key in ("orderbook", "order_book", "top_book", "book", "quote", "quote_diag", "canonical_tradeability"):
                    value = source.get(key)
                    if isinstance(value, dict):
                        containers.append(value)
            return containers

        for source in sources or ():
            if source is None:
                continue
            for container in _containers(source):
                if bool(_get(container, "selected_side_has_liquidity")):
                    return True
                if bool(_get(container, "orderbook_ready") or _get(container, "orderbook_exists") or _get(container, "normalized_orderbook_present")):
                    return True
                for key in (
                    "volume",
                    "volume_24h",
                    "open_interest",
                    "open_interest_fp",
                    "liquidity",
                    "liquidity_depth",
                    "yes_top_size",
                    "no_top_size",
                    "yes_ask_size",
                    "no_ask_size",
                    "yes_size",
                    "no_size",
                ):
                    if _positive(_get(container, key)):
                        return True
        return False

    def _sports_live_state_visible_tradable_signal(
        self,
        status_text=None,
        executable_book=False,
        market=None,
        sources=None,
        ticker_future_start=False,
    ):
        status_text = str(status_text or "").strip().lower()
        active_status = status_text in {
            "active",
            "open",
            "trading",
            "available",
            "accepting_orders",
            "accepting orders",
        }
        if ticker_future_start or not active_status or not executable_book:
            return False
        market = market if isinstance(market, dict) else {}
        if market:
            if bool(market.get("disabled") or market.get("is_disabled")):
                return False
            if bool(market.get("closed") or market.get("is_closed") or market.get("settled")):
                return False
        if not self._sports_live_state_has_visible_liquidity(sources or ([market] if market else [])):
            return False
        return True

    def _emit_sports_live_state_guard_log(self, tag, payload):
        try:
            print(f"[{tag}] " + json.dumps(payload if isinstance(payload, dict) else {}, sort_keys=True, default=str))
        except Exception:
            pass

    def _aion_ticker_embedded_start_timestamp(self, ticker):
        ticker_text = str(ticker or "").strip().upper()
        if not ticker_text:
            return None, None, None
        match = re.search(r"-(\d{2})(JAN|FEB|MAR|APR|MAY|JUN|JUL|AUG|SEP|OCT|NOV|DEC)(\d{2})(\d{4})?", ticker_text)
        if not match:
            return None, None, None
        month_map = {
            "JAN": 1,
            "FEB": 2,
            "MAR": 3,
            "APR": 4,
            "MAY": 5,
            "JUN": 6,
            "JUL": 7,
            "AUG": 8,
            "SEP": 9,
            "OCT": 10,
            "NOV": 11,
            "DEC": 12,
        }
        year = 2000 + int(match.group(1))
        month = month_map.get(match.group(2))
        day = int(match.group(3))
        hhmm = match.group(4)
        hour = 0
        minute = 0
        source_key = "ticker_date"
        if hhmm and len(hhmm) == 4:
            hour = int(hhmm[:2])
            minute = int(hhmm[2:])
            source_key = "ticker_datetime"
        try:
            dt = datetime(year, month, day, hour, minute, tzinfo=timezone.utc)
        except Exception:
            return None, None, None
        return dt.timestamp(), source_key, match.group(0).lstrip("-")

    def evaluate_sports_live_state_pre_submit_guard(self, payload, q=None, *, source="pre_submit", refresh=True):
        payload = payload if isinstance(payload, dict) else {}
        ticker = str(payload.get("ticker") or self._read_field(q, "ticker", default="") or "").strip()
        family = str(payload.get("family") or self._read_field(q, "family", "series_ticker", default="") or "").strip().upper()
        if not family and ticker:
            family = str(self.get_market_family({"ticker": ticker}) or "").strip().upper()
        side = self._normalize_live_side(payload.get("side") or payload.get("selected_side") or self._read_field(q, "selected_side", "side", default=None))
        action = str(payload.get("action") or "buy").strip().lower()
        reduce_only = bool(payload.get("reduce_only"))
        is_buy = action in {"", "buy"} and not reduce_only
        is_sports = bool(self.is_sports_family(family, ticker=ticker))
        if not is_sports or not is_buy:
            return {
                "ok": True,
                "reason": "not_sports_buy",
                "skipped": True,
                "ticker": ticker,
                "family": family,
                "side": side,
                "source": source,
            }

        metadata = []
        for candidate in (
            payload,
            payload.get("market") if isinstance(payload.get("market"), dict) else None,
            payload.get("entry_context") if isinstance(payload.get("entry_context"), dict) else None,
            q,
        ):
            if candidate is not None:
                metadata.append(candidate)
        detail = {}
        detail_reason = None
        if refresh and ticker:
            try:
                detail = self.get_live_market_detail(ticker)
                if isinstance(detail, dict) and detail:
                    metadata.insert(0, detail)
                else:
                    detail_reason = "market_detail_empty"
            except Exception as exc:
                detail_reason = f"market_detail_{exc.__class__.__name__}"

        now_ts = time.time()
        metadata_start_ts, metadata_start_key, metadata_start_raw = self._sports_live_state_hard_start_timestamp(metadata)
        occurrence_ts, occurrence_key, occurrence_raw = self._sports_live_state_occurrence_timestamp(metadata)
        start_ts, start_key, start_raw = metadata_start_ts, metadata_start_key, metadata_start_raw
        if start_ts is None:
            start_ts, start_key, start_raw = self._aion_ticker_embedded_start_timestamp(ticker)
        status_value, status_key = self._sports_live_state_field(metadata, "status", "market_status", "event_status", "game_status", "match_status", "live_state", "game_state")
        status_text = str(status_value or "").strip().lower()
        explicit_live_value, explicit_live_key = self._sports_live_state_field(metadata, "in_play", "inplay", "is_in_play", "is_live", "live", "currently_live", "is_currently_live")
        explicit_live = self._sports_live_state_bool(explicit_live_value)
        scoreboard_live, scoreboard_key, scoreboard_value = self._sports_live_state_has_scoreboard(metadata)
        executable_book, executable_book_key, executable_book_value = self._sports_live_state_has_executable_orderbook(metadata, side=side)
        closed_statuses = {"closed", "settled", "finalized", "expired", "halted", "cancelled", "canceled", "resolved"}
        pregame_statuses = {"scheduled", "pregame", "pre_game", "not_started", "not started", "upcoming", "preview"}
        live_statuses = {"live", "in_play", "inplay", "in-play", "in_progress", "running", "started", "midgame", "halftime", "intermission", "between_periods"}

        seconds_to_start = float(start_ts - now_ts) if start_ts is not None else None
        seconds_to_occurrence = float(occurrence_ts - now_ts) if occurrence_ts is not None else None
        metadata_future_start = bool(metadata_start_ts is not None and metadata_start_ts > now_ts + 30.0)
        future_occurrence_hint = bool(occurrence_ts is not None and occurrence_ts > now_ts + 30.0)
        exact_ticker_future_start = bool(start_key == "ticker_datetime" and start_ts is not None and start_ts > now_ts + 30.0)
        ambiguous_ticker_date_future = bool(start_key == "ticker_date" and start_ts is not None and start_ts > now_ts + 30.0)
        ambiguous_ticker_date_live_evidence = bool(
            ambiguous_ticker_date_future
            and executable_book
            and seconds_to_start is not None
            and seconds_to_start <= max(0, AION_TICKER_DATE_LIVE_AMBIGUITY_SECONDS)
            and status_text not in pregame_statuses
        )
        strong_live_signal = bool(explicit_live or status_text in live_statuses or scoreboard_live)
        visible_tradable_signal = bool(
            self._sports_live_state_visible_tradable_signal(
                status_text=status_text,
                executable_book=executable_book,
                market=metadata[0] if metadata and isinstance(metadata[0], dict) else None,
                sources=metadata,
                ticker_future_start=bool(ambiguous_ticker_date_future or exact_ticker_future_start),
            )
        )

        reason = "unknown_sports_live_state"
        ok = False
        live_state = "unknown"
        if status_text in closed_statuses:
            reason = "sports_market_closed"
            live_state = "closed"
        elif explicit_live:
            ok = True
            reason = "explicit_live_flag"
            live_state = "live"
        elif status_text in live_statuses:
            ok = True
            reason = "live_status"
            live_state = "live"
        elif scoreboard_live:
            ok = True
            reason = "scoreboard_live_state"
            live_state = "live"
        elif metadata_future_start or exact_ticker_future_start or (ambiguous_ticker_date_future and not ambiguous_ticker_date_live_evidence):
            reason = "future_start_time"
            live_state = "future"
        elif status_text in pregame_statuses:
            reason = "pregame_status"
            live_state = "pregame"
        elif start_ts is not None and start_ts <= now_ts + 30.0 and start_key != "ticker_date":
            ok = True
            reason = "start_time_elapsed"
            live_state = "started"
        elif future_occurrence_hint and visible_tradable_signal:
            ok = True
            reason = "active_executable_market_occurrence_hint"
            live_state = "live_evidence"
        elif future_occurrence_hint and not strong_live_signal:
            reason = "future_occurrence_no_live_evidence"
            live_state = "future"
        elif executable_book:
            ok = True
            reason = "fresh_executable_orderbook_ambiguous_ticker_date" if ambiguous_ticker_date_live_evidence else "fresh_executable_orderbook_no_future_start"
            live_state = "live_evidence"

        selected_price = payload.get("selected_price")
        if selected_price is None:
            price_key = "yes_price" if side == "yes" else "no_price" if side == "no" else None
            selected_price = payload.get(price_key) if price_key else None
        live_only_block_reasons = {
            "future_start_time",
            "pregame_status",
            "future_occurrence_no_live_evidence",
            "unknown_sports_live_state",
        }
        live_state_classification_ok = bool(ok)
        live_only_bypassed = bool(not ok and reason in live_only_block_reasons)
        guard_ok = bool(ok or live_only_bypassed)
        payload_log = {
            "ticker": ticker or None,
            "family": family or None,
            "side": side,
            "selected_price": selected_price,
            "ok": bool(guard_ok),
            "live_state_classification_ok": bool(live_state_classification_ok),
            "live_only_bypassed": bool(live_only_bypassed),
            "reason": reason,
            "source": source,
            "live_state": live_state,
            "start_key": start_key,
            "start_time": datetime.fromtimestamp(start_ts, tz=timezone.utc).isoformat().replace("+00:00", "Z") if start_ts is not None else None,
            "seconds_to_start": round(float(start_ts - now_ts), 3) if start_ts is not None else None,
            "occurrence_key": occurrence_key,
            "occurrence_time": datetime.fromtimestamp(occurrence_ts, tz=timezone.utc).isoformat().replace("+00:00", "Z") if occurrence_ts is not None else None,
            "seconds_to_occurrence": round(float(seconds_to_occurrence), 3) if seconds_to_occurrence is not None else None,
            "status_key": status_key,
            "status": status_value,
            "explicit_live_key": explicit_live_key,
            "explicit_live_value": explicit_live_value,
            "scoreboard_key": scoreboard_key,
            "scoreboard_value": scoreboard_value,
            "executable_book": bool(executable_book),
            "executable_book_key": executable_book_key,
            "executable_book_value": executable_book_value,
            "visible_tradable_signal": bool(visible_tradable_signal),
            "detail_reason": detail_reason,
            "metadata_sources": len(metadata),
        }
        if future_occurrence_hint and visible_tradable_signal and not strong_live_signal:
            self._emit_sports_live_state_guard_log(
                "AION-ADMISSION-RELAXED",
                {
                    **payload_log,
                    "old_reason": "future_occurrence_no_live_evidence",
                    "relaxation": "active_executable_market_occurrence_hint",
                    "reason": "tradable_visible_sports_market",
                },
            )
        if future_occurrence_hint and strong_live_signal:
            self._emit_sports_live_state_guard_log(
                "AION-LIVE-MARKET-MISMATCH",
                {
                    **payload_log,
                    "mismatch": "future_occurrence_datetime_with_live_signal",
                    "fix": "live_signal_overrides_occurrence_resolution_hint",
                },
            )
        self._emit_sports_live_state_guard_log(
            "AION-LIVE-CLASSIFICATION",
            {
                **payload_log,
                "classification_rule": "hard_start_fields_block_future;occurrence_datetime_is_resolution_hint",
            },
        )
        self._emit_sports_live_state_guard_log(
            "AION-ADMISSION-AUDIT",
            {
                **payload_log,
                "stage": "pre_submit_live_state_guard",
                "decision": "ALLOW" if guard_ok else "BLOCK",
            },
        )
        if not guard_ok:
            self._emit_sports_live_state_guard_log(
                "AION-ADMISSION-BLOCK",
                {
                    **payload_log,
                    "stage": "pre_submit_live_state_guard",
                    "block_reason": reason,
                },
            )
        elif live_only_bypassed:
            self._emit_sports_live_state_guard_log(
                "AION-ADMISSION-RELAXED",
                {
                    **payload_log,
                    "stage": "pre_submit_live_state_guard",
                    "relaxation": "live_only_sports_requirement_removed",
                    "block_reason": None,
                },
            )
        self._emit_sports_live_state_guard_log("AION-SPORTS-LIVE-STATE-CHECK", payload_log)
        self._emit_sports_live_state_guard_log("AION-LIVE-SPORTS-ALLOW" if guard_ok else "AION-LIVE-GUARD-BLOCK", payload_log)
        self._emit_sports_live_state_guard_log("AION-LIVE-GUARD-ALLOW" if guard_ok else "AION-LIVE-GUARD-BLOCK", payload_log)
        return {
            **payload_log,
            "ok": bool(guard_ok),
            "reason": "sports_live_state_ok" if live_state_classification_ok else ("sports_live_requirement_disabled" if guard_ok else "sports_market_not_executable"),
            "classification_reason": reason,
            "block_reason": None if guard_ok else reason,
            "start_time_raw": start_raw,
            "occurrence_time_raw": occurrence_raw,
        }

    def _aion_live_discovery_state(self, market=None, q=None, side=None):
        market = market if isinstance(market, dict) else {}
        metadata = [source for source in (market, q) if source is not None]
        now_ts = time.time()
        metadata_start_ts, metadata_start_key, metadata_start_raw = self._sports_live_state_hard_start_timestamp(metadata)
        occurrence_ts, occurrence_key, occurrence_raw = self._sports_live_state_occurrence_timestamp(metadata)
        start_ts, start_key, start_raw = metadata_start_ts, metadata_start_key, metadata_start_raw
        ticker_value = str(market.get("ticker") or self._read_field(q, "ticker", default="") or "").strip()
        ticker_start_ts, ticker_start_key, ticker_start_raw = self._aion_ticker_embedded_start_timestamp(ticker_value)
        if start_ts is None:
            start_ts, start_key, start_raw = ticker_start_ts, ticker_start_key, ticker_start_raw
        status_value, status_key = self._sports_live_state_field(
            metadata,
            "status",
            "market_status",
            "event_status",
            "game_status",
            "match_status",
            "live_state",
            "game_state",
        )
        status_text = str(status_value or "").strip().lower()
        explicit_live_value, explicit_live_key = self._sports_live_state_field(
            metadata,
            "in_play",
            "inplay",
            "is_in_play",
            "is_live",
            "live",
            "currently_live",
            "is_currently_live",
        )
        explicit_live = self._sports_live_state_bool(explicit_live_value)
        scoreboard_live, scoreboard_key, scoreboard_value = self._sports_live_state_has_scoreboard(metadata)
        executable_book, executable_book_key, executable_book_value = self._sports_live_state_has_executable_orderbook(metadata, side=side)
        closed_statuses = {"closed", "settled", "finalized", "expired", "halted", "cancelled", "canceled", "resolved"}
        pregame_statuses = {"scheduled", "pregame", "pre_game", "not_started", "not started", "upcoming", "preview"}
        live_statuses = {"live", "in_play", "inplay", "in-play", "in_progress", "running", "started", "midgame", "halftime", "intermission", "between_periods"}
        seconds_to_start = float(start_ts - now_ts) if start_ts is not None else None
        seconds_to_occurrence = float(occurrence_ts - now_ts) if occurrence_ts is not None else None
        metadata_future_start = bool(metadata_start_ts is not None and metadata_start_ts > now_ts + 30.0)
        future_occurrence_hint = bool(occurrence_ts is not None and occurrence_ts > now_ts + 30.0)
        exact_ticker_future_start = bool(start_key == "ticker_datetime" and start_ts is not None and start_ts > now_ts + 30.0)
        ambiguous_ticker_date_future = bool(start_key == "ticker_date" and start_ts is not None and start_ts > now_ts + 30.0)
        ambiguous_ticker_date_live_evidence = bool(
            ambiguous_ticker_date_future
            and executable_book
            and seconds_to_start is not None
            and seconds_to_start <= max(0, AION_TICKER_DATE_LIVE_AMBIGUITY_SECONDS)
            and status_text not in pregame_statuses
        )
        strong_live_signal = bool(explicit_live or status_text in live_statuses or scoreboard_live)
        visible_tradable_signal = bool(
            self._sports_live_state_visible_tradable_signal(
                status_text=status_text,
                executable_book=executable_book,
                market=market,
                sources=metadata,
                ticker_future_start=bool(ambiguous_ticker_date_future or exact_ticker_future_start),
            )
        )

        reason = "unknown_sports_live_state"
        live_state = "unknown"
        admit = False
        priority = 0
        terminal_drop = False
        if status_text in closed_statuses:
            reason = "sports_market_closed"
            live_state = "closed"
            terminal_drop = True
        elif explicit_live:
            reason = "explicit_live_flag"
            live_state = "live"
            admit = True
            priority = 90
        elif status_text in live_statuses:
            reason = "live_status"
            live_state = "live"
            admit = True
            priority = 85
        elif scoreboard_live:
            reason = "scoreboard_live_state"
            live_state = "live"
            admit = True
            priority = 80
        elif metadata_future_start or exact_ticker_future_start:
            reason = "future_start_time"
            live_state = "future"
            admit = True
            priority = 45
        elif (
            ticker_start_ts is not None
            and ticker_start_ts > now_ts + 30.0
            and status_text not in live_statuses
            and not explicit_live
            and not scoreboard_live
            and not ambiguous_ticker_date_live_evidence
        ):
            reason = "future_start_time"
            live_state = "future"
            admit = True
            priority = 45
        elif start_ts is not None and start_ts > now_ts + 30.0 and not ambiguous_ticker_date_live_evidence:
            reason = "future_start_time"
            live_state = "future"
            admit = True
            priority = 45
        elif status_text in pregame_statuses and not explicit_live and not scoreboard_live:
            reason = "pregame_status"
            live_state = "pregame"
            admit = True
            priority = 45
        elif start_ts is not None and start_ts <= now_ts + 30.0 and start_key != "ticker_date":
            reason = "start_time_elapsed"
            live_state = "started"
            admit = True
            priority = 70
        elif future_occurrence_hint and visible_tradable_signal:
            reason = "active_executable_market_occurrence_hint"
            live_state = "live_evidence"
            admit = True
            priority = 62
        elif future_occurrence_hint and not strong_live_signal:
            reason = "future_occurrence_no_live_evidence"
            live_state = "future"
            admit = True
            priority = 45
        elif executable_book:
            reason = "fresh_executable_orderbook_ambiguous_ticker_date" if ambiguous_ticker_date_live_evidence else "fresh_executable_orderbook_no_future_start"
            live_state = "live_evidence"
            admit = True
            priority = 60 if ambiguous_ticker_date_live_evidence else 55
        else:
            reason = "unknown_sports_live_state"
            live_state = "unknown"
            admit = True
            priority = 40

        return {
            "admit": bool(admit),
            "terminal_drop": bool(terminal_drop),
            "reason": reason,
            "live_state": live_state,
            "priority": int(priority),
            "start_key": start_key,
            "start_time": datetime.fromtimestamp(start_ts, tz=timezone.utc).isoformat().replace("+00:00", "Z") if start_ts is not None else None,
            "seconds_to_start": round(float(start_ts - now_ts), 3) if start_ts is not None else None,
            "start_time_raw": start_raw,
            "occurrence_key": occurrence_key,
            "occurrence_time": datetime.fromtimestamp(occurrence_ts, tz=timezone.utc).isoformat().replace("+00:00", "Z") if occurrence_ts is not None else None,
            "seconds_to_occurrence": round(float(seconds_to_occurrence), 3) if seconds_to_occurrence is not None else None,
            "occurrence_time_raw": occurrence_raw,
            "status_key": status_key,
            "status": status_value,
            "explicit_live_key": explicit_live_key,
            "explicit_live_value": explicit_live_value,
            "scoreboard_key": scoreboard_key,
            "scoreboard_value": scoreboard_value,
            "executable_book": bool(executable_book),
            "executable_book_key": executable_book_key,
            "executable_book_value": executable_book_value,
            "visible_tradable_signal": bool(visible_tradable_signal),
        }

    def _aion_sports_only_live_selector_admission(self, market=None, *, selection_merge_source=None):
        source = str(selection_merge_source or "").strip()
        if not self._sports_only_mode_enabled() or source not in {"provided_markets", "sports_only_live_discovery_selector"}:
            return False, {"reason": "selector_live_admission_not_applicable"}
        try:
            state = self._aion_live_discovery_state(market=market)
        except Exception as exc:
            return False, {"reason": f"selector_live_admission_exception:{exc.__class__.__name__}"}
        return bool(state.get("admit")), state

    def _aion_market_liquidity_rank_value(self, market):
        market = market if isinstance(market, dict) else {}
        total = 0.0
        for key in (
            "volume",
            "volume_24h",
            "open_interest",
            "open_interest_fp",
            "liquidity",
            "liquidity_depth",
            "yes_top_size",
            "no_top_size",
            "yes_ask_size",
            "no_ask_size",
        ):
            value = self.to_float(market.get(key), None)
            if value is not None and value > 0.0:
                total += float(value)
        return total

    def _dedupe_markets_by_ticker(self, markets):
        deduped = []
        seen = set()
        for market in markets or []:
            if not isinstance(market, dict):
                continue
            ticker = str(market.get("ticker") or "").strip()
            if not ticker:
                continue
            if ticker in seen:
                continue
            seen.add(ticker)
            deduped.append(market)
        return deduped

    def _emit_aion_live_discovery_summary(self, tag, payload):
        try:
            print(f"[{tag}] " + json.dumps(payload if isinstance(payload, dict) else {}, sort_keys=True, default=str))
        except Exception:
            pass

    def _filter_live_sports_discovery_markets(self, markets, *, source="live_discovery", limit=None):
        markets = self._dedupe_markets_by_ticker(markets)
        limit = int(limit or AION_LIVE_DISCOVERY_CANDIDATE_LIMIT or 96)
        if not self._sports_only_mode_enabled():
            return markets, {
                "source": source,
                "input_count": len(markets),
                "admitted_count": len(markets),
                "sports_only_mode": False,
            }

        admitted_entries = []
        dropped_future = []
        dropped_unknown = []
        reason_counts = Counter()
        family_counts = Counter()
        admitted_family_counts = Counter()
        ambiguous_hydration_attempts = 0
        ambiguous_hydration_success = 0
        ambiguous_hydration_failures = Counter()
        active_hydration_attempts = 0
        active_hydration_success = 0
        active_hydration_failures = Counter()
        classification_examples = []
        mismatch_examples = []
        classification_fix_examples = []
        relaxed_examples = []
        block_examples = []
        terminal_future_or_pregame_drops = 0

        def _should_hydrate_ambiguous_date_market(state):
            if not isinstance(state, dict):
                return False
            if state.get("reason") != "future_start_time" or state.get("start_key") != "ticker_date":
                return False
            seconds_to_start = self.to_float(state.get("seconds_to_start"), None)
            return bool(
                seconds_to_start is not None
                and seconds_to_start > 30.0
                and seconds_to_start <= max(0, AION_TICKER_DATE_LIVE_AMBIGUITY_SECONDS)
            )

        def _should_hydrate_active_occurrence_market(state, market):
            if not isinstance(state, dict) or not isinstance(market, dict):
                return False
            if state.get("reason") != "future_occurrence_no_live_evidence":
                return False
            if bool(state.get("executable_book")):
                return False
            status_text = str(market.get("status") or market.get("market_status") or "").strip().lower()
            if status_text not in {"active", "open", "trading", "available", "accepting_orders", "accepting orders"}:
                return False
            seconds_to_start = self.to_float(state.get("seconds_to_start"), None)
            if state.get("start_key") == "ticker_date" and seconds_to_start is not None and seconds_to_start > 30.0:
                return False
            return True

        def _hydrate_ambiguous_live_discovery_market(market, family):
            hydrated_market = dict(market or {})
            ticker = str(hydrated_market.get("ticker") or "").strip()
            if not ticker:
                return hydrated_market, "missing_ticker"
            detail_reason = "not_attempted"
            orderbook_reason = "not_attempted"
            try:
                detail = self.get_live_market_detail(ticker)
                if isinstance(detail, dict) and detail:
                    for key, value in detail.items():
                        if value not in (None, "", [], {}):
                            hydrated_market[key] = value
                    detail_reason = "market_detail_merged"
                else:
                    detail_reason = "market_detail_empty"
            except Exception as exc:
                detail_reason = f"market_detail_{exc.__class__.__name__}"
            try:
                orderbook_payload = self.get_live_market_orderbook(ticker)
                if isinstance(orderbook_payload, dict) and orderbook_payload:
                    orderbook_source = self._aion_coerce_orderbook_endpoint_source(
                        orderbook_payload,
                        ticker=ticker,
                        family=family,
                    )
                    if isinstance(orderbook_source, dict) and orderbook_source:
                        for key, value in orderbook_source.items():
                            if value not in (None, "", [], {}):
                                hydrated_market[key] = value
                        hydrated_market["orderbook_ready"] = bool(orderbook_source.get("normalized_orderbook_present") or orderbook_source.get("orderbook_exists"))
                        orderbook_reason = "orderbook_endpoint_merged"
                    else:
                        orderbook_reason = "orderbook_endpoint_empty_source"
                else:
                    orderbook_reason = "orderbook_endpoint_empty"
            except Exception as exc:
                orderbook_reason = f"orderbook_endpoint_{exc.__class__.__name__}"
            return hydrated_market, f"{detail_reason}+{orderbook_reason}"

        for market in markets:
            family = str(self.get_market_family(market) or "").strip().upper() or "UNKNOWN"
            ticker = str(market.get("ticker") or "").strip()
            family_counts[family] += 1
            if not self.is_sports_family(family, ticker=ticker):
                continue
            state = self._aion_live_discovery_state(market=market)
            if (
                not state.get("admit")
                and _should_hydrate_ambiguous_date_market(state)
                and ambiguous_hydration_attempts < max(0, AION_LIVE_DISCOVERY_AMBIGUOUS_HYDRATION_LIMIT)
            ):
                ambiguous_hydration_attempts += 1
                hydrated_market, hydration_reason = _hydrate_ambiguous_live_discovery_market(market, family)
                hydrated_state = self._aion_live_discovery_state(market=hydrated_market)
                if hydrated_state.get("admit"):
                    ambiguous_hydration_success += 1
                    market = hydrated_market
                    state = hydrated_state
                    state["reason"] = state.get("reason") or "ambiguous_date_hydrated_live"
                    state["hydration_reason"] = hydration_reason
                    try:
                        print(
                            "[AION-LIVE-MARKET-ADMITTED] "
                            + json.dumps(
                                {
                                    "source": source,
                                    "ticker": ticker or None,
                                    "family": family,
                                    "reason": state.get("reason"),
                                    "live_state": state.get("live_state"),
                                    "hydration_reason": hydration_reason,
                                    "start_key": state.get("start_key"),
                                    "seconds_to_start": state.get("seconds_to_start"),
                                },
                                sort_keys=True,
                                default=str,
                            )
                        )
                    except Exception:
                        pass
                else:
                    ambiguous_hydration_failures[hydrated_state.get("reason") or hydration_reason or "unknown"] += 1
            if (
                not state.get("admit")
                and _should_hydrate_active_occurrence_market(state, market)
                and active_hydration_attempts < max(0, AION_LIVE_DISCOVERY_AMBIGUOUS_HYDRATION_LIMIT)
            ):
                active_hydration_attempts += 1
                hydrated_market, hydration_reason = _hydrate_ambiguous_live_discovery_market(market, family)
                hydrated_state = self._aion_live_discovery_state(market=hydrated_market)
                if hydrated_state.get("admit"):
                    active_hydration_success += 1
                    market = hydrated_market
                    state = hydrated_state
                    state["reason"] = state.get("reason") or "active_occurrence_hydrated_live"
                    state["hydration_reason"] = hydration_reason
                    self._emit_aion_live_discovery_summary(
                        "AION-ADMISSION-RELAXED",
                        {
                            "source": source,
                            "stage": "active_occurrence_hydration",
                            "ticker": ticker or None,
                            "family": family,
                            "old_reason": "future_occurrence_no_live_evidence",
                            "reason": state.get("reason"),
                            "hydration_reason": hydration_reason,
                            "live_state": state.get("live_state"),
                            "executable_book": bool(state.get("executable_book")),
                            "executable_book_key": state.get("executable_book_key"),
                            "selected_price_hint": state.get("executable_book_value"),
                        },
                    )
                else:
                    active_hydration_failures[hydrated_state.get("reason") or hydration_reason or "unknown"] += 1
            reason_counts[state.get("reason") or "unknown"] += 1
            if state.get("reason") == "active_executable_market_occurrence_hint":
                relaxed_example = {
                    "ticker": ticker or None,
                    "event_ticker": market.get("event_ticker"),
                    "family": family,
                    "old_reason": "future_occurrence_no_live_evidence",
                    "reason": state.get("reason"),
                    "status": market.get("status"),
                    "occurrence_key": state.get("occurrence_key"),
                    "occurrence_time": state.get("occurrence_time"),
                    "executable_book": bool(state.get("executable_book")),
                    "executable_book_key": state.get("executable_book_key"),
                    "selected_price_hint": state.get("executable_book_value"),
                }
                if len(relaxed_examples) < 12:
                    relaxed_examples.append(relaxed_example)
                self._emit_aion_live_discovery_summary(
                    "AION-ADMISSION-RELAXED",
                    {
                        "source": source,
                        "stage": "live_discovery",
                        **relaxed_example,
                    },
                )
            if len(classification_examples) < 10:
                classification_examples.append(
                    {
                        "ticker": ticker or None,
                        "event_ticker": market.get("event_ticker"),
                        "family": family,
                        "status": market.get("status"),
                        "event_status": market.get("event_status"),
                        "game_status": market.get("game_status"),
                        "in_play": market.get("in_play", market.get("is_in_play")),
                        "start_key": state.get("start_key"),
                        "start_time": state.get("start_time"),
                        "occurrence_key": state.get("occurrence_key"),
                        "occurrence_time": state.get("occurrence_time"),
                        "expected_expiration_time": market.get("expected_expiration_time"),
                        "close_time": market.get("close_time"),
                        "scoreboard_key": state.get("scoreboard_key"),
                        "scoreboard_value": state.get("scoreboard_value"),
                        "executable_book": bool(state.get("executable_book")),
                        "aion_classification": state.get("reason"),
                        "live_state": state.get("live_state"),
                    }
                )
            if state.get("occurrence_key") and state.get("reason") in {"explicit_live_flag", "live_status", "scoreboard_live_state"}:
                if len(classification_fix_examples) < 10:
                    classification_fix_examples.append(
                        {
                            "ticker": ticker or None,
                            "family": family,
                            "reason": state.get("reason"),
                            "occurrence_key": state.get("occurrence_key"),
                            "occurrence_time": state.get("occurrence_time"),
                            "fix": "occurrence_datetime_did_not_override_live_signal",
                        }
                    )
            if (
                state.get("occurrence_key")
                and state.get("reason") in {"future_occurrence_no_live_evidence", "future_start_time"}
                and bool(state.get("executable_book") or self._aion_market_liquidity_rank_value(market) > 0.0)
                and len(mismatch_examples) < 10
            ):
                mismatch_examples.append(
                    {
                        "ticker": ticker or None,
                        "event_ticker": market.get("event_ticker"),
                        "family": family,
                        "status": market.get("status"),
                        "app_visible_state": "active_open_odds_possible",
                        "aion_classification": state.get("reason"),
                        "correct_classification": state.get("reason"),
                        "mismatch_explanation": "active_orderbook_or_volume_without_scoreboard_or_in_play_flag_is_not_sufficient_for_live_only_sports_entry",
                        "start_key": state.get("start_key"),
                        "start_time": state.get("start_time"),
                        "occurrence_key": state.get("occurrence_key"),
                        "occurrence_time": state.get("occurrence_time"),
                        "expected_expiration_time": market.get("expected_expiration_time"),
                        "scoreboard_key": state.get("scoreboard_key"),
                        "scoreboard_value": state.get("scoreboard_value"),
                        "executable_book": bool(state.get("executable_book")),
                        "volume_fp": market.get("volume_fp"),
                        "open_interest_fp": market.get("open_interest_fp"),
                    }
                )
            if state.get("admit"):
                admitted_family_counts[family] += 1
                admitted_entries.append((state, market))
            elif state.get("terminal_drop"):
                if state.get("reason") in {"future_start_time", "future_occurrence_no_live_evidence", "pregame_status"}:
                    terminal_future_or_pregame_drops += 1
                if len(block_examples) < 12:
                    block_examples.append(
                        {
                            "ticker": ticker or None,
                            "family": family,
                            "reason": state.get("reason"),
                            "live_state": state.get("live_state"),
                            "status": market.get("status"),
                            "executable_book": bool(state.get("executable_book")),
                        }
                    )
                if len(dropped_future) < 12:
                    dropped_future.append(
                        {
                            "ticker": ticker or None,
                            "family": family,
                            "reason": state.get("reason"),
                            "live_state": state.get("live_state"),
                            "start_time": state.get("start_time"),
                            "seconds_to_start": state.get("seconds_to_start"),
                        }
                    )
            else:
                if len(dropped_unknown) < 12:
                    dropped_unknown.append(
                        {
                            "ticker": ticker or None,
                            "family": family,
                            "reason": state.get("reason"),
                            "live_state": state.get("live_state"),
                        }
                    )

        admitted_entries = sorted(
            admitted_entries,
            key=lambda item: (
                -int(item[0].get("priority") or 0),
                -float(self._aion_market_liquidity_rank_value(item[1]) or 0.0),
                abs(float(item[0].get("seconds_to_start") or 0.0)),
                str(item[1].get("ticker") or ""),
            ),
        )
        admitted = [market for _, market in admitted_entries[: max(0, limit)]]
        payload = {
            "source": source,
            "input_count": int(len(markets)),
            "admitted_count": int(len(admitted)),
            "dropped_future_or_pregame": int(terminal_future_or_pregame_drops),
            "admitted_future_or_pregame": int(
                sum(
                    1
                    for state, _market in admitted_entries
                    if state.get("reason") in {"future_start_time", "future_occurrence_no_live_evidence", "pregame_status"}
                )
            ),
            "dropped_unknown": int(reason_counts.get("unknown_sports_live_state", 0)),
            "reason_counts": dict(reason_counts),
            "families_scanned": dict(family_counts.most_common(20)),
            "admitted_families": dict(admitted_family_counts.most_common(20)),
            "admitted_examples": [
                {
                    "ticker": str(market.get("ticker") or "").strip() or None,
                    "family": str(self.get_market_family(market) or "").strip().upper() or "UNKNOWN",
                    "reason": state.get("reason"),
                    "live_state": state.get("live_state"),
                    "start_time": state.get("start_time"),
                    "seconds_to_start": state.get("seconds_to_start"),
                }
                for state, market in admitted_entries[:8]
            ],
            "future_examples": dropped_future,
            "unknown_examples": dropped_unknown,
            "candidate_limit": int(limit),
            "ambiguous_hydration_attempts": int(ambiguous_hydration_attempts),
            "ambiguous_hydration_success": int(ambiguous_hydration_success),
            "ambiguous_hydration_failures": dict(ambiguous_hydration_failures.most_common(10)),
            "active_hydration_attempts": int(active_hydration_attempts),
            "active_hydration_success": int(active_hydration_success),
            "active_hydration_failures": dict(active_hydration_failures.most_common(10)),
            "classification_examples": classification_examples,
            "admission_relaxed_count": int(reason_counts.get("active_executable_market_occurrence_hint", 0)),
            "relaxed_examples": relaxed_examples,
            "block_examples": block_examples,
        }
        self._emit_aion_live_discovery_summary(
            "AION-ADMISSION-AUDIT",
            {
                "source": source,
                "input_count": int(len(markets)),
                "admitted_count": int(len(admitted)),
                "admission_relaxed_count": int(payload["admission_relaxed_count"]),
                "active_hydration_attempts": int(active_hydration_attempts),
                "active_hydration_success": int(active_hydration_success),
                "active_hydration_failures": dict(active_hydration_failures.most_common(8)),
                "dropped_future_or_pregame": int(payload["dropped_future_or_pregame"]),
                "admitted_future_or_pregame": int(payload["admitted_future_or_pregame"]),
                "dropped_unknown": int(payload["dropped_unknown"]),
                "reason_counts": dict(reason_counts),
                "families_scanned": dict(family_counts.most_common(12)),
                "admitted_families": dict(admitted_family_counts.most_common(12)),
                "relaxed_examples": relaxed_examples[:5],
                "block_examples": block_examples[:5],
            },
        )
        if block_examples:
            self._emit_aion_live_discovery_summary(
                "AION-ADMISSION-BLOCK",
                {
                    "source": source,
                    "stage": "live_discovery",
                    "count": int(payload["dropped_future_or_pregame"] + payload["dropped_unknown"]),
                    "examples": block_examples[:8],
                },
            )
        self._emit_aion_live_discovery_summary("AION-LIVE-DISCOVERY-SCAN", payload)
        now_log_ts = time.time()
        last_classification_log_ts = self.to_float(getattr(self, "_aion_live_classification_log_last_ts", 0.0), 0.0) or 0.0
        if now_log_ts - last_classification_log_ts >= 60.0:
            self._aion_live_classification_log_last_ts = now_log_ts
            self._emit_aion_live_discovery_summary(
                "AION-LIVE-CLASSIFICATION",
                {
                    "source": source,
                    "rule": "hard_start_fields_block_future;occurrence_datetime_is_resolution_hint;live_signal_overrides_occurrence_hint",
                    "examples": classification_examples,
                    "reason_counts": dict(reason_counts),
                },
            )
            if mismatch_examples:
                self._emit_aion_live_discovery_summary(
                    "AION-LIVE-MARKET-MISMATCH",
                    {
                        "source": source,
                        "mismatch_type": "active_odds_without_live_state",
                        "examples": mismatch_examples,
                    },
                )
            if classification_fix_examples:
                self._emit_aion_live_discovery_summary(
                    "AION-LIVE-CLASSIFICATION-FIX",
                    {
                        "source": source,
                        "examples": classification_fix_examples,
                    },
                )
        if dropped_future:
            self._emit_aion_live_discovery_summary(
                "AION-FUTURE-MARKET-DROPPED-EARLY",
                {
                    "source": source,
                    "count": int(payload["dropped_future_or_pregame"]),
                    "examples": dropped_future[:8],
                },
            )
        if admitted:
            self._emit_aion_live_discovery_summary(
                "AION-LIVE-MARKET-ADMITTED",
                {
                    "source": source,
                    "count": int(len(admitted)),
                    "families": dict(admitted_family_counts.most_common(12)),
                    "examples": payload["admitted_examples"],
                },
            )
            self._emit_aion_live_discovery_summary(
                "AION-LIVE-PARTICIPATION-RESTORED",
                {
                    "source": source,
                    "admitted_count": int(len(admitted)),
                    "admission_relaxed_count": int(payload.get("admission_relaxed_count", 0) or 0),
                    "families": dict(admitted_family_counts.most_common(12)),
                    "reason_counts": dict(reason_counts),
                    "examples": payload["admitted_examples"][:5],
                },
            )
        return admitted, payload

    def fetch_live_sports_discovery_markets(self, *, root_markets=None, scan_depth=1):
        root_markets = list(root_markets or [])
        scan_depth = max(1, int(scan_depth or 1))
        max_pages = max(1, min(int(AION_LIVE_DISCOVERY_SCAN_PAGES or 8) + max(0, scan_depth - 1), 12))
        discovered = []
        seen = set()

        def add_markets(markets):
            added = 0
            for market in markets or []:
                if not isinstance(market, dict):
                    continue
                ticker = str(market.get("ticker") or "").strip()
                if not ticker or ticker in seen:
                    continue
                seen.add(ticker)
                discovered.append(market)
                added += 1
            return added

        add_markets(root_markets)
        focus_series = [
            "KXATPCHALLENGERMATCH",
            "KXATPMATCH",
            "KXTENNISMATCH",
            "KXITFMATCH",
            "KXITFWMATCH",
            "KXWTAMATCH",
            "KXATP",
            "KXWTA",
            "KXITF",
            "KXSQUASHMATCH",
        ]
        focus_fetched = {}
        for series_ticker in focus_series:
            try:
                series_markets = self.get_markets(
                    limit=min(60, LIVE_SELECT_BATCH_SIZE),
                    status="open",
                    extra_params={"series_ticker": series_ticker, "mve_filter": "exclude"},
                )
            except Exception as exc:
                focus_fetched[series_ticker] = f"error:{exc.__class__.__name__}"
                continue
            focus_fetched[series_ticker] = int(len(series_markets))
            add_markets(series_markets)

        cursor = None
        pages_fetched = 0
        for _page in range(max_pages):
            try:
                batch, cursor = self.fetch_market_batch(cursor=cursor)
            except Exception as exc:
                self._emit_aion_live_discovery_summary(
                    "AION-LIVE-DISCOVERY-MISS",
                    {
                        "source": "live_paginated_scan",
                        "reason": f"fetch_market_batch_{exc.__class__.__name__}",
                        "pages_fetched": int(pages_fetched),
                        "discovered_count": int(len(discovered)),
                        "focus_series_fetched": focus_fetched,
                    },
                )
                break
            pages_fetched += 1
            add_markets(batch)
            if not cursor:
                break

        sports_markets = self._filter_sports_only_markets(
            discovered,
            source="live_discovery_expanded_scan",
            force_log=False,
        )
        admitted, summary = self._filter_live_sports_discovery_markets(
            sports_markets,
            source="live_discovery_expanded_scan",
            limit=AION_LIVE_DISCOVERY_CANDIDATE_LIMIT,
        )
        root_live, root_summary = self._filter_live_sports_discovery_markets(
            root_markets,
            source="live_discovery_root_probe",
            limit=AION_LIVE_DISCOVERY_CANDIDATE_LIMIT,
        )
        if not root_live and admitted:
            self._emit_aion_live_discovery_summary(
                "AION-LIVE-DISCOVERY-MISS",
                {
                    "source": "run_once_root_discovery",
                    "reason": "root_page_missed_live_markets",
                    "root_sports_candidates": int(len(root_markets)),
                    "root_future_or_pregame": int(root_summary.get("dropped_future_or_pregame", 0) or 0),
                    "expanded_live_admitted": int(len(admitted)),
                    "expanded_admitted_families": summary.get("admitted_families"),
                },
            )
        self._emit_aion_live_discovery_summary(
            "AION-LIVE-DISCOVERY-SCAN",
            {
                "source": "live_discovery_fetch_summary",
                "root_count": int(len(root_markets)),
                "unique_discovered": int(len(discovered)),
                "sports_discovered": int(len(sports_markets)),
                "admitted_live": int(len(admitted)),
                "pages_fetched": int(pages_fetched),
                "max_pages": int(max_pages),
                "focus_series_first": True,
                "focus_series_fetched": focus_fetched,
                "families_scanned": summary.get("families_scanned"),
                "admitted_families": summary.get("admitted_families"),
            },
        )
        return admitted, {
            **summary,
            "root_summary": root_summary,
            "pages_fetched": pages_fetched,
            "focus_series_fetched": focus_fetched,
            "unique_discovered": len(discovered),
            "sports_discovered": len(sports_markets),
        }

    def _aion_funnel_terminal_buckets(self):
        return (
            "future_start_time_block",
            "no_quote",
            "no_side",
            "no_price",
            "low_edge",
            "low_ev",
            "low_confidence",
            "liquidity_block",
            "spread_block",
            "duplicate_guard",
            "exposure_cap",
            "risk_governor",
            "sizing_zero",
            "submit_attempt",
            "submit_success",
            "final_readiness_failed",
            "other",
        )

    def _aion_funnel_terminal_reason(self, reason):
        reason_text = str(reason or "").strip().lower()
        if not reason_text:
            return "other"
        if any(token in reason_text for token in ("missing_quote", "no_quote", "quote_missing", "no_quote_ready", "missing_prices_and_sizes", "quote_invalid", "quote_crossed_or_invalid")):
            return "no_quote"
        if any(token in reason_text for token in ("missing_side", "no_side", "selected_side_missing", "side_missing")):
            return "no_side"
        if any(token in reason_text for token in ("missing_price", "no_price", "invalid_selected_price", "selected_price_missing", "selected_price_below", "selected_price_above", "missing_selected_side_price", "selected_side_present_price_missing", "selected_price_present_not_executable")):
            return "no_price"
        if any(token in reason_text for token in ("edge_below", "edge_too_low", "low_edge", "weak_edge", "negative_edge", "nonpositive_edge", "no_positive_edge")):
            return "low_edge"
        if any(token in reason_text for token in ("low_ev", "negative_ev", "ev_below", "expectancy_below", "weak_expectancy", "no_positive_expectancy")):
            return "low_ev"
        if "confidence" in reason_text and any(token in reason_text for token in ("low", "weak", "below", "insufficient")):
            return "low_confidence"
        if any(token in reason_text for token in ("liquidity", "thin_market", "no_depth", "zero_yes_size", "zero_no_size", "no_liquidity")):
            return "liquidity_block"
        if any(token in reason_text for token in ("spread", "unsafe_price", "wide", "stale_orderbook")):
            return "spread_block"
        if any(token in reason_text for token in ("duplicate", "already_holding", "opposite_side")):
            return "duplicate_guard"
        if any(token in reason_text for token in ("exposure", "position_limit", "same_thesis", "account_pct_cap", "family_cap")):
            return "exposure_cap"
        if any(token in reason_text for token in ("daily_loss", "risk", "live_mode_disabled", "live_not_armed", "live_env", "dry_run", "auth_", "can_open_new_position")):
            return "risk_governor"
        if any(token in reason_text for token in ("sizing_zero", "size_zero", "count_zero", "zero_contract", "resolved_size_zero")):
            return "sizing_zero"
        if any(token in reason_text for token in ("final_readiness", "final_not_ready", "readiness_failed", "entry_ready_unsubmitted", "not_selected_by_ranker", "valid_quote_no_terminal_record", "quote_side_price_valid_no_terminal_record")):
            return "final_readiness_failed"
        return "other"

    def _aion_funnel_candidate_price(self, market=None, q=None, side=None):
        side = self._aion_normalize_live_side(side or self._read_field(q, "selected_side", "side", default=None) or self._read_field(market, "selected_side", "side", default=None))
        raw_price = self._read_field(q, "selected_price", "selected_price_dollars", default=None)
        if raw_price is None:
            raw_price = self._read_field(market, "selected_price", "selected_price_dollars", default=None)
        if raw_price is None and side == "yes":
            raw_price = self._read_field(q, "yes_ask", "yes_price", default=None)
            if raw_price is None:
                raw_price = self._read_field(market, "yes_ask", "yes_price", default=None)
        if raw_price is None and side == "no":
            raw_price = self._read_field(q, "no_ask", "no_price", default=None)
            if raw_price is None:
                raw_price = self._read_field(market, "no_ask", "no_price", default=None)
        price = self.to_float(raw_price, None)
        if price is None:
            cents = self._read_field(q, "selected_price_cents", default=None)
            if cents is None:
                cents = self._read_field(market, "selected_price_cents", default=None)
            price = self.to_float(cents, None)
        if price is None:
            return None
        if price > 1.0:
            price = price / 100.0
        if KALSHI_CONTRACT_MIN_PRICE <= price <= KALSHI_CONTRACT_MAX_PRICE:
            return price
        return None

    def _propagate_quote_hydration_selection(self, quote=None, market=None, quote_diag=None, *, source="quote_hydration"):
        if quote is None:
            return {}
        market = market if isinstance(market, dict) else {}
        quote_diag = quote_diag if isinstance(quote_diag, dict) else {}
        canonical = quote_diag.get("canonical_tradeability") if isinstance(quote_diag.get("canonical_tradeability"), dict) else {}
        ticker = str(getattr(quote, "ticker", None) or market.get("ticker") or quote_diag.get("ticker") or canonical.get("ticker") or "").strip()
        family = str(
            getattr(quote, "family", None)
            or market.get("family")
            or market.get("series_ticker")
            or quote_diag.get("family")
            or canonical.get("family")
            or self.get_market_family(market or {"ticker": ticker})
            or "UNKNOWN"
        ).strip().upper() or "UNKNOWN"

        def _price_value(*values):
            for value in values:
                if value in (None, "", [], {}):
                    continue
                parsed = self.to_float(value, None)
                if parsed is None:
                    continue
                if parsed > 1.0:
                    parsed = parsed / 100.0
                if KALSHI_CONTRACT_MIN_PRICE <= parsed <= KALSHI_CONTRACT_MAX_PRICE:
                    return round(float(parsed), 4)
            return None

        side = self._aion_normalize_live_side(
            getattr(quote, "selected_side", None)
            or getattr(quote, "side", None)
            or quote_diag.get("selected_side")
            or quote_diag.get("side")
            or canonical.get("selected_side")
            or canonical.get("side")
            or canonical.get("executable_side")
            or canonical.get("chosen_side")
        )
        price = _price_value(
            getattr(quote, "selected_price", None),
            getattr(quote, "selected_price_dollars", None),
            quote_diag.get("selected_price_dollars"),
            quote_diag.get("selected_price"),
            quote_diag.get("selected_price_cents"),
            canonical.get("selected_price_dollars"),
            canonical.get("selected_price"),
            canonical.get("selected_price_cents"),
            canonical.get("chosen_price_dollars"),
            canonical.get("chosen_price"),
            canonical.get("chosen_price_cents"),
        )
        resolution = {}
        if ticker and (side not in {"yes", "no"} or price is None):
            try:
                resolution = self.resolve_aion_orderbook_for_payload(
                    ticker,
                    candidate=quote,
                    market=market,
                    quote_diag=quote_diag,
                    price_source="ask",
                    selected_side=side,
                    selection_stage=f"{source}_selection_propagation",
                    allow_refresh=False,
                ) or {}
            except Exception:
                resolution = {}
        if side not in {"yes", "no"} and resolution:
            side = self._aion_normalize_live_side(
                resolution.get("chosen_side")
                or resolution.get("selected_side")
                or resolution.get("side")
            )
        if price is None and resolution:
            price = _price_value(
                resolution.get("chosen_price_dollars"),
                resolution.get("chosen_price"),
                resolution.get("chosen_price_cents"),
                resolution.get("selected_price_dollars"),
                resolution.get("selected_price"),
                resolution.get("selected_price_cents"),
            )
        if side not in {"yes", "no"} or price is None:
            return {
                "ticker": ticker or None,
                "family": family,
                "selected_side": side or None,
                "selected_price": price,
                "applied": False,
                "reason": "selection_unresolved",
            }

        price_cents = int(round(float(price) * 100.0))
        for attr_name, attr_value in (
            ("selected_side", side),
            ("side", side),
            ("selected_price", price),
            ("selected_price_dollars", price),
            ("selected_price_cents", price_cents),
        ):
            try:
                setattr(quote, attr_name, attr_value)
            except Exception:
                pass
        for key, value in (
            ("selected_side", side),
            ("side", side),
            ("selected_price", price),
            ("selected_price_dollars", price),
            ("selected_price_cents", price_cents),
        ):
            quote_diag[key] = value
            if isinstance(market, dict) and market.get(key) in (None, "", 0, 0.0):
                market[key] = value
        if isinstance(market, dict):
            market.setdefault("family", family)
        return {
            "ticker": ticker or None,
            "family": family,
            "selected_side": side,
            "selected_price": price,
            "selected_price_cents": price_cents,
            "applied": True,
            "reason": "canonical_selection_propagated",
        }

    def _aion_funnel_future_or_pregame_reason(self, market=None, q=None):
        metadata = [source for source in (market, q) if source is not None]
        now_ts = time.time()
        metadata_start_ts, metadata_start_key, metadata_start_raw = self._sports_live_state_hard_start_timestamp(metadata)
        occurrence_ts, occurrence_key, occurrence_raw = self._sports_live_state_occurrence_timestamp(metadata)
        start_ts, start_key, start_raw = metadata_start_ts, metadata_start_key, metadata_start_raw
        if start_ts is None:
            ticker_value = str(self._read_field(market, "ticker", default="") or self._read_field(q, "ticker", default="") or "").strip()
            start_ts, start_key, start_raw = self._aion_ticker_embedded_start_timestamp(ticker_value)
        status_value, status_key = self._sports_live_state_field(
            metadata,
            "status",
            "market_status",
            "event_status",
            "game_status",
            "match_status",
            "live_state",
            "game_state",
        )
        status_text = str(status_value or "").strip().lower()
        explicit_live_value, explicit_live_key = self._sports_live_state_field(metadata, "in_play", "inplay", "is_in_play", "is_live", "live", "currently_live", "is_currently_live")
        scoreboard_live, scoreboard_key, scoreboard_value = self._sports_live_state_has_scoreboard(metadata)
        executable_book, executable_book_key, executable_book_value = self._sports_live_state_has_executable_orderbook(metadata)
        pregame_statuses = {"scheduled", "pregame", "pre_game", "not_started", "not started", "upcoming", "preview"}
        seconds_to_start = float(start_ts - now_ts) if start_ts is not None else None
        seconds_to_occurrence = float(occurrence_ts - now_ts) if occurrence_ts is not None else None
        metadata_future_start = bool(metadata_start_ts is not None and metadata_start_ts > now_ts + 30.0)
        future_occurrence_hint = bool(occurrence_ts is not None and occurrence_ts > now_ts + 30.0)
        exact_ticker_future_start = bool(start_key == "ticker_datetime" and start_ts is not None and start_ts > now_ts + 30.0)
        ambiguous_ticker_date_future = bool(start_key == "ticker_date" and start_ts is not None and start_ts > now_ts + 30.0)
        ambiguous_ticker_date_live_evidence = bool(
            ambiguous_ticker_date_future
            and executable_book
            and seconds_to_start is not None
            and seconds_to_start <= max(0, AION_TICKER_DATE_LIVE_AMBIGUITY_SECONDS)
            and status_text not in pregame_statuses
        )
        strong_live_signal = bool(self._sports_live_state_bool(explicit_live_value) or status_text in {"live", "in_play", "inplay", "in-play", "in_progress", "running", "started", "midgame", "halftime", "intermission", "between_periods"} or scoreboard_live)
        visible_tradable_signal = bool(
            self._sports_live_state_visible_tradable_signal(
                status_text=status_text,
                executable_book=executable_book,
                market=market,
                sources=metadata,
                ticker_future_start=bool(ambiguous_ticker_date_future or exact_ticker_future_start),
            )
        )
        if (metadata_future_start or exact_ticker_future_start or (start_ts is not None and start_ts > now_ts + 30.0 and not ambiguous_ticker_date_live_evidence)):
            return {
                "reason": "future_start_time",
                "start_key": start_key,
                "start_time": datetime.fromtimestamp(start_ts, tz=timezone.utc).isoformat().replace("+00:00", "Z"),
                "seconds_to_start": round(float(start_ts - now_ts), 3),
                "start_time_raw": start_raw,
                "occurrence_key": occurrence_key,
                "occurrence_time": datetime.fromtimestamp(occurrence_ts, tz=timezone.utc).isoformat().replace("+00:00", "Z") if occurrence_ts is not None else None,
                "seconds_to_occurrence": round(float(seconds_to_occurrence), 3) if seconds_to_occurrence is not None else None,
                "occurrence_time_raw": occurrence_raw,
                "executable_book": bool(executable_book),
                "executable_book_key": executable_book_key,
                "executable_book_value": executable_book_value,
            }
        if strong_live_signal or (start_ts is not None and start_ts <= now_ts + 30.0 and not start_key == "ticker_date"):
            return None
        if future_occurrence_hint and visible_tradable_signal:
            return None
        if future_occurrence_hint and not strong_live_signal:
            return {
                "reason": "future_occurrence_no_live_evidence",
                "occurrence_key": occurrence_key,
                "occurrence_time": datetime.fromtimestamp(occurrence_ts, tz=timezone.utc).isoformat().replace("+00:00", "Z"),
                "seconds_to_occurrence": round(float(seconds_to_occurrence), 3),
                "occurrence_time_raw": occurrence_raw,
                "start_key": start_key,
                "start_time": datetime.fromtimestamp(start_ts, tz=timezone.utc).isoformat().replace("+00:00", "Z") if start_ts is not None else None,
                "seconds_to_start": round(float(seconds_to_start), 3) if seconds_to_start is not None else None,
                "start_time_raw": start_raw,
                "executable_book": bool(executable_book),
                "executable_book_key": executable_book_key,
                "executable_book_value": executable_book_value,
            }
        if status_text in {"scheduled", "pregame", "pre_game", "not_started", "not started", "upcoming", "preview"}:
            if not self._sports_live_state_bool(explicit_live_value) and not scoreboard_live:
                return {
                    "reason": "pregame_status",
                    "status_key": status_key,
                    "status": status_value,
                    "explicit_live_key": explicit_live_key,
                    "explicit_live_value": explicit_live_value,
                    "scoreboard_key": scoreboard_key,
                    "scoreboard_value": scoreboard_value,
                }
        return None

    def _build_aion_live_candidate_terminal_accounting(
        self,
        *,
        markets=None,
        quotes_by_ticker=None,
        quote_hydration_summary=None,
        trade_readiness_records=None,
        live_select_summary=None,
        execution_funnel=None,
        selected_ticker=None,
        submit_attempted=False,
        submit_success=False,
        stage="post_quote_hydration",
    ):
        markets = list(markets or [])
        quotes_by_ticker = quotes_by_ticker if isinstance(quotes_by_ticker, dict) else {}
        quote_hydration_summary = quote_hydration_summary if isinstance(quote_hydration_summary, dict) else {}
        live_select_summary = live_select_summary if isinstance(live_select_summary, dict) else {}
        execution_funnel = execution_funnel if isinstance(execution_funnel, dict) else {}
        selected_ticker = str(selected_ticker or "").strip()
        def _terminal_record_score(record):
            record = record if isinstance(record, dict) else {}
            if not record:
                return 0
            status = str(record.get("realm_vv_status") or record.get("phase55_status") or "").strip().lower()
            decision = str(record.get("decision") or "").strip().upper()
            reason_text = str(
                record.get("final_block_reason")
                or record.get("canonical_final_block_reason")
                or record.get("reject_reason")
                or record.get("blocker")
                or record.get("blocker_class")
                or record.get("decision_reason")
                or record.get("entry_ready_reason")
                or record.get("readiness_mapping_error")
                or ""
            ).strip().lower()
            score = 0
            if status and status not in {"unknown", "none"}:
                score += 3
            if status and status not in {"entry_ready", "unknown", "none"}:
                score += 3
            if decision in {"SKIP", "WAIT", "BUY"}:
                score += 2
            if reason_text and reason_text not in {"unknown", "none", "eligible"}:
                score += 2
            if record.get("final_block_reason") or record.get("canonical_final_block_reason") or record.get("blocker"):
                score += 2
            return score

        def _preferred_terminal_record(current, candidate):
            if not isinstance(candidate, dict) or not candidate:
                return current if isinstance(current, dict) else None
            if not isinstance(current, dict) or not current:
                return candidate
            return candidate if _terminal_record_score(candidate) >= _terminal_record_score(current) else current

        record_by_ticker = {}
        for record in list(trade_readiness_records or []):
            if not isinstance(record, dict):
                continue
            ticker_key = str(record.get("ticker") or "").strip()
            if ticker_key:
                record_by_ticker[ticker_key] = _preferred_terminal_record(record_by_ticker.get(ticker_key), record)

        def _spread_from_quote_fields(market=None, q=None, side=None):
            side = self._aion_normalize_live_side(side)

            def _price(value):
                value = self.to_float(value, None)
                if value is None:
                    return None
                if value > 1.0:
                    value = value / 100.0
                return value

            def _field(*names):
                for name in names:
                    value = self._read_field(q, name, default=None)
                    if value is not None:
                        return value
                    value = self._read_field(market, name, default=None)
                    if value is not None:
                        return value
                return None

            direct = _price(_field("spread", "spread_width", "sports_spread"))
            if direct is not None:
                return max(0.0, float(direct))

            spreads = []
            if side in {"yes", None}:
                yes_ask = _price(_field("yes_ask", "yes_price"))
                yes_bid = _price(_field("yes_bid"))
                if yes_ask is not None and yes_bid is not None:
                    spreads.append(max(0.0, yes_ask - yes_bid))
            if side in {"no", None}:
                no_ask = _price(_field("no_ask", "no_price"))
                no_bid = _price(_field("no_bid"))
                if no_ask is not None and no_bid is not None:
                    spreads.append(max(0.0, no_ask - no_bid))
            return max(spreads) if spreads else None

        buckets = self._aion_funnel_terminal_buckets()
        counts = Counter({bucket: 0 for bucket in buckets})
        examples = {bucket: [] for bucket in buckets}
        raw_reasons = Counter()
        terminal_records = []

        for market in markets:
            market = market if isinstance(market, dict) else {}
            ticker = str(market.get("ticker") or "").strip()
            family = str(self.get_market_family(market or {"ticker": ticker}) or market.get("family") or market.get("category") or "UNKNOWN").strip().upper() or "UNKNOWN"
            q = quotes_by_ticker.get(ticker) if ticker else None
            record = record_by_ticker.get(ticker) if ticker else None
            gate_record = {}
            if ticker:
                try:
                    gate_record = self._get_realm_vv_live_execution_gate_record(ticker, stage=f"terminal_accounting:{stage}") or {}
                except Exception:
                    gate_record = {}
            record = _preferred_terminal_record(record, gate_record)
            outcome = "other"
            reason = "unclassified"
            side = None
            selected_price = None

            if ticker and selected_ticker and ticker == selected_ticker and bool(submit_success or execution_funnel.get("execution_submitted") or execution_funnel.get("submitted")):
                outcome = "submit_success"
                reason = "submit_success"
            elif ticker and selected_ticker and ticker == selected_ticker and bool(submit_attempted or execution_funnel.get("execution_attempted")):
                outcome = "submit_attempt"
                reason = "submit_attempt"
            else:
                if q is None:
                    outcome = "no_quote"
                    reason = "missing_quote_object"
                else:
                    side = self._aion_normalize_live_side(
                        self._read_field(q, "selected_side", "side", default=None)
                        or self._read_field(market, "selected_side", "side", default=None)
                    )
                    if not side:
                        outcome = "no_side"
                        reason = "missing_side"
                    else:
                        selected_price = self._aion_funnel_candidate_price(market=market, q=q, side=side)
                        if selected_price is None:
                            outcome = "no_price"
                            reason = "missing_selected_price"
                        elif isinstance(record, dict):
                            reason = (
                                record.get("final_block_reason")
                                or record.get("canonical_final_block_reason")
                                or record.get("reject_reason")
                                or record.get("blocker")
                                or record.get("blocker_class")
                                or record.get("realm_vv_status")
                                or record.get("phase55_status")
                                or record.get("decision_reason")
                                or record.get("reject_reason")
                                or record.get("entry_ready_reason")
                                or record.get("readiness_mapping_error")
                                or "record_present_unclassified"
                            )
                            outcome = self._aion_funnel_terminal_reason(reason)
                            if outcome == "other":
                                edge = self.to_float(
                                    record.get("final_edge"),
                                    self.to_float(record.get("edge_after_cost"), self.to_float(record.get("sports_edge_after_cost"), None)),
                                )
                                confidence = self.to_float(record.get("probability_confidence"), None)
                                liquidity = self.to_float(record.get("liquidity"), None)
                                spread_bucket = str(record.get("spread_bucket") or "").strip().lower()
                                if edge is not None and edge <= 0.0:
                                    outcome = "low_edge"
                                    reason = "edge_too_low"
                                elif confidence is not None and confidence <= 0.0:
                                    outcome = "low_confidence"
                                    reason = "low_confidence"
                                elif liquidity is not None and liquidity <= 0.0:
                                    outcome = "liquidity_block"
                                    reason = "no_liquidity"
                                elif spread_bucket in {"unsafe", "too_wide", "wide_unsafe"}:
                                    outcome = "spread_block"
                                    reason = "unsafe_spread"
                                elif str(record.get("phase55_status") or record.get("realm_vv_status") or "").strip().lower() == "entry_ready":
                                    outcome = "final_readiness_failed"
                                    reason = "entry_ready_unsubmitted"
                        else:
                            dominant_reason = (
                                live_select_summary.get("final_no_candidate_reason")
                                or live_select_summary.get("top_reject_reason")
                                or live_select_summary.get("execution_block_reason")
                                or live_select_summary.get("block_reason")
                                or (live_select_summary.get("top_missing_reason") if isinstance(live_select_summary.get("top_missing_reason"), str) else None)
                            )
                            mapped = self._aion_funnel_terminal_reason(dominant_reason)
                            if dominant_reason and mapped != "other":
                                outcome = mapped
                                reason = dominant_reason
                            else:
                                quote_spread = _spread_from_quote_fields(market=market, q=q, side=side)
                                quote_spread_bucket = str(
                                    getattr(q, "spread_bucket", None)
                                    or getattr(q, "sports_spread_bucket", None)
                                    or market.get("spread_bucket")
                                    or ""
                                ).strip().lower()
                                unsafe_price_status = str(
                                    getattr(q, "unsafe_price_status", None)
                                    or market.get("unsafe_price_status")
                                    or ""
                                ).strip().lower()
                                spread_block_threshold = max(
                                    self.to_float(AION_SPORTS_SPREAD_PREFILTER_MAX_EXECUTABLE, 0.42) or 0.42,
                                    self.to_float(AION_SPORTS_MAX_SPREAD_HARD, 0.24) or 0.24,
                                )
                                if (
                                    quote_spread is not None
                                    and quote_spread > spread_block_threshold
                                ) or quote_spread_bucket in {"unsafe", "too_wide", "wide_unsafe", "spread_absurd", "absurd"} or unsafe_price_status in {"spread_extreme", "sports_spread_absurd_for_family", "spread_absurd_unusable", "catastrophic_spread"}:
                                    outcome = "spread_block"
                                    reason = "spread_absurd_unusable"
                                elif quote_spread is not None and quote_spread > AION_SPORTS_MAX_SPREAD_SOFT:
                                    outcome = "spread_block"
                                    reason = "wide_spread"
                                else:
                                    outcome = "final_readiness_failed"
                                    reason = dominant_reason or "valid_quote_no_terminal_record"

            counts[outcome] += 1
            raw_reasons[str(reason or outcome)] += 1
            terminal_records.append(
                {
                    "stage": stage,
                    "ticker": ticker or None,
                    "family": family,
                    "terminal_outcome": outcome,
                    "reason": reason,
                    "side": side,
                    "selected_price": selected_price,
                    "spread": _spread_from_quote_fields(market=market, q=q, side=side),
                    "liquidity": self.to_float(getattr(q, "liquidity", None), self.to_float(market.get("liquidity"), None)) if q is not None else self.to_float(market.get("liquidity"), None),
                    "volume": self.to_float(getattr(q, "volume", None), self.to_float(market.get("volume"), None)) if q is not None else self.to_float(market.get("volume"), None),
                    "subsystem": "live_candidate_terminal_accounting",
                }
            )
            if len(examples[outcome]) < 5:
                examples[outcome].append({"ticker": ticker or None, "family": family, "reason": reason})

        terminal_total = int(sum(counts.values()))
        sports_candidates = int(len(markets))
        balanced = terminal_total == sports_candidates
        percentages = {
            bucket: round((float(counts.get(bucket, 0)) / max(sports_candidates, 1)) * 100.0, 2)
            for bucket in buckets
        }
        dominant = counts.most_common(1)[0][0] if terminal_total else "none"
        return {
            "stage": stage,
            "sports_candidates": sports_candidates,
            "terminal_total": terminal_total,
            "terminal_balance_ok": bool(balanced),
            "terminal_outcomes": {bucket: int(counts.get(bucket, 0)) for bucket in buckets},
            "terminal_percentages": percentages,
            "dominant_terminal_outcome": dominant,
            "top_raw_reasons": [{"reason": reason, "count": int(count)} for reason, count in raw_reasons.most_common(20)],
            "examples": {bucket: values for bucket, values in examples.items() if values},
            "terminal_records": terminal_records,
            "quote_hydration_attempted": int(quote_hydration_summary.get("attempted", 0) or 0),
            "quote_hydration_success": int(quote_hydration_summary.get("success", 0) or 0),
            "quote_hydration_failure": int(quote_hydration_summary.get("failure", 0) or 0),
        }

    def _emit_aion_live_candidate_terminal_accounting(self, accounting):
        accounting = accounting if isinstance(accounting, dict) else {}
        try:
            compact_accounting = dict(accounting)
            if "terminal_records" in compact_accounting:
                compact_accounting["terminal_records_count"] = len(list(compact_accounting.get("terminal_records") or []))
                compact_accounting.pop("terminal_records", None)
            builtins.print("[AION-FUNNEL-ACCOUNTING] " + json.dumps(compact_accounting, sort_keys=True, default=str))
            stage = str(accounting.get("stage") or "").strip().lower()
            if stage == "post_selector":
                final_readiness_examples = [
                    {
                        "ticker": record.get("ticker"),
                        "family": record.get("family"),
                        "side": record.get("side"),
                        "selected_price": record.get("selected_price"),
                        "spread": record.get("spread"),
                        "liquidity": record.get("liquidity"),
                        "reason": record.get("reason") or "unknown",
                    }
                    for record in list(accounting.get("terminal_records") or [])
                    if isinstance(record, dict) and str(record.get("terminal_outcome") or "").strip() == "final_readiness_failed"
                ][:8]
                if final_readiness_examples:
                    builtins.print(
                        "[AION-FINAL-READINESS-DETAIL] "
                        + json.dumps(
                            {
                                "stage": accounting.get("stage"),
                                "count": int((accounting.get("terminal_outcomes") or {}).get("final_readiness_failed", len(final_readiness_examples))),
                                "examples": final_readiness_examples,
                                "subsystem": "live_candidate_terminal_accounting",
                            },
                            sort_keys=True,
                            default=str,
                        )
                    )
                seen = getattr(self, "_aion_final_reject_seen_keys", None)
                if not isinstance(seen, set):
                    seen = set()
                    self._aion_final_reject_seen_keys = seen
                cycle_id = int(getattr(self, "cycle_count", 0) or 0)
                for record in list(accounting.get("terminal_records") or []):
                    if not isinstance(record, dict):
                        continue
                    terminal_outcome = str(record.get("terminal_outcome") or "").strip()
                    if terminal_outcome in {"submit_success", "submit_attempt"}:
                        continue
                    ticker = str(record.get("ticker") or "").strip()
                    reason = str(record.get("reason") or terminal_outcome or "unknown").strip() or "unknown"
                    reject_key = (cycle_id, ticker, reason)
                    if reject_key in seen:
                        continue
                    seen.add(reject_key)
                    builtins.print(
                        "[AION-FINAL-REJECT] "
                        + json.dumps(
                            {
                                "cycle_id": cycle_id,
                                "ticker": ticker or None,
                                "family": record.get("family"),
                                "side": record.get("side"),
                                "selected_price": record.get("selected_price"),
                                "spread": record.get("spread"),
                                "liquidity": record.get("liquidity"),
                                "volume": record.get("volume"),
                                "reason": reason,
                                "terminal_outcome": terminal_outcome,
                                "subsystem": record.get("subsystem") or "live_candidate_terminal_accounting",
                            },
                            sort_keys=True,
                            default=str,
                        )
                    )
            if not bool(accounting.get("terminal_balance_ok")):
                builtins.print(
                    "[AION-FUNNEL-ACCOUNTING-FAIL] "
                    + json.dumps(
                        {
                            "stage": accounting.get("stage"),
                            "sports_candidates": accounting.get("sports_candidates"),
                            "terminal_total": accounting.get("terminal_total"),
                            "terminal_outcomes": accounting.get("terminal_outcomes"),
                            "reason": "sports_candidates_did_not_equal_terminal_outcomes",
                        },
                        sort_keys=True,
                        default=str,
                    )
                )
        except Exception:
            pass

    def compute_no_vig_probability(self, *args, **kwargs):
        if sports_calibration is None or not hasattr(sports_calibration, "compute_no_vig_probability"):
            raise RuntimeError("sports.calibration.compute_no_vig_probability unavailable")
        return sports_calibration.compute_no_vig_probability(bot=self, *args, **kwargs)

    def compute_calibrated_sports_probability(self, *args, **kwargs):
        if sports_calibration is None or not hasattr(sports_calibration, "compute_calibrated_sports_probability"):
            raise RuntimeError("sports.calibration.compute_calibrated_sports_probability unavailable")
        return sports_calibration.compute_calibrated_sports_probability(bot=self, *args, **kwargs)

    def compute_sports_dynamic_buffer(self, *args, **kwargs):
        if sports_calibration is None or not hasattr(sports_calibration, "compute_sports_dynamic_buffer"):
            raise RuntimeError("sports.calibration.compute_sports_dynamic_buffer unavailable")
        result = sports_calibration.compute_sports_dynamic_buffer(bot=self, *args, **kwargs)
        if isinstance(result, dict):
            normalized = dict(result)
            if "dynamic_buffer" not in normalized and "sports_dynamic_buffer" in normalized:
                normalized["dynamic_buffer"] = normalized.get("sports_dynamic_buffer")
            if "sports_dynamic_buffer" not in normalized and "dynamic_buffer" in normalized:
                normalized["sports_dynamic_buffer"] = normalized.get("dynamic_buffer")
            return normalized
        return result

    def compute_sports_post_cost_edge(self, *args, **kwargs):
        return _call_sports_live_intelligence("compute_sports_post_cost_edge", self, *args, **kwargs)

    def compute_sports_spread_context(self, *args, **kwargs):
        return _call_sports_live_intelligence("compute_sports_spread_context", self, *args, **kwargs)

    def _get_sports_market_calibration_bucket(self, container_name, key):
        buckets = getattr(self, container_name, None)
        if not isinstance(buckets, dict):
            buckets = {}
            setattr(self, container_name, buckets)
        bucket = buckets.setdefault(
            key,
            {
                "first_seen_time": None,
                "last_seen_time": 0.0,
                "ticker": None,
                "family": None,
                "total_sports_scanned": 0,
                "rejected_wide_spread": 0,
                "rejected_edge_below_cost": 0,
                "rejected_flat_bias": 0,
                "rejected_missing_quotes": 0,
                "rejected_weak_liquidity": 0,
                "rejected_decaying_regime": 0,
                "near_pass_count": 0,
                "allow_normal_validation_count": 0,
                "best_sports_edge_after_cost": 0.0,
                "best_sports_score": 0.0,
                "best_sports_ticker": None,
                "best_sports_family": None,
                "best_sports_reason": "unknown",
                "latest_sports_action": "reject",
                "latest_reject_reason": "unknown",
                "latest_summary": {},
                "score_history": deque(maxlen=24),
                "action_history": deque(maxlen=24),
                "blocker_history": deque(maxlen=24),
            },
        )
        bucket.setdefault("score_history", deque(maxlen=24))
        bucket.setdefault("action_history", deque(maxlen=24))
        bucket.setdefault("blocker_history", deque(maxlen=24))
        return bucket

    def _build_sports_market_calibration_family_summary(self, family=None):
        family = str(family or "UNKNOWN").strip().upper() or "UNKNOWN"
        ticker_container = getattr(self, "sports_harvest_by_ticker", {}) or {}
        family_buckets = []
        if isinstance(ticker_container, dict):
            for bucket in ticker_container.values():
                if not isinstance(bucket, dict):
                    continue
                if str(bucket.get("family") or "").strip().upper() == family:
                    family_buckets.append(bucket)
        family_bucket = self._get_sports_market_calibration_bucket("sports_harvest_by_family", f"family:{family}")
        if not family_buckets:
            summary = {
                "family": family,
                "candidate_count": 0,
                "total_sports_scanned": 0,
                "rejected_wide_spread": 0,
                "rejected_edge_below_cost": 0,
                "rejected_flat_bias": 0,
                "rejected_missing_quotes": 0,
                "rejected_weak_liquidity": 0,
                "rejected_decaying_regime": 0,
                "near_pass_count": 0,
                "allow_normal_validation_count": 0,
                "clv_improving_count": 0,
                "clv_decaying_count": 0,
                "clv_recovered_after_near_pass_count": 0,
                "best_sports_ticker": None,
                "best_sports_calibrated_probability": 0.0,
                "best_sports_no_vig_probability": 0.0,
                "best_sports_edge_after_cost": 0.0,
                "best_sports_family": None,
                "best_sports_score": 0.0,
                "live_arb_enabled": bool(AION_LIVE_ARB_ENABLED),
            }
            family_bucket["last_summary"] = summary
            return summary
        best_bucket = max(
            family_buckets,
            key=lambda bucket: (
                self.to_float(bucket.get("best_sports_edge_after_cost"), 0.0),
                self.to_float(bucket.get("best_sports_score"), 0.0),
            ),
        )
        summary = {
            "family": family,
            "candidate_count": int(len(family_buckets)),
            "total_sports_scanned": int(sum(int(bucket.get("total_sports_scanned", 0) or 0) for bucket in family_buckets)),
            "rejected_wide_spread": int(sum(int(bucket.get("rejected_wide_spread", 0) or 0) for bucket in family_buckets)),
            "rejected_edge_below_cost": int(sum(int(bucket.get("rejected_edge_below_cost", 0) or 0) for bucket in family_buckets)),
            "rejected_flat_bias": int(sum(int(bucket.get("rejected_flat_bias", 0) or 0) for bucket in family_buckets)),
            "rejected_missing_quotes": int(sum(int(bucket.get("rejected_missing_quotes", 0) or 0) for bucket in family_buckets)),
            "rejected_weak_liquidity": int(sum(int(bucket.get("rejected_weak_liquidity", 0) or 0) for bucket in family_buckets)),
            "rejected_decaying_regime": int(sum(int(bucket.get("rejected_decaying_regime", 0) or 0) for bucket in family_buckets)),
            "near_pass_count": int(sum(int(bucket.get("near_pass_count", 0) or 0) for bucket in family_buckets)),
            "allow_normal_validation_count": int(sum(int(bucket.get("allow_normal_validation_count", 0) or 0) for bucket in family_buckets)),
            "clv_improving_count": int(sum(int(bucket.get("clv_improving_count", 0) or 0) for bucket in family_buckets)),
            "clv_decaying_count": int(sum(int(bucket.get("clv_decaying_count", 0) or 0) for bucket in family_buckets)),
            "clv_recovered_after_near_pass_count": int(sum(int(bucket.get("clv_recovered_after_near_pass_count", 0) or 0) for bucket in family_buckets)),
            "best_sports_ticker": str(best_bucket.get("ticker") or "").strip() or None,
            "best_sports_family": str(best_bucket.get("family") or "").strip().upper() or None,
            "best_sports_calibrated_probability": round(self.to_float(best_bucket.get("calibrated_probability"), 0.0) or 0.0, 4),
            "best_sports_no_vig_probability": round(self.to_float(best_bucket.get("no_vig_probability"), 0.0) or 0.0, 4),
            "best_sports_edge_after_cost": round(self.to_float(best_bucket.get("best_sports_edge_after_cost"), 0.0) or 0.0, 4),
            "best_sports_score": round(self.to_float(best_bucket.get("best_sports_score"), 0.0) or 0.0, 4),
            "best_sports_reason": str(best_bucket.get("best_sports_reason") or "unknown"),
            "live_arb_enabled": bool(AION_LIVE_ARB_ENABLED),
        }
        family_bucket["last_summary"] = summary
        return summary

