    def _emit_aion_selected_price_rejected_compact(self, **payload):
        try:
            now = time.time()
            ticker = str(payload.get("ticker") or "UNKNOWN")
            family = str(payload.get("family") or "UNKNOWN")
            stage = str(payload.get("selection_stage") or "unknown")
            side = str(payload.get("selected_side") or "none")
            reason = str(payload.get("final_reason") or payload.get("blocker") or "unknown")
            key = (ticker, family, stage, side, reason)
            throttle = getattr(self, "_aion_selected_price_reject_throttle", None)
            if not isinstance(throttle, dict):
                throttle = {}
                self._aion_selected_price_reject_throttle = throttle
            state = throttle.get(key, {})
            last_emit = float(state.get("last_emit", 0.0) or 0.0)
            suppressed = int(state.get("suppressed", 0) or 0)
            if last_emit and (now - last_emit) < 60.0:
                state["suppressed"] = suppressed + 1
                throttle[key] = state
                return
            throttle[key] = {"last_emit": now, "suppressed": 0}
            compact = {
                "ticker": ticker if ticker != "UNKNOWN" else None,
                "family": family,
                "selection_stage": stage,
                "selected_side": payload.get("selected_side"),
                "selected_price_cents": payload.get("selected_price_cents"),
                "selected_price_dollars": payload.get("selected_price_dollars"),
                "selected_price_source": payload.get("selected_price_source"),
                "missing_source": payload.get("missing_source"),
                "yes_bid": payload.get("yes_bid"),
                "yes_ask": payload.get("yes_ask"),
                "no_bid": payload.get("no_bid"),
                "no_ask": payload.get("no_ask"),
                "refresh_attempted": bool(payload.get("refresh_attempted")),
                "final_reason": reason,
                "suppressed_count": suppressed,
            }
            print("[AION-SELECTED-PRICE-REJECTED] " + json.dumps(compact, sort_keys=True, default=str))
        except Exception:
            pass

    def _aion_normalize_live_side(self, side):
        side = str(side or "").strip().lower()
        return side if side in {"yes", "no"} else None

    def _aion_select_bidirectional_side(
        self,
        *,
        ticker=None,
        family=None,
        lane=None,
        market=None,
        q=None,
        quote_diag=None,
        yes_bid=None,
        yes_ask=None,
        no_bid=None,
        no_ask=None,
        yes_top_size=None,
        no_top_size=None,
        preferred_side=None,
        source="side_selection",
        emit_log=False,
    ):
        market = market if isinstance(market, dict) else {}
        quote_diag = quote_diag if isinstance(quote_diag, dict) else {}
        ticker = str(ticker or market.get("ticker") or getattr(q, "ticker", "") or "").strip() or None
        family = str(family or (self.get_market_family({"ticker": ticker}) if ticker else self.get_market_family(market) if market else "UNKNOWN") or "UNKNOWN").strip() or "UNKNOWN"
        is_sports = bool(lane == "SPORTS" or self._is_sports_market_or_family(family))
        lane = "SPORTS" if is_sports else "OTHER"

        def _pick(*values):
            for value in values:
                if value is None:
                    continue
                if isinstance(value, str) and not value.strip():
                    continue
                return value
            return None

        def _q_get(*names):
            if q is None:
                return None
            for name in names:
                try:
                    value = getattr(q, name, None)
                except Exception:
                    value = None
                if value not in (None, ""):
                    return value
            return None

        def _context_value(*names):
            for name in names:
                for container in (quote_diag, market):
                    if isinstance(container, dict):
                        value = container.get(name)
                        if value not in (None, ""):
                            return value
                value = _q_get(name)
                if value not in (None, ""):
                    return value
            return None

        def _price(value):
            numeric = self.to_float(value, None)
            if numeric is None:
                return None
            if 1.0 < numeric <= 100.0:
                numeric = numeric / 100.0
            if numeric is None or not math.isfinite(float(numeric)):
                return None
            return round(float(numeric), 4) if 0.0 < float(numeric) <= 1.0 else None

        def _bid_price(value):
            numeric = self.to_float(value, None)
            if numeric is None:
                return None
            if 1.0 < numeric <= 100.0:
                numeric = numeric / 100.0
            if numeric is None or not math.isfinite(float(numeric)):
                return None
            return round(float(numeric), 4) if 0.0 <= float(numeric) < 1.0 else None

        def _size(value):
            numeric = self.to_float(value, None)
            if numeric is None or not math.isfinite(float(numeric)):
                return 0.0
            return max(0.0, float(numeric))

        yes_bid = _bid_price(_pick(yes_bid, quote_diag.get("yes_bid"), quote_diag.get("yes_bid_dollars"), market.get("yes_bid_dollars"), market.get("yes_bid"), _q_get("yes_bid", "yes_bid_dollars")))
        yes_ask = _price(_pick(yes_ask, quote_diag.get("yes_ask"), quote_diag.get("yes_ask_dollars"), market.get("yes_ask_dollars"), market.get("yes_ask"), _q_get("yes_ask", "yes_ask_dollars")))
        no_bid = _bid_price(_pick(no_bid, quote_diag.get("no_bid"), quote_diag.get("no_bid_dollars"), market.get("no_bid_dollars"), market.get("no_bid"), _q_get("no_bid", "no_bid_dollars")))
        no_ask = _price(_pick(no_ask, quote_diag.get("no_ask"), quote_diag.get("no_ask_dollars"), market.get("no_ask_dollars"), market.get("no_ask"), _q_get("no_ask", "no_ask_dollars")))
        yes_ask_source = "ask" if yes_ask is not None else None
        no_ask_source = "ask" if no_ask is not None else None
        try:
            yes_bid, yes_ask, no_bid, no_ask = self._infer_missing_binary_quotes(yes_bid, yes_ask, no_bid, no_ask)
        except Exception:
            pass
        yes_bid = _bid_price(yes_bid)
        yes_ask = _price(yes_ask)
        no_bid = _bid_price(no_bid)
        no_ask = _price(no_ask)
        if yes_ask_source is None and yes_ask is not None and no_bid is not None:
            yes_ask_source = "opposite_side_equivalent"
        if no_ask_source is None and no_ask is not None and yes_bid is not None:
            no_ask_source = "opposite_side_equivalent"

        yes_top_size = _size(_pick(yes_top_size, quote_diag.get("yes_top_size"), quote_diag.get("yes_ask_size"), market.get("yes_top_size"), market.get("yes_ask_size"), market.get("yes_ask_size_fp"), _q_get("yes_top_size", "yes_ask_size")))
        no_top_size = _size(_pick(no_top_size, quote_diag.get("no_top_size"), quote_diag.get("no_ask_size"), market.get("no_top_size"), market.get("no_ask_size"), market.get("no_ask_size_fp"), _q_get("no_top_size", "no_ask_size")))
        reported_liquidity = _size(_pick(quote_diag.get("liquidity_depth"), quote_diag.get("liquidity"), market.get("liquidity_depth"), market.get("liquidity"), market.get("liquidity_dollars"), _q_get("liquidity_depth", "liquidity")))
        preferred_side = self._aion_normalize_live_side(
            preferred_side
            or quote_diag.get("selected_side")
            or market.get("selected_side")
            or _q_get("selected_side", "side")
        )
        selected_price_hint = _price(
            _context_value(
                "selected_price_dollars",
                "selected_price",
                "selected_price_hint",
                "intended_entry_price",
            )
        )
        if selected_price_hint is not None and preferred_side == "yes" and yes_ask is None:
            yes_ask = selected_price_hint
            yes_ask_source = "selected_price_hint"
        if selected_price_hint is not None and preferred_side == "no" and no_ask is None:
            no_ask = selected_price_hint
            no_ask_source = "selected_price_hint"

        def _prob(value):
            numeric = self.to_float(value, None)
            if numeric is None:
                return None
            if numeric > 1.0 and numeric <= 100.0:
                numeric = numeric / 100.0
            if numeric is None or not math.isfinite(float(numeric)):
                return None
            return max(0.0, min(1.0, float(numeric)))

        yes_probability = _prob(_context_value("yes_probability", "yes_prob", "p_yes", "model_yes_probability"))
        no_probability = _prob(_context_value("no_probability", "no_prob", "p_no", "model_no_probability"))
        model_yes_probability = _prob(
            _context_value(
                "estimated_win_probability",
                "calibrated_probability",
                "model_probability",
                "win_probability",
                "probability",
            )
        )
        if yes_probability is None and model_yes_probability is not None:
            yes_probability = model_yes_probability
        if no_probability is None and yes_probability is not None:
            no_probability = max(0.0, min(1.0, 1.0 - yes_probability))
        if yes_probability is None and no_probability is not None:
            yes_probability = max(0.0, min(1.0, 1.0 - no_probability))

        def _edge(side, ask_price):
            side_edge = self.to_float(
                _context_value(
                    f"{side}_edge_after_cost",
                    f"{side}_final_edge",
                    f"{side}_ev_edge",
                    f"{side}_edge",
                ),
                None,
            )
            if side_edge is not None:
                return float(side_edge), "side_specific_edge"
            probability = yes_probability if side == "yes" else no_probability
            if probability is not None and ask_price is not None:
                return round(float(probability) - float(ask_price), 6), "model_probability_minus_ask"
            generic_side = self._aion_normalize_live_side(_context_value("selected_side", "side", "outcome_side"))
            generic_edge = self.to_float(_context_value("edge_after_cost", "final_edge", "ev_edge", "edge"), None)
            if generic_edge is not None and generic_side == side:
                return float(generic_edge), "selected_side_generic_edge"
            return 0.0, "no_edge_signal"

        def _momentum_direction_value():
            raw = str(
                _context_value(
                    "momentum_direction",
                    "asset_momentum_direction",
                    "price_momentum_direction",
                    "trend_direction",
                    "target_direction",
                )
                or ""
            ).strip().lower()
            if raw in {"up", "bull", "bullish", "positive", "rising", "pump", "toward_range", "toward"}:
                return "up"
            if raw in {"down", "bear", "bearish", "negative", "falling", "dump", "away_from_range", "away"}:
                return "down"
            return "unknown"

        momentum_direction = _momentum_direction_value()
        momentum_strength = self.to_float(
            _context_value("momentum_strength", "momentum_score", "asset_momentum", "repricing_velocity", "trend_score"),
            0.0,
        ) or 0.0
        try:
            momentum_strength = abs(float(momentum_strength))
        except Exception:
            momentum_strength = 0.0
        momentum_strength = max(0.0, min(1.0, momentum_strength if momentum_strength <= 1.0 else momentum_strength / 100.0))
        yes_direction = None
        no_direction = None

        def _momentum_alignment(side):
            wanted = yes_direction if side == "yes" else no_direction
            if momentum_direction == "unknown" or wanted is None:
                return 0.0, "unknown"
            if momentum_direction == wanted:
                return max(0.08, momentum_strength), "aligned"
            return -max(0.08, momentum_strength), "opposed"

        def _side_snapshot(side, bid, ask, top_size):
            ask_source = yes_ask_source if side == "yes" else no_ask_source
            side_edge, edge_source = _edge(side, ask)
            spread = None
            if bid is not None and ask is not None and ask >= bid:
                spread = round(max(0.0, float(ask) - float(bid)), 4)
            side_liquidity = max(_size(top_size), reported_liquidity if _size(top_size) <= 0.0 else 0.0)
            sports_thin_executable = bool(
                is_sports
                and ask is not None
                and KALSHI_CONTRACT_MIN_PRICE <= ask <= KALSHI_CONTRACT_MAX_PRICE
                and (
                    bid is not None
                    or preferred_side == side
                    or selected_price_hint is not None
                )
            )
            executable = bool(
                ask is not None
                and KALSHI_CONTRACT_MIN_PRICE <= ask <= KALSHI_CONTRACT_MAX_PRICE
                and (side_liquidity > 0.0 or sports_thin_executable)
            )
            momentum_alignment, momentum_reason = _momentum_alignment(side)
            spread_penalty = (spread if spread is not None else 0.20) * 18.0
            liquidity_score = min(8.0, math.log10(side_liquidity + 1.0) * 2.0) if side_liquidity > 0.0 else 0.0
            edge_score = float(side_edge) * 100.0
            momentum_score = momentum_alignment * 12.0
            preference_score = 0.25 if preferred_side == side else 0.0
            total_top = max(0.0, yes_top_size) + max(0.0, no_top_size)
            side_pressure = (side_liquidity + 1.0) / max(total_top + 2.0, 2.0)
            depth_score = self._clamp(math.log1p(side_liquidity) / math.log1p(30.0), 0.0, 1.0)
            if spread is None:
                spread_fill_score = 0.48
            else:
                spread_fill_score = 1.0 - self._clamp((spread - 0.02) / 0.30, 0.0, 1.0)
            edge_fill_score = self._clamp(max(0.0, side_edge) / 0.025, 0.0, 1.0)
            book_fill_score = 1.0 if bid is not None and ask is not None and executable else 0.25
            fill_probability = self._clamp(
                depth_score * 0.34
                + spread_fill_score * 0.26
                + edge_fill_score * 0.20
                + book_fill_score * 0.10
                + self._clamp(0.45 + side_pressure * 0.65, 0.0, 1.0) * 0.10,
                0.0,
                1.0,
            )
            fill_score = (fill_probability - 0.50) * 8.0
            final_score = edge_score + liquidity_score + momentum_score + preference_score + fill_score - spread_penalty
            return {
                "side": side,
                "bid": bid,
                "ask": ask,
                "selected_price": ask,
                "selected_price_source": ask_source,
                "spread": spread,
                "top_size": top_size,
                "liquidity": side_liquidity,
                "side_pressure": round(side_pressure, 4),
                "fill_probability": round(fill_probability, 4),
                "fill_score": round(fill_score, 4),
                "edge_after_cost": round(float(side_edge), 6),
                "edge_source": edge_source,
                "momentum_alignment": round(momentum_alignment, 4),
                "momentum_reason": momentum_reason,
                "final_score": round(final_score, 6),
                "executable": executable,
                "block_reason": None if executable else (
                    f"missing_{side}_ask" if ask is None else
                    f"{side}_price_out_of_bounds" if ask < KALSHI_CONTRACT_MIN_PRICE or ask > KALSHI_CONTRACT_MAX_PRICE else
                    f"missing_{side}_liquidity"
                ),
                "sports_thin_executable": bool(sports_thin_executable),
            }

        yes_snapshot = _side_snapshot("yes", yes_bid, yes_ask, yes_top_size)
        no_snapshot = _side_snapshot("no", no_bid, no_ask, no_top_size)
        two_sided_quote_ready = bool(yes_snapshot["selected_price"] is not None and no_snapshot["selected_price"] is not None)
        reason = "selected_by_two_sided_score"
        selected = None
        if not two_sided_quote_ready:
            if is_sports:
                executable = [item for item in (yes_snapshot, no_snapshot) if item["executable"]]
                if executable:
                    selected = max(executable, key=lambda item: item["final_score"])
                    reason = f"sports_one_sided_{selected['side']}_executable"
                else:
                    reason = "missing_two_sided_quote"
            else:
                reason = "missing_two_sided_quote"
        else:
            executable = [item for item in (yes_snapshot, no_snapshot) if item["executable"]]
            if not executable:
                reason = "no_executable_side"
            elif len(executable) == 1:
                selected = executable[0]
                reason = f"only_{selected['side']}_executable"
            else:
                selected = max(executable, key=lambda item: item["final_score"])
                if selected["edge_after_cost"] <= 0.0 and preferred_side in {"yes", "no"}:
                    preferred_snapshot = yes_snapshot if preferred_side == "yes" else no_snapshot
                    if preferred_snapshot["executable"] and preferred_snapshot["edge_after_cost"] >= selected["edge_after_cost"]:
                        selected = preferred_snapshot
                        reason = "kept_preferred_side_no_positive_edge_delta"
                if reason == "selected_by_two_sided_score" and selected["side"] != preferred_side:
                    reason = f"switched_to_{selected['side']}_better_score"
        payload = {
            "ticker": ticker,
            "lane": lane,
            "family": family,
            "market_type": market.get("market_type") or market.get("category"),
            "asset": None,
            "timeframe": None,
            "sport": (market.get("sport") or quote_diag.get("sport")) if is_sports else None,
            "yes_bid": yes_snapshot["bid"],
            "yes_ask": yes_snapshot["ask"],
            "no_bid": no_snapshot["bid"],
            "no_ask": no_snapshot["ask"],
            "yes_spread": yes_snapshot["spread"],
            "no_spread": no_snapshot["spread"],
            "yes_top_size": yes_snapshot["top_size"],
            "no_top_size": no_snapshot["top_size"],
            "yes_edge_after_cost": yes_snapshot["edge_after_cost"],
            "no_edge_after_cost": no_snapshot["edge_after_cost"],
            "yes_final_score": yes_snapshot["final_score"],
            "no_final_score": no_snapshot["final_score"],
            "yes_fill_probability": yes_snapshot["fill_probability"],
            "no_fill_probability": no_snapshot["fill_probability"],
            "yes_fill_score": yes_snapshot["fill_score"],
            "no_fill_score": no_snapshot["fill_score"],
            "yes_side_pressure": yes_snapshot["side_pressure"],
            "no_side_pressure": no_snapshot["side_pressure"],
            "yes_executable": bool(yes_snapshot["executable"]),
            "no_executable": bool(no_snapshot["executable"]),
            "preferred_side": preferred_side,
            "selected_side": selected["side"] if selected else None,
            "selected_price": selected["selected_price"] if selected else None,
            "selected_price_source": selected["selected_price_source"] if selected else None,
            "selected_top_size": selected["top_size"] if selected else None,
            "selected_edge_after_cost": selected["edge_after_cost"] if selected else None,
            "selected_final_score": selected["final_score"] if selected else None,
            "selected_fill_probability": selected["fill_probability"] if selected else None,
            "selected_side_pressure": selected["side_pressure"] if selected else None,
            "momentum_direction": momentum_direction,
            "momentum_strength": momentum_strength,
            "two_sided_quote_ready": bool(two_sided_quote_ready),
            "reason": reason,
            "source": source,
        }
        if emit_log:
            try:
                print("[AION-SIDE-COMPARE] " + json.dumps(payload, sort_keys=True, default=str))
                print("[AION-YES-EDGE] " + json.dumps({**payload, "side": "yes", "side_edge_after_cost": yes_snapshot["edge_after_cost"], "side_final_score": yes_snapshot["final_score"], "side_executable": bool(yes_snapshot["executable"])}, sort_keys=True, default=str))
                print("[AION-NO-EDGE] " + json.dumps({**payload, "side": "no", "side_edge_after_cost": no_snapshot["edge_after_cost"], "side_final_score": no_snapshot["final_score"], "side_executable": bool(no_snapshot["executable"])}, sort_keys=True, default=str))
                print("[AION-SIDE-SELECT] " + json.dumps(payload, sort_keys=True, default=str))
                if is_sports:
                    print("[SPORTS-SIDE-COMPARE] " + json.dumps(payload, sort_keys=True, default=str))
                    print("[SPORTS-SIDE-SELECT] " + json.dumps(payload, sort_keys=True, default=str))
            except Exception:
                pass
        return payload

    def _record_sports_quote_continuity_snapshot(self, ticker, family, yes_bid, yes_ask, no_bid, no_ask, yes_top_size=None, no_top_size=None, source="build_quote"):
        if not ticker or not self._is_sports_market_or_family(family):
            return
        if None in (yes_bid, yes_ask, no_bid, no_ask):
            return
        try:
            spread = float(yes_ask) - float(yes_bid)
        except (TypeError, ValueError):
            return
        adaptive_spread = SPORTS_ADAPTIVE_SPREAD_MAX if self._is_sports_market_or_family(family) else MAX_ENTRY_SPREAD
        if spread < 0.0 or spread > adaptive_spread:
            return
        previous = dict(self.sports_quote_continuity_cache.get(ticker, {}) or {})
        stable_cycles = 1
        if previous:
            quote_delta = max(
                abs(float(previous.get("yes_bid", yes_bid)) - float(yes_bid)),
                abs(float(previous.get("yes_ask", yes_ask)) - float(yes_ask)),
                abs(float(previous.get("no_bid", no_bid)) - float(no_bid)),
                abs(float(previous.get("no_ask", no_ask)) - float(no_ask)),
            )
            stable_cycles = int(previous.get("stable_cycles", 1) or 1) + 1 if quote_delta <= 0.02 else 1
        self.sports_quote_continuity_cache[ticker] = {
            "ts": time.time(),
            "family": family,
            "yes_bid": float(yes_bid),
            "yes_ask": float(yes_ask),
            "no_bid": float(no_bid),
            "no_ask": float(no_ask),
            "spread": round(spread, 4),
            "yes_top_size": yes_top_size,
            "no_top_size": no_top_size,
            "source": source,
            "stable_cycles": stable_cycles,
            "adaptive_spread": adaptive_spread,
        }

    def _apply_sports_quote_continuity(self, market, yes_bid, yes_ask, no_bid, no_ask):
        ticker = str((market or {}).get("ticker", "") or "").strip()
        family = self.get_market_family(market) if isinstance(market, dict) else "UNKNOWN"
        if not SPORTS_QUOTE_CONTINUITY_ENABLED or not ticker or not self._is_sports_market_or_family(family):
            return yes_bid, yes_ask, no_bid, no_ask, False, "not_applicable"
        missing_count = sum(1 for value in (yes_bid, yes_ask, no_bid, no_ask) if value is None)
        cached = dict(self.sports_quote_continuity_cache.get(ticker, {}) or {})
        age_seconds = time.time() - float(cached.get("ts", 0.0) or 0.0) if cached else None
        stable_cycles = int(cached.get("stable_cycles", 0) or 0) if cached else 0
        if missing_count <= 0:
            print(
                f"[LIVE-SPORTS-CONTINUITY] ticker={ticker} family={family} eligibility_status=not_needed "
                f"missing_count={missing_count} cache_age={round(age_seconds, 2) if age_seconds is not None else None} "
                f"prior_valid_quotes={'yes' if cached else 'no'} carry_forward_used=no stability_confidence={stable_cycles} "
                f"reason=complete_current_quote"
            )
            return yes_bid, yes_ask, no_bid, no_ask, False, "missing_count_not_eligible"
        if missing_count > 3:
            print(
                f"[LIVE-SPORTS-CONTINUITY] ticker={ticker} family={family} eligibility_status=blocked "
                f"missing_count={missing_count} cache_age={round(age_seconds, 2) if age_seconds is not None else None} "
                f"prior_valid_quotes={'yes' if cached else 'no'} carry_forward_used=no stability_confidence={stable_cycles} "
                f"reason=too_many_missing_quote_fields"
            )
            self._record_live_reject_telemetry(
                reason="missing_count_not_eligible",
                ticker=ticker,
                family=family,
                spread=None,
                stage="sports_continuity",
                category="continuity",
                details={"continuity_reason": "missing_count_not_eligible", "missing_count": missing_count, "cached": bool(cached)},
            )
            return yes_bid, yes_ask, no_bid, no_ask, False, "missing_count_not_eligible"
        if not cached:
            print(
                f"[LIVE-SPORTS-CONTINUITY] ticker={ticker} family={family} eligibility_status=blocked "
                f"missing_count={missing_count} cache_age=None prior_valid_quotes=no carry_forward_used=no "
                f"stability_confidence=0 reason=no_recent_valid_quote"
            )
            self._record_live_reject_telemetry(
                reason="no_recent_valid_quote",
                ticker=ticker,
                family=family,
                spread=None,
                stage="sports_continuity",
                category="continuity",
                details={"continuity_reason": "no_recent_valid_quote", "missing_count": missing_count},
            )
            return yes_bid, yes_ask, no_bid, no_ask, False, "no_recent_valid_quote"
        if age_seconds > SPORTS_QUOTE_CONTINUITY_MAX_AGE_SECONDS:
            print(
                f"[LIVE-SPORTS-CONTINUITY] ticker={ticker} family={family} eligibility_status=blocked "
                f"missing_count={missing_count} cache_age={round(age_seconds, 2)} prior_valid_quotes=yes "
                f"carry_forward_used=no stability_confidence={stable_cycles} reason=recent_quote_too_old"
            )
            self._record_live_reject_telemetry(
                reason="recent_quote_too_old",
                ticker=ticker,
                family=family,
                spread=None,
                stage="sports_continuity",
                category="continuity",
                details={"continuity_reason": "recent_quote_too_old", "missing_count": missing_count, "cache_age": round(age_seconds, 2)},
            )
            return yes_bid, yes_ask, no_bid, no_ask, False, "recent_quote_too_old"
        topbook_snapshot = self._extract_non_targeted_topbook_snapshot(market)
        yes_top_size = self.to_float(topbook_snapshot.get("yes_top_size"), 0.0) or 0.0
        no_top_size = self.to_float(topbook_snapshot.get("no_top_size"), 0.0) or 0.0
        top_size_ok = max(yes_top_size, no_top_size, self.to_float(cached.get("yes_top_size"), 0.0) or 0.0, self.to_float(cached.get("no_top_size"), 0.0) or 0.0) >= SPORTS_QUOTE_CONTINUITY_MIN_TOP_SIZE
        cached_spread = self.to_float(cached.get("spread"), None)
        adaptive_spread = self._get_sports_adaptive_spread_threshold(
            market,
            spread=cached_spread,
            liquidity=market.get("liquidity_dollars", market.get("liquidity")),
            yes_top_size=yes_top_size or cached.get("yes_top_size"),
            no_top_size=no_top_size or cached.get("no_top_size"),
            context="continuity_apply",
        ).get("adaptive_threshold", MAX_ENTRY_SPREAD)
        continuity_spread_limit = min(SPORTS_ADAPTIVE_SPREAD_MAX, max(SPORTS_QUOTE_CONTINUITY_MAX_SPREAD, adaptive_spread))
        if cached_spread is None or cached_spread < 0.0 or cached_spread > continuity_spread_limit:
            print(
                f"[LIVE-SPORTS-CONTINUITY] ticker={ticker} family={family} eligibility_status=blocked "
                f"missing_count={missing_count} cache_age={round(age_seconds, 2)} prior_valid_quotes=yes "
                f"carry_forward_used=no stability_confidence={stable_cycles} cached_spread={cached_spread} "
                f"adaptive_spread={round(continuity_spread_limit, 4)} reason=cached_spread_not_safe"
            )
            self._record_live_reject_telemetry(
                reason="cached_spread_not_safe",
                ticker=ticker,
                family=family,
                spread=cached_spread,
                stage="sports_continuity",
                category="continuity",
                details={"continuity_reason": "cached_spread_not_safe", "cache_age": round(age_seconds, 2), "adaptive_spread": round(continuity_spread_limit, 4)},
            )
            return yes_bid, yes_ask, no_bid, no_ask, False, "cached_spread_not_safe"
        liquidity = self.to_float(market.get("liquidity_dollars", market.get("liquidity")), 0.0) or 0.0
        if not top_size_ok and liquidity < MIN_ENTRY_LIQUIDITY:
            print(
                f"[LIVE-SPORTS-CONTINUITY] ticker={ticker} family={family} eligibility_status=blocked "
                f"missing_count={missing_count} cache_age={round(age_seconds, 2)} prior_valid_quotes=yes "
                f"carry_forward_used=no stability_confidence={stable_cycles} top_size_ok=no liquidity={liquidity} "
                f"reason=continuity_liquidity_not_safe"
            )
            self._record_live_reject_telemetry(
                reason="continuity_liquidity_not_safe",
                ticker=ticker,
                family=family,
                spread=cached_spread,
                stage="sports_continuity",
                category="continuity",
                details={"continuity_reason": "continuity_liquidity_not_safe", "cache_age": round(age_seconds, 2), "liquidity": liquidity},
            )
            return yes_bid, yes_ask, no_bid, no_ask, False, "continuity_liquidity_not_safe"
        recovered = {
            "yes_bid": yes_bid if yes_bid is not None else cached.get("yes_bid"),
            "yes_ask": yes_ask if yes_ask is not None else cached.get("yes_ask"),
            "no_bid": no_bid if no_bid is not None else cached.get("no_bid"),
            "no_ask": no_ask if no_ask is not None else cached.get("no_ask"),
        }
        print(
            f"[LIVE-TOPBOOK-CONVERTED] ticker={ticker} family={family} raw_payload_keys={self._safe_payload_keys(market)} "
            f"detected_fields={self._get_raw_liquidity_candidate_fields(market)} yes_bid={recovered.get('yes_bid')} yes_ask={recovered.get('yes_ask')} "
            f"no_bid={recovered.get('no_bid')} no_ask={recovered.get('no_ask')} spread={cached_spread} liquidity={liquidity} "
            f"exact_reject_reason=soft_continuity_used age_seconds={round(age_seconds, 2)} top_size_ok={'yes' if top_size_ok else 'no'}"
        )
        print(
            f"[LIVE-SPORTS-CONTINUITY] ticker={ticker} family={family} eligibility_status=allowed "
            f"missing_count={missing_count} cache_age={round(age_seconds, 2)} prior_valid_quotes=yes "
            f"prior_yes_bid={cached.get('yes_bid')} prior_yes_ask={cached.get('yes_ask')} "
            f"prior_no_bid={cached.get('no_bid')} prior_no_ask={cached.get('no_ask')} "
            f"carry_forward_used=yes stability_confidence={stable_cycles} cached_spread={cached_spread} "
            f"adaptive_spread={round(continuity_spread_limit, 4)} reason=soft_continuity_used"
        )
        return recovered["yes_bid"], recovered["yes_ask"], recovered["no_bid"], recovered["no_ask"], True, "soft_continuity_used"

    def append_live_audit_log(self, event_type, **fields):
        try:
            log_path = LIVE_AUDIT_LOG_FILE
            file_exists = os.path.exists(log_path)
            fieldnames = [
                "timestamp",
                "event_type",
                "ticker",
                "order_id",
                "side",
                "action",
                "count",
                "price",
                "reason",
                "status_code",
            ]
            row = {name: "" for name in fieldnames}
            row["timestamp"] = time.strftime("%Y-%m-%d %H:%M:%S")
            row["event_type"] = event_type
            for key in fieldnames:
                if key in fields:
                    row[key] = fields[key]
            needs_header = not file_exists or os.path.getsize(log_path) == 0
            with open(log_path, "a", newline="") as csv_file:
                writer = csv.DictWriter(csv_file, fieldnames=fieldnames)
                if needs_header:
                    writer.writeheader()
                writer.writerow(row)
        except OSError:
            return

    def _learning_archive_value(self, sources, *names):
        for source in sources or []:
            if source is None:
                continue
            for name in names:
                if isinstance(source, dict):
                    value = source.get(name)
                else:
                    value = getattr(source, name, None)
                if value not in (None, ""):
                    return value
        return None

    def _learning_archive_float(self, value):
        value = self.to_float(value, None)
        return round(value, 6) if value is not None else None

    def _learning_archive_int(self, value):
        value = self.to_float(value, None)
        return int(value) if value is not None else None

    def append_aion_learning_archive_event(self, event_type, q=None, payload=None, order=None, result=None, decision=None, position=None, extra=None):
        try:
            event_type = str(event_type or "").strip().lower()
            if event_type not in {"candidate_seen", "trade_opened", "trade_closed"}:
                return {"ok": False, "reason": "unsupported_event_type"}
            payload = payload if isinstance(payload, dict) else {}
            order = order if isinstance(order, dict) else {}
            result = result if isinstance(result, dict) else {}
            decision = decision if isinstance(decision, dict) else {}
            position = position if isinstance(position, dict) else {}
            extra = extra if isinstance(extra, dict) else {}
            order_summary = self.extract_order_execution_summary(order) if order else {}
            entry_context = payload.get("entry_context") if isinstance(payload.get("entry_context"), dict) else {}
            if not entry_context and isinstance(position.get("entry_context"), dict):
                entry_context = position.get("entry_context")
            sources = [extra, payload, order_summary, position, decision, entry_context, q]
            ticker = str(self._learning_archive_value(sources, "ticker", "market_ticker") or "").strip()
            family = str(self._learning_archive_value(sources, "family") or (self.get_market_family({"ticker": ticker}) if ticker else "UNKNOWN")).strip().upper()
            side = str(self._learning_archive_value(sources, "selected_side", "side", "outcome_side") or "").strip().lower() or None
            sports_context = self._learning_archive_value(sources, "sports_edge_context", "sports_edge_ranking_context")
            sports_context = sports_context if isinstance(sports_context, dict) else {}
            structural_context = self._learning_archive_value(sources, "structural_edge_context")
            structural_context = structural_context if isinstance(structural_context, dict) else {}
            cross_market_context = (
                self._learning_archive_value(sources, "cross_market_edge_context")
                or structural_context.get("cross_market_edge_context")
            )
            cross_market_context = cross_market_context if isinstance(cross_market_context, dict) else {}
            elite_signal_context = self._learning_archive_value(sources, "elite_public_signal_context", "elite_signal_context")
            elite_signal_context = elite_signal_context if isinstance(elite_signal_context, dict) else {}
            elite_signal_payload = elite_signal_context.get("signal") if isinstance(elite_signal_context.get("signal"), dict) else {}
            elite_signal_used = bool(
                self._learning_archive_value(sources, "elite_signal_used", "elite_public_signal_match")
                or elite_signal_context.get("matched")
            )
            elite_trader_handle = (
                self._learning_archive_value(sources, "elite_trader_handle", "trader_handle")
                or elite_signal_payload.get("trader_handle")
            )
            elite_boost_used = self._learning_archive_float(
                self._learning_archive_value(sources, "elite_boost_used", "elite_public_signal_boost")
                or elite_signal_context.get("boost")
            )
            sports_tags_raw = (
                self._learning_archive_value(sources, "sports_tags", "sports_edge_tags")
                or sports_context.get("tags")
                or []
            )
            if isinstance(sports_tags_raw, str):
                sports_tags = [tag.strip() for tag in sports_tags_raw.replace(";", ",").split(",") if tag.strip()]
            elif isinstance(sports_tags_raw, (list, tuple, set)):
                sports_tags = [str(tag).strip() for tag in sports_tags_raw if str(tag or "").strip()]
            else:
                sports_tags = []
            structural_tags_raw = (
                self._learning_archive_value(sources, "structural_tags", "structural_edge_tags")
                or structural_context.get("tags")
                or []
            )
            if isinstance(structural_tags_raw, str):
                structural_tags = [tag.strip() for tag in structural_tags_raw.replace(";", ",").split(",") if tag.strip()]
            elif isinstance(structural_tags_raw, (list, tuple, set)):
                structural_tags = [str(tag).strip() for tag in structural_tags_raw if str(tag or "").strip()]
            else:
                structural_tags = []
            structural_pattern_keys_raw = (
                self._learning_archive_value(sources, "structural_pattern_keys")
                or structural_context.get("structural_pattern_keys")
                or cross_market_context.get("pattern_keys")
                or []
            )
            if isinstance(structural_pattern_keys_raw, str):
                structural_pattern_keys = [key.strip() for key in structural_pattern_keys_raw.replace(";", ",").split(",") if key.strip()]
            elif isinstance(structural_pattern_keys_raw, (list, tuple, set)):
                structural_pattern_keys = [str(key).strip() for key in structural_pattern_keys_raw if str(key or "").strip()]
            else:
                structural_pattern_keys = []
            structural_edge_score = self._learning_archive_float(
                self._learning_archive_value(sources, "STRUCTURAL_EDGE_SCORE", "structural_edge_score")
                or structural_context.get("STRUCTURAL_EDGE_SCORE")
                or structural_context.get("structural_edge_score")
            )
            cross_market_edge_score = self._learning_archive_float(
                self._learning_archive_value(sources, "CROSS_MARKET_EDGE_SCORE", "cross_market_edge_score")
                or structural_context.get("CROSS_MARKET_EDGE_SCORE")
                or cross_market_context.get("CROSS_MARKET_EDGE_SCORE")
                or cross_market_context.get("score")
            )
            elite_edge_context = (
                self._learning_archive_value(sources, "elite_edge_context")
                or structural_context.get("elite_edge_context")
            )
            elite_edge_context = elite_edge_context if isinstance(elite_edge_context, dict) else {}
            elite_edge_confidence = self._learning_archive_float(
                self._learning_archive_value(sources, "ELITE_EDGE_CONFIDENCE", "elite_edge_confidence")
                or structural_context.get("ELITE_EDGE_CONFIDENCE")
                or elite_edge_context.get("ELITE_EDGE_CONFIDENCE")
            )
            sports_score_at_entry = self._learning_archive_float(
                self._learning_archive_value(sources, "sports_score_at_entry", "sports_edge_score_at_entry", "score_at_entry")
                or sports_context.get("score_at_entry")
            )
            sports_edge_boost = self._learning_archive_float(
                self._learning_archive_value(sources, "sports_edge_boost", "sports_edge_rank_boost", "sports_edge_score_boost")
                or sports_context.get("boost")
            )
            sports_memory_context = self._learning_archive_value(sources, "sports_memory_context")
            sports_memory_context = sports_memory_context if isinstance(sports_memory_context, dict) else {}
            sports_memory_dimensions = (
                self._learning_archive_value(sources, "sports_memory_dimensions")
                or sports_memory_context.get("dimensions")
            )
            sports_memory_dimensions = sports_memory_dimensions if isinstance(sports_memory_dimensions, dict) else {}
            game_thesis_context = self._learning_archive_value(sources, "game_thesis_context")
            game_thesis_context = game_thesis_context if isinstance(game_thesis_context, dict) else {}
            sports_graph_context = self._learning_archive_value(sources, "sports_graph_context")
            sports_graph_context = sports_graph_context if isinstance(sports_graph_context, dict) else {}
            sports_ladder_context = self._learning_archive_value(sources, "sports_ladder_context")
            sports_ladder_context = sports_ladder_context if isinstance(sports_ladder_context, dict) else {}
            sports_ml_context = self._learning_archive_value(sources, "sports_ml_probability_context")
            sports_ml_context = sports_ml_context if isinstance(sports_ml_context, dict) else {}
            price = self._learning_archive_float(
                self._learning_archive_value(
                    sources,
                    "price",
                    "selected_price",
                    "selected_price_dollars",
                    "entry_price",
                    "avg_price",
                    "exit_price",
                    "current_price",
                )
            )
            contracts = self._learning_archive_int(
                self._learning_archive_value(sources, "contracts", "count", "filled_count", "size")
            )
            notional_dollars = None
            if price is not None and contracts is not None:
                notional_dollars = round(price * contracts, 6)
            if event_type == "candidate_seen":
                now_ts = time.time()
                candidate_seen_recent = getattr(self, "_aion_learning_candidate_seen_recent", {})
                if not isinstance(candidate_seen_recent, dict):
                    candidate_seen_recent = {}
                candidate_key = f"{ticker}|{side}|{price}"
                previous_seen_ts = self.to_float(candidate_seen_recent.get(candidate_key), None)
                if previous_seen_ts is not None and now_ts - previous_seen_ts < AION_LEARNING_ARCHIVE_CANDIDATE_MIN_SECONDS:
                    return {"ok": True, "skipped": True, "reason": "candidate_seen_recent"}
                candidate_seen_recent[candidate_key] = now_ts
                self._aion_learning_candidate_seen_recent = {
                    key: ts
                    for key, ts in candidate_seen_recent.items()
                    if self.to_float(ts, 0.0) and now_ts - self.to_float(ts, 0.0) <= AION_LEARNING_ARCHIVE_CANDIDATE_MIN_SECONDS
                }
            now_utc = datetime.now(timezone.utc).isoformat()
            event = {
                "event_type": event_type,
                "timestamp_utc": now_utc,
                "ticker": ticker or None,
                "market_title": self._learning_archive_value(sources, "market_title", "title"),
                "family": family or "UNKNOWN",
                "category": self.get_market_discovery_category(family or ticker or "unknown"),
                "elite_signal_used": elite_signal_used,
                "elite_trader_handle": elite_trader_handle,
                "elite_boost_used": elite_boost_used,
                "sports_memory_context": sports_memory_context,
                "sports_memory_dimensions": sports_memory_dimensions,
                "sports_memory_regime": self._learning_archive_value(sources, "sports_memory_regime") or sports_memory_context.get("regime"),
                "sports_memory_rank_adjustment": self._learning_archive_float(
                    self._learning_archive_value(sources, "sports_memory_rank_adjustment")
                    or sports_memory_context.get("rank_adjustment")
                ),
                "sports_memory_size_multiplier": self._learning_archive_float(
                    self._learning_archive_value(sources, "sports_memory_size_multiplier")
                    or sports_memory_context.get("size_multiplier")
                ),
                "game_thesis_context": game_thesis_context,
                "game_id": self._learning_archive_value(sources, "game_id") or game_thesis_context.get("game_id"),
                "game_thesis_type": self._learning_archive_value(sources, "game_thesis_type") or game_thesis_context.get("thesis_type"),
                "game_thesis_confidence": self._learning_archive_float(
                    self._learning_archive_value(sources, "game_thesis_confidence")
                    or game_thesis_context.get("thesis_confidence")
                    or game_thesis_context.get("confidence")
                ),
                "game_thesis_rank_boost": self._learning_archive_float(
                    self._learning_archive_value(sources, "game_thesis_rank_boost")
                    or game_thesis_context.get("applied_rank_boost")
                    or game_thesis_context.get("ranking_boost")
                ),
                "game_thesis_size_multiplier": self._learning_archive_float(
                    self._learning_archive_value(sources, "game_thesis_size_multiplier")
                    or game_thesis_context.get("applied_size_multiplier")
                    or game_thesis_context.get("size_multiplier")
                ),
                "sports_graph_context": sports_graph_context,
                "sports_graph_game_id": self._learning_archive_value(sources, "sports_graph_game_id") or sports_graph_context.get("game_id"),
                "sports_graph_role": self._learning_archive_value(sources, "sports_graph_role") or sports_graph_context.get("role"),
                "sports_graph_direction": self._learning_archive_value(sources, "sports_graph_direction") or sports_graph_context.get("direction"),
                "sports_graph_relationship_types": self._learning_archive_value(sources, "sports_graph_relationship_types") or sports_graph_context.get("relationship_types"),
                "sports_graph_lag_detected": bool(self._learning_archive_value(sources, "sports_graph_lag_detected") or sports_graph_context.get("lag_detected")),
                "sports_graph_rank_adjustment": self._learning_archive_float(
                    self._learning_archive_value(sources, "sports_graph_rank_adjustment")
                    or sports_graph_context.get("rank_adjustment")
                ),
                "sports_graph_size_multiplier": self._learning_archive_float(
                    self._learning_archive_value(sources, "sports_graph_size_multiplier")
                    or sports_graph_context.get("size_multiplier")
                ),
                "sports_graph_conflict_count": self._learning_archive_float(
                    self._learning_archive_value(sources, "sports_graph_conflict_count")
                    or sports_graph_context.get("conflict_count")
                ),
                "sports_ladder_context": sports_ladder_context,
                "sports_ladder_plan_id": self._learning_archive_value(sources, "sports_ladder_plan_id") or sports_ladder_context.get("plan_id"),
                "sports_ladder_role": self._learning_archive_value(sources, "sports_ladder_role") or sports_ladder_context.get("role"),
                "sports_ladder_leg_type": self._learning_archive_value(sources, "sports_ladder_leg_type") or sports_ladder_context.get("leg_type"),
                "sports_ladder_score": self._learning_archive_float(
                    self._learning_archive_value(sources, "sports_ladder_score")
                    or sports_ladder_context.get("ladder_score")
                ),
                "sports_ladder_size_cap": self._learning_archive_float(
                    self._learning_archive_value(sources, "sports_ladder_size_cap")
                    or sports_ladder_context.get("size_cap")
                ),
                "sports_ml_probability_context": sports_ml_context,
                "sports_ml_base_probability": self._learning_archive_float(
                    self._learning_archive_value(sources, "sports_ml_base_probability")
                    or sports_ml_context.get("base_probability")
                ),
                "sports_ml_probability": self._learning_archive_float(
                    self._learning_archive_value(sources, "sports_ml_probability")
                    or sports_ml_context.get("ml_probability")
                ),
                "sports_ml_final_probability": self._learning_archive_float(
                    self._learning_archive_value(sources, "sports_ml_final_probability")
                    or sports_ml_context.get("final_probability")
                ),
                "sports_ml_edge_estimate": self._learning_archive_float(
                    self._learning_archive_value(sources, "sports_ml_edge_estimate")
                    or sports_ml_context.get("edge_estimate")
                ),
                "sports_ml_rank_adjustment": self._learning_archive_float(
                    self._learning_archive_value(sources, "sports_ml_rank_adjustment")
                    or sports_ml_context.get("rank_adjustment")
                ),
                "sports_ml_size_multiplier": self._learning_archive_float(
                    self._learning_archive_value(sources, "sports_ml_size_multiplier")
                    or sports_ml_context.get("size_multiplier")
                ),
                "sports_ml_fallback_used": bool(
                    self._learning_archive_value(sources, "sports_ml_fallback_used")
                    or sports_ml_context.get("fallback_used")
                ),
            }
            if event_type in {"candidate_seen", "trade_opened"}:
                event.update(
                    {
                        "side": side,
                        "price": price,
                        "contracts": contracts,
                        "notional_dollars": notional_dollars,
                        "confidence": self._learning_archive_float(self._learning_archive_value(sources, "confidence", "confidence_score", "candidate_score", "probability_estimate")),
                        "ev_score": self._learning_archive_float(self._learning_archive_value(sources, "ev_score", "edge_after_cost", "final_edge", "final_edge_value", "sports_edge_after_cost", "expectancy_score")),
                        "kelly_fraction": self._learning_archive_float(self._learning_archive_value(sources, "kelly_fraction", "kelly_size_fraction")),
                        "liquidity_dollars": self._learning_archive_float(self._learning_archive_value(sources, "liquidity_dollars", "liquidity")),
                        "spread": self._learning_archive_float(self._learning_archive_value(sources, "spread", "spread_cents")),
                        "yes_bid": self._learning_archive_float(self._learning_archive_value(sources, "yes_bid", "yes_bid_dollars")),
                        "yes_ask": self._learning_archive_float(self._learning_archive_value(sources, "yes_ask", "yes_ask_dollars")),
                        "no_bid": self._learning_archive_float(self._learning_archive_value(sources, "no_bid", "no_bid_dollars")),
                        "no_ask": self._learning_archive_float(self._learning_archive_value(sources, "no_ask", "no_ask_dollars")),
                        "orderbook_imbalance": self._learning_archive_float(self._learning_archive_value(sources, "orderbook_imbalance", "imbalance")),
                        "entry_reason": self._learning_archive_value(sources, "entry_reason", "reason", "selector_reason", "final_block_reason"),
                        "entry_mode": self._learning_archive_value(sources, "entry_mode", "lane", "mode", "trade_mode"),
                        "phase_or_realm_source": self._learning_archive_value(sources, "phase_or_realm_source", "source", "subsystem", "selection_stage"),
                        "daily_trade_count": int(getattr(self, "live_trade_count_today", 0) or 0),
                        "max_daily_trade_cap": int(MAX_LIVE_TRADES_PER_DAY),
                        "position_id": self._learning_archive_value(sources, "position_id"),
                        "order_id": self._learning_archive_value(sources, "order_id", "id"),
                        "sports_tags": sports_tags,
                        "sports_score_at_entry": sports_score_at_entry,
                        "sports_edge_boost": sports_edge_boost,
                        "sports_implied_probability": self._learning_archive_float(
                            self._learning_archive_value(sources, "sports_implied_probability", "sports_edge_implied_probability")
                            or sports_context.get("implied_probability")
                        ),
                        "sports_payout_multiple": self._learning_archive_float(
                            self._learning_archive_value(sources, "sports_payout_multiple", "sports_edge_payout_multiple")
                            or sports_context.get("payout_multiple")
                        ),
                        "sports_family_activity_level": sports_context.get("sports_family_activity_level"),
                        "sports_data_tag": ",".join(sports_context.get("data_readiness_tags") or []) if isinstance(sports_context.get("data_readiness_tags"), list) else None,
                        "odds_bucket": sports_context.get("odds_bucket"),
                        "asymmetry_bucket": sports_context.get("asymmetry_bucket"),
                        "liquidity_bucket": sports_context.get("liquidity_bucket"),
                        "spread_bucket": sports_context.get("spread_bucket"),
                        "sport_type": sports_context.get("sport_type"),
                        "structural_edge_score": structural_edge_score,
                        "STRUCTURAL_EDGE_SCORE": structural_edge_score,
                        "cross_market_edge_score": cross_market_edge_score,
                        "CROSS_MARKET_EDGE_SCORE": cross_market_edge_score,
                        "structural_tags": structural_tags,
                        "structural_pattern_keys": structural_pattern_keys,
                        "cross_market_bucket": cross_market_context.get("cross_market_bucket"),
                        "cross_market_peer_count": cross_market_context.get("peer_count"),
                        "cross_market_reason": cross_market_context.get("reason"),
                        "elite_edge_confidence": elite_edge_confidence,
                        "ELITE_EDGE_CONFIDENCE": elite_edge_confidence,
                        "elite_edge_tier": elite_edge_context.get("tier"),
                        "elite_edge_size_multiplier": elite_edge_context.get("size_multiplier"),
                    }
                )
            else:
                close_timestamp = self._learning_archive_value(sources, "close_timestamp_utc", "closed_at", "exit_timestamp_utc") or now_utc
                pnl_dollars = self._learning_archive_float(
                    self._learning_archive_value(sources, "pnl_dollars", "realized_pnl", "realized_pnl_delta", "unrealized_pnl", "pnl")
                )
                pnl_percent = self._learning_archive_float(self._learning_archive_value(sources, "pnl_percent", "return_percent", "roi"))
                hold_seconds = self._learning_archive_float(self._learning_archive_value(sources, "hold_seconds"))
                entry_ts = self.to_float(self._learning_archive_value(sources, "entry_ts"), None)
                if hold_seconds is None and entry_ts is not None:
                    hold_seconds = round(max(0.0, time.time() - entry_ts), 3)
                if pnl_dollars is None and price is not None:
                    entry_price = self._learning_archive_float(self._learning_archive_value(sources, "entry_price", "avg_price"))
                    if entry_price is not None and contracts is not None:
                        pnl_dollars = round((price - entry_price) * contracts, 6)
                outcome = str(self._learning_archive_value(sources, "result", "outcome") or "").strip().lower()
                if not outcome and pnl_dollars is not None:
                    outcome = "win" if pnl_dollars > 0 else "loss" if pnl_dollars < 0 else "breakeven"
                won = None
                if pnl_dollars is not None:
                    won = bool(pnl_dollars > 0)
                event.update(
                    {
                        "close_timestamp_utc": close_timestamp,
                        "result": outcome or "unknown",
                        "pnl_dollars": pnl_dollars,
                        "pnl_percent": pnl_percent,
                        "exit_reason": self._learning_archive_value(sources, "exit_reason", "reason") or "unknown",
                        "hold_seconds": hold_seconds,
                        "won": won,
                        "original_confidence": self._learning_archive_float(self._learning_archive_value(sources, "original_confidence", "confidence", "confidence_score")),
                        "original_ev_score": self._learning_archive_float(self._learning_archive_value(sources, "original_ev_score", "ev_score", "edge_after_cost", "final_edge")),
                        "position_id": self._learning_archive_value(sources, "position_id"),
                        "order_id": self._learning_archive_value(sources, "order_id", "exit_order_id", "id"),
                        "sports_tags": sports_tags,
                        "sports_score_at_entry": sports_score_at_entry,
                        "sports_edge_boost": sports_edge_boost,
                        "structural_edge_score": structural_edge_score,
                        "STRUCTURAL_EDGE_SCORE": structural_edge_score,
                        "cross_market_edge_score": cross_market_edge_score,
                        "CROSS_MARKET_EDGE_SCORE": cross_market_edge_score,
                        "structural_tags": structural_tags,
                        "structural_pattern_keys": structural_pattern_keys,
                        "cross_market_bucket": cross_market_context.get("cross_market_bucket"),
                        "elite_edge_confidence": elite_edge_confidence,
                        "ELITE_EDGE_CONFIDENCE": elite_edge_confidence,
                        "elite_edge_tier": elite_edge_context.get("tier"),
                        "elite_edge_size_multiplier": elite_edge_context.get("size_multiplier"),
                        "entry_price": self._learning_archive_float(self._learning_archive_value(sources, "entry_price", "avg_price")),
                        "exit_price": price,
                        "contracts": contracts,
                        "position_size": contracts,
                        "sizing_reason": self._learning_archive_value(sources, "sizing_reason", "size_reason"),
                    }
                )
            archive_path = _Path(AION_LEARNING_ARCHIVE_FILE)
            archive_path.parent.mkdir(parents=True, exist_ok=True)
            with archive_path.open("a", encoding="utf-8") as archive_file:
                archive_file.write(json.dumps(event, sort_keys=True, separators=(",", ":"), default=str) + "\n")
            print(
                "[AION-LEARNING-ARCHIVE-WRITE] "
                + json.dumps(
                    {"event_type": event_type, "ticker": ticker or None, "path": str(archive_path)},
                    sort_keys=True,
                    default=str,
                )
            )
            if sports_tags or self._is_sports_market_or_family(family):
                print(
                    "[AION-SPORTS-LEARN] "
                    + json.dumps(
                        {
                            "event_type": event_type,
                            "ticker": ticker or None,
                            "family": family or "UNKNOWN",
                            "tags": sports_tags,
                            "score_at_entry": sports_score_at_entry,
                            "pnl_dollars": event.get("pnl_dollars"),
                            "result": event.get("result"),
                        },
                        sort_keys=True,
                        default=str,
                    )
                )
            if structural_tags or structural_edge_score or cross_market_edge_score:
                print(
                    "[AION-STRUCTURAL-LEARN] "
                    + json.dumps(
                        {
                            "event_type": event_type,
                            "ticker": ticker or None,
                            "family": family or "UNKNOWN",
                            "STRUCTURAL_EDGE_SCORE": structural_edge_score,
                            "CROSS_MARKET_EDGE_SCORE": cross_market_edge_score,
                            "ELITE_EDGE_CONFIDENCE": elite_edge_confidence,
                            "tags": structural_tags[:8],
                            "pnl_dollars": event.get("pnl_dollars"),
                            "result": event.get("result"),
                        },
                        sort_keys=True,
                        default=str,
                    )
                )
            self._record_aion_distilled_memory_event(event_type, event)
            if event_type == "trade_closed":
                self._record_sports_memory_trade_event(event)
            try:
                self._export_obsidian_learning_event(event_type, event)
            except Exception as obsidian_exc:
                try:
                    print(
                        "[OBSIDIAN-EXPORT-ERROR] "
                        + json.dumps(
                            {
                                "action": "learning_archive_event",
                                "event_type": event_type,
                                "reason": obsidian_exc.__class__.__name__,
                            },
                            sort_keys=True,
                            default=str,
                        )
                    )
                except Exception:
                    pass
            return {"ok": True, "path": str(archive_path), "event_type": event_type}
        except Exception as exc:
            try:
                print(
                    "[AION-LEARNING-ARCHIVE-WARN] "
                    + json.dumps(
                        {"event_type": str(event_type or "unknown"), "reason": exc.__class__.__name__, "path": str(AION_LEARNING_ARCHIVE_FILE)},
                        sort_keys=True,
                        default=str,
                    )
                )
            except Exception:
                pass
            return {"ok": False, "reason": exc.__class__.__name__}

