    def load_live_position_state(self):
        if not os.path.exists(LIVE_POSITION_STATE_FILE):
            return {}
        try:
            with open(LIVE_POSITION_STATE_FILE) as state_file:
                data = json.load(state_file)
            return data if isinstance(data, dict) else {}
        except (OSError, ValueError, TypeError):
            print(f"[LIVE-STATE] warning unable_to_load path={LIVE_POSITION_STATE_FILE}")
            return {}

    def save_live_position_state(self, state):
        try:
            ok = bool(
                callable(safe_atomic_json_write)
                and safe_atomic_json_write(LIVE_POSITION_STATE_FILE, state if isinstance(state, dict) else {})
            )
            if callable(record_persist_event):
                record_persist_event(
                    subsystem="LIVE-STATE",
                    path=LIVE_POSITION_STATE_FILE,
                    action="persist_state",
                    success=ok,
                    reason=None if ok else "write_failed",
                )
            if not ok:
                print(f"[LIVE-STATE] warning unable_to_save path={LIVE_POSITION_STATE_FILE}")
        except OSError:
            print(f"[LIVE-STATE] warning unable_to_save path={LIVE_POSITION_STATE_FILE}")

    def _get_aion_expectancy_state_path(self):
        if callable(runtime_state_file):
            try:
                return runtime_state_file("aion_expectancy_state.json")
            except Exception:
                pass
        return os.path.join(os.path.dirname(os.path.abspath(__file__)), "runtime", "state", "aion_expectancy_state.json")

