    def _refresh_probability_intelligence(self, source="live", markets=None, quotes=None, selected_quote=None, live_select_summary=None, force=False):
        engine = getattr(self, "realm_xxiii_engine", None)
        if engine is None or not getattr(engine, "enabled", False):
            return None
        try:
            enriched_markets = []
            for market in markets or []:
                if isinstance(market, dict):
                    enriched_market = dict(market)
                    if not str(enriched_market.get("family") or "").strip():
                        enriched_market["family"] = self.get_market_family(enriched_market)
                    enriched_markets.append(enriched_market)
            if not enriched_markets:
                enriched_markets = markets or []
            selected = selected_quote
            if selected is None and quotes:
                selected = quotes[0]
            personality_context = self._get_personality_snapshot(
                market=enriched_markets[0] if enriched_markets else None,
                q=selected,
                family=self.get_market_family(enriched_markets[0]) if enriched_markets else "UNKNOWN",
                ws_snapshot=self._get_websocket_snapshot(getattr(selected, "ticker", None), market=enriched_markets[0] if enriched_markets else None) if selected is not None else {},
                live_select_summary=live_select_summary or {},
                stage_label=source,
            )
            summary = engine.evaluate_market(
                market=enriched_markets[0] if enriched_markets else {},
                quote=selected,
                personality_context=personality_context or {},
                websocket_manager=getattr(self, "websocket_manager", None),
                source=source,
            )
            self.last_realm_xxiii_summary = summary or {}
            return summary
        except AttributeError:
            print(f"[REALM-XXIII-DEGRADED] source={source} reason=telemetry_mismatch")
            return None
        except Exception as exc:
            print(f"[REALM-XXIII-ERROR] reason={exc.__class__.__name__} source={source}")
            return None

