    def get_live_submit_authorization(self, payload=None):
        return kalshi_risk_module.get_live_submit_authorization(
            self,
            payload,
            live_test_ticker=globals().get("LIVE_TEST_TICKER"),
        )

    def prune_live_position_state(self, active_tickers=None):
        active_tickers = {
            str(ticker or "").strip()
            for ticker in (active_tickers or [])
            if str(ticker or "").strip()
        }
        tracked_open_tickers = {
            str(position.get("ticker") or "").strip()
            for position in self.live_positions
            if isinstance(position, dict)
            and str(position.get("ticker") or "").strip()
            and str(position.get("status", "open") or "open").strip().lower() == "open"
        }
        keep_tickers = active_tickers | tracked_open_tickers
        state = self.load_live_position_state()
        removed = []
        for ticker in list(state.keys()):
            if ticker not in keep_tickers:
                removed.append(ticker)
                state.pop(ticker, None)
        if removed:
            print(f"[LIVE-STATE-PRUNE] removed={removed} keep_count={len(keep_tickers)}")
            self.save_live_position_state(state)
        return removed

    def normalize_contract_price(self, price, ticker=None, source="unknown"):
        if price is None:
            print(
                f"[LIVE-PRICE-NORMALIZE] ticker={ticker or 'UNKNOWN'} source={source} "
                f"raw_pre=None normalized_price=None action=rejected"
            )
            return None
        try:
            numeric_price = float(price)
        except (TypeError, ValueError):
            print(
                f"[LIVE-PRICE-NORMALIZE] ticker={ticker or 'UNKNOWN'} source={source} "
                f"raw_pre={price} normalized_price=None action=rejected"
            )
            return None
        if 0 < numeric_price <= 1:
            normalized_price = round(numeric_price, 4)
            action = "kept"
        elif 1 < numeric_price <= 100:
            normalized_price = round(numeric_price / 100.0, 4)
            action = "divided_by_100"
        else:
            normalized_price = None
            action = "rejected"
        print(
            f"[LIVE-PRICE-NORMALIZE] ticker={ticker or 'UNKNOWN'} source={source} "
            f"raw_pre={numeric_price} normalized_price={normalized_price} action={action}"
        )
        return normalized_price

    def _resolve_aion_canonical_binary_prices(self, source=None, *, ticker=None, source_label="unknown"):
        source_dict = self._coerce_aion_orderbook_source(source)
        ticker_text = str(ticker or source_dict.get("ticker") or "").strip()

        def _normalized_price(raw_value, key_label):
            normalized = self.normalize_contract_price(
                raw_value,
                ticker=ticker_text or None,
                source=f"{source_label}.{key_label}",
            )
            return self.to_float(normalized, None)

        raw_yes_bid = source_dict.get(
            "yes_bid_dollars",
            source_dict.get("yes_bid", source_dict.get("best_yes_bid", source_dict.get("yes_top_price"))),
        )
        raw_yes_ask = source_dict.get(
            "yes_ask_dollars",
            source_dict.get("yes_ask", source_dict.get("best_yes_ask")),
        )
        raw_no_bid = source_dict.get(
            "no_bid_dollars",
            source_dict.get("no_bid", source_dict.get("best_no_bid", source_dict.get("no_top_price"))),
        )
        raw_no_ask = source_dict.get(
            "no_ask_dollars",
            source_dict.get("no_ask", source_dict.get("best_no_ask")),
        )

        yes_bid = _normalized_price(raw_yes_bid, "yes_bid")
        yes_ask = _normalized_price(raw_yes_ask, "yes_ask")
        no_bid = _normalized_price(raw_no_bid, "no_bid")
        no_ask = _normalized_price(raw_no_ask, "no_ask")

        derived_yes_bid = False
        derived_yes_ask = False
        derived_no_bid = False
        derived_no_ask = False

        if yes_ask is None and no_bid is not None:
            yes_ask = self._clamp(1.0 - no_bid, 0.0, 1.0)
            derived_yes_ask = True
        if no_ask is None and yes_bid is not None:
            no_ask = self._clamp(1.0 - yes_bid, 0.0, 1.0)
            derived_no_ask = True
        if yes_bid is None and no_ask is not None:
            yes_bid = self._clamp(1.0 - no_ask, 0.0, 1.0)
            derived_yes_bid = True
        if no_bid is None and yes_ask is not None:
            no_bid = self._clamp(1.0 - yes_ask, 0.0, 1.0)
            derived_no_bid = True

        yes_bid_cents = int(round(yes_bid * 100.0)) if yes_bid is not None else None
        yes_ask_cents = int(round(yes_ask * 100.0)) if yes_ask is not None else None
        no_bid_cents = int(round(no_bid * 100.0)) if no_bid is not None else None
        no_ask_cents = int(round(no_ask * 100.0)) if no_ask is not None else None

        yes_spread = round(max(0.0, yes_ask - yes_bid), 4) if yes_bid is not None and yes_ask is not None else None
        no_spread = round(max(0.0, no_ask - no_bid), 4) if no_bid is not None and no_ask is not None else None
        spread = yes_spread if yes_spread is not None else no_spread
        book_valid = bool(
            yes_bid is not None and yes_ask is not None and no_bid is not None and no_ask is not None
            and 0.0 <= yes_bid <= 1.0 and 0.0 <= yes_ask <= 1.0 and 0.0 <= no_bid <= 1.0 and 0.0 <= no_ask <= 1.0
        )
        normalized_consistent = bool(
            yes_bid is not None and yes_ask is not None and no_bid is not None and no_ask is not None
            and abs((yes_bid + no_ask) - 1.0) <= 0.02 and abs((no_bid + yes_ask) - 1.0) <= 0.02
        )
        return {
            "ticker": ticker_text or None,
            "raw_yes_bid": self.to_float(raw_yes_bid, None),
            "raw_yes_ask": self.to_float(raw_yes_ask, None),
            "raw_no_bid": self.to_float(raw_no_bid, None),
            "raw_no_ask": self.to_float(raw_no_ask, None),
            "yes_bid": yes_bid,
            "yes_ask": yes_ask,
            "no_bid": no_bid,
            "no_ask": no_ask,
            "yes_bid_cents": yes_bid_cents,
            "yes_ask_cents": yes_ask_cents,
            "no_bid_cents": no_bid_cents,
            "no_ask_cents": no_ask_cents,
            "derived_yes_bid": derived_yes_bid,
            "derived_yes_ask": derived_yes_ask,
            "derived_no_bid": derived_no_bid,
            "derived_no_ask": derived_no_ask,
            "yes_spread": yes_spread,
            "no_spread": no_spread,
            "spread": spread,
            "book_valid": book_valid,
            "normalized_consistent": normalized_consistent,
            "source_label": source_label,
        }

    def _resolve_aion_canonical_spread_context(self, *, market=None, q=None, payload=None, quote_diag=None, selected_side=None, source_label="unknown"):
        market = market if isinstance(market, dict) else {}
        payload = payload if isinstance(payload, dict) else {}
        quote_diag = quote_diag if isinstance(quote_diag, dict) else {}
        q = q if q is not None else None
        def _q_get(obj, *names, default=None):
            if obj is None:
                return default
            for name in names:
                if isinstance(obj, dict):
                    value = obj.get(name)
                else:
                    value = getattr(obj, name, None)
                if value is not None:
                    return value
            return default
        ticker = str(
            _q_get(q, "ticker", default="")
            or payload.get("ticker", "")
            or market.get("ticker", "")
            or quote_diag.get("ticker", "")
            or ""
        ).strip() or None
        family = str(
            quote_diag.get("family")
            or market.get("family")
            or (self.get_market_family(market) if market else None)
            or getattr(q, "family", "")
            or "UNKNOWN"
        ).strip().upper() or "UNKNOWN"

        def _pick(*values):
            for value in values:
                if value is None:
                    continue
                if isinstance(value, str) and not value.strip():
                    continue
                return value
            return None

        def _as_bool(value, default=None):
            if value is None:
                return default
            if isinstance(value, bool):
                return value
            if isinstance(value, (int, float)):
                return bool(value)
            if isinstance(value, str):
                normalized = value.strip().lower()
                if normalized in {"true", "1", "yes", "y", "on"}:
                    return True
                if normalized in {"false", "0", "no", "n", "off", "none", "null", ""}:
                    return False
            return bool(value)

        def _normalize_price(raw_value, field_label):
            normalized = self.normalize_contract_price(
                raw_value,
                ticker=ticker or None,
                source=f"{source_label}.{field_label}",
            )
            price = self.to_float(normalized, None)
            return price if price is not None and price > 0.0 else None

        selected_side_value = str(
            selected_side
            or _q_get(q, "selected_side")
            or _q_get(q, "side")
            or payload.get("selected_side")
            or quote_diag.get("selected_side")
            or ""
        ).strip().lower() or None
        raw_selected_price = _pick(
            _q_get(q, "selected_price"),
            _q_get(q, "selected_price_dollars"),
            payload.get("selected_price"),
            payload.get("selected_price_dollars"),
            quote_diag.get("selected_price"),
            quote_diag.get("selected_price_dollars"),
        )
        selected_price = _normalize_price(raw_selected_price, "selected_price")
        selected_price_cents = _pick(
            payload.get("selected_price_cents"),
            _q_get(q, "selected_price_cents"),
            quote_diag.get("selected_price_cents"),
        )
        try:
            if selected_price_cents not in (None, ""):
                selected_price_cents = int(round(float(selected_price_cents)))
        except (TypeError, ValueError):
            selected_price_cents = None

        yes_bid = _normalize_price(
            _pick(
                _q_get(q, "yes_bid"),
                _q_get(q, "yes_bid_dollars"),
                payload.get("yes_bid"),
                payload.get("yes_bid_dollars"),
                market.get("yes_bid_dollars"),
                market.get("yes_bid"),
                quote_diag.get("yes_bid"),
                quote_diag.get("yes_bid_dollars"),
            ),
            "yes_bid",
        )
        yes_ask = _normalize_price(
            _pick(
                _q_get(q, "yes_ask"),
                _q_get(q, "yes_ask_dollars"),
                payload.get("yes_ask"),
                payload.get("yes_ask_dollars"),
                market.get("yes_ask_dollars"),
                market.get("yes_ask"),
                quote_diag.get("yes_ask"),
                quote_diag.get("yes_ask_dollars"),
            ),
            "yes_ask",
        )
        no_bid = _normalize_price(
            _pick(
                _q_get(q, "no_bid"),
                _q_get(q, "no_bid_dollars"),
                payload.get("no_bid"),
                payload.get("no_bid_dollars"),
                market.get("no_bid_dollars"),
                market.get("no_bid"),
                quote_diag.get("no_bid"),
                quote_diag.get("no_bid_dollars"),
            ),
            "no_bid",
        )
        no_ask = _normalize_price(
            _pick(
                _q_get(q, "no_ask"),
                _q_get(q, "no_ask_dollars"),
                payload.get("no_ask"),
                payload.get("no_ask_dollars"),
                market.get("no_ask_dollars"),
                market.get("no_ask"),
                quote_diag.get("no_ask"),
                quote_diag.get("no_ask_dollars"),
            ),
            "no_ask",
        )
        yes_top_price = _normalize_price(
            _pick(
                market.get("yes_top_price"),
                quote_diag.get("yes_top_price"),
                quote_diag.get("top_yes_price"),
                payload.get("yes_top_price"),
                _q_get(q, "yes_top_price"),
            ),
            "yes_top_price",
        )
        no_top_price = _normalize_price(
            _pick(
                market.get("no_top_price"),
                quote_diag.get("no_top_price"),
                quote_diag.get("top_no_price"),
                payload.get("no_top_price"),
                _q_get(q, "no_top_price"),
            ),
            "no_top_price",
        )
        yes_top_size = self.to_float(
            _pick(
                market.get("yes_top_size"),
                quote_diag.get("yes_top_size"),
                payload.get("yes_top_size"),
                _q_get(q, "yes_top_size"),
            ),
            None,
        )
        no_top_size = self.to_float(
            _pick(
                market.get("no_top_size"),
                quote_diag.get("no_top_size"),
                payload.get("no_top_size"),
                _q_get(q, "no_top_size"),
            ),
            None,
        )
        source_fields_checked = [
            "q.selected_price",
            "q.selected_price_dollars",
            "q.selected_price_cents",
            "q.selected_side",
            "q.side",
            "q.yes_bid",
            "q.yes_ask",
            "q.no_bid",
            "q.no_ask",
            "q.yes_top_price",
            "q.no_top_price",
            "q.yes_top_size",
            "q.no_top_size",
            "payload.selected_price",
            "payload.selected_price_dollars",
            "payload.selected_price_cents",
            "payload.selected_side",
            "payload.yes_bid",
            "payload.yes_ask",
            "payload.no_bid",
            "payload.no_ask",
            "payload.yes_top_price",
            "payload.no_top_price",
            "market.yes_bid_dollars",
            "market.yes_ask_dollars",
            "market.no_bid_dollars",
            "market.no_ask_dollars",
            "market.yes_top_price",
            "market.no_top_price",
            "market.yes_top_size",
            "market.no_top_size",
            "quote_diag.yes_bid",
            "quote_diag.yes_ask",
            "quote_diag.no_bid",
            "quote_diag.no_ask",
            "quote_diag.yes_top_price",
            "quote_diag.no_top_price",
            "quote_diag.yes_top_size",
            "quote_diag.no_top_size",
        ]
        spread = None
        spread_cents = None
        spread_source = None
        spread_reason = None
        computed_spread_attempted = False
        fallback_attempted = False
        spread_missing_fields = []
        spread_candidate_details = []

        def _pair_spread(pair_label, bid_value, ask_value):
            if orderbook_health_compute_pair_spread is not None:
                return orderbook_health_compute_pair_spread(pair_label, bid_value, ask_value)
            pair_missing_fields = []
            if bid_value is None:
                pair_missing_fields.append(f"{pair_label}_bid")
            if ask_value is None:
                pair_missing_fields.append(f"{pair_label}_ask")
            if pair_missing_fields:
                return None, pair_missing_fields, "missing_bid_ask"
            try:
                bid_float = float(bid_value)
                ask_float = float(ask_value)
            except (TypeError, ValueError):
                return None, [f"{pair_label}_bid", f"{pair_label}_ask"], "non_numeric_bid_ask"
            if bid_float <= 0.0 or ask_float <= 0.0:
                return None, [f"{pair_label}_bid", f"{pair_label}_ask"], "fake_book"
            if ask_float < bid_float:
                return None, [f"{pair_label}_bid", f"{pair_label}_ask"], "inverted_bid_ask"
            return round(max(0.0, ask_float - bid_float), 4), [], None

        def _topbook_spread(yes_top_price_value, no_top_price_value):
            if orderbook_health_compute_topbook_spread is not None:
                return orderbook_health_compute_topbook_spread(yes_top_price_value, no_top_price_value)
            if yes_top_price_value is None or no_top_price_value is None:
                missing = []
                if yes_top_price_value is None:
                    missing.append("yes_top_price")
                if no_top_price_value is None:
                    missing.append("no_top_price")
                return None, missing, "missing_topbook_pair"
            try:
                yes_top_float = float(yes_top_price_value)
                no_top_float = float(no_top_price_value)
            except (TypeError, ValueError):
                return None, ["yes_top_price", "no_top_price"], "non_numeric_topbook_pair"
            if yes_top_float <= 0.0 or no_top_float <= 0.0:
                return None, ["yes_top_price", "no_top_price"], "fake_topbook"
            raw_spread_value = yes_top_float + no_top_float - 1.0
            if raw_spread_value < 0.0:
                return None, ["yes_top_price", "no_top_price"], "inverted_topbook_pair"
            spread_value = round(raw_spread_value, 4)
            return spread_value, [], None

        selected_side_preference = selected_side_value if selected_side_value in {"yes", "no"} else None
        pair_order = []
        if selected_side_preference == "yes":
            pair_order = [("yes", yes_bid, yes_ask), ("no", no_bid, no_ask)]
        elif selected_side_preference == "no":
            pair_order = [("no", no_bid, no_ask), ("yes", yes_bid, yes_ask)]
        else:
            pair_order = [("yes", yes_bid, yes_ask), ("no", no_bid, no_ask)]

        for pair_label, bid_value, ask_value in pair_order:
            computed_spread_attempted = True
            pair_spread, pair_missing_fields, pair_reason = _pair_spread(pair_label, bid_value, ask_value)
            if pair_spread is not None:
                spread = pair_spread
                if pair_order and pair_label != pair_order[0][0]:
                    fallback_attempted = True
                if selected_side_preference is None:
                    spread_source = "yes_bid_yes_ask" if pair_label == "yes" else "no_bid_no_ask"
                elif pair_label == selected_side_preference:
                    spread_source = f"selected_side_{pair_label}"
                else:
                    spread_source = f"opposite_side_{pair_label}"
                spread_reason = pair_reason or "bid_ask_pair"
                break
            if pair_reason is not None:
                spread_candidate_details.append(
                    {
                        "pair": pair_label,
                        "reason": pair_reason,
                        "missing_fields": pair_missing_fields,
                    }
                )

        if spread is None:
            fallback_attempted = True
            topbook_spread, topbook_missing_fields, topbook_reason = _topbook_spread(yes_top_price, no_top_price)
            if topbook_spread is not None:
                spread = topbook_spread
                spread_source = "topbook_yes_no_prices"
                spread_reason = topbook_reason or "topbook_complement"
            elif topbook_reason is not None:
                spread_candidate_details.append(
                    {
                        "pair": "topbook",
                        "reason": topbook_reason,
                        "missing_fields": topbook_missing_fields,
                    }
                )

        if spread is not None:
            try:
                spread_cents = int(round(float(spread) * 100.0))
            except (TypeError, ValueError):
                spread_cents = None
            print(
                "[AION-SPREAD-COMPUTED] "
                + json.dumps(
                    {
                        "ticker": ticker,
                        "family": family,
                        "caller": source_label,
                        "selected_side": selected_side_value,
                        "selected_price": selected_price,
                        "selected_price_cents": selected_price_cents,
                        "yes_bid": yes_bid,
                        "yes_ask": yes_ask,
                        "no_bid": no_bid,
                        "no_ask": no_ask,
                        "yes_top_price": yes_top_price,
                        "no_top_price": no_top_price,
                        "spread": spread,
                        "spread_cents": spread_cents,
                        "source": spread_source,
                        "reason": spread_reason or "computed",
                    },
                    sort_keys=True,
                    default=str,
                )
            )
        else:
            if not spread_candidate_details:
                spread_candidate_details.append(
                    {
                        "pair": "selected_side",
                        "reason": "missing_bid_ask",
                        "missing_fields": ["yes_bid", "yes_ask", "no_bid", "no_ask", "yes_top_price", "no_top_price"],
                    }
                )
            spread_missing_fields = []
            for detail in spread_candidate_details:
                spread_missing_fields.extend(detail.get("missing_fields") or [])
            spread_missing_fields = list(dict.fromkeys(spread_missing_fields))
            spread_reason = spread_candidate_details[0].get("reason") if spread_candidate_details else "missing_bid_ask"
            exact_missing_field = spread_missing_fields[0] if spread_missing_fields else (spread_reason or "missing_spread")
            self._emit_aion_spread_missing_detail_trace(
                caller=source_label,
                return_path=f"{source_label}.missing_spread",
                ticker=ticker,
                family=family,
                selected_side=selected_side_value,
                selected_price=selected_price,
                yes_bid=yes_bid,
                yes_ask=yes_ask,
                no_bid=no_bid,
                no_ask=no_ask,
                spread_cents=spread_cents,
                exact_missing_field=exact_missing_field,
                computed_spread_attempted=computed_spread_attempted,
                fallback_attempted=fallback_attempted,
                spread_missing_fields=spread_missing_fields,
                source_fields_checked=source_fields_checked,
            )
        print(
            "[AION-SPREAD-FINAL] "
            + json.dumps(
                {
                    "ticker": ticker,
                    "family": family,
                    "caller": source_label,
                    "selected_side": selected_side_value,
                    "selected_price": selected_price,
                    "selected_price_cents": selected_price_cents,
                    "yes_bid": yes_bid,
                    "yes_ask": yes_ask,
                    "no_bid": no_bid,
                    "no_ask": no_ask,
                    "yes_top_price": yes_top_price,
                    "no_top_price": no_top_price,
                    "spread": spread,
                    "spread_cents": spread_cents,
                    "spread_source": spread_source,
                    "spread_present": bool(spread is not None),
                    "computed_spread_attempted": bool(computed_spread_attempted),
                    "fallback_attempted": bool(fallback_attempted),
                    "spread_missing_fields": spread_missing_fields,
                    "reason": spread_reason or ("computed" if spread is not None else "missing_spread"),
                },
                sort_keys=True,
                default=str,
            )
        )
        return {
            "ticker": ticker,
            "family": family,
            "selected_side": selected_side_value,
            "selected_price": selected_price,
            "selected_price_cents": selected_price_cents,
            "yes_bid": yes_bid,
            "yes_ask": yes_ask,
            "no_bid": no_bid,
            "no_ask": no_ask,
            "yes_top_price": yes_top_price,
            "no_top_price": no_top_price,
            "yes_top_size": yes_top_size,
            "no_top_size": no_top_size,
            "spread": spread,
            "spread_cents": spread_cents,
            "spread_source": spread_source,
            "spread_reason": spread_reason,
            "spread_ready": bool(spread is not None and spread >= 0.0),
            "spread_present": bool(spread is not None),
            "computed_spread_attempted": bool(computed_spread_attempted),
            "fallback_attempted": bool(fallback_attempted),
            "spread_missing_fields": spread_missing_fields,
            "source_fields_checked": source_fields_checked,
            "source_label": source_label,
        }

    def persist_live_entry_metadata(self, order=None, payload=None, order_id=None):
        summary = self.extract_order_execution_summary(order or {})
        ticker = (summary.get("ticker") or (payload or {}).get("ticker") or "").strip()
        side = summary.get("side") or (payload or {}).get("side")
        entry_price = summary.get("price")
        if entry_price is None and payload:
            entry_price = payload.get("yes_price")
            if entry_price is None:
                entry_price = payload.get("no_price")
        count = summary.get("filled_count")
        if count is None and payload:
            try:
                count = float(payload.get("count"))
            except (TypeError, ValueError):
                count = None
        if not ticker or not side or count in (None, 0):
            return
        entry_price = self.normalize_contract_price(entry_price, ticker=ticker, source="persist_live_entry_metadata")
        state = self.load_live_position_state()
        entry_context = (payload or {}).get("entry_context")
        state[ticker] = {
            "ticker": ticker,
            "side": side,
            "entry_price": entry_price,
            "count": count,
            "entry_ts": time.time(),
            "order_id": summary.get("order_id") or order_id,
            "entry_context": entry_context if isinstance(entry_context, dict) else None,
            "aion_relaxation_used": bool((payload or {}).get("aion_relaxation_used")),
            "aion_relaxation_reason": (payload or {}).get("aion_relaxation_reason"),
        }
        self.save_live_position_state(state)

    def remove_live_entry_metadata(self, ticker):
        ticker = (ticker or "").strip()
        if not ticker:
            return
        state = self.load_live_position_state()
        if ticker in state:
            state.pop(ticker, None)
            self.save_live_position_state(state)

    def get_live_entry_metadata(self, ticker):
        ticker = (ticker or "").strip()
        state = self.load_live_position_state()
        entry = state.get(ticker)
        print(
            f"[LIVE-STATE-LOOKUP] ticker={ticker} "
            f"found={'yes' if isinstance(entry, dict) else 'no'} keys={sorted(list(state.keys()))[:10]}"
        )
        return entry if isinstance(entry, dict) else None

    def upsert_live_entry_metadata_from_position(self, position_summary):
        ticker = (position_summary.get("ticker") or "").strip()
        count = position_summary.get("count")
        if not ticker or count is None or abs(count) == 0:
            return None
        state = self.load_live_position_state()
        existing = state.get(ticker) if isinstance(state.get(ticker), dict) else None
        updated_ts = position_summary.get("updated_ts")
        source = "last_updated_ts" if updated_ts is not None else "now"
        entry_ts = updated_ts if updated_ts is not None else time.time()
        if existing and existing.get("entry_ts") is not None:
            entry_ts = existing.get("entry_ts")
        elif not existing:
            print(f"[LIVE-STATE-BACKFILL] ticker={ticker} entry_ts={entry_ts} source={source}")
        normalized_avg_price = self.normalize_contract_price(
            position_summary.get("avg_price"),
            ticker=ticker,
            source="upsert_live_entry_metadata_from_position.avg_price",
        )
        selected_entry_price = normalized_avg_price
        if existing:
            existing_entry_price = self.normalize_contract_price(
                existing.get("entry_price"),
                ticker=ticker,
                source="upsert_live_entry_metadata_from_position.existing_entry_price",
            )
            if existing_entry_price is not None and 0 < existing_entry_price <= 1:
                selected_entry_price = existing_entry_price
        state[ticker] = {
            "ticker": ticker,
            "side": position_summary.get("side"),
            "entry_price": selected_entry_price,
            "count": count,
            "entry_ts": entry_ts,
            "last_update_ts": updated_ts if updated_ts is not None else time.time(),
            "entry_context": position_summary.get("entry_context") if isinstance(position_summary.get("entry_context"), dict) else existing.get("entry_context") if isinstance(existing, dict) else None,
            "aion_relaxation_used": bool(existing.get("aion_relaxation_used")) if isinstance(existing, dict) else False,
            "aion_relaxation_reason": existing.get("aion_relaxation_reason") if isinstance(existing, dict) else None,
        }
        self.save_live_position_state(state)
        return state[ticker]

    def print_recent_live_audit_entries(self, last_n=5):
        if not os.path.exists(LIVE_AUDIT_LOG_FILE):
            print("[LIVE-AUDIT] no audit log found")
            return
        try:
            with open(LIVE_AUDIT_LOG_FILE, newline="") as csv_file:
                rows = list(csv.DictReader(csv_file))
        except OSError:
            print("[LIVE-AUDIT] unable to read audit log")
            return
        if not rows:
            print("[LIVE-AUDIT] no audit log found")
            return
        recent_rows = rows[-last_n:]
        print(f"[LIVE-AUDIT] showing last {len(recent_rows)} entries")
        for row in recent_rows:
            print(
                f"[LIVE-AUDIT] {row.get('timestamp', '')} | {row.get('event_type', '')} | "
                f"ticker={row.get('ticker', '')} | order_id={row.get('order_id', '')} | "
                f"reason={row.get('reason', '')}"
            )

    def print_live_startup_checklist(self, args=None):
        config_status = self.get_live_config_status()
        effective_live_dry_run = compute_effective_live_dry_run()
        canary_required = bool(args is not None and getattr(args, "run_live_canary", False))
        canary_ticker_ok = (not canary_required) or bool(
            getattr(args, "live_test_ticker", None) or globals().get("LIVE_TEST_TICKER")
        )
        canary_available_ok = (not canary_required) or (not self.live_canary_submitted)
        checks = [
            ("LIVE_MODE", bool(globals().get("LIVE_MODE", False))),
            ("LIVE_ARMED", bool(globals().get("LIVE_ARMED", False))),
            ("ENV_CONFIRMED", bool(globals().get("LIVE_ENV_CONFIRMED", False))),
            ("EFFECTIVE_DRY_RUN", bool(effective_live_dry_run)),
            ("CONFIG_READY", bool(config_status.get("ok"))),
            ("AUTH_READY", bool(self.can_build_live_auth())),
            ("ORDER_API_PATH", bool(self.has_live_order_api_path())),
            ("RATE_LIMIT_CONFIG", bool(LIVE_ORDER_RATE_LIMIT and LIVE_ORDER_RATE_WINDOW_SEC)),
            ("DAILY_CAP_CONFIG", bool(MAX_LIVE_TRADES_PER_DAY)),
            ("SIZE_CAP_CONFIG", bool(MAX_LIVE_ORDER_SIZE)),
            ("CANARY_TICKER", canary_ticker_ok),
            ("CANARY_AVAILABLE", canary_available_ok),
        ]
        for name, ok in checks:
            print(f"[LIVE-CHECK] {name}: {'PASS' if ok else 'FAIL'}")

    def run_live_preflight(self, args=None):
        print("[LIVE-PREFLIGHT] starting")
        config_status = self.get_live_config_status()
        effective_live_dry_run = compute_effective_live_dry_run()
        canary_required = bool(args is not None and getattr(args, "run_live_canary", False))
        canary_ticker_ok = (not canary_required) or bool(
            getattr(args, "live_test_ticker", None) or globals().get("LIVE_TEST_TICKER")
        )
        canary_available_ok = (not canary_required) or (not self.live_canary_submitted)
        checks = {
            "LIVE_MODE": bool(globals().get("LIVE_MODE", False)),
            "LIVE_ARMED": bool(globals().get("LIVE_ARMED", False)),
            "ENV_CONFIRMED": bool(globals().get("LIVE_ENV_CONFIRMED", False)),
            "EFFECTIVE_DRY_RUN": bool(effective_live_dry_run),
            "CONFIG_READY": bool(config_status.get("ok")),
            "AUTH_READY": bool(self.can_build_live_auth()),
            "ORDER_API_PATH": bool(self.has_live_order_api_path()),
            "RATE_LIMIT_CONFIG": bool(LIVE_ORDER_RATE_LIMIT and LIVE_ORDER_RATE_WINDOW_SEC),
            "DAILY_CAP_CONFIG": bool(MAX_LIVE_TRADES_PER_DAY),
            "SIZE_CAP_CONFIG": bool(MAX_LIVE_ORDER_SIZE),
            "CANARY_TICKER": canary_ticker_ok,
            "CANARY_AVAILABLE": canary_available_ok,
        }
        for name, ok in checks.items():
            print(f"[LIVE-PREFLIGHT] {name}={'PASS' if ok else 'FAIL'}")
        required_checks = (
            "LIVE_MODE",
            "LIVE_ARMED",
            "ENV_CONFIRMED",
            "CONFIG_READY",
            "AUTH_READY",
            "ORDER_API_PATH",
            "RATE_LIMIT_CONFIG",
            "DAILY_CAP_CONFIG",
            "SIZE_CAP_CONFIG",
        )
        if canary_required:
            required_checks = required_checks + ("CANARY_TICKER", "CANARY_AVAILABLE")
        ready = all(checks[name] for name in required_checks)
        print(f"[LIVE-PREFLIGHT] {'READY' if ready else 'NOT READY'}")
        return {
            "ok": ready,
            "reason": "ready" if ready else "not_ready",
            "checks": checks,
        }

    def build_quote(self, market):
        ticker = market.get("ticker", "N/A")
        title = market.get("title") or market.get("subtitle") or "Untitled"
        family = self.get_market_family(market)
        is_sports_family = self._is_sports_market_or_family(family)

        def _normalize_price_like(value):
            numeric = self.to_float(value, None)
            if numeric is None or numeric <= 0.0:
                return None
            return numeric

        def _present(value):
            return value not in (None, "", [], {})

        sports_quote_snapshot = {}
        orderbook_shape = "none"
        if isinstance(market.get("orderbook_fp"), dict):
            orderbook_shape = "orderbook_fp"
        elif isinstance(market.get("orderbook"), dict):
            orderbook_shape = "orderbook"
        elif market.get("yes") not in (None, "", [], {} ) or market.get("no") not in (None, "", [], {}):
            orderbook_shape = "side_levels"
        elif market.get("yes_dollars") not in (None, "", [], {} ) or market.get("no_dollars") not in (None, "", [], {}):
            orderbook_shape = "root_dollars"
        if is_sports_family:
            try:
                sports_quote_snapshot = self._extract_non_targeted_topbook_snapshot(market)
            except Exception as exc:
                sports_quote_snapshot = {
                    "failure_stage": "topbook_snapshot_exception",
                    "failure_reason": exc.__class__.__name__,
                }

        try:
            print(
                "[AION-QUOTE-HYDRATION-ROOT] "
                + json.dumps(
                    {
                        "ticker": ticker or None,
                        "family": family,
                        "source_path": "build_quote",
                        "market_keys": sorted(list(market.keys()))[:64],
                        "has_orderbook": bool(orderbook_shape != "none"),
                        "orderbook_shape": orderbook_shape,
                        "build_quote_called": True,
                        "recursion_detected": False,
                        "fallback_attempted": False,
                        "fallback_success": False,
                        "topbook_extract_success": False,
                        "yes_bid": None,
                        "yes_ask": None,
                        "no_bid": None,
                        "no_ask": None,
                    },
                    sort_keys=True,
                    default=str,
                )
            )
        except Exception:
            pass

        yes_bid_raw = self.to_float(market.get("yes_bid_dollars", market.get("yes_bid")), None)
        yes_ask_raw = self.to_float(market.get("yes_ask_dollars", market.get("yes_ask")), None)
        last_price = self.to_float(
            market.get("last_price_dollars", market.get("last_price", yes_bid_raw))
        )
        volume = self.to_float(market.get("volume_fp", market.get("volume")), 0.0)
        liquidity = self.to_float(market.get("liquidity_dollars"), 0.0)

        no_bid_raw = self.to_float(market.get("no_bid_dollars", market.get("no_bid")), None)
        no_ask_raw = self.to_float(market.get("no_ask_dollars", market.get("no_ask")), None)

        yes_bid = _normalize_price_like(yes_bid_raw)
        yes_ask = _normalize_price_like(yes_ask_raw)
        no_bid = _normalize_price_like(no_bid_raw)
        no_ask = _normalize_price_like(no_ask_raw)

        source_fields_snapshot = {
            "yes_bid_dollars": yes_bid_raw,
            "yes_ask_dollars": yes_ask_raw,
            "no_bid_dollars": no_bid_raw,
            "no_ask_dollars": no_ask_raw,
            "best_yes_price": self.to_float(market.get("best_yes_price"), None),
            "best_no_price": self.to_float(market.get("best_no_price"), None),
            "yes_top_price": self.to_float(sports_quote_snapshot.get("yes_top_price"), None),
            "no_top_price": self.to_float(sports_quote_snapshot.get("no_top_price"), None),
            "yes_top_size": self.to_float(sports_quote_snapshot.get("yes_top_size"), None),
            "no_top_size": self.to_float(sports_quote_snapshot.get("no_top_size"), None),
            "orderbook": market.get("orderbook"),
            "orderbook_fp": market.get("orderbook_fp"),
            "yes_dollars": market.get("yes_dollars"),
            "no_dollars": market.get("no_dollars"),
            "yes": market.get("yes"),
            "no": market.get("no"),
        }
        source_quote_fields_present = sorted(
            [name for name, value in source_fields_snapshot.items() if _present(value)]
        )
        source_quote_fields_missing = sorted(
            [name for name in ("yes_bid_dollars", "yes_ask_dollars", "no_bid_dollars", "no_ask_dollars") if not _normalize_price_like(source_fields_snapshot.get(name))]
        )
        candidate_price_fields_before_mapping = {
            "yes_bid": yes_bid,
            "yes_ask": yes_ask,
            "no_bid": no_bid,
            "no_ask": no_ask,
        }
        quote_mapping_applied = False
        quote_mapping_reason = "direct_fields"
        quote_mapping_block_reason = None

        if self._is_sports_market_or_family(family):
            yes_top_price = self.to_float(sports_quote_snapshot.get("yes_top_price"), None)
            no_top_price = self.to_float(sports_quote_snapshot.get("no_top_price"), None)
            if yes_ask is None and yes_top_price is not None and yes_top_price > 0.0:
                yes_ask = yes_top_price
                quote_mapping_applied = True
                quote_mapping_reason = "yes_top_price_fallback"
            if no_ask is None and no_top_price is not None and no_top_price > 0.0:
                no_ask = no_top_price
                quote_mapping_applied = True
                quote_mapping_reason = "no_top_price_fallback"
            if yes_bid is None and no_ask is not None:
                yes_bid = max(0.0, 1.0 - float(no_ask))
                quote_mapping_applied = True
                quote_mapping_reason = "paired_topbook_recovery"
            if no_bid is None and yes_ask is not None:
                no_bid = max(0.0, 1.0 - float(yes_ask))
                quote_mapping_applied = True
                quote_mapping_reason = "paired_topbook_recovery"
            yes_bid, yes_ask, no_bid, no_ask = self._infer_missing_binary_quotes(yes_bid, yes_ask, no_bid, no_ask)
            if (
                yes_bid is None
                and yes_ask is None
                and no_bid is None
                and no_ask is None
                and (yes_top_price is None or yes_top_price <= 0.0)
                and (no_top_price is None or no_top_price <= 0.0)
            ):
                quote_mapping_block_reason = "no_valid_quote_or_orderbook_prices"
        else:
            yes_bid, yes_ask, no_bid, no_ask = self._infer_missing_binary_quotes(yes_bid, yes_ask, no_bid, no_ask)

        if self._is_sports_market_or_family(family):
            self._emit_topbook_trace(
                "[LIVE-TOPBOOK-RAW]",
                market,
                family=family,
                reason="build_quote_input",
                ticker=ticker,
                yes_bid=yes_bid,
                yes_ask=yes_ask,
                no_bid=no_bid,
                no_ask=no_ask,
            )

        continuity_used = False
        continuity_reason = "not_needed"
        if self._is_sports_market_or_family(family):
            yes_bid, yes_ask, no_bid, no_ask, continuity_used, continuity_reason = self._apply_sports_quote_continuity(
                market,
                yes_bid,
                yes_ask,
                no_bid,
                no_ask,
            )

        yes_bid = self.to_float(yes_bid, 0.0)
        yes_ask = self.to_float(yes_ask, 0.0)
        no_bid = self.to_float(no_bid, 0.0)
        no_ask = self.to_float(no_ask, 0.0)
        provisional_quote_ready = bool((yes_bid > 0.0 and yes_ask > 0.0) or (no_bid > 0.0 and no_ask > 0.0))
        quote_complete = bool(yes_bid > 0.0 and yes_ask > 0.0 and no_bid > 0.0 and no_ask > 0.0)
        final_quote_ready = provisional_quote_ready
        quote_ready_reason = "direct_fields" if provisional_quote_ready else "missing_quote_object"
        if self._is_sports_market_or_family(family):
            spread = round(yes_ask - yes_bid, 4) if yes_bid > 0.0 and yes_ask > 0.0 else None
            if sports_quote_snapshot.get("failure_stage") or sports_quote_snapshot.get("failure_reason"):
                self._record_execution_failure_audit(
                    reason=sports_quote_snapshot.get("failure_reason") or sports_quote_snapshot.get("failure_stage") or "orderbook_parse_failed",
                    stage="orderbook_parse",
                    orderbook_parse_failure=True,
                )
                if sports_quote_snapshot.get("failure_reason"):
                    quote_mapping_block_reason = quote_mapping_block_reason or f"quote_orderbook_snapshot_{sports_quote_snapshot.get('failure_reason')}"
            provisional_quote_ready = bool((yes_bid > 0.0 and yes_ask > 0.0) or (no_bid > 0.0 and no_ask > 0.0))
            final_quote_ready = provisional_quote_ready
            sports_threshold_quote_diag = {
                "ticker": ticker,
                "quote_ready": bool(provisional_quote_ready),
                "quote_ready_before_fallback": bool(quote_ready_reason != "missing_quote_object"),
                "quote_ready_after_fallback": bool(provisional_quote_ready),
                "quote_complete": bool(quote_complete),
                "selected_side": selected_side if 'selected_side' in locals() else None,
                "selected_price": selected_price if 'selected_price' in locals() else None,
                "orderbook_exists": bool((yes_bid > 0.0 and yes_ask > 0.0) or (no_bid > 0.0 and no_ask > 0.0) or (sports_quote_snapshot.get("yes_top_size") or 0.0) > 0.0 or (sports_quote_snapshot.get("no_top_size") or 0.0) > 0.0),
                "topbook_snapshot_present": bool(sports_quote_snapshot and not sports_quote_snapshot.get("failure_stage")),
                "orderbook_exists": bool((yes_bid > 0.0 and yes_ask > 0.0) or (no_bid > 0.0 and no_ask > 0.0) or (sports_quote_snapshot.get("yes_top_size") or 0.0) > 0.0 or (sports_quote_snapshot.get("no_top_size") or 0.0) > 0.0 or (sports_quote_snapshot and not sports_quote_snapshot.get("failure_stage"))),
                "topbook_depth_exists": bool((sports_quote_snapshot.get("yes_top_size") or 0.0) > 0.0 or (sports_quote_snapshot.get("no_top_size") or 0.0) > 0.0 or (sports_quote_snapshot and not sports_quote_snapshot.get("failure_stage"))),
                "no_top_size": sports_quote_snapshot.get("no_top_size"),
                "quote_source": quote_ready_reason,
                "source_of_quote_data": quote_ready_reason,
                "failure_stage": sports_quote_snapshot.get("failure_stage"),
                "failure_reason": sports_quote_snapshot.get("failure_reason"),
                "orderbook_ready": bool((sports_quote_snapshot.get("yes_top_size") or 0.0) > 0.0 or (sports_quote_snapshot.get("no_top_size") or 0.0) > 0.0 or quote_mapping_applied),
                "orderbook_ready": bool((sports_quote_snapshot.get("yes_top_size") or 0.0) > 0.0 or (sports_quote_snapshot.get("no_top_size") or 0.0) > 0.0 or quote_mapping_applied or (sports_quote_snapshot and not sports_quote_snapshot.get("failure_stage"))),
            }
            adaptive_spread_limit = self._get_sports_adaptive_spread_threshold(
                market,
                spread=spread,
                liquidity=liquidity,
                yes_top_size=sports_quote_snapshot.get("yes_top_size"),
                no_top_size=sports_quote_snapshot.get("no_top_size"),
                context="build_quote_final",
                quote_diag=sports_threshold_quote_diag,
            ).get("adaptive_threshold", MAX_ENTRY_SPREAD)
            reject_reason = self._topbook_reject_reason(
                yes_price=yes_ask if yes_ask > 0.0 else None,
                yes_size=sports_quote_snapshot.get("yes_top_size"),
                no_price=no_ask if no_ask > 0.0 else None,
                no_size=sports_quote_snapshot.get("no_top_size"),
                spread=spread,
                max_spread=adaptive_spread_limit,
            )
            self._emit_topbook_trace(
                "[LIVE-TOPBOOK-FINAL]",
                market,
                family=family,
                reason=f"{reject_reason};continuity={continuity_reason}",
                ticker=ticker,
                yes_bid=yes_bid,
                yes_ask=yes_ask,
                no_bid=no_bid,
                no_ask=no_ask,
                yes_price=yes_ask,
                no_price=no_ask,
                yes_size=sports_quote_snapshot.get("yes_top_size"),
                no_size=sports_quote_snapshot.get("no_top_size"),
                spread=spread,
                continuity_used="yes" if continuity_used else "no",
            )
            self._record_sports_quote_continuity_snapshot(
                ticker,
                family,
                yes_bid,
                yes_ask,
                no_bid,
                no_ask,
                yes_top_size=sports_quote_snapshot.get("yes_top_size"),
                no_top_size=sports_quote_snapshot.get("no_top_size"),
                source="build_quote",
            )
            quote_complete = bool(yes_bid > 0.0 and yes_ask > 0.0 and no_bid > 0.0 and no_ask > 0.0)
            final_quote_ready = bool((yes_bid > 0.0 and yes_ask > 0.0) or (no_bid > 0.0 and no_ask > 0.0))
            if quote_mapping_applied or quote_mapping_block_reason or spread is None or not final_quote_ready:
                quote_ready_reason = (
                    "recovered_from_topbook_pair"
                    if quote_mapping_applied and final_quote_ready
                    else (
                        quote_mapping_block_reason
                        or (
                            "incomplete_quote_fields:"
                            + ",".join(
                                name
                                for name, value in {
                                    "yes_bid": yes_bid,
                                    "yes_ask": yes_ask,
                                    "no_bid": no_bid,
                                    "no_ask": no_ask,
                                }.items()
                                if value in (None, "", 0, 0.0)
                            )
                            if not final_quote_ready
                            else "direct_fields"
                        )
                    )
                )
                quote_source_trace = {
                    "ticker": ticker,
                    "family": family,
                    "source_quote_fields_present": source_quote_fields_present,
                    "source_quote_fields_missing": source_quote_fields_missing,
                    "candidate_price_fields_before_mapping": candidate_price_fields_before_mapping,
                    "candidate_price_fields_after_mapping": {
                        "yes_bid": yes_bid,
                        "yes_ask": yes_ask,
                        "no_bid": no_bid,
                        "no_ask": no_ask,
                    },
                    "computed_spread": spread,
                    "quote_ready": final_quote_ready,
                    "quote_complete": quote_complete,
                    "quote_missing_fields": [
                        name
                        for name, value in {
                            "yes_bid": yes_bid,
                            "yes_ask": yes_ask,
                            "no_bid": no_bid,
                            "no_ask": no_ask,
                        }.items()
                        if value in (None, "", 0, 0.0)
                    ],
                    "quote_ready_reason": quote_ready_reason,
                    "orderbook_source_object": sports_quote_snapshot,
                    "source_of_quote_data": sports_quote_snapshot.get("source_path") or ("topbook_recovery" if quote_mapping_applied else "direct_fields"),
                }
                print("[AION-QUOTE-SOURCE-TRACE] " + json.dumps(quote_source_trace, sort_keys=True, default=str))
                print("[AION-PRICE-MAPPING-TRACE] " + json.dumps(
                    {
                        **quote_source_trace,
                        "mapping_applied": quote_mapping_applied,
                        "mapping_reason": quote_mapping_reason,
                        "mapping_block_reason": quote_mapping_block_reason,
                    },
                    sort_keys=True,
                    default=str,
                ))
                if final_quote_ready and not quote_complete:
                    print(
                        "[AION-QUOTE-CONSISTENCY-WARN] "
                        + json.dumps(
                            {
                                "ticker": ticker,
                                "quote_ready": True,
                                "quote_complete": False,
                                "quote_missing_fields": quote_source_trace.get("quote_missing_fields"),
                                "source_of_quote_data": quote_source_trace.get("source_of_quote_data"),
                                "block_reason": "partial_quote_complete",
                            },
                            sort_keys=True,
                            default=str,
                        )
                    )
                if final_quote_ready and quote_mapping_applied:
                    print("[AION-QUOTE-MAPPING-RECOVERED] " + json.dumps(
                        {
                            **quote_source_trace,
                            "recovery_source": quote_source_trace.get("source_of_quote_data"),
                            "mapping_reason": quote_mapping_reason,
                        },
                        sort_keys=True,
                        default=str,
                    ))
                elif not final_quote_ready:
                    if not quote_mapping_block_reason:
                        quote_mapping_block_reason = (
                            "incomplete_quote_fields:"
                            + ",".join(
                                name
                                for name, value in {
                                    "yes_bid": yes_bid,
                                    "yes_ask": yes_ask,
                                    "no_bid": no_bid,
                                    "no_ask": no_ask,
                                }.items()
                                if value in (None, "", 0, 0.0)
                            )
                        )
                    print("[AION-QUOTE-MAPPING-BLOCKED] " + json.dumps(
                        {
                            **quote_source_trace,
                            "block_reason": quote_mapping_block_reason or "incomplete_quote_fields",
                        },
                        sort_keys=True,
                        default=str,
                    ))

        try:
            print(
                "[AION-QUOTE-HYDRATION-SOURCE] "
                + json.dumps(
                    {
                        "ticker": ticker or None,
                        "family": family,
                        "source_path": sports_quote_snapshot.get("source_path") or "none",
                        "market_keys": sorted(list(market.keys()))[:64],
                        "has_orderbook": bool(orderbook_shape != "none"),
                        "orderbook_shape": orderbook_shape,
                        "build_quote_called": True,
                        "recursion_detected": bool(sports_quote_snapshot.get("failure_reason") == "RecursionError"),
                        "fallback_attempted": bool(quote_mapping_applied),
                        "fallback_success": bool(quote_mapping_applied and final_quote_ready),
                        "topbook_extract_success": bool((sports_quote_snapshot.get("yes_top_size") or 0.0) > 0.0 or (sports_quote_snapshot.get("no_top_size") or 0.0) > 0.0),
                        "recursion_guard_hit": bool(sports_quote_snapshot.get("failure_reason") == "RecursionError" or getattr(self, "_last_orderbook_recursion_guard_hit", False)),
                        "yes_bid": yes_bid,
                        "yes_ask": yes_ask,
                        "no_bid": no_bid,
                        "no_ask": no_ask,
                    },
                    sort_keys=True,
                    default=str,
                )
            )
            print(
                "[AION-QUOTE-HYDRATION-BUILD] "
                + json.dumps(
                    {
                        "ticker": ticker or None,
                        "family": family,
                        "source_path": sports_quote_snapshot.get("source_path") or "none",
                        "market_keys": sorted(list(market.keys()))[:64],
                        "has_orderbook": bool(orderbook_shape != "none"),
                        "orderbook_shape": orderbook_shape,
                        "build_quote_called": True,
                        "build_quote_success": bool(final_quote_ready),
                        "failure_reason": None if final_quote_ready else (quote_mapping_block_reason or "missing_quote_object"),
                        "recursion_detected": bool(sports_quote_snapshot.get("failure_reason") == "RecursionError"),
                        "fallback_attempted": bool(quote_mapping_applied),
                        "fallback_success": bool(quote_mapping_applied and final_quote_ready),
                        "topbook_extract_success": bool((sports_quote_snapshot.get("yes_top_size") or 0.0) > 0.0 or (sports_quote_snapshot.get("no_top_size") or 0.0) > 0.0),
                        "yes_bid": yes_bid,
                        "yes_ask": yes_ask,
                        "no_bid": no_bid,
                        "no_ask": no_ask,
                    },
                    sort_keys=True,
                    default=str,
                )
            )
            if not final_quote_ready:
                print(
                    "[AION-QUOTE-HYDRATION-FAIL] "
                    + json.dumps(
                        {
                            "ticker": ticker or None,
                            "family": family,
                            "source_path": sports_quote_snapshot.get("source_path") or "none",
                            "market_keys": sorted(list(market.keys()))[:64],
                            "has_orderbook": bool(orderbook_shape != "none"),
                            "orderbook_shape": orderbook_shape,
                            "build_quote_called": True,
                            "build_quote_success": False,
                            "failure_reason": quote_mapping_block_reason or "missing_quote_object",
                            "recursion_detected": bool(sports_quote_snapshot.get("failure_reason") == "RecursionError"),
                            "fallback_attempted": bool(quote_mapping_applied),
                            "fallback_success": False,
                            "topbook_extract_success": bool((sports_quote_snapshot.get("yes_top_size") or 0.0) > 0.0 or (sports_quote_snapshot.get("no_top_size") or 0.0) > 0.0),
                            "yes_bid": yes_bid,
                            "yes_ask": yes_ask,
                            "no_bid": no_bid,
                            "no_ask": no_ask,
                        },
                        sort_keys=True,
                        default=str,
                    )
                )
        except Exception:
            pass

        selected_side = None
        selected_price = None
        yes_top_size = self.to_float(
            sports_quote_snapshot.get("yes_top_size") if isinstance(sports_quote_snapshot, dict) else None,
            self.to_float(market.get("yes_top_size"), None),
        )
        no_top_size = self.to_float(
            sports_quote_snapshot.get("no_top_size") if isinstance(sports_quote_snapshot, dict) else None,
            self.to_float(market.get("no_top_size"), None),
        )
        return Quote(
            ticker=ticker,
            title=title,
            yes_bid=yes_bid,
            yes_ask=yes_ask,
            no_bid=no_bid,
            no_ask=no_ask,
            last_price=last_price,
            volume=volume,
            liquidity=liquidity,
            yes_top_size=yes_top_size,
            no_top_size=no_top_size,
            selected_side=selected_side,
            selected_price=selected_price,
        )

    def _diagnose_quote_readiness_context(self, *, market=None, q=None, family=None, sports_context=None, source="unknown"):
        market = market if isinstance(market, dict) else {}
        sports_context = sports_context if isinstance(sports_context, dict) else {}
        q = q if q is not None else None
        ticker = str(getattr(q, "ticker", "") or market.get("ticker", "") or "").strip()
        family = str(family or self.get_market_family(market) or getattr(q, "family", "") or "UNKNOWN").strip().upper() or "UNKNOWN"

        def _value_or_none(*values):
            for value in values:
                if value is None:
                    continue
                if isinstance(value, str) and not value.strip():
                    continue
                return value
            return None

        yes_bid = self.to_float(_value_or_none(getattr(q, "yes_bid", None), market.get("yes_bid_dollars"), market.get("yes_bid")), None)
        yes_ask = self.to_float(_value_or_none(getattr(q, "yes_ask", None), market.get("yes_ask_dollars"), market.get("yes_ask")), None)
        no_bid = self.to_float(_value_or_none(getattr(q, "no_bid", None), market.get("no_bid_dollars"), market.get("no_bid")), None)
        no_ask = self.to_float(_value_or_none(getattr(q, "no_ask", None), market.get("no_ask_dollars"), market.get("no_ask")), None)
        last_price = self.to_float(_value_or_none(getattr(q, "last_price", None), market.get("last_price_dollars"), market.get("last_price")), None)
        volume = self.to_float(_value_or_none(getattr(q, "volume", None), market.get("volume_fp"), market.get("volume")), 0.0) or 0.0
        liquidity = self.to_float(_value_or_none(getattr(q, "liquidity", None), market.get("liquidity_dollars"), market.get("liquidity")), 0.0) or 0.0

        topbook_snapshot = {}
        try:
            topbook_snapshot = self._extract_non_targeted_topbook_snapshot(market) if market else {}
        except Exception as exc:
            topbook_snapshot = {"failure_stage": "topbook_snapshot_exception", "failure_reason": exc.__class__.__name__}

        quote_orderbook_snapshot = {}
        try:
            quote_orderbook_snapshot = self.resolve_aion_quote_orderbook_snapshot(
                ticker or market.get("ticker", "") or None,
                candidate=q,
                market=market,
                quote_diag=sports_context,
                price_source="bid",
                selected_side=sports_context.get("selected_side"),
                selection_stage=source,
                allow_refresh=True,
            ) or {}
        except Exception as exc:
            try:
                import traceback as _traceback
                print(
                    "[AION-QUOTE-USABILITY-TRACE] "
                    + json.dumps(
                        {
                            "ticker": ticker or None,
                            "family": family,
                            "quote_ready": False,
                            "orderbook_ready": False,
                            "source_of_quote_data": "diagnostic_exception",
                            "quote_source": f"quote_orderbook_snapshot_{exc.__class__.__name__}",
                            "topbook_snapshot_present": bool(topbook_snapshot and not topbook_snapshot.get("failure_stage")),
                            "normalized_quote_present": False,
                            "normalized_orderbook_present": False,
                            "selected_side": None,
                            "selected_price": None,
                            "selected_price_source": "bid",
                            "missing_fields": [],
                            "stale_seconds": None,
                            "cache_hit": False,
                            "cache_age": None,
                            "fetch_attempted": False,
                            "fetch_success": False,
                            "failure_stage": f"quote_orderbook_snapshot_{exc.__class__.__name__}",
                            "block_reason": f"quote_orderbook_snapshot_{exc.__class__.__name__}",
                            "traceback": _traceback.format_exc(limit=18),
                        },
                        sort_keys=True,
                        default=str,
                    )
                )
            except Exception:
                pass
            quote_orderbook_snapshot = {
                "quote_ready": False,
                "quote_missing": True,
                "quote_complete": False,
                "quote_missing_fields": [],
                "quote_source": f"quote_orderbook_snapshot_{exc.__class__.__name__}",
                "orderbook_ready": False,
                "orderbook_source": None,
                "orderbook_missing_reason": f"quote_orderbook_snapshot_{exc.__class__.__name__}",
                "orderbook_fetch_called": False,
                "orderbook_fetch_success": False,
                "cache_hit": False,
                "cache_age_seconds": None,
                "yes_bid": None,
                "yes_ask": None,
                "no_bid": None,
                "no_ask": None,
                "yes_bid_dollars": None,
                "yes_ask_dollars": None,
                "no_bid_dollars": None,
                "no_ask_dollars": None,
                "selected_side": None,
                "selected_price": None,
                "payload_price_source": "bid",
                "blocker_reason": f"quote_orderbook_snapshot_{exc.__class__.__name__}",
                "orderbook_keys": [],
                "best_action": None,
            }

        canonical_tradeability = {}
        try:
            canonical_tradeability = self.resolve_canonical_tradeability(
                market,
                quote=q,
                context={
                    "quote_diag": sports_context,
                    "selected_side": sports_context.get("selected_side"),
                    "price_source": "bid",
                    "selection_stage": source,
                    "allow_refresh": True,
                    "ticker": ticker or market.get("ticker", ""),
                },
                source=source,
            ) or {}
        except Exception:
            canonical_tradeability = {}
        if canonical_tradeability:
            quote_orderbook_snapshot.update(canonical_tradeability)

        yes_top_price = self.to_float(topbook_snapshot.get("yes_top_price"), None)
        no_top_price = self.to_float(topbook_snapshot.get("no_top_price"), None)
        yes_top_size = self.to_float(topbook_snapshot.get("yes_top_size"), 0.0) or 0.0
        no_top_size = self.to_float(topbook_snapshot.get("no_top_size"), 0.0) or 0.0
        topbook_bucket = str(topbook_snapshot.get("top_book_bucket") or "unknown").strip().lower()
        topbook_snapshot_present = bool(topbook_snapshot and not topbook_snapshot.get("failure_stage"))
        market_direct_quote_ready = bool(
            any(
                self.to_float(market.get(key), None) not in (None, 0.0)
                for key in (
                    "yes_bid_dollars", "yes_bid", "yes_ask_dollars", "yes_ask",
                    "no_bid_dollars", "no_bid", "no_ask_dollars", "no_ask",
                )
            )
        )
        market_direct_orderbook_ready = bool(
            yes_top_size > 0.0
            or no_top_size > 0.0
            or self.to_float(market.get("yes_ask_size_fp"), None) not in (None, 0.0)
            or self.to_float(market.get("yes_bid_size_fp"), None) not in (None, 0.0)
            or self.to_float(market.get("no_ask_size_fp"), None) not in (None, 0.0)
            or self.to_float(market.get("no_bid_size_fp"), None) not in (None, 0.0)
            or self.to_float(market.get("yes_top_price"), None) not in (None, 0.0)
            or self.to_float(market.get("no_top_price"), None) not in (None, 0.0)
            or bool(market.get("orderbook"))
            or bool(market.get("orderbook_fp"))
        )

        quote_fields = {
            "yes_bid": yes_bid,
            "yes_ask": yes_ask,
            "no_bid": no_bid,
            "no_ask": no_ask,
            "last_price": last_price,
            "volume": volume,
            "liquidity": liquidity,
        }
        missing_fields = [name for name, value in quote_fields.items() if value in (None, "", 0, 0.0)]
        yes_bid_missing = yes_bid is None or yes_bid <= 0.0
        yes_ask_missing = yes_ask is None or yes_ask <= 0.0
        no_bid_missing = no_bid is None or no_bid <= 0.0
        no_ask_missing = no_ask is None or no_ask <= 0.0
        orderbook_exists = bool(
            (yes_bid is not None and yes_bid > 0.0)
            or (yes_ask is not None and yes_ask > 0.0)
            or (no_bid is not None and no_bid > 0.0)
            or (no_ask is not None and no_ask > 0.0)
            or (yes_top_price is not None and yes_top_price > 0.0)
            or (no_top_price is not None and no_top_price > 0.0)
            or yes_top_size > 0.0
            or no_top_size > 0.0
            or bool(topbook_bucket and topbook_bucket not in {"unknown", "zero_top_book"})
        )
        canonical_source = {}
        canonical_source_guard_fallback_used = True
        try:
            canonical_source = self._resolve_aion_canonical_binary_prices(
                q if q is not None else market,
                ticker=ticker or None,
                source_label=f"quote_readiness.{source}",
            ) or {}
            canonical_source_guard_fallback_used = False
        except Exception:
            canonical_source = {}
            canonical_source_guard_fallback_used = True
        try:
            print("[AION-CANONICAL-SOURCE-GUARD] " + json.dumps({
                "function": "_diagnose_quote_readiness_context",
                "ticker": ticker or None,
                "canonical_source": canonical_source,
                "fallback_used": bool(canonical_source_guard_fallback_used),
            }, sort_keys=True, default=str))
        except Exception:
            pass
        book_valid = bool(
            canonical_source.get("book_valid")
            or canonical_source.get("orderbook_ready")
            or canonical_source.get("quote_ready")
            or topbook_snapshot_present
        )
        topbook_depth_exists = bool(
            yes_top_size > 0.0
            or no_top_size > 0.0
            or topbook_bucket in {"both_non_zero", "one_non_zero"}
            or self.to_float(canonical_source.get("yes_bid_cents"), 0.0) > 0.0
            or self.to_float(canonical_source.get("no_bid_cents"), 0.0) > 0.0
            or self.to_float(canonical_source.get("yes_ask_cents"), 0.0) > 0.0
            or self.to_float(canonical_source.get("no_ask_cents"), 0.0) > 0.0
            or market_direct_quote_ready
            or market_direct_orderbook_ready
            or book_valid
        )
        liquidity_depth = round(yes_top_size + no_top_size, 4)
        quote_ready_from_fields = bool(
            (yes_bid is not None or yes_ask is not None or no_bid is not None or no_ask is not None)
            and not (yes_bid_missing and yes_ask_missing and no_bid_missing and no_ask_missing)
        )
        quote_missing = not quote_ready_from_fields
        parser_related = bool(topbook_snapshot.get("failure_stage") or topbook_snapshot.get("failure_reason"))
        stale_seconds = self.to_float(market.get("staleness_seconds"), None)
        stale_related = bool(
            (stale_seconds is not None and stale_seconds > REALM_XX_WS_STALE_SECONDS)
            or str(market.get("status") or "").strip().lower() in {"closed", "resolved", "expired", "halted"}
            or bool(market.get("is_stale"))
        )
        empty_market_related = bool(not orderbook_exists and quote_missing and not topbook_depth_exists)
        fallback_quote = None
        fallback_quote_ready = False
        fallback_source = "none"
        sports_quote_cache = getattr(self, "sports_quote_continuity_cache", {}) or {}
        recent_cache = dict(sports_quote_cache.get(ticker, {}) or {}) if self._is_sports_market_or_family(family) else {}
        cache_age_seconds = None
        if recent_cache.get("ts"):
            try:
                cache_age_seconds = max(0.0, time.time() - float(recent_cache.get("ts") or 0.0))
            except (TypeError, ValueError):
                cache_age_seconds = None
        cache_stable_cycles = int(recent_cache.get("stable_cycles", 0) or 0) if recent_cache else 0
        if not quote_ready_from_fields and market:
            try:
                fallback_snapshot = topbook_snapshot if isinstance(topbook_snapshot, dict) else {}
                fallback_quote = q
                fallback_source = "topbook_snapshot"
                fallback_quote_ready = bool(
                    (fallback_snapshot.get("yes_top_size") or 0.0) > 0.0
                    or (fallback_snapshot.get("no_top_size") or 0.0) > 0.0
                    or (fallback_snapshot.get("yes_top_price") or 0.0) > 0.0
                    or (fallback_snapshot.get("no_top_price") or 0.0) > 0.0
                    or topbook_depth_exists
                    or orderbook_exists
                )
            except Exception as exc:
                parser_related = True
                fallback_quote = None
                fallback_source = f"topbook_snapshot_{exc.__class__.__name__}"
        if not fallback_quote_ready and topbook_depth_exists and orderbook_exists:
            fallback_quote_ready = True
            if fallback_source == "none":
                fallback_source = "topbook_snapshot"
        resolved_quote_ready = bool(quote_orderbook_snapshot.get("quote_ready"))
        resolved_quote_missing = bool(quote_orderbook_snapshot.get("quote_missing"))
        resolved_quote_complete = bool(quote_orderbook_snapshot.get("quote_complete"))
        resolved_selected_side = quote_orderbook_snapshot.get("selected_side")
        resolved_selected_price = quote_orderbook_snapshot.get("selected_price")
        resolved_orderbook_ready = bool(quote_orderbook_snapshot.get("orderbook_ready") or quote_orderbook_snapshot.get("selected_price") not in (None, "", 0, 0.0) or quote_orderbook_snapshot.get("yes_bid") not in (None, "", 0, 0.0) or quote_orderbook_snapshot.get("yes_ask") not in (None, "", 0, 0.0) or quote_orderbook_snapshot.get("no_bid") not in (None, "", 0, 0.0) or quote_orderbook_snapshot.get("no_ask") not in (None, "", 0, 0.0) or (topbook_snapshot and not topbook_snapshot.get("failure_stage")) or topbook_snapshot_present)
        quote_ready = bool(quote_ready_from_fields or fallback_quote_ready or resolved_quote_ready or bool(sports_context.get("quote_ready")))
        hydrated_quote_ready = bool(
            q is not None and any(
                self.to_float(getattr(q, field, None), None) not in (None, 0.0)
                for field in ("yes_bid", "yes_ask", "no_bid", "no_ask")
            )
        )
        if q is not None and hydrated_quote_ready and not quote_ready:
            quote_ready = True
            quote_ready_reason = "hydrated_quote_object"
            source_of_quote_data = "hydrated_quote_object"
            fallback_quote_ready = True
            resolved_quote_ready = True
            quote_missing = False
        orderbook_salvaged = False
        if not resolved_orderbook_ready and (topbook_snapshot_present or topbook_depth_exists) and (
            resolved_selected_price not in (None, "", 0, 0.0)
            or yes_bid is not None
            or yes_ask is not None
            or no_bid is not None
            or no_ask is not None
            or resolved_quote_ready
        ):
            resolved_orderbook_ready = True
            orderbook_salvaged = True
            quote_orderbook_snapshot["orderbook_ready"] = True
            quote_orderbook_snapshot["orderbook_exists"] = True
            quote_orderbook_snapshot["normalized_orderbook_present"] = True
            quote_orderbook_snapshot["topbook_snapshot_present"] = bool(topbook_snapshot_present)
            quote_orderbook_snapshot["topbook_depth_exists"] = bool(topbook_depth_exists)
            quote_orderbook_snapshot["orderbook_missing_reason"] = None
            quote_orderbook_snapshot["blocker_reason"] = None
            try:
                print("[AION-ORDERBOOK-SALVAGED] " + json.dumps({
                    "ticker": ticker or None,
                    "family": family,
                    "source_path": source,
                    "topbook_snapshot_present": bool(topbook_snapshot_present),
                    "topbook_depth_exists": bool(topbook_depth_exists),
                    "selected_side": resolved_selected_side,
                    "selected_price": resolved_selected_price,
                    "quote_ready": bool(quote_ready),
                    "orderbook_ready": True,
                    "failure_reason": None,
                }, sort_keys=True, default=str))
            except Exception:
                pass
        elif not resolved_orderbook_ready:
            try:
                print("[AION-ORDERBOOK-REJECT] " + json.dumps({
                    "ticker": ticker or None,
                    "family": family,
                    "source_path": source,
                    "topbook_snapshot_present": bool(topbook_snapshot_present),
                    "topbook_depth_exists": bool(topbook_depth_exists),
                    "selected_side": resolved_selected_side,
                    "selected_price": resolved_selected_price,
                    "quote_ready": bool(quote_ready),
                    "orderbook_ready": False,
                    "failure_reason": quote_orderbook_snapshot.get("orderbook_missing_reason") or "orderbook_not_usable",
                }, sort_keys=True, default=str))
            except Exception:
                pass
        quote_complete = bool(
            resolved_quote_complete
            or (yes_bid is not None and yes_bid > 0.0 and yes_ask is not None and yes_ask > 0.0 and no_bid is not None and no_bid > 0.0 and no_ask is not None and no_ask > 0.0)
        )
        raw_quote_candidates = {
            "yes_bid": getattr(q, "yes_bid", None) if q is not None else market.get("yes_bid"),
            "yes_ask": getattr(q, "yes_ask", None) if q is not None else market.get("yes_ask"),
            "no_bid": getattr(q, "no_bid", None) if q is not None else market.get("no_bid"),
            "no_ask": getattr(q, "no_ask", None) if q is not None else market.get("no_ask"),
        }
        malformed_quote_fields = [
            name for name, raw_value in raw_quote_candidates.items()
            if raw_value not in (None, "", 0, 0.0) and self.to_float(raw_value, None) is None
        ]
        missing_quote_fields = [
            name for name, raw_value in raw_quote_candidates.items()
            if raw_value in (None, "", 0, 0.0)
        ]
        if quote_ready:
            quote_missing = False
        if quote_ready_from_fields:
            quote_ready_reason = "direct_fields"
            source_of_quote_data = "direct_fields"
        elif fallback_quote_ready:
            quote_ready_reason = fallback_source
            source_of_quote_data = fallback_source
        elif resolved_quote_ready:
            quote_ready_reason = quote_orderbook_snapshot.get("quote_source") or "resolved_orderbook"
            source_of_quote_data = quote_orderbook_snapshot.get("quote_source") or "resolved_orderbook"
        elif parser_related:
            quote_ready_reason = "parser_failure"
            source_of_quote_data = "parser_failure"
        elif stale_related:
            quote_ready_reason = "stale_or_closed"
            source_of_quote_data = "stale_or_closed"
        elif empty_market_related:
            quote_ready_reason = "empty_market"
            source_of_quote_data = "empty_market"
        elif not orderbook_exists:
            quote_ready_reason = "missing_orderbook_data"
            source_of_quote_data = "missing_orderbook_data"
        elif not topbook_depth_exists:
            quote_ready_reason = "missing_topbook_depth"
            source_of_quote_data = "missing_topbook_depth"
        elif not recent_cache:
            quote_ready_reason = "no_recent_valid_quote"
            source_of_quote_data = "no_recent_valid_quote"
        elif cache_age_seconds is not None and cache_age_seconds > SPORTS_QUOTE_CONTINUITY_MAX_AGE_SECONDS:
            quote_ready_reason = "recent_quote_too_old"
            source_of_quote_data = "continuity_cache_too_old"
        else:
            quote_ready_reason = "quote_not_ready"
            source_of_quote_data = fallback_source if fallback_source != "none" else "unknown"
        diagnostics = {
            "ticker": ticker or None,
            "family": family,
            "source": source,
            "quote_source": quote_orderbook_snapshot.get("quote_source"),
            "selected_side": resolved_selected_side,
            "selected_price": resolved_selected_price,
            "normalized_quote_present": bool(quote_ready and not quote_missing),
            "normalized_orderbook_present": bool(resolved_orderbook_ready),
            "quote_ready_before_fallback": bool(sports_context.get("quote_ready") or quote_ready_from_fields),
            "quote_ready_after_fallback": bool(quote_ready),
            "quote_complete": bool(quote_complete),
            "quote_ready_reason": quote_ready_reason,
            "quote_missing_before_fallback": bool(sports_context.get("quote_missing") or quote_missing),
            "quote_missing_after_fallback": bool(not quote_ready),
            "missing_fields": missing_fields,
            "missing_quote_fields": missing_quote_fields,
            "usable_yes_bid": quote_orderbook_snapshot.get("yes_bid"),
            "usable_yes_ask": quote_orderbook_snapshot.get("yes_ask"),
            "usable_no_bid": quote_orderbook_snapshot.get("no_bid"),
            "usable_no_ask": quote_orderbook_snapshot.get("no_ask"),
            "malformed_quote_fields": malformed_quote_fields,
            "yes_bid_missing": bool(yes_bid_missing),
            "yes_ask_missing": bool(yes_ask_missing),
            "no_bid_missing": bool(no_bid_missing),
            "no_ask_missing": bool(no_ask_missing),
            "orderbook_exists": bool(orderbook_exists),
            "topbook_depth_exists": bool(topbook_depth_exists),
            "liquidity_depth": liquidity_depth,
            "topbook_bucket": topbook_bucket,
            "yes_top_size": round(yes_top_size, 4),
            "no_top_size": round(no_top_size, 4),
            "cache_hit": bool(quote_orderbook_snapshot.get("cache_hit")),
            "cache_age": quote_orderbook_snapshot.get("cache_age_seconds"),
            "fetch_attempted": bool(quote_orderbook_snapshot.get("orderbook_fetch_called")),
            "fetch_success": bool(quote_orderbook_snapshot.get("orderbook_fetch_success")),
            "failure_stage": quote_orderbook_snapshot.get("blocker_reason") or topbook_snapshot.get("failure_stage"),
            "spread": round(self.to_float(yes_ask - yes_bid, None), 4) if yes_bid is not None and yes_ask is not None else None,
            "spread_bucket": str(sports_context.get("spread_bucket") or sports_context.get("sports_spread_bucket") or "unknown").strip().lower(),
            "orderbook_age_seconds": round(cache_age_seconds, 2) if cache_age_seconds is not None else None,
            "quote_stability_cycles": int(cache_stable_cycles or 0),
            "parser_related": bool(parser_related),
            "stale_related": bool(stale_related),
            "empty_market_related": bool(empty_market_related),
            "fallback_source": fallback_source,
            "source_of_quote_data": source_of_quote_data,
            "fallback_quote_ready": bool(fallback_quote_ready),
            "quote_ready": bool(quote_ready),
            "quote_missing": bool(not quote_ready),
            "fallback_quote": fallback_quote,
        }
        diagnostics["canonical_tradeability"] = canonical_tradeability
        diagnostics["market_personality"] = _classify_market_personality(self, market=market, quote_diag=diagnostics, q=q, family=family)
        diagnostics["confidence_profile"] = _compute_realm_vv_confidence(self,
            edge_after_cost=canonical_tradeability.get("edge_after_cost", sports_context.get("edge_after_cost")),
            liquidity_depth=liquidity_depth,
            spread_bucket=diagnostics.get("spread_bucket"),
            market_personality=diagnostics["market_personality"],
            profile_settings={"profile": _normalize_aion_aggression_profile(AION_AGGRESSION_PROFILE)},
        )
        if yes_bid is not None and yes_ask is not None:
            try:
                diagnostics["spread"] = round(max(0.0, float(yes_ask) - float(yes_bid)), 4)
            except (TypeError, ValueError):
                diagnostics["spread"] = None
        if not quote_ready or quote_missing or parser_related or stale_related or empty_market_related or not resolved_orderbook_ready:
            print(
                "[AION-QUOTE-USABILITY-TRACE] "
                + json.dumps(
                    {
                        "ticker": ticker or None,
                        "family": family,
                        "quote_ready": bool(quote_ready),
                        "orderbook_ready": bool(resolved_orderbook_ready),
                        "source_of_quote_data": source_of_quote_data,
                        "quote_source": quote_orderbook_snapshot.get("quote_source"),
                        "topbook_snapshot_present": bool(topbook_snapshot and not topbook_snapshot.get("failure_stage")),
                        "normalized_quote_present": bool(quote_ready and not quote_missing),
                        "normalized_orderbook_present": bool(resolved_orderbook_ready),
                        "selected_side": resolved_selected_side,
                        "selected_price": resolved_selected_price,
                        "selected_price_source": quote_orderbook_snapshot.get("selected_price_source_used") or quote_orderbook_snapshot.get("payload_price_source"),
                        "usable_yes_bid": quote_orderbook_snapshot.get("yes_bid"),
                        "usable_yes_ask": quote_orderbook_snapshot.get("yes_ask"),
                        "usable_no_bid": quote_orderbook_snapshot.get("no_bid"),
                        "usable_no_ask": quote_orderbook_snapshot.get("no_ask"),
                        "missing_fields": missing_fields,
                        "stale_seconds": stale_seconds,
                        "cache_hit": bool(quote_orderbook_snapshot.get("cache_hit")),
                        "cache_age": quote_orderbook_snapshot.get("cache_age_seconds"),
                        "fetch_attempted": bool(quote_orderbook_snapshot.get("orderbook_fetch_called")),
                        "fetch_success": bool(quote_orderbook_snapshot.get("orderbook_fetch_success")),
                        "failure_stage": quote_orderbook_snapshot.get("blocker_reason") or (topbook_snapshot.get("failure_stage") if isinstance(topbook_snapshot, dict) else None),
                        "block_reason": quote_orderbook_snapshot.get("blocker_reason") or quote_ready_reason,
                    },
                    sort_keys=True,
                    default=str,
                )
            )
            print("[AION-QUOTE-READINESS-DIAGNOSTIC] " + json.dumps({k: v for k, v in diagnostics.items() if k != "fallback_quote"}, sort_keys=True, default=str))
        return diagnostics

    def _resolve_unsafe_price_detail(self, *, market=None, q=None, family=None, quote_diag=None, source="unknown"):
        market = market if isinstance(market, dict) else {}
        quote_diag = quote_diag if isinstance(quote_diag, dict) else {}
        q = q if q is not None else None
        family = str(family or self.get_market_family(market) or getattr(q, "family", "") or "UNKNOWN").strip().upper() or "UNKNOWN"
        ticker = str(getattr(q, "ticker", "") or market.get("ticker", "") or "").strip()
        aggression_profile = _normalize_aion_aggression_profile(
            quote_diag.get("profile") or quote_diag.get("aggression_profile") or AION_AGGRESSION_PROFILE
        )

        def _pick(*values):
            for value in values:
                if value is None:
                    continue
                if isinstance(value, str) and not value.strip():
                    continue
                return value
            return None

        canonical_source = self._resolve_aion_canonical_binary_prices(
            q if q is not None else market,
            ticker=ticker or None,
            source_label=f"unsafe_price.{source}",
        )
        yes_bid = canonical_source.get("yes_bid")
        yes_ask = canonical_source.get("yes_ask")
        no_bid = canonical_source.get("no_bid")
        no_ask = canonical_source.get("no_ask")
        raw_yes_price = canonical_source.get("raw_yes_ask") if canonical_source.get("raw_yes_ask") is not None else canonical_source.get("raw_yes_bid")
        raw_no_price = canonical_source.get("raw_no_ask") if canonical_source.get("raw_no_ask") is not None else canonical_source.get("raw_no_bid")

        yes_bid_valid = yes_bid is not None and yes_bid > 0.0
        yes_ask_valid = yes_ask is not None and yes_ask > 0.0
        no_bid_valid = no_bid is not None and no_bid > 0.0
        no_ask_valid = no_ask is not None and no_ask > 0.0

        book_source = None
        best_bid = None
        best_ask = None
        midpoint = None
        spread = canonical_source.get("spread")
        if yes_bid_valid and yes_ask_valid:
            book_source = "yes"
            best_bid = yes_bid
            best_ask = yes_ask
            midpoint = (yes_bid + yes_ask) / 2.0
        elif no_bid_valid and no_ask_valid:
            book_source = "no"
            best_bid = max(0.0, 1.0 - no_ask)
            best_ask = max(0.0, 1.0 - no_bid)
            midpoint = max(0.0, min(1.0, 1.0 - ((no_bid + no_ask) / 2.0)))
        elif yes_bid_valid or yes_ask_valid:
            book_source = "yes_partial"
            best_bid = yes_bid if yes_bid_valid else None
            best_ask = yes_ask if yes_ask_valid else None
            if best_bid is not None and best_ask is not None:
                midpoint = (best_bid + best_ask) / 2.0
                spread = max(0.0, best_ask - best_bid)
        elif no_bid_valid or no_ask_valid:
            book_source = "no_partial"
            best_bid = max(0.0, 1.0 - no_ask) if no_ask_valid else None
            best_ask = max(0.0, 1.0 - no_bid) if no_bid_valid else None
            if best_bid is not None and best_ask is not None:
                midpoint = (best_bid + best_ask) / 2.0
                spread = max(0.0, best_ask - best_bid)

        normalized_yes_price = None
        normalized_no_price = None
        if midpoint is not None:
            normalized_yes_price = self._clamp(midpoint, 0.0, 1.0)
            normalized_no_price = self._clamp(1.0 - normalized_yes_price, 0.0, 1.0)
        elif raw_yes_price is not None:
            normalized_yes_price = self._clamp(raw_yes_price, 0.0, 1.0)
            normalized_no_price = self._clamp(1.0 - normalized_yes_price, 0.0, 1.0)
        elif raw_no_price is not None:
            normalized_no_price = self._clamp(raw_no_price, 0.0, 1.0)
            normalized_yes_price = self._clamp(1.0 - normalized_no_price, 0.0, 1.0)

        spread_bucket = str(
            quote_diag.get("spread_bucket")
            or quote_diag.get("sports_spread_bucket")
            or ("ultra_tight" if spread is not None and spread <= 0.012 else ("tight" if spread is not None and spread <= 0.03 else ("wide_but_possible" if spread is not None and spread <= AION_SPORTS_MAX_SPREAD_SOFT else ("extreme_wide" if spread is not None and spread <= AION_SPORTS_MAX_SPREAD_HARD else "unsafe"))))
        ).strip().lower() or "unknown"
        canonical_tradeability = quote_diag.get("canonical_tradeability") if isinstance(quote_diag.get("canonical_tradeability"), dict) else {}
        canonical_spread_classification = str(
            canonical_tradeability.get("spread_classification")
            or quote_diag.get("spread_classification")
            or quote_diag.get("canonical_spread_classification")
            or "UNSAFE"
        ).strip().upper() or "UNSAFE"
        valid_spread_bucket = spread_bucket in {"ultra_tight", "tight", "wide_but_possible", "extreme_wide"}
        book_valid = bool(canonical_source.get("book_valid"))
        normalized_consistent = bool(canonical_source.get("normalized_consistent"))
        bid_ask_consistent = bool(best_bid is None or best_ask is None or best_bid <= best_ask)
        book_missing_reasons = []
        if not yes_bid_valid and not yes_ask_valid:
            book_missing_reasons.append("yes_side_missing")
        if not no_bid_valid and not no_ask_valid:
            book_missing_reasons.append("no_side_missing")
        if best_bid is None or best_ask is None:
            book_missing_reasons.append("missing_bid_ask")
        elif best_bid <= 0.0 or best_ask <= 0.0:
            book_missing_reasons.append("non_positive_bid_ask")
        elif not bid_ask_consistent:
            book_missing_reasons.append("inverted_bid_ask")
        if not normalized_consistent:
            book_missing_reasons.append("normalized_inconsistent")
        if not valid_spread_bucket:
            book_missing_reasons.append("spread_bucket_not_allowed")
        if not book_valid and not book_missing_reasons:
            book_missing_reasons.append("insufficient_quote_detail")

        selected_price_candidate = self.to_float(
            quote_diag.get("selected_price_dollars", quote_diag.get("selected_price")),
            None,
        )
        if selected_price_candidate is None:
            selected_side_candidate = str(quote_diag.get("selected_side") or "").strip().lower() or None
            if selected_side_candidate == "yes":
                selected_price_candidate = yes_ask if yes_ask is not None else yes_bid
            elif selected_side_candidate == "no":
                selected_price_candidate = no_ask if no_ask is not None else no_bid
            else:
                selected_price_candidate = yes_ask if yes_ask is not None else (no_ask if no_ask is not None else (yes_bid if yes_bid is not None else no_bid))
        price_bounds_pass = bool(selected_price_candidate is not None and KALSHI_CONTRACT_MIN_PRICE <= selected_price_candidate <= KALSHI_CONTRACT_MAX_PRICE)
        topbook_depth_exists = bool(
            self.to_float(quote_diag.get("yes_top_size"), 0.0) > 0.0
            or self.to_float(quote_diag.get("no_top_size"), 0.0) > 0.0
            or self.to_float(quote_diag.get("yes_bid"), 0.0) > 0.0
            or self.to_float(quote_diag.get("no_bid"), 0.0) > 0.0
            or self.to_float(quote_diag.get("yes_ask"), 0.0) > 0.0
            or self.to_float(quote_diag.get("no_ask"), 0.0) > 0.0
            or self.to_float(canonical_source.get("yes_bid_cents"), 0.0) > 0.0
            or self.to_float(canonical_source.get("no_bid_cents"), 0.0) > 0.0
            or self.to_float(canonical_source.get("yes_ask_cents"), 0.0) > 0.0
            or self.to_float(canonical_source.get("no_ask_cents"), 0.0) > 0.0
            or bool(quote_diag.get("topbook_snapshot_present"))
            or bool(quote_diag.get("normalized_orderbook_present"))
        )
        edge_after_cost_value = self.to_float(quote_diag.get("edge_after_cost"), self.to_float(quote_diag.get("final_edge"), self.to_float(quote_diag.get("sports_edge_after_cost"), 0.0)))
        liquidity_depth_value = self.to_float(quote_diag.get("liquidity_depth"), self.to_float(quote_diag.get("liquidity"), 0.0))
        if liquidity_depth_value <= 0.0 and topbook_depth_exists:
            liquidity_depth_value = max(1.0, self.to_float(quote_diag.get("yes_top_size"), 0.0) + self.to_float(quote_diag.get("no_top_size"), 0.0))
        aggression_profile = _normalize_aion_aggression_profile(AION_AGGRESSION_PROFILE)
        aggression_settings = _aion_aggression_profile_settings(aggression_profile, family=family, spread_bucket=spread_bucket, context=source)
        freshness_seconds = self.to_float(quote_diag.get("stale_seconds"), self.to_float(quote_diag.get("cache_age_seconds"), None))
        fresh_enough = bool(freshness_seconds is None or freshness_seconds <= 900.0)
        selected_side_has_price = bool(price_bounds_pass and selected_price_candidate is not None)
        selected_side_has_liquidity = bool(
            topbook_depth_exists
            or liquidity_depth_value > 0.0
            or self.to_float(quote_diag.get("yes_top_size"), 0.0) > 0.0
            or self.to_float(quote_diag.get("no_top_size"), 0.0) > 0.0
        )
        depth_available = bool(topbook_depth_exists or selected_side_has_liquidity)
        book_usable = bool(book_valid or topbook_depth_exists or selected_side_has_price or selected_side_has_liquidity)
        opportunistic_edge_floor = max(self.to_float(aggression_settings.get("effective_edge_threshold"), 0.001), 0.0015)
        extreme_edge_floor = max(opportunistic_edge_floor * 1.5, 0.0025)
        if not book_valid and not any(book_missing_reasons):
            unsafe_price_status = "both_sides_unexecutable"
            unsafe_resolution_reason = "missing_quote_book"
        elif not price_bounds_pass:
            unsafe_price_status = "unexecutable_price"
            unsafe_resolution_reason = "selected_price_out_of_bounds"
        elif book_valid and spread_bucket in {"ultra_tight", "tight", "wide_but_possible"} and normalized_consistent:
            unsafe_price_status = "safe"
            unsafe_resolution_reason = "valid_structurally_consistent_book"
        elif book_usable and spread_bucket in {"unsafe", "extreme_wide"}:
            edge_floor = extreme_edge_floor if spread_bucket == "extreme_wide" else opportunistic_edge_floor
            opportunistic_wide_spread_ok = bool(
                aggression_profile in {"opportunistic", "beast"}
                and price_bounds_pass
                and selected_side_has_price
                and fresh_enough
                and edge_after_cost_value >= edge_floor
                and (normalized_consistent or book_valid or topbook_depth_exists)
            )
            if opportunistic_wide_spread_ok:
                unsafe_price_status = "caution_wide_spread"
                unsafe_resolution_reason = "wide_spread_but_executable"
                spread_bucket = "wide_but_possible"
            else:
                unsafe_price_status = "unsafe_spread"
                unsafe_resolution_reason = "spread_bucket_not_allowed" if spread_bucket != "extreme_wide" else "extreme_wide_edge_weak"
        elif book_usable:
            unsafe_price_status = "caution_wide_spread" if price_bounds_pass and selected_side_has_price and edge_after_cost_value >= opportunistic_edge_floor else "unsafe_spread"
            unsafe_resolution_reason = "partial_quote_but_executable" if unsafe_price_status == "caution_wide_spread" else "spread_bucket_not_allowed"
        elif yes_bid_valid or yes_ask_valid or no_bid_valid or no_ask_valid:
            unsafe_price_status = "unexecutable_price"
            unsafe_resolution_reason = "partial_quote_book"
        else:
            unsafe_price_status = "both_sides_unexecutable"
            unsafe_resolution_reason = "missing_quote_book"

        beast_spread_override_applied = bool(
            aggression_profile == "beast"
            and canonical_spread_classification == "AGGRESSIVE_BUT_TRADEABLE"
            and price_bounds_pass
            and edge_after_cost_value > 0.0
            and (book_valid or normalized_consistent or topbook_depth_exists or selected_side_has_price)
        )
        if beast_spread_override_applied and unsafe_price_status in {"unsafe_spread", "unsafe"}:
            unsafe_price_status = "caution_wide_spread"
            unsafe_resolution_reason = "beast_mode_wide_spread_allowed"
            if spread_bucket == "unsafe":
                spread_bucket = "wide_but_possible"
        thin_book_override_applied = bool(
            aggression_profile == "beast"
            and canonical_spread_classification == "AGGRESSIVE_BUT_TRADEABLE"
            and selected_side_has_price
            and edge_after_cost_value > 0.0
            and (book_valid or topbook_depth_exists or selected_side_has_liquidity or normalized_consistent or fresh_enough)
            and unsafe_price_status not in {"unsafe_spread", "unexecutable_price", "both_sides_unexecutable"}
        )
        if thin_book_override_applied:
            unsafe_price_status = "caution_wide_spread"
            unsafe_resolution_reason = "thin_book_beast_allowed"

        spread_severity = "catastrophic" if unsafe_price_status in {"unsafe_spread", "unexecutable_price", "both_sides_unexecutable"} else "survivable"
        spread_is_catastrophic = bool(spread_severity == "catastrophic" and not beast_spread_override_applied)
        spread_is_survivable = bool(not spread_is_catastrophic)
        final_submit_allowed_by_realm_vv = bool(
            price_bounds_pass
            and edge_after_cost_value > 0.0
            and quote_diag.get("quote_ready", True)
            and (not spread_is_catastrophic or thin_book_override_applied)
        )
        payload = {
            "ticker": ticker or None,
            "family": family,
            "best_bid": round(best_bid, 4) if best_bid is not None else None,
            "best_ask": round(best_ask, 4) if best_ask is not None else None,
            "midpoint": round(midpoint, 4) if midpoint is not None else None,
            "spread": round(spread, 4) if spread is not None else None,
            "raw_yes_price": round(raw_yes_price, 4) if raw_yes_price is not None else None,
            "raw_no_price": round(raw_no_price, 4) if raw_no_price is not None else None,
            "normalized_yes_price": round(normalized_yes_price, 4) if normalized_yes_price is not None else None,
            "normalized_no_price": round(normalized_no_price, 4) if normalized_no_price is not None else None,
            "book_valid": bool(book_valid),
            "book_missing_reason": ",".join(dict.fromkeys(book_missing_reasons)) or None,
            "selected_side_has_price": bool(selected_side_has_price),
            "selected_side_has_liquidity": bool(selected_side_has_liquidity),
            "depth_available": bool(depth_available),
            "derived_price_used": bool(quote_diag.get("derived_price_used") or quote_diag.get("derived_price_source") not in (None, "", "unknown")),
            "derived_price_source": str(quote_diag.get("derived_price_source") or "unknown").strip().lower() or "unknown",
            "thin_book_override_applied": bool(thin_book_override_applied),
            "unsafe_price_status": unsafe_price_status,
            "unsafe_resolution_reason": unsafe_resolution_reason,
            "spread_classification": canonical_spread_classification,
            "spread_severity": spread_severity,
            "spread_is_catastrophic": bool(spread_is_catastrophic),
            "spread_is_survivable": bool(spread_is_survivable),
            "beast_spread_override_applied": bool(beast_spread_override_applied),
            "final_submit_allowed_by_realm_vv": bool(final_submit_allowed_by_realm_vv),
            "source": source,
        }
        print("[AION-UNSAFE-PRICE-DETAIL] " + json.dumps(payload, sort_keys=True, default=str))
        return payload

    def _realm_vv_selection_priority(self, market, q):
        market = market if isinstance(market, dict) else {}
        ticker = str(getattr(q, "ticker", "") or market.get("ticker", "") or "").strip()
        gate_record = self._get_phase55_live_execution_gate_record(ticker, stage="canary_selection") if ticker else {}
        if not self._realm_vv_record_has_meaningful_data(gate_record):
            return False, 0.0, gate_record
        candidate_source = str(gate_record.get("candidate_source") or "").strip().lower()
        decision = str(gate_record.get("decision") or "").strip().upper()
        entry_ready = bool(gate_record.get("entry_ready") is True or gate_record.get("entry_timing_pass") is True or gate_record.get("normalized_ready") is True)
        final_submit_allowed = bool(
            gate_record.get("final_submit_allowed_by_realm_vv")
            if gate_record.get("final_submit_allowed_by_realm_vv") is not None
            else gate_record.get("realm_vv_final_submit_allowed_by_realm_vv")
        )
        quote_ready = bool(gate_record.get("quote_ready") is not False)
        price = self.to_float(getattr(q, "yes_ask", None), self.to_float(gate_record.get("selected_price_dollars"), None))
        price_bounds_pass = bool(price is not None and 0.0 < price < 1.0)
        allowed = bool(
            candidate_source == "realm_vv_entry_engine"
            and decision in {"BUY", "LIVE_PROMOTION"}
            and entry_ready
            and final_submit_allowed
            and quote_ready
            and price_bounds_pass
        )
        if not allowed:
            return False, 0.0, gate_record
        priority_boost = 20.0
        if gate_record.get("beast_spread_override_applied") is True:
            priority_boost += 5.0
        if gate_record.get("spread_classification") in {"AGGRESSIVE_BUT_TRADEABLE", "CAUTION_WIDE_SPREAD"}:
            priority_boost += 5.0
        return True, priority_boost, gate_record

    def _score_live_ticker_candidate(self, q: Quote, market=None):
        market = market if isinstance(market, dict) else {}
        spread = q.yes_ask - q.yes_bid
        mid_price = q.yes_ask
        if q.yes_bid > 0:
            mid_price = (q.yes_bid + q.yes_ask) / 2
        score = 0.0
        score += max(0.0, MAX_ENTRY_SPREAD - spread) * 40
        score += min(q.liquidity, 500) / 25
        score += min(q.volume, 500) / 40
        if 0.68 <= q.yes_ask <= 0.93 and 0 <= spread <= 0.045:
            score += 10.0
        if q.volume > SMART_ENTRY_PRIORITY_VOLUME_THRESHOLD and 0 <= spread <= SMART_ENTRY_PRIORITY_TIGHT_SPREAD:
            score += 8.0
            if 0.68 <= q.yes_ask <= 0.93:
                score += 6.0
        realm_vv_priority, realm_vv_priority_boost, _realm_vv_gate = self._realm_vv_selection_priority(market, q)
        if realm_vv_priority:
            score += realm_vv_priority_boost
        score += max(0.0, 0.25 - abs(mid_price - 0.5)) * 8
        score += max(0.0, 24 - len(q.ticker)) / 24
        return round(score, 4)

    def _should_adaptive_allow_momentum_warning(self, ticker, yes_ask=None, spread=None, payload=None):
        ticker = str(ticker or "").strip()
        gate_record = self._get_phase55_live_execution_gate_record(ticker, stage="adaptive_momentum")
        payload_action = str((payload or {}).get("action") or "").strip().lower() if isinstance(payload, dict) else ""
        decision = str(gate_record.get("decision") or "").strip().upper()
        buy_intent = bool(decision == "BUY" or payload_action == "buy")
        phase55_status = str(gate_record.get("phase55_status") or "").strip()
        entry_timing_pass = gate_record.get("entry_timing_pass") is True
        price_valid = yes_ask is not None and yes_ask > 0
        spread_valid = spread is not None and spread <= 0.03
        adaptive_allow = bool(
            ticker
            and buy_intent
            and price_valid
            and spread_valid
        )
        why = []
        if not ticker:
            why.append("missing_ticker")
        if not buy_intent:
            why.append("decision_not_buy")
        if not price_valid:
            why.append("invalid_price")
        if not spread_valid:
            why.append("spread_above_0.03")
        return adaptive_allow, {
            "decision": decision,
            "buy_intent": buy_intent,
            "phase55_status": phase55_status,
            "entry_timing_pass": entry_timing_pass,
            "price_valid": price_valid,
            "spread_valid": spread_valid,
            "why": ",".join(why) if why else "eligible",
        }

    def _aion_final_submit_stale_spread_blocker_reasons(self, *, family=None, ticker=None, crypto_final_submit_lane=False):
        if not (crypto_final_submit_lane or self.is_sports_family(family, ticker=ticker)):
            return set()
        return {
            "spread_too_wide",
            "spread_not_tight_enough",
        }

    def _evaluate_mlb_total_entry_confirmation(self, ticker, recent_prices, recent_delta, spread, adaptive_allow=False):
        recent_prices = [float(price) for price in (recent_prices or []) if price is not None]
        if spread is None or spread > 0.03:
            return False, "spread_not_tight_enough"
        if len(recent_prices) < 3:
            return False, "insufficient_recent_price_history"
        recent_range = max(recent_prices) - min(recent_prices)
        last_step_delta = recent_prices[-1] - recent_prices[-2]
        reversing = recent_prices[-1] < recent_prices[-2]
        if recent_delta is None or recent_delta < MLB_TOTAL_MIN_MOMENTUM_DELTA:
            return False, "momentum_too_weak"
        if recent_range < MLB_TOTAL_MIN_MOMENTUM_RANGE:
            return False, "price_action_flat"
        if last_step_delta < MLB_TOTAL_MIN_LAST_STEP_DELTA:
            return False, "last_step_not_improving"
        if reversing:
            return False, "recent_reversal_detected"
        if adaptive_allow and last_step_delta <= 0:
            return False, "adaptive_allow_without_stronger_confirmation"
        return True, "confirmed"

    def _evaluate_smart_entry_gate(self, market, q, payload=None):
        ticker = getattr(q, "ticker", "") or str((market or {}).get("ticker", "") or "").strip()
        family = self.get_market_family(market or {"ticker": ticker}) if ticker else "UNKNOWN"
        payload = payload if isinstance(payload, dict) else {}
        def _q_get(obj, *names, default=None):
            if obj is None:
                return default
            for name in names:
                if isinstance(obj, dict):
                    value = obj.get(name)
                else:
                    value = getattr(obj, name, None)
                if value is not None:
                    return value
            return default
        price_source_fields_checked = []
        yes_bid = self.normalize_contract_price(_q_get(q, "yes_bid", default=0.0) or 0.0, ticker=ticker, source="smart_entry.yes_bid")
        yes_ask = self.normalize_contract_price(_q_get(q, "yes_ask", default=0.0) or 0.0, ticker=ticker, source="smart_entry.yes_ask")
        no_bid = self.normalize_contract_price(_q_get(q, "no_bid", default=0.0) or 0.0, ticker=ticker, source="smart_entry.no_bid")
        no_ask = self.normalize_contract_price(_q_get(q, "no_ask", default=0.0) or 0.0, ticker=ticker, source="smart_entry.no_ask")
        selected_side = str(
            _q_get(q, "selected_side")
            or _q_get(q, "side")
            or payload.get("selected_side")
            or ""
        ).strip().lower() or None
        raw_selected_price = _q_get(q, "selected_price")
        raw_selected_price_dollars = _q_get(q, "selected_price_dollars")
        raw_selected_price_cents = _q_get(q, "selected_price_cents")
        payload_selected_price = payload.get("selected_price")
        payload_selected_price_dollars = payload.get("selected_price_dollars")
        payload_selected_price_cents = payload.get("selected_price_cents")
        raw_price_candidate = (
            raw_selected_price
            if raw_selected_price is not None
            else raw_selected_price_dollars
            if raw_selected_price_dollars is not None
            else payload_selected_price
            if payload_selected_price is not None
            else payload_selected_price_dollars
            if payload_selected_price_dollars is not None
            else yes_ask
            if selected_side == "yes"
            else no_ask
            if selected_side == "no"
            else yes_ask
        )
        normalized_price = self.normalize_contract_price(raw_price_candidate, ticker=ticker, source="smart_entry.selected_price_candidate")
        selected_price_value = self.to_float(
            raw_selected_price_dollars if raw_selected_price_dollars is not None else raw_selected_price,
            self.to_float(payload_selected_price_dollars if payload_selected_price_dollars is not None else payload_selected_price, normalized_price),
        )
        selected_price_cents = raw_selected_price_cents if raw_selected_price_cents is not None else payload_selected_price_cents
        try:
            if selected_price_cents is not None and selected_price_cents != "":
                selected_price_cents = int(round(float(selected_price_cents)))
        except (TypeError, ValueError):
            selected_price_cents = None
        evaluated_price = normalized_price if normalized_price is not None else yes_ask if selected_side == "yes" else no_ask if selected_side == "no" else yes_ask
        min_price_bound = KALSHI_CONTRACT_MIN_PRICE
        max_price_bound = KALSHI_CONTRACT_MAX_PRICE
        price_bounds_decision = self._aion_price_bounds_decision(
            selected_price=selected_price_value,
            selected_price_cents=selected_price_cents,
            yes_ask=yes_ask,
            yes_bid=yes_bid,
            no_ask=no_ask,
            no_bid=no_bid,
            min_price=min_price_bound,
            max_price=max_price_bound,
        )
        spread_context = self._resolve_aion_canonical_spread_context(
            market=market,
            q=q,
            payload=payload,
            quote_diag={},
            selected_side=selected_side,
            source_label="smart_entry.spread",
        )
        spread = self.to_float(spread_context.get("spread"), None)
        spread_cents = spread_context.get("spread_cents")
        spread_source = spread_context.get("spread_source")
        spread_reason = spread_context.get("spread_reason")
        spread_missing_fields = list(spread_context.get("spread_missing_fields") or [])
        spread_source_fields_checked = list(spread_context.get("source_fields_checked") or [])
        self._emit_aion_price_bounds_source(
            caller="smart_entry_gate",
            price_bounds_decision=price_bounds_decision,
            selected_price=selected_price_value,
            selected_price_cents=selected_price_cents,
            ticker=ticker,
            family=family,
            source_of_truth="selected_price_cents" if selected_price_cents is not None else "selected_price_normalized",
            rejection_origin=price_bounds_decision.get("block_reason"),
        )
        spread_trace = {
            "ticker": ticker or None,
            "family": family,
            "stage": "smart_entry_gate",
            "selected_side": selected_side,
            "yes_ask": yes_ask,
            "yes_bid": yes_bid,
            "no_ask": no_ask,
            "no_bid": no_bid,
            "spread": spread,
            "spread_cents": spread_cents,
            "spread_source": spread_source,
            "spread_reason": spread_reason,
            "spread_missing_fields": spread_missing_fields,
            "source_fields_checked": sorted(set(price_source_fields_checked + spread_source_fields_checked)),
        }
        print("[AION-SPREAD-EVAL] " + json.dumps(spread_trace, sort_keys=True, default=str))
        if spread_source and spread_source != "yes_bid_yes_ask":
            print("[AION-SPREAD-DERIVED] " + json.dumps(spread_trace, sort_keys=True, default=str))
        edge = "bad"
        reason = "missing_yes_top_book"
        momentum_ok = True
        recent_delta = None
        high_prob_ok = False
        adaptive_allow = False
        sports_smart_spread_context = None
        recent_prices = []
        session_adjustment = self._get_live_session_entry_adjustment(adaptive_entry=False, borderline=False)
        price_source_fields_checked = [
            "q.selected_price",
            "q.selected_price_dollars",
            "q.selected_price_cents",
            "q.selected_side",
            "q.side",
            "q.yes_ask",
            "q.no_ask",
            "q.yes_bid",
            "q.no_bid",
            "payload.selected_price",
            "payload.selected_price_dollars",
            "payload.selected_price_cents",
            "payload.yes_price",
            "payload.no_price",
        ]
        print(
            "[AION-PRICE-RANGE-EVAL] "
            + json.dumps(
                {
                    "ticker": ticker or None,
                    "family": family,
                    "selected_side": selected_side,
                    "raw_price": raw_price_candidate,
                    "normalized_price": normalized_price,
                    "evaluated_price": evaluated_price,
                    "min_bound": min_price_bound,
                    "max_bound": max_price_bound,
                    "selected_price": selected_price_value,
                    "selected_price_cents": selected_price_cents,
                    "yes_ask": yes_ask,
                    "yes_bid": yes_bid,
                    "no_ask": no_ask,
                    "no_bid": no_bid,
                    "source_fields_checked": price_source_fields_checked,
                },
                sort_keys=True,
                default=str,
            ),
            flush=True,
        )
        if evaluated_price is None or evaluated_price <= 0 or evaluated_price < min_price_bound or evaluated_price > max_price_bound:
            allowed = False
            reason = "price_out_of_range"
            try:
                reject_key = (
                    ticker,
                    str(raw_price_candidate),
                    str(yes_ask),
                    str(no_ask),
                    str(payload_selected_price),
                )
                reject_seen = getattr(self, "_aion_price_range_real_reject_seen_ts", {})
                now_ts = time.time()
                last_seen_ts = float(reject_seen.get(reject_key, 0.0) or 0.0) if isinstance(reject_seen, dict) else 0.0
                if now_ts - last_seen_ts >= 60.0:
                    if not isinstance(reject_seen, dict):
                        reject_seen = {}
                    reject_seen[reject_key] = now_ts
                    self._aion_price_range_real_reject_seen_ts = reject_seen
                    print(
                        "[AION-PRICE-RANGE-REAL-REJECT] "
                        + json.dumps(
                            {
                                "ticker": ticker or None,
                                "family": family,
                                "reason": reason,
                                "selected_side": selected_side,
                                "raw_price": raw_price_candidate,
                                "normalized_price": normalized_price,
                                "evaluated_price": evaluated_price,
                                "min_bound": min_price_bound,
                                "max_bound": max_price_bound,
                                "selected_price": selected_price_value,
                                "selected_price_cents": selected_price_cents,
                                "yes_ask": yes_ask,
                                "yes_bid": yes_bid,
                                "no_ask": no_ask,
                                "no_bid": no_bid,
                                "payload_selected_price": payload_selected_price,
                                "payload_selected_price_dollars": payload_selected_price_dollars,
                                "payload_selected_price_cents": payload_selected_price_cents,
                                "payload_selected_side": payload.get("selected_side"),
                                "source_fields_checked": price_source_fields_checked,
                            },
                            sort_keys=True,
                            default=str,
                        ),
                        flush=True,
                    )
            except Exception:
                pass
        elif spread is None or spread < 0:
            allowed = False
            reason = "missing_spread"
            reject_ts = time.time()
            print("[AION-SPREAD-REAL-REJECT] " + json.dumps(spread_trace, sort_keys=True, default=str))
            reject_ticker = ticker or None
            if reject_ticker:
                cooldown_until = reject_ts + float(AION_MISSING_SPREAD_TICKER_COOLDOWN_SECONDS)
                current_cooldown_until = float(self.market_cooldowns.get(reject_ticker, 0.0) or 0.0)
                if cooldown_until > current_cooldown_until:
                    self.market_cooldowns[reject_ticker] = cooldown_until
                print(
                    "[AION-MISSING-SPREAD-TICKER-COOLDOWN] "
                    + json.dumps(
                        {
                            "ticker": reject_ticker,
                            "family": family,
                            "reason": reason,
                            "cooldown_seconds": int(AION_MISSING_SPREAD_TICKER_COOLDOWN_SECONDS),
                            "cooldown_until": round(cooldown_until, 3),
                            "source_fields_checked": sorted(set(price_source_fields_checked + spread_source_fields_checked)),
                        },
                        sort_keys=True,
                        default=str,
                    )
                )
                print(
                    "[AION-SCAN-CONTINUE-AFTER-SPREAD-REJECT] "
                    + json.dumps(
                        {
                            "ticker": reject_ticker,
                            "family": family,
                            "reason": reason,
                            "next_action": "continue_scan",
                            "cooldown_applied": True,
                        },
                        sort_keys=True,
                        default=str,
                    )
                )
            self._record_missing_spread_family_reject(family, ticker, reason, now_ts=reject_ts)
        else:
            high_prob_spread_limit = 0.045
            if self._is_sports_market_or_family(family):
                adaptive_spread_context = self._get_sports_adaptive_spread_threshold(
                    market or {"ticker": ticker},
                    spread=spread,
                    context="smart_entry_gate",
                )
                high_prob_spread_limit = max(
                    high_prob_spread_limit,
                    self.to_float(adaptive_spread_context.get("adaptive_threshold"), high_prob_spread_limit),
                )
            high_prob_ok = bool(spread <= high_prob_spread_limit)
            timing_history_key = self._build_phase55_timing_history_key(market or {"ticker": ticker}, q, family=family)
            rolling_history_map = getattr(self, "phase55_rolling_price_history", {})
            rolling_history = list((rolling_history_map if isinstance(rolling_history_map, dict) else {}).get(str(timing_history_key or "").strip(), []))
            recent_prices = [float(price) for price in rolling_history[-4:] if price is not None]
            if len(recent_prices) >= 2:
                recent_delta = recent_prices[-1] - recent_prices[0]
                momentum_ok = recent_delta >= 0
            allowed = bool(high_prob_ok and momentum_ok)
            if allowed:
                edge = "good"
                reason = "junk_bond_neutral_momentum" if recent_delta is None else "junk_bond"
            elif not high_prob_ok:
                if self.is_sports_family(family, ticker=ticker):
                    sports_smart_spread_context = self._sports_adaptive_spread_decision(
                        market or {"ticker": ticker, "series_ticker": family},
                        q=q,
                        family=family,
                        spread=spread,
                        liquidity=payload.get("liquidity") or payload.get("liquidity_depth") or getattr(q, "liquidity", None),
                        quote_diag={
                            "ticker": ticker,
                            "family": family,
                            "selected_side": selected_side,
                            "selected_price": selected_price_value,
                            "selected_price_dollars": selected_price_value,
                            "selected_price_cents": selected_price_cents,
                            "yes_bid": yes_bid,
                            "yes_ask": yes_ask,
                            "no_bid": no_bid,
                            "no_ask": no_ask,
                            "yes_top_size": payload.get("yes_top_size") or getattr(q, "yes_top_size", None),
                            "no_top_size": payload.get("no_top_size") or getattr(q, "no_top_size", None),
                            "liquidity": payload.get("liquidity") or payload.get("liquidity_depth") or getattr(q, "liquidity", None),
                            "edge_after_cost": payload.get("edge_after_cost") or payload.get("sports_edge_after_cost") or getattr(q, "edge_after_cost", None),
                            "sports_edge_after_cost": payload.get("sports_edge_after_cost") or payload.get("edge_after_cost") or getattr(q, "sports_edge_after_cost", None),
                            "selected_fill_probability": payload.get("selected_fill_probability") or getattr(q, "selected_fill_probability", None),
                            "game_thesis_confidence": payload.get("game_thesis_confidence") or getattr(q, "game_thesis_confidence", None),
                            "sports_regime": payload.get("sports_regime") or getattr(q, "sports_regime", None),
                            "sports_momentum_classification": payload.get("sports_momentum_classification") or getattr(q, "sports_momentum_classification", None),
                            "sports_ladder_role": payload.get("sports_ladder_role") or getattr(q, "sports_ladder_role", None),
                        },
                        context="smart_entry_gate",
                    )
                    if sports_smart_spread_context.get("allowed"):
                        allowed = True
                        adaptive_allow = True
                        edge = "good"
                        reason = "sports_wide_spread_cost_smart_entry_pass"
                    else:
                        reason = str(sports_smart_spread_context.get("reason") or "sports_spread_book_block")
                else:
                    reason = "spread_too_wide"
            else:
                adaptive_allow, adaptive_details = self._should_adaptive_allow_momentum_warning(
                    ticker,
                    yes_ask=yes_ask,
                    spread=spread,
                    payload=payload,
                )
                if adaptive_allow:
                    borderline_adaptive = bool(yes_ask >= 0.85 or (spread is not None and spread >= 0.025) or recent_delta is None)
                    session_adjustment = self._get_live_session_entry_adjustment(
                        adaptive_entry=True,
                        borderline=borderline_adaptive,
                    )
                    if session_adjustment.get("adaptive_block"):
                        adaptive_allow = False
                        allowed = False
                        reason = "session_mode_requires_stronger_confirmation"
                    else:
                        allowed = True
                        edge = "good"
                        reason = "momentum_warning"
                        print(
                            f"[LIVE-EXECUTION-MOMENTUM-WARN] ticker={ticker} "
                            f"adaptive_allow=yes original_reason=momentum_not_stable "
                            f"price={yes_ask} spread={spread}"
                        )
                else:
                    sports_timing_cost_allowed = bool(
                        self.is_sports_family(family, ticker=ticker)
                        and evaluated_price is not None
                        and min_price_bound <= evaluated_price <= max_price_bound
                        and spread is not None
                        and 0.0 <= spread <= float(AION_SPORTS_MAX_SPREAD_HARD)
                        and (
                            selected_side in {"yes", "no"}
                            or yes_ask is not None
                            or no_ask is not None
                            or selected_price_cents is not None
                        )
                    )
                    if sports_timing_cost_allowed:
                        adaptive_allow = True
                        allowed = True
                        edge = "good"
                        reason = "sports_timing_gate_demoted_to_execution_cost"
                        print(
                            "[AION-TIMING-GATE-BYPASS] "
                            + json.dumps(
                                {
                                    "ticker": ticker or None,
                                    "family": family,
                                    "gate": "smart_entry_gate",
                                    "original_reason": "momentum_not_stable",
                                    "selected_side": selected_side,
                                    "selected_price": selected_price_value,
                                    "evaluated_price": evaluated_price,
                                    "spread": spread,
                                    "reason": reason,
                                },
                                sort_keys=True,
                                default=str,
                            )
                        )
                    else:
                        reason = "momentum_not_stable"
                        now_ts = time.time()
                        last_log_ts = float(self.live_momentum_hard_block_log_last_seen.get(ticker, 0.0) or 0.0)
                        if (now_ts - last_log_ts) >= 30.0:
                            print(
                                f"[LIVE-EXECUTION-MOMENTUM-HARD-BLOCK] ticker={ticker} "
                                f"reason=momentum_not_stable why={adaptive_details.get('why')}"
                            )
                            self.live_momentum_hard_block_log_last_seen[ticker] = now_ts
        if family == "KXMLBTOTAL" and (allowed or adaptive_allow):
            mlb_confirm_ok, mlb_confirm_reason = self._evaluate_mlb_total_entry_confirmation(
                ticker,
                recent_prices=recent_prices,
                recent_delta=recent_delta,
                spread=spread,
                adaptive_allow=adaptive_allow,
            )
            if mlb_confirm_ok:
                print(
                    f"[LIVE-MLB-ENTRY-CONFIRM-PASS] ticker={ticker} spread={spread} "
                    f"delta={recent_delta} adaptive_allow={'yes' if adaptive_allow else 'no'}"
                )
            else:
                print(
                    f"[LIVE-MLB-ENTRY-CONFIRM-REJECT] ticker={ticker} spread={spread} "
                    f"delta={recent_delta} adaptive_allow={'yes' if adaptive_allow else 'no'} reason={mlb_confirm_reason}"
                )
                allowed = False
                adaptive_allow = False
                edge = "bad"
                reason = mlb_confirm_reason
        status = "adaptive_allowed" if adaptive_allow else ("accepted" if allowed else "rejected")
        momentum_status = "passed" if momentum_ok else "blocked"
        print(f"[MOMENTUM-CHECK] ticker={ticker} status={momentum_status} delta={recent_delta}")
        print(f"[SMART-ENTRY] ticker={ticker} price={yes_ask} spread={spread} edge={edge}")
        print(f"[HIGH-PROB-ENTRY] ticker={ticker} price={yes_ask} spread={spread} status={status} reason={reason}")
        print(f"[EDGE-ENTRY] ticker={ticker} price={yes_ask} spread={spread} status={status} reason={reason}")
        return allowed, reason, {
            "ticker": ticker,
            "family": family,
            "price": yes_ask,
            "edge": edge,
            "momentum_ok": momentum_ok,
            "recent_delta": recent_delta,
            "spread": spread,
            "high_prob_ok": high_prob_ok,
            "high_prob_spread_limit": high_prob_spread_limit if spread is not None else None,
            "adaptive_allow": adaptive_allow,
            "raw_price": raw_price_candidate,
            "normalized_price": normalized_price,
            "evaluated_price": evaluated_price,
            "min_bound": min_price_bound,
            "max_bound": max_price_bound,
            "selected_price": selected_price_value,
            "selected_price_cents": selected_price_cents,
            "spread": spread,
            "spread_source": spread_source,
            "spread_missing_fields": spread_missing_fields,
            "sports_spread_context": sports_smart_spread_context,
            "yes_ask": yes_ask,
            "yes_bid": yes_bid,
            "no_ask": no_ask,
            "no_bid": no_bid,
            "source_fields_checked": sorted(set(price_source_fields_checked + spread_source_fields_checked)),
        }

    def _is_high_prob_submission_candidate(self, q, market=None):
        ticker = getattr(q, "ticker", "") or str((market or {}).get("ticker", "") or "").strip()
        market = market or {"ticker": ticker}
        family = self.get_market_family(market) if ticker else "UNKNOWN"
        yes_bid = self.normalize_contract_price(getattr(q, "yes_bid", 0.0) or 0.0, ticker=ticker, source="submission_candidate.yes_bid")
        yes_ask = self.normalize_contract_price(getattr(q, "yes_ask", 0.0) or 0.0, ticker=ticker, source="submission_candidate.yes_ask")
        spread = (yes_ask - yes_bid) if yes_ask and yes_bid else None
        recent_delta = None
        momentum_ok = True
        if yes_ask is None or yes_ask < KALSHI_CONTRACT_MIN_PRICE or yes_ask > KALSHI_CONTRACT_MAX_PRICE or spread is None or spread < 0 or spread > 0.045:
            return False, {"ticker": ticker, "family": family, "yes_ask": yes_ask, "spread": spread, "recent_delta": recent_delta}
        timing_history_key = self._build_phase55_timing_history_key(market, q, family=family)
        rolling_history_map = getattr(self, "phase55_rolling_price_history", {})
        rolling_history = list((rolling_history_map if isinstance(rolling_history_map, dict) else {}).get(str(timing_history_key or "").strip(), []))
        recent_prices = [float(price) for price in rolling_history[-4:] if price is not None]
        if len(recent_prices) >= 2:
            recent_delta = recent_prices[-1] - recent_prices[0]
            momentum_ok = recent_delta >= 0
        return bool(momentum_ok), {"ticker": ticker, "family": family, "yes_ask": yes_ask, "spread": spread, "recent_delta": recent_delta}

    def _classify_entry_block_reason(self, reason):
        reason = str(reason or "").strip().lower()
        if (
            "phase55" in reason
            or reason in {
                "insufficient_data",
                "trigger_wait",
                "no_crossover",
                "pullback_wait",
                "immediate_entry_block",
            }
        ):
            return "phase55"
        if "negative_edge" in reason or "top_book" in reason:
            return "negative_edge"
        if "stale_signal" in reason or "direction_changed" in reason or "spread_deteriorated" in reason:
            return "stale"
        if "duplicate" in reason or "sim_position_open" in reason or "live_position_open_same_ticker" in reason:
            return "duplicate"
        return "other"

