    def _emit_aion_memory_log(self, tag, payload, marker=None):
        markers = getattr(self, "aion_distilled_memory_log_markers", None)
        if markers is None:
            self.aion_distilled_memory_log_markers = {}
            markers = self.aion_distilled_memory_log_markers
        if marker is not None:
            marker_key = tuple(marker) if isinstance(marker, (list, tuple)) else marker
            if marker_key in markers:
                return
            markers[marker_key] = time.time()
            if len(markers) > 1000:
                cutoff = time.time() - 3600.0
                self.aion_distilled_memory_log_markers = {
                    key: value for key, value in markers.items() if self.to_float(value, 0.0) >= cutoff
                }
        try:
            print(f"{tag} " + json.dumps(payload, sort_keys=True, default=str))
        except Exception:
            print(f"{tag} " + json.dumps({"reason": "memory_log_failed"}))

    def _aion_distilled_book_quality_tag(self, *, spread=None, liquidity=None, sports_tags=None):
        sports_tags = sports_tags if isinstance(sports_tags, list) else []
        if "SPORTS_GOOD_BOOK" in sports_tags:
            return "BOOK_GOOD"
        if "SPORTS_THIN_BOOK_RISK" in sports_tags:
            return "BOOK_THIN"
        spread_value = self.to_float(spread, None)
        liquidity_value = self.to_float(liquidity, None)
        if spread_value is not None and spread_value <= 0.03 and (liquidity_value is None or liquidity_value >= 0.0):
            return "BOOK_GOOD"
        if spread_value is not None and spread_value >= 0.12:
            return "BOOK_WIDE"
        return "BOOK_UNKNOWN"

    def _aion_distilled_odds_bucket(self, price):
        price_value = self.to_float(price, None)
        if price_value is None:
            return "unknown"
        if price_value > 1.0 and price_value <= 100.0:
            price_value = price_value / 100.0
        if price_value < 0.20:
            return "under_20"
        if price_value <= 0.35:
            return "20_35"
        if price_value <= 0.45:
            return "35_45"
        if price_value <= 0.60:
            return "45_60"
        if price_value <= 0.80:
            return "60_80"
        return "over_80"

    def _aion_distilled_asymmetry_bucket(self, price=None, payout_multiple=None):
        multiple = self.to_float(payout_multiple, None)
        price_value = self.to_float(price, None)
        if price_value is not None and price_value > 1.0 and price_value <= 100.0:
            price_value = price_value / 100.0
        if multiple is None and price_value is not None and price_value > 0.0:
            multiple = 1.0 / price_value
        if multiple is None:
            return "unknown"
        if multiple < 1.5:
            return "low_asymmetry"
        if multiple < 2.25:
            return "moderate_asymmetry"
        if multiple < 3.5:
            return "strong_asymmetry"
        return "extreme_asymmetry"

    def _aion_distilled_spread_bucket(self, spread):
        spread_value = self.to_float(spread, None)
        if spread_value is None:
            return "unknown"
        if spread_value > 1.0 and spread_value <= 100.0:
            spread_value = spread_value / 100.0
        if spread_value <= 0.03:
            return "tight"
        if spread_value <= 0.06:
            return "usable"
        if spread_value <= 0.12:
            return "wide"
        return "very_wide"

    def _aion_distilled_liquidity_bucket(self, liquidity):
        liquidity_value = self.to_float(liquidity, None)
        if liquidity_value is None:
            return "unknown"
        if liquidity_value < 25.0:
            return "thin"
        if liquidity_value < 250.0:
            return "light"
        if liquidity_value < 1000.0:
            return "usable"
        if liquidity_value < 5000.0:
            return "deep"
        return "very_deep"

    def _aion_distilled_sport_type(self, family=None, title=None, ticker=None):
        text = " ".join(str(value or "").upper() for value in (family, title, ticker))
        if "NBA" in text or "WNBA" in text:
            return "nba"
        if "MLB" in text or "BASEBALL" in text:
            return "mlb"
        if "NFL" in text or "FOOTBALL" in text or "CFB" in text or "NCAAF" in text:
            return "football"
        if "NHL" in text or "HOCKEY" in text:
            return "nhl"
        if "NCAA" in text or "CBB" in text or "NCAAB" in text:
            return "ncaa"
        if "ATP" in text or "WTA" in text or "TENNIS" in text:
            return "tennis"
        if "GOLF" in text or "PGA" in text:
            return "golf"
        if "EPL" in text or "SOCCER" in text:
            return "soccer"
        if "UFC" in text or "MMA" in text or "BOX" in text:
            return "combat"
        if "IPL" in text or "CRICKET" in text:
            return "cricket"
        return "sports"

    def _get_aion_distilled_learning_signal(
        self,
        *,
        family=None,
        category=None,
        sports_tags=None,
        odds_bucket=None,
        book_quality_tag=None,
        elite_trader_handle=None,
        side=None,
        asymmetry_bucket=None,
        liquidity_bucket=None,
        spread_bucket=None,
        sport_type=None,
        structural_tags=None,
        structural_pattern_keys=None,
        cross_market_bucket=None,
        elite_edge_bucket=None,
    ):
        engine = getattr(self, "aion_persistent_intelligence", None)
        if not AION_DISTILLED_MEMORY_ENABLED or engine is None or not hasattr(engine, "get_distilled_learning_signal"):
            return {
                "rank_adjustment": 0.0,
                "sports_boost_adjustment": 0.0,
                "sizing_confidence_multiplier": 1.0,
                "elite_trust_weight": 1.0,
                "components": [],
            }
        try:
            signal = engine.get_distilled_learning_signal(
                family=family,
                category=category,
                sports_tags=sports_tags if isinstance(sports_tags, list) else [],
                odds_bucket=odds_bucket,
                book_quality_tag=book_quality_tag,
                elite_trader_handle=elite_trader_handle,
                side=side,
                asymmetry_bucket=asymmetry_bucket,
                liquidity_bucket=liquidity_bucket,
                spread_bucket=spread_bucket,
                sport_type=sport_type,
                structural_tags=structural_tags if isinstance(structural_tags, list) else [],
                structural_pattern_keys=structural_pattern_keys if isinstance(structural_pattern_keys, list) else [],
                cross_market_bucket=cross_market_bucket,
                elite_edge_bucket=elite_edge_bucket,
            )
            return signal if isinstance(signal, dict) else {}
        except Exception as exc:
            self._emit_aion_memory_log(
                "[AION-MEMORY-LEARN]",
                {"reason": "signal_failed", "error": exc.__class__.__name__, "family": family},
                marker=("signal_failed", family, exc.__class__.__name__),
            )
            return {}

    def _record_aion_distilled_memory_event(self, event_type, event):
        if not AION_DISTILLED_MEMORY_ENABLED:
            return {"ok": False, "reason": "disabled"}
        engine = getattr(self, "aion_persistent_intelligence", None)
        if engine is None:
            return {"ok": False, "reason": "engine_unavailable"}
        if not isinstance(event, dict):
            return {"ok": False, "reason": "invalid_event"}
        try:
            family = str(event.get("family") or "UNKNOWN").strip().upper() or "UNKNOWN"
            category = str(event.get("category") or self.get_market_discovery_category(family) or "unknown").strip().lower() or "unknown"
            sports_tags = event.get("sports_tags") if isinstance(event.get("sports_tags"), list) else []
            sports_context = event.get("sports_edge_context") if isinstance(event.get("sports_edge_context"), dict) else {}
            structural_tags = event.get("structural_tags") if isinstance(event.get("structural_tags"), list) else []
            structural_pattern_keys = event.get("structural_pattern_keys") if isinstance(event.get("structural_pattern_keys"), list) else []
            selected_price = event.get("entry_price") if event.get("entry_price") is not None else event.get("price")
            elite_confidence_value = self.to_float(event.get("ELITE_EDGE_CONFIDENCE") or event.get("elite_edge_confidence"), None)
            elite_edge_bucket = (
                "elite_edge_elite" if elite_confidence_value is not None and elite_confidence_value >= 88.0 else
                "elite_edge_strong" if elite_confidence_value is not None and elite_confidence_value >= 75.0 else
                "elite_edge_promising" if elite_confidence_value is not None and elite_confidence_value >= 60.0 else
                "elite_edge_standard" if elite_confidence_value is not None and elite_confidence_value >= 42.0 else
                "elite_edge_weak" if elite_confidence_value is not None else
                None
            )
            record = {
                **event,
                "timestamp": event.get("timestamp_utc") or event.get("close_timestamp_utc"),
                "category": category,
                "family": family,
                "yes_price": event.get("yes_ask") or event.get("yes_bid"),
                "no_price": event.get("no_ask") or event.get("no_bid"),
                "price": selected_price,
                "entry_price": event.get("entry_price") or (selected_price if event_type in {"trade_opened", "candidate_seen"} else None),
                "exit_price": event.get("exit_price") or (selected_price if event_type == "trade_closed" else None),
                "position_size": event.get("contracts"),
                "candidate_score": event.get("confidence"),
                "score_at_entry": event.get("sports_score_at_entry") or event.get("confidence"),
                "sports_edge_score": event.get("sports_score_at_entry"),
                "structural_tags": structural_tags,
                "structural_pattern_keys": structural_pattern_keys,
                "structural_edge_score": event.get("STRUCTURAL_EDGE_SCORE") or event.get("structural_edge_score"),
                "cross_market_edge_score": event.get("CROSS_MARKET_EDGE_SCORE") or event.get("cross_market_edge_score"),
                "cross_market_bucket": event.get("cross_market_bucket"),
                "elite_edge_confidence": event.get("ELITE_EDGE_CONFIDENCE") or event.get("elite_edge_confidence"),
                "elite_edge_tier": event.get("elite_edge_tier"),
                "elite_edge_bucket": event.get("elite_edge_bucket") or elite_edge_bucket,
                "asymmetry_score": event.get("sports_payout_multiple"),
                "odds_bucket": event.get("odds_bucket") or sports_context.get("odds_bucket") or self._aion_distilled_odds_bucket(selected_price),
                "asymmetry_bucket": event.get("asymmetry_bucket") or sports_context.get("asymmetry_bucket") or self._aion_distilled_asymmetry_bucket(
                    price=selected_price,
                    payout_multiple=event.get("sports_payout_multiple") or sports_context.get("payout_multiple"),
                ),
                "liquidity_bucket": event.get("liquidity_bucket") or sports_context.get("liquidity_bucket") or self._aion_distilled_liquidity_bucket(
                    event.get("liquidity_dollars") or sports_context.get("book_depth")
                ),
                "spread_bucket": event.get("spread_bucket") or sports_context.get("spread_bucket") or self._aion_distilled_spread_bucket(event.get("spread")),
                "sport_type": event.get("sport_type") or sports_context.get("sport_type") or self._aion_distilled_sport_type(
                    family=family,
                    title=event.get("market_title"),
                    ticker=event.get("ticker"),
                ),
                "orderbook_quality_tag": self._aion_distilled_book_quality_tag(
                    spread=event.get("spread"),
                    liquidity=event.get("liquidity_dollars"),
                    sports_tags=sports_tags,
                ),
                "decision": event.get("entry_reason") or event.get("result") or event_type,
                "pnl": event.get("pnl_dollars"),
            }
            if event_type in {"candidate_seen", "trade_opened"}:
                result = engine.record_distilled_observation(
                    record,
                    throttle_seconds=AION_DISTILLED_MEMORY_OBSERVATION_MIN_SECONDS,
                )
                if result.get("ok") and not result.get("skipped"):
                    self._emit_aion_memory_log(
                        "[AION-MEMORY-STORE]",
                        {
                            "event_type": event_type,
                            "ticker": event.get("ticker"),
                            "family": family,
                            "category": category,
                            "sports_tags": sports_tags,
                            "structural_tags": structural_tags,
                            "elite_signal_used": bool(event.get("elite_signal_used")),
                            "decision": record.get("decision"),
                        },
                        marker=("store", event_type, event.get("ticker"), record.get("odds_bucket")),
                    )
                return result
            if event_type == "trade_closed":
                result = engine.record_distilled_outcome(record)
                if result.get("ok"):
                    self._emit_aion_memory_log(
                        "[AION-MEMORY-OUTCOME]",
                        {
                            "ticker": event.get("ticker"),
                            "family": family,
                            "category": category,
                            "pnl": event.get("pnl_dollars"),
                            "result": event.get("result"),
                            "sports_tags": sports_tags,
                            "elite_signal_used": bool(event.get("elite_signal_used")),
                        },
                        marker=("outcome", event.get("ticker"), event.get("result"), event.get("pnl_dollars")),
                    )
                    signal = self._get_aion_distilled_learning_signal(
                        family=family,
                        category=category,
                        sports_tags=sports_tags,
                        odds_bucket=record.get("odds_bucket"),
                        book_quality_tag=record.get("orderbook_quality_tag"),
                        elite_trader_handle=event.get("elite_trader_handle"),
                        side=event.get("side"),
                        asymmetry_bucket=record.get("asymmetry_bucket"),
                        liquidity_bucket=record.get("liquidity_bucket"),
                        spread_bucket=record.get("spread_bucket"),
                        sport_type=record.get("sport_type"),
                        structural_tags=structural_tags,
                        structural_pattern_keys=structural_pattern_keys,
                        cross_market_bucket=record.get("cross_market_bucket"),
                        elite_edge_bucket=record.get("elite_edge_bucket"),
                    )
                    self._emit_aion_memory_log(
                        "[AION-MEMORY-LEARN]",
                        {
                            "ticker": event.get("ticker"),
                            "family": family,
                            "rank_adjustment": signal.get("rank_adjustment"),
                            "sports_boost_adjustment": signal.get("sports_boost_adjustment"),
                            "sizing_confidence_multiplier": signal.get("sizing_confidence_multiplier"),
                            "elite_trust_weight": signal.get("elite_trust_weight"),
                            "structural_tags": structural_tags[:8],
                            "component_count": len(signal.get("components") or []),
                        },
                        marker=("learn", family, event.get("result"), round(self.to_float(event.get("pnl_dollars"), 0.0) or 0.0, 4)),
                    )
                    if structural_tags or structural_pattern_keys:
                        self._emit_aion_memory_log(
                            "[AION-STRUCTURAL-LEARN]",
                            {
                                "ticker": event.get("ticker"),
                                "family": family,
                                "STRUCTURAL_EDGE_SCORE": record.get("structural_edge_score"),
                                "CROSS_MARKET_EDGE_SCORE": record.get("cross_market_edge_score"),
                                "ELITE_EDGE_CONFIDENCE": record.get("elite_edge_confidence"),
                                "tags": structural_tags[:8],
                                "rank_adjustment": signal.get("rank_adjustment"),
                                "sizing_confidence_multiplier": signal.get("sizing_confidence_multiplier"),
                                "pnl": event.get("pnl_dollars"),
                            },
                            marker=("structural_learn", family, event.get("ticker"), event.get("result")),
                        )
                    if category == "sports" or sports_tags or self.is_sports_family(family, ticker=event.get("ticker")):
                        self._emit_aion_memory_log(
                            "[AION-SPORTS-LEARN]",
                            {
                                "ticker": event.get("ticker"),
                                "family": family,
                                "tags": sports_tags,
                                "pnl": event.get("pnl_dollars"),
                                "rank_adjustment": signal.get("rank_adjustment"),
                                "sports_boost_adjustment": signal.get("sports_boost_adjustment"),
                            },
                            marker=("sports_learn", family, event.get("ticker"), event.get("result")),
                        )
                    if event.get("elite_signal_used"):
                        self._emit_aion_memory_log(
                            "[AION-ELITE-LEARN]",
                            {
                                "ticker": event.get("ticker"),
                                "family": family,
                                "category": category,
                                "elite_trader_handle": event.get("elite_trader_handle"),
                                "pnl": event.get("pnl_dollars"),
                                "elite_trust_weight": signal.get("elite_trust_weight"),
                            },
                            marker=("elite_learn", event.get("elite_trader_handle"), category, event.get("ticker")),
                        )
                    self._maybe_emit_aion_distilled_memory_audit(source="outcome")
                return result
        except Exception as exc:
            self._emit_aion_memory_log(
                "[AION-MEMORY-STORE]",
                {"event_type": event_type, "reason": "write_failed", "error": exc.__class__.__name__, "action": "continue_trading"},
                marker=("write_failed", event_type, exc.__class__.__name__),
            )
            return {"ok": False, "reason": exc.__class__.__name__}
        return {"ok": False, "reason": "unsupported_event_type"}

    def _maybe_emit_aion_distilled_memory_audit(self, *, force=False, source="live_cycle"):
        engine = getattr(self, "aion_persistent_intelligence", None)
        if engine is None or not hasattr(engine, "audit_distilled_learning"):
            return {}
        now_ts = time.time()
        last_ts = self.to_float(getattr(self, "aion_distilled_memory_last_audit_ts", 0.0), 0.0) or 0.0
        if not force and now_ts - last_ts < max(60.0, self.to_float(AION_DISTILLED_MEMORY_AUDIT_SECONDS, 900.0)):
            return {}
        try:
            audit = engine.audit_distilled_learning()
            self.aion_distilled_memory_last_audit_ts = now_ts
            self._emit_aion_memory_log(
                "[AION-MEMORY-AUDIT]",
                {"source": source, **audit},
                marker=("audit", int(now_ts // max(60.0, self.to_float(AION_DISTILLED_MEMORY_AUDIT_SECONDS, 900.0)))),
            )
            return audit
        except Exception as exc:
            self._emit_aion_memory_log(
                "[AION-MEMORY-AUDIT]",
                {"source": source, "reason": exc.__class__.__name__},
                marker=("audit_failed", exc.__class__.__name__),
            )
            return {}

    def _extract_family_from_ranked_candidate(self, item):
        if isinstance(item, dict):
            return self._normalize_family_for_profit_memory(item.get("family"), ticker=item.get("ticker"))
        if isinstance(item, (list, tuple)):
            family = item[3] if len(item) > 3 else None
            q = item[1] if len(item) > 1 else None
            return self._normalize_family_for_profit_memory(family, q=q)
        return "UNKNOWN"

    def _rank_score_for_family_profit_memory(self, item):
        if isinstance(item, dict):
            return self.to_float(item.get("adjusted_score"), self.to_float(item.get("candidate_score"), self.to_float(item.get("quality_score"), 0.0)))
        if isinstance(item, (list, tuple)) and item:
            return self.to_float(item[0], 0.0)
        return 0.0

    def _apply_family_profit_memory_ranking(self, ranked, *, source="ranking"):
        ranked = list(ranked or [])
        if not ranked:
            return ranked
        decorated = []
        for index, item in enumerate(ranked):
            family = self._extract_family_from_ranked_candidate(item)
            adjustment = self._get_family_profit_memory_adjustment(family, log=True, source=source)
            decorated.append((self._rank_score_for_family_profit_memory(item) + adjustment, -index, item))
        decorated.sort(key=lambda entry: (entry[0], entry[1]), reverse=True)
        return [item for _rank_score, _tie_breaker, item in decorated]

    def _normalize_orderbook_imbalance_side(self, side):
        return kalshi_orderbook_module.normalize_orderbook_imbalance_side(side)

    def _extract_ticker_from_ranked_candidate(self, item):
        if isinstance(item, dict):
            q = item.get("q") or item.get("quote")
            return str(item.get("ticker") or getattr(q, "ticker", "") or "").strip()
        if isinstance(item, (list, tuple)) and len(item) > 1:
            return str(getattr(item[1], "ticker", "") or "").strip()
        return ""

    def _elite_signal_abs_path(self, path_value):
        path_text = str(path_value or "").strip()
        if not path_text:
            return None
        path_obj = _Path(path_text)
        if not path_obj.is_absolute():
            path_obj = _Path(os.path.dirname(os.path.abspath(__file__))) / path_obj
        return path_obj

    def _elite_signal_paths(self):
        paths = []
        for value in (AION_ELITE_SIGNAL_FILE, AION_ELITE_SIGNAL_CSV_FILE):
            path_obj = self._elite_signal_abs_path(value)
            if path_obj is not None:
                paths.append(path_obj)
        return paths

    def _emit_elite_signal_log(self, tag, payload, marker=None):
        markers = getattr(self, "elite_public_signal_log_markers", None)
        if markers is None:
            self.elite_public_signal_log_markers = {}
            markers = self.elite_public_signal_log_markers
        marker_key = None
        if marker is not None:
            marker_key = tuple(marker) if isinstance(marker, (list, tuple)) else marker
            if marker_key in markers:
                return
            markers[marker_key] = time.time()
        try:
            print(f"{tag} " + json.dumps(payload, sort_keys=True, default=str))
        except Exception:
            print(f"{tag} " + json.dumps({"reason": "elite_signal_log_failed"}))

    def _elite_signal_public_summary(self, signal):
        if signal is None:
            return {}
        payload = signal.public_dict() if hasattr(signal, "public_dict") else {}
        raw_text = str(payload.get("raw_text") or "")
        if raw_text:
            payload["raw_text_len"] = len(raw_text)
            payload.pop("raw_text", None)
        return {
            key: payload.get(key)
            for key in (
                "trader_handle",
                "source_url_or_label",
                "observed_at",
                "market_title",
                "ticker",
                "side",
                "category",
                "confidence_parse_score",
                "resolved_ticker",
                "resolved_category",
                "match_confidence",
                "raw_text_len",
            )
            if payload.get(key) not in (None, "")
        }

    def _refresh_elite_public_signals(self, markets=None, *, force=False, source="ranking"):
        if not AION_ELITE_SIGNAL_ENABLED:
            self._emit_elite_signal_log(
                "[AION-ELITE-SIGNAL-SKIP]",
                {"reason": "disabled", "source": source},
                marker=("disabled",),
            )
            return []
        if elite_public_signals_module is None:
            self._emit_elite_signal_log(
                "[AION-ELITE-SIGNAL-SKIP]",
                {"reason": "module_unavailable", "source": source},
                marker=("module_unavailable",),
            )
            return []
        cache = getattr(self, "elite_public_signal_cache", {}) or {}
        now_ts = time.time()
        if not force and cache.get("signals") is not None and now_ts - self.to_float(cache.get("loaded_at"), 0.0) < 60.0:
            return list(cache.get("signals") or [])
        paths = self._elite_signal_paths()
        signals, load_summary = elite_public_signals_module.load_signal_files(paths)
        market_list = [market for market in (markets or []) if isinstance(market, dict)]
        resolve_summary = {}
        if market_list and signals:
            signals, resolve_summary = elite_public_signals_module.resolve_signals_to_markets(
                signals,
                market_list,
                min_confidence=max(0.0, min(1.0, AION_ELITE_SIGNAL_MIN_MATCH_CONFIDENCE)),
            )
        existing_paths = [str(path) for path in paths if path.exists()]
        self.elite_public_signal_cache = {
            "loaded_at": now_ts,
            "signals": list(signals or []),
            "summary": {
                "load": load_summary,
                "resolve": resolve_summary,
                "existing_paths": existing_paths,
            },
        }
        self._emit_elite_signal_log(
            "[AION-ELITE-SIGNAL-LOAD]",
            {
                "source": source,
                "enabled": True,
                "signals_loaded": len(signals or []),
                "existing_paths": existing_paths,
                "files_missing": load_summary.get("files_missing"),
                "rows_seen": load_summary.get("rows_seen"),
                "rows_loaded": load_summary.get("rows_loaded"),
                "rows_skipped": load_summary.get("rows_skipped"),
                "errors": load_summary.get("errors"),
                "resolved": resolve_summary.get("resolved"),
                "unresolved": resolve_summary.get("unresolved"),
                "min_match_confidence": AION_ELITE_SIGNAL_MIN_MATCH_CONFIDENCE,
            },
            marker=("load", tuple(existing_paths), load_summary.get("rows_loaded"), resolve_summary.get("resolved")),
        )
        if not existing_paths:
            self._emit_elite_signal_log(
                "[AION-ELITE-SIGNAL-SKIP]",
                {
                    "reason": "signal_input_missing",
                    "source": source,
                    "paths": [str(path) for path in paths],
                },
                marker=("missing_input", tuple(str(path) for path in paths)),
            )
        for signal in list(signals or [])[:50]:
            resolved_ticker = str(getattr(signal, "resolved_ticker", "") or "")
            marker = (
                "resolved" if resolved_ticker else "unresolved",
                str(getattr(signal, "source_url_or_label", "") or ""),
                str(getattr(signal, "market_title", "") or getattr(signal, "raw_text", "") or "")[:80],
                resolved_ticker,
            )
            if resolved_ticker:
                self._emit_elite_signal_log(
                    "[AION-ELITE-SIGNAL-MATCH]",
                    {
                        "source": source,
                        "resolved_ticker": resolved_ticker,
                        "match_confidence": round(self.to_float(getattr(signal, "match_confidence", 0.0), 0.0), 4),
                        "signal": self._elite_signal_public_summary(signal),
                    },
                    marker=marker,
                )
            else:
                self._emit_elite_signal_log(
                    "[AION-ELITE-SIGNAL-UNRESOLVED]",
                    {
                        "source": source,
                        "reason": "below_match_confidence_or_no_active_market",
                        "min_match_confidence": AION_ELITE_SIGNAL_MIN_MATCH_CONFIDENCE,
                        "signal": self._elite_signal_public_summary(signal),
                    },
                    marker=marker,
                )
        return list(signals or [])

    def _elite_signal_candidate_title(self, *, item=None, market=None, q=None):
        fields = []
        market = market if isinstance(market, dict) else {}
        if isinstance(item, dict):
            fields.extend([item.get("market_title"), item.get("title"), item.get("raw_text")])
            q = q or item.get("q") or item.get("quote")
        fields.extend([
            market.get("title"),
            market.get("subtitle"),
            market.get("event_title"),
            market.get("yes_sub_title"),
            market.get("no_sub_title"),
            market.get("event_ticker"),
            market.get("series_ticker"),
            market.get("ticker"),
        ])
        if q is not None:
            fields.extend([
                getattr(q, "market_title", None),
                getattr(q, "title", None),
                getattr(q, "ticker", None),
            ])
        return " ".join(str(value).strip() for value in fields if str(value or "").strip())

    def _attach_elite_signal_context(self, item=None, q=None, context=None):
        context = context if isinstance(context, dict) else {}
        signal = context.get("signal") if isinstance(context.get("signal"), dict) else {}
        elite_handle = signal.get("trader_handle") or context.get("elite_trader_handle")
        if isinstance(item, dict):
            item["elite_public_signal_context"] = context
            item["elite_public_signal_boost"] = context.get("boost", 0.0)
            item["elite_public_signal_match"] = context.get("matched", False)
            item["elite_public_signal_confidence"] = context.get("confidence")
            item["elite_trader_handle"] = elite_handle
        if q is not None:
            for field, value in (
                ("elite_public_signal_context", context),
                ("elite_public_signal_boost", context.get("boost", 0.0)),
                ("elite_public_signal_match", context.get("matched", False)),
                ("elite_public_signal_confidence", context.get("confidence")),
                ("elite_signal_used", bool(context.get("matched"))),
                ("elite_trader_handle", elite_handle),
            ):
                try:
                    setattr(q, field, value)
                except Exception:
                    pass

    def _get_elite_public_signal_match(self, item=None, *, market=None, q=None, ticker=None, family=None, category=None, source="ranking", markets=None):
        if not AION_ELITE_SIGNAL_ENABLED or elite_public_signals_module is None:
            return {"matched": False, "boost": 0.0, "reason": "disabled_or_unavailable"}
        market = market if isinstance(market, dict) else {}
        if isinstance(item, dict):
            q = q or item.get("q") or item.get("quote")
            ticker = ticker or item.get("ticker") or getattr(q, "ticker", None)
            family = family or item.get("family")
        elif isinstance(item, (list, tuple)):
            q = q or (item[1] if len(item) > 1 else None)
            ticker = ticker or getattr(q, "ticker", None)
            family = family or (item[3] if len(item) > 3 else None)
        ticker = str(ticker or getattr(q, "ticker", None) or market.get("ticker", "") or "").strip()
        family = self._normalize_family_for_profit_memory(family, ticker=ticker, market=market, q=q)
        category = str(category or self.get_market_discovery_category(market or family) or "").strip().lower()
        title = self._elite_signal_candidate_title(item=item, market=market, q=q)
        signal_markets = markets if markets is not None else ([market] if market else None)
        signals = self._refresh_elite_public_signals(markets=signal_markets, source=source)
        if not signals:
            return {"matched": False, "boost": 0.0, "reason": "no_signals"}
        match = elite_public_signals_module.best_candidate_match(
            signals,
            ticker=ticker,
            title=title,
            category=category,
            family=family,
            max_age_hours=AION_ELITE_SIGNAL_MAX_AGE_HOURS,
            min_confidence=max(0.0, min(1.0, AION_ELITE_SIGNAL_MIN_MATCH_CONFIDENCE)),
        )
        if not match.get("matched"):
            return {
                "matched": False,
                "boost": 0.0,
                "reason": match.get("reason") or "no_match",
                "confidence": match.get("confidence"),
            }
        signal = match.get("signal")
        signal_summary = self._elite_signal_public_summary(signal)
        elite_handle = signal_summary.get("trader_handle")
        memory_signal = self._get_aion_distilled_learning_signal(
            family=family,
            category=category,
            elite_trader_handle=elite_handle,
        )
        trust_weight = self.to_float(memory_signal.get("elite_trust_weight"), 1.0) or 1.0
        base_boost = AION_ELITE_SIGNAL_STRONG_BOOST if match.get("strong") else AION_ELITE_SIGNAL_SCORE_BOOST
        boost = max(0.0, self.to_float(base_boost, 0.0) * max(0.65, min(1.35, trust_weight)))
        context = {
            "matched": True,
            "boost": round(max(0.0, self.to_float(boost, 0.0)), 4),
            "base_boost": round(max(0.0, self.to_float(base_boost, 0.0)), 4),
            "trust_weight": round(trust_weight, 4),
            "memory_signal": memory_signal,
            "confidence": round(self.to_float(match.get("confidence"), 0.0), 4),
            "reason": match.get("reason"),
            "strong": bool(match.get("strong")),
            "ticker": ticker,
            "family": family,
            "category": category,
            "elite_trader_handle": elite_handle,
            "signal": signal_summary,
            "source": source,
        }
        if memory_signal.get("components"):
            context["history_aligned"] = any(str(component.get("label") or "").startswith("sports_history_") for component in memory_signal.get("components") or [])
        self._attach_elite_signal_context(item=item, q=q, context=context)
        self._emit_elite_signal_log(
            "[AION-ELITE-SIGNAL-BOOST]",
            context,
            marker=("boost", source, ticker, context["boost"], context["confidence"]),
        )
        return context

    def _get_elite_public_signal_rank_adjustment(self, item=None, *, market=None, q=None, family=None, source="ranking", markets=None, log=True):
        context = self._get_elite_public_signal_match(
            item,
            market=market,
            q=q,
            family=family,
            source=source,
            markets=markets,
        )
        if not context.get("matched"):
            self._attach_elite_signal_context(item=item, q=q, context=context)
        return context

    def _emit_aion_data_coverage_logs(self, audit, *, source="live_cycle"):
        audit = audit if isinstance(audit, dict) else {}
        totals = audit.get("totals") if isinstance(audit.get("totals"), dict) else {}
        sports = audit.get("sports") if isinstance(audit.get("sports"), dict) else {}
        family_coverage = audit.get("sports_family_coverage") if isinstance(audit.get("sports_family_coverage"), list) else []
        try:
            print(
                "[AION-DATA-AUDIT] "
                + json.dumps(
                    {
                        "source": source,
                        "include_telemetry": bool(audit.get("include_telemetry")),
                        "total_records": totals.get("records"),
                        "oldest_timestamp": totals.get("oldest_timestamp"),
                        "newest_timestamp": totals.get("newest_timestamp"),
                        "unique_markets_tickers": totals.get("unique_markets_tickers"),
                        "total_categories_families": totals.get("total_categories_families"),
                        "source_count": len(audit.get("sources") or []),
                    },
                    sort_keys=True,
                    default=str,
                )
            )
            print(
                "[AION-SPORTS-DATA] "
                + json.dumps(
                    {
                        "source": source,
                        "sports_record_count": sports.get("record_count"),
                        "sports_unique_markets_tickers": sports.get("unique_markets_tickers"),
                        "sports_oldest_timestamp": sports.get("oldest_timestamp"),
                        "sports_newest_timestamp": sports.get("newest_timestamp"),
                        "top_sports_families": sports.get("top_families"),
                    },
                    sort_keys=True,
                    default=str,
                )
            )
            for family in family_coverage[:8]:
                print(
                    "[AION-SPORTS-FAMILY-COVERAGE] "
                    + json.dumps(
                        {
                            "source": source,
                            "family": family.get("family"),
                            "records": family.get("records"),
                            "unique_markets_tickers": family.get("unique_markets_tickers"),
                            "liquidity_samples": family.get("liquidity_samples"),
                            "price_observations": family.get("price_observations"),
                            "oldest_timestamp": family.get("oldest_timestamp"),
                            "newest_timestamp": family.get("newest_timestamp"),
                            "avg_spread": family.get("avg_spread"),
                            "avg_liquidity": family.get("avg_liquidity"),
                            "win_rate": family.get("win_rate"),
                            "pnl_dollars": family.get("pnl_dollars"),
                            "tags": family.get("tags"),
                        },
                        sort_keys=True,
                        default=str,
                    )
                )
            print(
                "[AION-SPORTS-DATA-READY] "
                + json.dumps(
                    {
                        "source": source,
                        "ready_families": sports.get("ready_families"),
                        "active_families": sports.get("active_families"),
                        "thin_families": sports.get("thin_families"),
                        "stale_families": sports.get("stale_families"),
                    },
                    sort_keys=True,
                    default=str,
                )
            )
        except Exception as exc:
            print(
                "[AION-DATA-AUDIT] "
                + json.dumps({"source": source, "error": exc.__class__.__name__}, sort_keys=True, default=str)
            )

    def _refresh_aion_data_coverage_cache(self, *, force=False, source="live_cycle"):
        if not AION_DATA_COVERAGE_AUDIT_ENABLED or audit_kalshi_data_coverage is None:
            return getattr(self, "aion_data_coverage_cache", {}) if isinstance(getattr(self, "aion_data_coverage_cache", {}), dict) else {}
        now_ts = time.time()
        last_ts = self.to_float(getattr(self, "aion_data_coverage_last_ts", 0.0), 0.0) or 0.0
        cache = getattr(self, "aion_data_coverage_cache", {})
        if (
            not force
            and isinstance(cache, dict)
            and cache
            and now_ts - last_ts < max(60, int(AION_DATA_COVERAGE_REFRESH_SECONDS or 900))
        ):
            return cache
        try:
            repo_root = _Path(__file__).resolve().parent
            audit = audit_kalshi_data_coverage(
                repo_root,
                include_telemetry=bool(AION_DATA_COVERAGE_INCLUDE_TELEMETRY),
            )
            self.aion_data_coverage_cache = audit
            self.aion_data_coverage_last_ts = now_ts
            self._emit_aion_data_coverage_logs(audit, source=source)
            return audit
        except Exception as exc:
            print(
                "[AION-DATA-AUDIT] "
                + json.dumps(
                    {
                        "source": source,
                        "error": exc.__class__.__name__,
                        "action": "continue_trading",
                    },
                    sort_keys=True,
                    default=str,
                )
            )
            return cache if isinstance(cache, dict) else {}

    def _get_sports_data_signal(self, family):
        if build_sports_data_signal is None:
            return {}
        audit = getattr(self, "aion_data_coverage_cache", {})
        if not isinstance(audit, dict) or not audit:
            audit = self._refresh_aion_data_coverage_cache(force=False, source="sports_edge_lazy")
        try:
            return build_sports_data_signal(audit, family)
        except Exception:
            return {}

    def _sports_edge_read_value(self, sources, *names):
        for source in sources or []:
            if source is None:
                continue
            for name in names:
                if isinstance(source, dict):
                    value = source.get(name)
                else:
                    value = getattr(source, name, None)
                if value not in (None, ""):
                    return value
        return None

    def _sports_edge_price_value(self, value):
        numeric = self.to_float(value, None)
        if numeric is None:
            return None
        if numeric > 1.0 and numeric <= 100.0:
            numeric = numeric / 100.0
        if numeric <= 0.0:
            return None
        return round(float(numeric), 6)

    def _emit_sports_edge_log(self, tag, payload, marker=None):
        markers = getattr(self, "sports_edge_ranking_log_markers", None)
        if markers is None:
            self.sports_edge_ranking_log_markers = {}
            markers = self.sports_edge_ranking_log_markers
        marker_key = None
        if marker is not None:
            marker_key = tuple(marker) if isinstance(marker, (list, tuple)) else marker
            if marker_key in markers:
                return
            markers[marker_key] = time.time()
        try:
            print(f"{tag} " + json.dumps(payload, sort_keys=True, default=str))
        except Exception:
            print(f"{tag} " + json.dumps({"reason": "sports_edge_log_failed"}))

