    def _candidate_unified_score(self, candidate=None):
        candidate = candidate if isinstance(candidate, dict) else {}
        allocation = candidate.get("allocation") if isinstance(candidate.get("allocation"), dict) else {}
        context = allocation.get("unified_opportunity") if isinstance(allocation.get("unified_opportunity"), dict) else {}
        return self.to_float(
            candidate.get("unified_opportunity_score"),
            self.to_float(
                allocation.get("unified_opportunity_score"),
                self.to_float(context.get("unified_score"), self.to_float(allocation.get("allocation_score"), candidate.get("candidate_score"))),
            ),
        ) or 0.0

    def _cash_pressure_context(self):
        available_cash = None
        for attr_name in (
            "available_cash",
            "available_balance",
            "live_available_balance",
            "last_live_available_balance",
            "last_available_balance",
        ):
            if hasattr(self, attr_name):
                available_cash = self.to_float(getattr(self, attr_name, None), None)
                if available_cash is not None:
                    break
        if available_cash is None:
            balance = getattr(self, "live_balance", None)
            if isinstance(balance, dict):
                available_cash = self.to_float(balance.get("available_balance", balance.get("available_cash")), None)
        open_positions = 0
        try:
            open_positions = sum(
                1
                for position in getattr(self, "live_positions", []) or []
                if str((position or {}).get("status", "open") or "open").strip().lower() == "open"
            )
        except Exception:
            open_positions = 0
        max_positions = max(1, int(MAX_SIMULTANEOUS_LIVE_POSITIONS or 1))
        low_cash = bool(
            (available_cash is not None and available_cash <= max(25.0, float(MAX_LIVE_ORDER_SIZE or 1) * 2.0))
            or open_positions >= max(0, max_positions - 1)
        )
        return {
            "available_cash": available_cash,
            "open_positions": open_positions,
            "max_positions": max_positions,
            "low_cash": bool(low_cash),
        }

    def _opportunity_cost_gate(self, candidate=None, candidates=None, *, source="parallel_lane_submit"):
        candidate = candidate if isinstance(candidate, dict) else {}
        candidates = [
            item for item in (candidates or [])
            if isinstance(item, dict)
            and str(item.get("lane") or "").strip().upper() == "SPORTS"
            and self._is_sports_market_or_family(item.get("market") if isinstance(item.get("market"), dict) else item.get("family"))
        ]
        sorted_candidates = sorted(candidates, key=lambda item: self._candidate_unified_score(item), reverse=True)
        ticker = str(candidate.get("ticker") or "").strip()
        candidate_score = self._candidate_unified_score(candidate)
        best_candidate = sorted_candidates[0] if sorted_candidates else candidate
        best_score = self._candidate_unified_score(best_candidate)
        rank = next((idx + 1 for idx, item in enumerate(sorted_candidates) if str(item.get("ticker") or "").strip() == ticker), None)
        cash_context = self._cash_pressure_context()
        score_gap = max(0.0, best_score - candidate_score)
        both_elite = bool(best_score >= 78.0 and candidate_score >= 72.0 and score_gap <= 14.0)
        suppressed = False
        reason = "opportunity_allowed"
        if candidate_score < 50.0:
            suppressed = True
            reason = "unified_score_below_minimum"
        elif cash_context.get("low_cash") and rank and rank > 1 and not both_elite:
            suppressed = True
            reason = "low_cash_concentrate_best_opportunity"
        elif rank and rank > 1 and score_gap >= 22.0 and candidate_score < 75.0:
            suppressed = True
            reason = "clear_superior_opportunity_cost"
        payload = {
            "source": source,
            "ticker": ticker,
            "lane": candidate.get("lane"),
            "family": candidate.get("family"),
            "rank": rank,
            "candidate_unified_score": round(candidate_score, 4),
            "best_ticker": best_candidate.get("ticker"),
            "best_lane": best_candidate.get("lane"),
            "best_unified_score": round(best_score, 4),
            "score_gap": round(score_gap, 4),
            "available_cash": cash_context.get("available_cash"),
            "open_positions": cash_context.get("open_positions"),
            "low_cash": bool(cash_context.get("low_cash")),
            "both_elite": bool(both_elite),
            "suppressed": bool(suppressed),
            "reason": reason,
        }
        print("[AION-OPPORTUNITY-COST-CHECK] " + json.dumps(payload, sort_keys=True, default=str))
        if cash_context.get("low_cash"):
            print("[AION-CAPITAL-CONCENTRATION] " + json.dumps(payload, sort_keys=True, default=str))
        if suppressed:
            print("[AION-WEAK-CANDIDATE-SUPPRESSED] " + json.dumps(payload, sort_keys=True, default=str))
        return {"allowed": not suppressed, "reason": reason, "payload": payload}

    def _apply_unified_size_pressure(self, size, allocation=None, q=None, *, source="submit"):
        allocation = allocation if isinstance(allocation, dict) else {}
        context = allocation.get("unified_opportunity") if isinstance(allocation.get("unified_opportunity"), dict) else {}
        multiplier = self.to_float(
            allocation.get("unified_size_multiplier"),
            self.to_float(context.get("size_multiplier"), self.to_float(getattr(q, "unified_size_multiplier", None), 1.0) if q is not None else 1.0),
        )
        if multiplier is None or multiplier <= 0.0:
            multiplier = 1.0
        requested = max(1, int(round(self.to_float(size, 1) or 1)))
        hard_max = max(1, int(MAX_LIVE_ORDER_SIZE or 1))
        adjusted = max(1, min(hard_max, int(round(requested * multiplier))))
        if adjusted != requested:
            print(
                "[AION-CAPITAL-CONCENTRATION] "
                + json.dumps(
                    {
                        "source": source,
                        "ticker": allocation.get("ticker") or getattr(q, "ticker", None),
                        "lane": allocation.get("lane"),
                        "requested_size": requested,
                        "adjusted_size": adjusted,
                        "unified_score": allocation.get("unified_opportunity_score") or context.get("unified_score"),
                        "capital_lock_penalty": allocation.get("capital_lock_penalty") or context.get("capital_lock_penalty"),
                        "size_multiplier": round(multiplier, 4),
                        "reason": "unified_opportunity_size_pressure",
                    },
                    sort_keys=True,
                    default=str,
                )
            )
        return adjusted

    def _apply_dual_lane_allocation_ranking(self, *args, **kwargs):
        return _call_sports_live_intelligence("_apply_dual_lane_allocation_ranking", self, *args, **kwargs)

    def _lane_submit_truth_payload(
        self,
        *,
        candidate,
        allocation,
        result=None,
        payload=None,
        duplicate_guard=None,
        submit_allowed=False,
        reason=None,
        source=None,
    ):
        allocation = allocation if isinstance(allocation, dict) else {}
        candidate = candidate if isinstance(candidate, dict) else {}
        result = result if isinstance(result, dict) else {}
        payload = payload if isinstance(payload, dict) else {}
        duplicate_guard = duplicate_guard if isinstance(duplicate_guard, dict) else {}
        q = candidate.get("q")
        ticker = str(candidate.get("ticker") or payload.get("ticker") or getattr(q, "ticker", "") or "").strip()
        lane = str(candidate.get("lane") or allocation.get("lane") or "").strip().upper()
        selected_price = (
            payload.get("price")
            if payload.get("price") is not None
            else allocation.get("selected_price")
            if allocation.get("selected_price") is not None
            else allocation.get("selected_price_dollars")
        )
        selected_side = (
            payload.get("side")
            or allocation.get("selected_side")
            or getattr(q, "selected_side", None)
            or getattr(q, "side", None)
        )
        selected_price_float = self.to_float(selected_price, None)
        daily_count = int(self.live_trade_count_today or 0)
        max_daily = int(MAX_LIVE_TRADES_PER_DAY or 0)
        duplicate_result = duplicate_guard.get("reason") or ("blocked" if duplicate_guard.get("blocked") else "pass")
        return {
            "source": source,
            "ticker": ticker,
            "lane": lane,
            "family": candidate.get("family") or allocation.get("family"),
            "EV": allocation.get("edge"),
            "edge_after_cost": allocation.get("edge"),
            "confidence": allocation.get("confidence"),
            "profitability_score": allocation.get("confidence") or allocation.get("profitability_score"),
            "selected_side": selected_side,
            "selected_price": selected_price,
            "spread": allocation.get("spread") if allocation.get("spread") is not None else candidate.get("spread"),
            "liquidity": allocation.get("liquidity"),
            "top_size": allocation.get("liquidity_depth") or allocation.get("liquidity"),
            "orderbook_ready": bool(payload) if "orderbook_ready" not in allocation else bool(allocation.get("orderbook_ready")),
            "price_bounds_pass": bool(selected_price_float is not None and 0.0 < selected_price_float < 1.0),
            "duplicate_guard": duplicate_result,
            "exposure_daily_cap": "pass" if daily_count < max_daily else "warning_only",
            "daily_trade_count": daily_count,
            "max_daily_trades": max_daily,
            "submit_allowed": bool(submit_allowed),
            "submitted": bool(result.get("submitted")),
            "reason": reason or result.get("reason"),
            "count": payload.get("count") or (result.get("payload") or {}).get("count"),
        }

    def _aion_concurrency_settings(self):
        return {
            "max_open_positions": max(1, int(AION_MAX_OPEN_POSITIONS or 1)),
            "max_submits_per_cycle": max(1, int(AION_MAX_SUBMITS_PER_CYCLE or 1)),
            "max_new_positions_per_10min": max(1, int(AION_MAX_NEW_POSITIONS_PER_10MIN or 1)),
            "min_seconds_between_submits": max(0.0, float(AION_MIN_SECONDS_BETWEEN_SUBMITS or 0.0)),
            "max_same_family_positions": max(1, int(AION_MAX_SAME_FAMILY_POSITIONS or 1)),
            "max_same_game_positions": max(1, int(AION_MAX_SAME_GAME_POSITIONS or 1)),
            "live_order_rate_limit": max(1, int(LIVE_ORDER_RATE_LIMIT or 1)),
            "live_order_rate_window_sec": max(1, int(LIVE_ORDER_RATE_WINDOW_SEC or 60)),
        }

    def _emit_aion_concurrency_log(self, tag, payload):
        try:
            print(f"[{tag}] " + json.dumps(payload if isinstance(payload, dict) else {}, sort_keys=True, default=str))
        except Exception:
            pass

    def _aion_concurrency_candidate_meta(self, candidate):
        candidate = candidate if isinstance(candidate, dict) else {}
        allocation = candidate.get("allocation") if isinstance(candidate.get("allocation"), dict) else {}
        market = candidate.get("market") if isinstance(candidate.get("market"), dict) else {}
        q = candidate.get("q")
        ticker = str(candidate.get("ticker") or allocation.get("ticker") or getattr(q, "ticker", "") or market.get("ticker") or "").strip()
        family = str(
            candidate.get("family")
            or allocation.get("family")
            or getattr(q, "family", "")
            or market.get("series_ticker")
            or (self.get_market_family(market or {"ticker": ticker}) if ticker else "")
            or "UNKNOWN"
        ).strip().upper() or "UNKNOWN"
        selected_side = self._normalize_live_side(
            allocation.get("selected_side")
            or allocation.get("side")
            or getattr(q, "selected_side", None)
            or getattr(q, "side", None)
        )
        selected_price = self.to_float(
            allocation.get("selected_price")
            or allocation.get("price")
            or getattr(q, "selected_price", None),
            None,
        )
        game_key = str(
            allocation.get("game_id")
            or allocation.get("sports_graph_game_id")
            or getattr(q, "game_id", None)
            or getattr(q, "sports_graph_game_id", None)
            or market.get("game_id")
            or market.get("event_ticker")
            or ""
        ).strip()
        if not game_key and ticker:
            try:
                game_key = self._extract_sports_game_key(ticker, market=market)
            except Exception:
                game_key = ticker
        return {
            "ticker": ticker,
            "family": family,
            "q": q,
            "market": market,
            "allocation": allocation,
            "lane": str(candidate.get("lane") or allocation.get("lane") or "").strip().upper(),
            "selected_side": selected_side,
            "selected_price": selected_price,
            "game_key": game_key or None,
            "edge": self.to_float(allocation.get("edge") or allocation.get("edge_after_cost") or allocation.get("EV"), None),
            "confidence": self.to_float(allocation.get("confidence"), None),
            "spread": self.to_float(allocation.get("spread"), None),
            "liquidity": self.to_float(allocation.get("liquidity"), None),
            "score": self._candidate_unified_score(candidate),
            "decision": allocation.get("decision"),
            "reason": allocation.get("reason"),
        }

    def _aion_concurrency_entry_from_meta(self, meta, *, source=None, count=None, price=None, side=None):
        meta = meta if isinstance(meta, dict) else {}
        return {
            "ticker": str(meta.get("ticker") or "").strip(),
            "family": str(meta.get("family") or "UNKNOWN").strip().upper() or "UNKNOWN",
            "game_key": str(meta.get("game_key") or "").strip() or None,
            "side": self._normalize_live_side(side or meta.get("selected_side")),
            "count": count,
            "price": price,
            "source": source,
        }

    def _aion_concurrency_snapshot(self, reserved_entries=None):
        reserved_entries = [entry for entry in (reserved_entries or []) if isinstance(entry, dict)]
        open_positions = list(self._get_open_live_positions() or [])
        family_counts = Counter()
        game_counts = Counter()
        open_tickers = set()
        for position in open_positions:
            if not isinstance(position, dict):
                continue
            ticker = str(position.get("ticker") or position.get("market_ticker") or "").strip()
            if not ticker:
                continue
            open_tickers.add(ticker)
            family = str(position.get("family") or position.get("series_ticker") or self.get_market_family({"ticker": ticker}) or "UNKNOWN").strip().upper() or "UNKNOWN"
            family_counts[family] += 1
            entry_context = position.get("entry_context") if isinstance(position.get("entry_context"), dict) else {}
            game_key = str(entry_context.get("game_id") or entry_context.get("sports_graph_game_id") or position.get("game_id") or "").strip()
            if not game_key:
                try:
                    game_key = self._extract_sports_game_key(ticker)
                except Exception:
                    game_key = ticker
            if game_key:
                game_counts[game_key] += 1
        reserved_count = 0
        for entry in reserved_entries:
            ticker = str(entry.get("ticker") or "").strip()
            if not ticker or ticker in open_tickers:
                continue
            reserved_count += 1
            family = str(entry.get("family") or self.get_market_family({"ticker": ticker}) or "UNKNOWN").strip().upper() or "UNKNOWN"
            family_counts[family] += 1
            game_key = str(entry.get("game_key") or "").strip()
            if not game_key:
                try:
                    game_key = self._extract_sports_game_key(ticker)
                except Exception:
                    game_key = ticker
            if game_key:
                game_counts[game_key] += 1
        return {
            "open_positions": open_positions,
            "open_count": len(open_positions) + reserved_count,
            "family_counts": family_counts,
            "game_counts": game_counts,
            "open_tickers": open_tickers,
        }

    def _evaluate_aion_concurrency_candidate(self, candidate, *, submitted_entries=None, source="multi_submit"):
        submitted_entries = [entry for entry in (submitted_entries or []) if isinstance(entry, dict)]
        settings = self._aion_concurrency_settings()
        meta = self._aion_concurrency_candidate_meta(candidate)
        ticker = meta.get("ticker")
        family = meta.get("family")
        game_key = meta.get("game_key")
        snapshot = self._aion_concurrency_snapshot(submitted_entries)
        try:
            active_timestamps = list(self._active_live_order_timestamps() or [])
        except Exception:
            active_timestamps = []
        try:
            recent_10min = int(self.recent_submitted_order_count_total(window_seconds=600) or 0)
        except Exception:
            recent_10min = 0
        last_submit_ts = max(active_timestamps) if active_timestamps else 0.0
        seconds_since_submit = None if not last_submit_ts else max(0.0, time.time() - float(last_submit_ts))
        pending_same_ticker = any(str(entry.get("ticker") or "").strip() == ticker for entry in submitted_entries)
        same_family_count = int(snapshot["family_counts"].get(family, 0))
        same_game_count = int(snapshot["game_counts"].get(game_key, 0)) if game_key else 0
        block_reason = None
        if not ticker:
            block_reason = "missing_ticker"
        elif meta.get("lane") != "SPORTS":
            block_reason = "non_sports_lane"
        elif len(submitted_entries) >= settings["max_submits_per_cycle"]:
            block_reason = "max_submits_per_cycle"
        elif len(active_timestamps) >= settings["live_order_rate_limit"]:
            block_reason = "rate_limited"
        elif (
            settings["min_seconds_between_submits"] > 0.0
            and not submitted_entries
            and seconds_since_submit is not None
            and seconds_since_submit < settings["min_seconds_between_submits"]
        ):
            block_reason = "min_seconds_between_submits"
        elif recent_10min + len(submitted_entries) >= settings["max_new_positions_per_10min"]:
            block_reason = "max_new_positions_per_10min"
        elif snapshot["open_count"] >= settings["max_open_positions"]:
            block_reason = "max_open_positions"
        elif same_family_count >= settings["max_same_family_positions"]:
            block_reason = "max_same_family_positions"
        elif game_key and same_game_count >= settings["max_same_game_positions"]:
            block_reason = "max_same_game_positions"
        elif bool(getattr(self, "trading_halted", False)):
            block_reason = "trading_halted"
        elif self.to_float(getattr(self, "realized_pnl", 0.0), 0.0) <= -MAX_DAILY_LOSS or self.to_float(getattr(self, "live_realized_pnl_today", 0.0), 0.0) <= -MAX_DAILY_LOSS:
            block_reason = "daily_loss_guard"
        elif pending_same_ticker:
            block_reason = "duplicate_cycle_ticker"
        elif self.already_holding(ticker):
            block_reason = "duplicate_position_guard"
        duplicate = {"blocked": False}
        if block_reason is None:
            try:
                duplicate = self.check_live_duplicate_position_api(ticker) or {"blocked": False}
            except Exception as exc:
                duplicate = {"blocked": True, "reason": f"duplicate_check_exception:{exc.__class__.__name__}"}
            if duplicate.get("blocked"):
                block_reason = duplicate.get("reason") or "duplicate_position_guard"
        payload = {
            "source": source,
            "ticker": ticker,
            "family": family,
            "side": meta.get("selected_side"),
            "selected_price": meta.get("selected_price"),
            "game_key": game_key,
            "edge_after_cost": meta.get("edge"),
            "confidence": meta.get("confidence"),
            "spread": meta.get("spread"),
            "liquidity": meta.get("liquidity"),
            "candidate_score": meta.get("score"),
            "open_positions": snapshot["open_count"],
            "same_family_count": same_family_count,
            "same_game_count": same_game_count,
            "submitted_this_cycle": len(submitted_entries),
            "recent_new_positions_10min": recent_10min,
            "active_order_timestamps": len(active_timestamps),
            "settings": settings,
            "duplicate_guard": duplicate,
            "decision": "ALLOW" if block_reason is None else "BLOCK",
            "reason": block_reason or "concurrency_capacity_available",
            "subsystem": "multi_sports_submit",
        }
        self._emit_aion_concurrency_log("AION-CONCURRENCY-AUDIT", payload)
        if block_reason is None:
            self._emit_aion_concurrency_log("AION-CONCURRENCY-ALLOW", payload)
            return {"allowed": True, "reason": "concurrency_capacity_available", "meta": meta, "audit": payload}
        self._emit_aion_concurrency_log("AION-CONCURRENCY-BLOCK", payload)
        return {"allowed": False, "reason": block_reason, "meta": meta, "audit": payload}

    def _apply_multi_submit_candidate_metadata(self, q, allocation):
        if q is None or not isinstance(allocation, dict):
            return
        for attr_name in (
            "unified_opportunity_score",
            "unified_size_multiplier",
            "capital_duration_size_multiplier",
            "capital_lock_penalty",
            "time_to_event_minutes",
            "time_to_expiry_minutes",
            "sports_memory_context",
            "sports_memory_dimensions",
            "sports_memory_rank_adjustment",
            "sports_memory_size_multiplier",
            "sports_memory_aggression_multiplier",
            "sports_memory_regime",
            "sports_regime_context",
            "sports_regime",
            "sports_regime_type",
            "sports_momentum_classification",
            "sports_momentum_score",
            "sports_regime_rank_adjustment",
            "sports_regime_size_multiplier",
            "sports_regime_aggression_multiplier",
            "sports_graph_context",
            "sports_graph_game_id",
            "sports_graph_role",
            "sports_graph_direction",
            "sports_graph_relationship_types",
            "sports_graph_lag_detected",
            "sports_graph_rank_adjustment",
            "sports_graph_size_multiplier",
            "sports_graph_conflict_count",
            "sports_graph_alignment_count",
            "game_thesis_context",
            "game_id",
            "game_thesis_type",
            "game_thesis_confidence",
            "game_thesis_rank_boost",
            "game_thesis_size_multiplier",
            "game_thesis_aggression_multiplier",
            "game_related_candidates",
            "game_primary_candidate",
            "game_secondary_candidates",
        ):
            attr_value = allocation.get(attr_name)
            if attr_value is not None:
                try:
                    setattr(q, attr_name, attr_value)
                except Exception:
                    pass

    def _execute_multi_sports_submit_cycle(self, *, primary_ticker=None, primary_lane=None, primary_result=None, source="multi_submit_cycle"):
        candidates = sorted(
            [candidate for candidate in (getattr(self, "last_dual_lane_buy_candidates", []) or []) if isinstance(candidate, dict)],
            key=lambda item: self._candidate_unified_score(item),
            reverse=True,
        )
        primary_ticker = str(primary_ticker or "").strip()
        primary_lane = str(primary_lane or "").strip().upper()
        primary_result = primary_result if isinstance(primary_result, dict) else {}
        submitted_entries = []
        if primary_ticker and primary_result.get("submitted"):
            primary_meta = None
            for candidate in candidates:
                if str(candidate.get("ticker") or "").strip() == primary_ticker:
                    primary_meta = self._aion_concurrency_candidate_meta(candidate)
                    break
            if primary_meta is None:
                payload = primary_result.get("payload") if isinstance(primary_result.get("payload"), dict) else {}
                primary_meta = {
                    "ticker": primary_ticker,
                    "family": self.get_market_family({"ticker": primary_ticker}),
                    "game_key": None,
                    "selected_side": payload.get("side") or payload.get("selected_side"),
                }
            submitted_entries.append(self._aion_concurrency_entry_from_meta(primary_meta, source="primary"))
        submitted = []
        skipped = []
        stop_reasons = {
            "max_submits_per_cycle",
            "rate_limited",
            "min_seconds_between_submits",
            "max_new_positions_per_10min",
            "max_open_positions",
            "daily_loss_guard",
            "trading_halted",
        }
        for candidate in candidates:
            meta = self._aion_concurrency_candidate_meta(candidate)
            ticker = str(meta.get("ticker") or "").strip()
            family = str(meta.get("family") or "UNKNOWN").strip().upper() or "UNKNOWN"
            lane = str(meta.get("lane") or "").strip().upper()
            allocation = meta.get("allocation") if isinstance(meta.get("allocation"), dict) else {}
            if not ticker or lane != "SPORTS":
                continue
            if primary_ticker and ticker == primary_ticker:
                skipped.append({"ticker": ticker, "reason": "primary_candidate_already_attempted"})
                continue
            if allocation.get("decision") == "SKIP_WEAK_SPORT" or allocation.get("final_quality_action") == "skip":
                reason = allocation.get("final_quality_reason") or allocation.get("reason") or "weak_sports_quality_demoted"
                skipped.append({"ticker": ticker, "reason": reason})
                self._emit_aion_concurrency_log("AION-CONCURRENCY-BLOCK", {
                    "source": source,
                    "ticker": ticker,
                    "family": family,
                    "reason": reason,
                    "decision": "BLOCK",
                    "subsystem": "multi_sports_submit",
                })
                continue
            if self._sports_only_execution_blocked(
                family=family,
                ticker=ticker,
                market=meta.get("market") if isinstance(meta.get("market"), dict) else {},
                q=meta.get("q"),
                lane="SPORTS",
                reason=self._sports_only_block_reason(family=family, ticker=ticker, market=meta.get("market"), q=meta.get("q"), lane="SPORTS"),
                source=source,
            ):
                skipped.append({"ticker": ticker, "reason": "sports_only_non_sports_block"})
                continue
            concurrency = self._evaluate_aion_concurrency_candidate(candidate, submitted_entries=submitted_entries, source=source)
            if not concurrency.get("allowed"):
                reason = concurrency.get("reason") or "concurrency_block"
                skipped.append({"ticker": ticker, "reason": reason})
                if reason in stop_reasons:
                    break
                continue
            q = meta.get("q")
            if q is None:
                skipped.append({"ticker": ticker, "reason": "missing_quote_object"})
                continue
            self._apply_multi_submit_candidate_metadata(q, allocation)
            payload = self.build_live_order_payload(
                q,
                market=meta.get("market") if isinstance(meta.get("market"), dict) else {},
                selected_ticker=ticker,
                selection_stage="multi_sports_submit",
                allow_orderbook_refresh=True,
            )
            if not isinstance(payload, dict):
                skipped.append({"ticker": ticker, "reason": "selected_price_missing_or_invalid_payload"})
                self._emit_aion_concurrency_log("AION-CONCURRENCY-BLOCK", {
                    "source": source,
                    "ticker": ticker,
                    "family": family,
                    "reason": "selected_price_missing_or_invalid_payload",
                    "decision": "BLOCK",
                    "subsystem": "multi_sports_submit",
                })
                continue
            pre_submit_check = self._sports_momentum_pre_submit_check(
                q=q,
                market=meta.get("market") if isinstance(meta.get("market"), dict) else {},
                payload=payload,
                allocation=allocation,
                source="multi_sports_submit_pre_submit",
            )
            if not pre_submit_check.get("allowed"):
                reason = pre_submit_check.get("reason") or "sports_momentum_pre_submit_skip"
                skipped.append({"ticker": ticker, "reason": reason})
                self._emit_aion_concurrency_log("AION-CONCURRENCY-BLOCK", {
                    "source": source,
                    "ticker": ticker,
                    "family": family,
                    "reason": reason,
                    "decision": "BLOCK",
                    "subsystem": "multi_sports_submit",
                })
                continue
            result = self.submit_live_order(
                q,
                lane="sports_multi_submit",
                payload_override=payload,
            )
            if not isinstance(result, dict):
                result = {"submitted": False, "reason": "submit_error", "payload": payload}
            submitted_payload = result.get("payload") if isinstance(result.get("payload"), dict) else payload
            if result.get("submitted"):
                self.record_live_position(
                    q,
                    size=submitted_payload.get("count"),
                    entry_price=submitted_payload.get("price"),
                    side=submitted_payload.get("side"),
                )
                print(
                    "[POSITION-OPEN] "
                    + json.dumps(
                        {
                            "ticker": ticker,
                            "family": family,
                            "side": submitted_payload.get("side"),
                            "price": submitted_payload.get("price"),
                            "count": submitted_payload.get("count"),
                            "subsystem": "kalshi_web.multi_sports_submit",
                        },
                        sort_keys=True,
                        default=str,
                    )
                )
                submitted_entries.append(
                    self._aion_concurrency_entry_from_meta(
                        meta,
                        source="multi_submit",
                        count=submitted_payload.get("count"),
                        price=submitted_payload.get("price"),
                        side=submitted_payload.get("side"),
                    )
                )
                submitted.append({
                    "ticker": ticker,
                    "family": family,
                    "side": submitted_payload.get("side"),
                    "price": submitted_payload.get("price"),
                    "count": submitted_payload.get("count"),
                })
                continue
            reason = result.get("reason") or "submit_blocked"
            skipped.append({"ticker": ticker, "reason": reason})
            self._emit_aion_concurrency_log("AION-CONCURRENCY-BLOCK", {
                "source": source,
                "ticker": ticker,
                "family": family,
                "reason": reason,
                "decision": "BLOCK",
                "subsystem": "multi_sports_submit",
            })
            if reason in stop_reasons:
                break
        summary = {
            "source": source,
            "primary_ticker": primary_ticker or None,
            "primary_lane": primary_lane or None,
            "primary_submitted": bool(primary_result.get("submitted")),
            "submitted": bool(submitted),
            "submitted_count": len(submitted),
            "submitted_tickers": [entry.get("ticker") for entry in submitted],
            "skipped": skipped[:12],
            "settings": self._aion_concurrency_settings(),
            "reason": "multi_submit_completed" if submitted else "no_additional_sports_submits",
        }
        self._emit_aion_concurrency_log("AION-MULTI-SUBMIT-CYCLE", summary)
        return summary

    def _execute_dual_lane_secondary_candidate(self, *, primary_ticker=None, primary_lane=None, target_lane=None, source="parallel_lane_submit"):
        if not AION_DUAL_LANE_SECONDARY_ENABLED:
            return {"submitted": False, "reason": "dual_lane_secondary_disabled"}
        primary_ticker = str(primary_ticker or "").strip()
        primary_lane = str(primary_lane or "").strip().upper()
        target_lane = str(target_lane or "").strip().upper()
        crypto_lanes = {"CRYPTO_LADDER", "BTC1H_LADDER"}
        target_lanes = set()
        if target_lane in crypto_lanes:
            target_lanes = set(crypto_lanes)
        elif target_lane:
            target_lanes = {target_lane}
        candidates = sorted(
            list(getattr(self, "last_dual_lane_buy_candidates", []) or []),
            key=lambda item: self._candidate_unified_score(item),
            reverse=True,
        )
        last_attempt_result = None
        for candidate in candidates:
            if not isinstance(candidate, dict):
                continue
            ticker = str(candidate.get("ticker") or "").strip()
            lane = str(candidate.get("lane") or "").strip().upper()
            allocation = candidate.get("allocation") if isinstance(candidate.get("allocation"), dict) else {}
            if not ticker or ticker == primary_ticker:
                continue
            if lane not in {"CRYPTO_LADDER", "BTC1H_LADDER", "SPORTS"}:
                continue
            if target_lanes and lane not in target_lanes:
                continue
            if not target_lanes and primary_lane and lane == primary_lane:
                continue
            if self._sports_only_crypto_execution_blocked(
                family=candidate.get("family") or allocation.get("family"),
                ticker=ticker,
                market=candidate.get("market") if isinstance(candidate.get("market"), dict) else {},
                q=candidate.get("q"),
                lane=lane,
                reason="crypto_blocked_before_secondary_submit",
                source=source,
            ):
                result = {"submitted": False, "reason": "sports_only_crypto_execution_disabled"}
                truth_payload = self._lane_submit_truth_payload(
                    candidate=candidate,
                    allocation=allocation,
                    result=result,
                    submit_allowed=False,
                    reason=result.get("reason"),
                    source=source,
                )
                print("[AION-PROMOTED-NOT-SUBMITTED] " + json.dumps(truth_payload, sort_keys=True, default=str))
                print("[AION-PARALLEL-SUBMIT] " + json.dumps(truth_payload, sort_keys=True, default=str))
                last_attempt_result = result
                if target_lanes:
                    return result
                continue
            opportunity_gate = self._opportunity_cost_gate(candidate, candidates, source=source)
            if not opportunity_gate.get("allowed"):
                result = {"submitted": False, "reason": opportunity_gate.get("reason") or "opportunity_cost_suppressed"}
                truth_payload = self._lane_submit_truth_payload(
                    candidate=candidate,
                    allocation=allocation,
                    result=result,
                    submit_allowed=False,
                    reason=result.get("reason"),
                    source=source,
                )
                print("[AION-PROMOTED-NOT-SUBMITTED] " + json.dumps(truth_payload, sort_keys=True, default=str))
                print("[AION-PARALLEL-SUBMIT] " + json.dumps(truth_payload, sort_keys=True, default=str))
                last_attempt_result = result
                if target_lanes:
                    return result
                continue
            winner_tag = "[AION-SPORTS-LANE-WINNER]"
            print(
                winner_tag
                + " "
                + json.dumps(
                    self._lane_submit_truth_payload(
                        candidate=candidate,
                        allocation=allocation,
                        source=source,
                        reason="lane_winner_selected",
                    ),
                    sort_keys=True,
                    default=str,
                )
            )
            if allocation.get("decision") == "SKIP_WEAK_SPORT" or allocation.get("final_quality_action") == "skip":
                result = {"submitted": False, "reason": "weak_sports_quality_demoted"}
                truth_payload = self._lane_submit_truth_payload(
                    candidate=candidate,
                    allocation=allocation,
                    result=result,
                    submit_allowed=False,
                    reason=result.get("reason"),
                    source=source,
                )
                print(
                    "[AION-FINAL-QUALITY-GATE] "
                    + json.dumps(
                        {
                            "source": "dual_lane_secondary",
                            "lane": lane,
                            "ticker": ticker,
                            "family": allocation.get("family"),
                            "trash_pattern_matched": allocation.get("trash_prop_patterns"),
                            "EV": allocation.get("edge"),
                            "confidence": allocation.get("confidence"),
                            "spread": allocation.get("spread"),
                            "liquidity": allocation.get("liquidity"),
                            "quality_boost": allocation.get("quality_boost"),
                            "trash_prop_penalty": allocation.get("trash_prop_penalty"),
                            "final_action": "skip",
                            "reason": allocation.get("final_quality_reason") or allocation.get("reason"),
                        },
                        sort_keys=True,
                        default=str,
                    )
                )
                print("[AION-PROMOTED-NOT-SUBMITTED] " + json.dumps(truth_payload, sort_keys=True, default=str))
                print("[AION-PARALLEL-SUBMIT] " + json.dumps(truth_payload, sort_keys=True, default=str))
                last_attempt_result = result
                if target_lanes:
                    return result
                continue
            q = candidate.get("q")
            market = candidate.get("market") if isinstance(candidate.get("market"), dict) else {}
            family = str(candidate.get("family") or self.get_market_family(market or {"ticker": ticker}) or "UNKNOWN").strip().upper()
            if q is not None:
                unified_context = allocation.get("unified_opportunity") if isinstance(allocation.get("unified_opportunity"), dict) else {}
                for attr_name, attr_value in (
                    ("unified_opportunity_score", allocation.get("unified_opportunity_score") or unified_context.get("unified_score")),
                    ("unified_size_multiplier", allocation.get("unified_size_multiplier") or unified_context.get("size_multiplier")),
                    ("capital_duration_size_multiplier", allocation.get("unified_size_multiplier") or unified_context.get("size_multiplier")),
                    ("capital_lock_penalty", allocation.get("capital_lock_penalty") or unified_context.get("capital_lock_penalty")),
                    ("time_to_event_minutes", allocation.get("time_to_event_minutes") or unified_context.get("time_to_event_minutes")),
                    ("time_to_expiry_minutes", allocation.get("time_to_expiry_minutes") or unified_context.get("time_to_expiry_minutes")),
                    ("sports_memory_context", allocation.get("sports_memory_context") or unified_context.get("sports_memory_context")),
                    ("sports_memory_dimensions", allocation.get("sports_memory_dimensions") or (allocation.get("sports_memory_context") or {}).get("dimensions")),
                    ("sports_memory_rank_adjustment", allocation.get("sports_memory_rank_adjustment") or unified_context.get("sports_memory_rank_adjustment")),
                    ("sports_memory_size_multiplier", allocation.get("sports_memory_size_multiplier") or unified_context.get("sports_memory_size_multiplier")),
                    ("sports_memory_aggression_multiplier", allocation.get("sports_memory_aggression_multiplier") or unified_context.get("sports_memory_aggression_multiplier")),
                    ("sports_memory_regime", allocation.get("sports_memory_regime") or unified_context.get("sports_memory_regime")),
                    ("sports_regime_context", allocation.get("sports_regime_context") or unified_context.get("sports_regime_context")),
                    ("sports_regime", allocation.get("sports_regime") or unified_context.get("sports_regime")),
                    ("sports_regime_type", allocation.get("sports_regime_type") or unified_context.get("sports_regime_type")),
                    ("sports_momentum_classification", allocation.get("sports_momentum_classification") or unified_context.get("sports_momentum_classification")),
                    ("sports_momentum_score", allocation.get("sports_momentum_score") or unified_context.get("sports_momentum_score")),
                    ("sports_regime_rank_adjustment", allocation.get("sports_regime_rank_adjustment") or unified_context.get("sports_regime_rank_adjustment")),
                    ("sports_regime_size_multiplier", allocation.get("sports_regime_size_multiplier") or unified_context.get("sports_regime_size_multiplier")),
                    ("sports_regime_aggression_multiplier", allocation.get("sports_regime_aggression_multiplier") or unified_context.get("sports_regime_aggression_multiplier")),
                    ("sports_graph_context", allocation.get("sports_graph_context") or unified_context.get("sports_graph_context")),
                    ("sports_graph_game_id", allocation.get("sports_graph_game_id") or allocation.get("game_id")),
                    ("sports_graph_role", allocation.get("sports_graph_role") or unified_context.get("sports_graph_role")),
                    ("sports_graph_direction", allocation.get("sports_graph_direction") or unified_context.get("sports_graph_direction")),
                    ("sports_graph_relationship_types", allocation.get("sports_graph_relationship_types") or unified_context.get("sports_graph_relationship_types")),
                    ("sports_graph_lag_detected", allocation.get("sports_graph_lag_detected") or unified_context.get("sports_graph_lag_detected")),
                    ("sports_graph_rank_adjustment", allocation.get("sports_graph_rank_adjustment") or unified_context.get("sports_graph_rank_adjustment")),
                    ("sports_graph_size_multiplier", allocation.get("sports_graph_size_multiplier") or unified_context.get("sports_graph_size_multiplier")),
                    ("sports_graph_conflict_count", allocation.get("sports_graph_conflict_count") or unified_context.get("sports_graph_conflict_count")),
                    ("sports_graph_alignment_count", allocation.get("sports_graph_alignment_count") or unified_context.get("sports_graph_alignment_count")),
                    ("game_thesis_context", allocation.get("game_thesis_context")),
                    ("game_id", allocation.get("game_id")),
                    ("game_thesis_type", allocation.get("game_thesis_type")),
                    ("game_thesis_confidence", allocation.get("game_thesis_confidence")),
                    ("game_thesis_rank_boost", allocation.get("game_thesis_rank_boost")),
                    ("game_thesis_size_multiplier", allocation.get("game_thesis_size_multiplier")),
                    ("game_thesis_aggression_multiplier", allocation.get("game_thesis_aggression_multiplier")),
                    ("game_related_candidates", allocation.get("game_related_candidates")),
                    ("game_primary_candidate", allocation.get("game_primary_candidate")),
                    ("game_secondary_candidates", allocation.get("game_secondary_candidates")),
                ):
                    if attr_value is not None:
                        try:
                            setattr(q, attr_name, attr_value)
                        except Exception:
                            pass
            duplicate = {"blocked": False}
            payload = None
            attempt_tag = "[AION-SPORTS-SUBMIT-ATTEMPT]"
            if self.already_holding(ticker):
                reason = "duplicate_position_guard"
                result = {"submitted": False, "reason": reason}
            else:
                duplicate = self.check_live_duplicate_position_api(ticker)
                if duplicate.get("blocked"):
                    result = {"submitted": False, "reason": duplicate.get("reason") or "duplicate_position_guard"}
                else:
                    if int(self.live_trade_count_today or 0) >= int(MAX_LIVE_TRADES_PER_DAY or 0):
                        try:
                            print(
                                "[AION-RISK-GOVERNOR] "
                                + json.dumps(
                                    {
                                        "ticker": ticker,
                                        "family": family,
                                        "ok": True,
                                        "reason": "daily_trade_count_warning",
                                        "live_trade_count_today": int(self.live_trade_count_today or 0),
                                        "max_live_trades_per_day": int(MAX_LIVE_TRADES_PER_DAY or 0),
                                        "responsible_subsystem": "dual_lane_secondary",
                                    },
                                    sort_keys=True,
                                    default=str,
                                )
                            )
                        except Exception:
                            pass
                    payload = self.build_live_order_payload(
                        q,
                        market=market,
                        selected_ticker=ticker,
                        selection_stage="dual_lane_secondary",
                        allow_orderbook_refresh=True,
                    )
                    pre_submit_check = {"allowed": bool(payload), "reason": "submit_live_order" if payload else "invalid_payload"}
                    if lane == "SPORTS" and not isinstance(payload, dict):
                        self._emit_sports_regime_log(
                            "SPORTS-MOMENTUM-SKIP",
                            {
                                "source": source,
                                "ticker": ticker,
                                "family": family,
                                "reason": "selected_price_missing_or_invalid_payload",
                            },
                            marker=("SPORTS-MOMENTUM-SKIP", source, ticker, "invalid_payload", int(time.time() // 180)),
                        )
                    elif lane == "SPORTS":
                        pre_submit_check = self._sports_momentum_pre_submit_check(
                            q=q,
                            market=market,
                            payload=payload,
                            allocation=allocation,
                            source="dual_lane_secondary_pre_submit",
                        )
                    print(
                        attempt_tag
                        + " "
                        + json.dumps(
                            self._lane_submit_truth_payload(
                                candidate=candidate,
                                allocation=allocation,
                                payload=payload if isinstance(payload, dict) else {},
                                duplicate_guard=duplicate,
                                submit_allowed=bool(payload) and bool(pre_submit_check.get("allowed")),
                                reason="submit_live_order" if payload and pre_submit_check.get("allowed") else pre_submit_check.get("reason") or "invalid_payload",
                                source=source,
                            ),
                            sort_keys=True,
                            default=str,
                        )
                    )
                    result = self.submit_live_order(
                        q,
                        lane="dual_lane_secondary",
                        payload_override=payload,
                    ) if payload and pre_submit_check.get("allowed") else {"submitted": False, "reason": pre_submit_check.get("reason") or "invalid_payload", "payload": payload}
                    if result.get("submitted"):
                        submitted_payload = result.get("payload") or payload or {}
                        self.record_live_position(
                            q,
                            size=submitted_payload.get("count"),
                            entry_price=submitted_payload.get("price"),
                            side=submitted_payload.get("side"),
                        )
                        print(
                            "[POSITION-OPEN] "
                            + json.dumps(
                                {
                                    "ticker": ticker,
                                    "family": family,
                                    "side": submitted_payload.get("side"),
                                    "price": submitted_payload.get("price"),
                                    "count": submitted_payload.get("count"),
                                    "subsystem": "kalshi_web.dual_lane_secondary",
                                },
                                sort_keys=True,
                                default=str,
                            )
                        )
                        self._emit_btc1h_live_execute_log(
                            ticker,
                            result=result,
                            payload=submitted_payload,
                            family=family,
                        )
            if not payload and not result.get("submitted"):
                print(
                    attempt_tag
                    + " "
                    + json.dumps(
                        self._lane_submit_truth_payload(
                            candidate=candidate,
                            allocation=allocation,
                            duplicate_guard=duplicate,
                            submit_allowed=False,
                            reason=result.get("reason"),
                            source=source,
                        ),
                        sort_keys=True,
                        default=str,
                    )
                )
            payload_for_log = result.get("payload") if isinstance(result, dict) else {}
            if not payload_for_log and isinstance(payload, dict):
                payload_for_log = payload
            log_payload = {
                "lane": lane,
                "ticker": ticker,
                "family": family,
                "score": allocation.get("allocation_score"),
                "unified_score": allocation.get("unified_opportunity_score"),
                "capital_lock_penalty": allocation.get("capital_lock_penalty"),
                "EV": allocation.get("edge"),
                "confidence": allocation.get("confidence"),
                "spread": allocation.get("spread"),
                "liquidity": allocation.get("liquidity"),
                "btc1h_boost": allocation.get("btc1h_boost"),
                "sports_quality_reason": allocation.get("reason") if lane == "SPORTS" else None,
                "execution_result": "submitted" if result.get("submitted") else result.get("reason"),
                "final_decision": "EXECUTE" if result.get("submitted") else "SKIP",
                "side": (payload_for_log or {}).get("side"),
                "price": (payload_for_log or {}).get("price"),
                "count": (payload_for_log or {}).get("count"),
            }
            print("[AION-DUAL-LANE-EXECUTE] " + json.dumps(log_payload, sort_keys=True, default=str))
            truth_payload = self._lane_submit_truth_payload(
                candidate=candidate,
                allocation=allocation,
                result=result,
                payload=(payload_for_log or {}),
                duplicate_guard=duplicate,
                submit_allowed=bool(result.get("submitted")),
                reason="submitted" if result.get("submitted") else result.get("reason"),
                source=source,
            )
            if not result.get("submitted"):
                print("[AION-PROMOTED-NOT-SUBMITTED] " + json.dumps(truth_payload, sort_keys=True, default=str))
            print("[AION-PARALLEL-SUBMIT] " + json.dumps(truth_payload, sort_keys=True, default=str))
            self.last_dual_lane_execution_summary = log_payload
            last_attempt_result = result
            if result.get("submitted"):
                return result
            if target_lanes:
                if lane == "SPORTS" and str(result.get("reason") or "") in {
                    "invalid_payload",
                    "selected_price_missing",
                    "selected_price_missing_or_invalid_payload",
                    "selected_side_missing",
                    "spread_not_sane",
                }:
                    continue
                if lane == "SPORTS" and str(result.get("reason") or "").startswith("orderbook_invalid"):
                    continue
                return result
        self.last_dual_lane_execution_summary = last_attempt_result or {"submitted": False, "reason": "no_secondary_lane_candidate"}
        return self.last_dual_lane_execution_summary

    def _execute_parallel_lane_submit_attempts(self, *, primary_ticker=None, primary_lane=None, primary_result=None, source="final_allocation"):
        candidates = list(getattr(self, "last_dual_lane_buy_candidates", []) or [])
        if not candidates:
            summary = {"source": source, "submitted": False, "reason": "no_lane_candidates"}
            print("[AION-FINAL-ALLOCATION-TRUTH] " + json.dumps(summary, sort_keys=True, default=str))
            return summary
        primary_ticker = str(primary_ticker or "").strip()
        primary_lane = str(primary_lane or "").strip().upper()
        primary_result = primary_result if isinstance(primary_result, dict) else {}
        if primary_ticker and not primary_lane:
            for lane_candidate in candidates:
                if str((lane_candidate or {}).get("ticker") or "").strip() == primary_ticker:
                    primary_lane = str((lane_candidate or {}).get("lane") or "").strip().upper()
                    break
        already_submitted = {
            "SPORTS": bool(primary_result.get("submitted") and primary_lane == "SPORTS"),
        }
        results = {}
        best_by_lane = {}
        for candidate in candidates:
            if not isinstance(candidate, dict):
                continue
            candidate_lane = str(candidate.get("lane") or "").strip().upper()
            lane_key = "SPORTS" if candidate_lane == "SPORTS" else None
            if lane_key is None:
                continue
            if lane_key not in best_by_lane or self._candidate_unified_score(candidate) > self._candidate_unified_score(best_by_lane[lane_key]):
                best_by_lane[lane_key] = candidate
        eligible_lane_names = ("SPORTS",)
        lane_order = sorted(
            eligible_lane_names,
            key=lambda lane_name: self._candidate_unified_score(best_by_lane.get(lane_name)) if lane_name in best_by_lane else -1.0,
            reverse=True,
        )
        print(
            "[AION-CAPITAL-ALLOCATION-WINNER] "
            + json.dumps(
                    {
                        "source": source,
                        "lane_order": lane_order,
                        "sports_top_ticker": (best_by_lane.get("SPORTS") or {}).get("ticker"),
                        "sports_top_unified_score": self._candidate_unified_score(best_by_lane.get("SPORTS")),
                        "reason": "rank_lanes_by_unified_opportunity_score",
                },
                sort_keys=True,
                default=str,
            )
        )
        sports_ladder_result = self._execute_sports_ladder_attempts(
            primary_ticker=primary_ticker,
            primary_result=primary_result,
            source=source,
        )
        if isinstance(sports_ladder_result, dict):
            results["SPORTS_LADDER"] = sports_ladder_result
            if sports_ladder_result.get("submitted"):
                already_submitted["SPORTS"] = True
        sports_multi_result = self._execute_multi_sports_submit_cycle(
            primary_ticker=primary_ticker,
            primary_lane=primary_lane,
            primary_result=primary_result,
            source=source,
        )
        results["SPORTS_MULTI"] = sports_multi_result if isinstance(sports_multi_result, dict) else {"submitted": False, "reason": "unknown"}
        if (results.get("SPORTS_MULTI") or {}).get("submitted"):
            results["SPORTS"] = results["SPORTS_MULTI"]
        elif already_submitted.get("SPORTS"):
            results["SPORTS"] = {
                "submitted": True,
                "reason": "sports_ladder_already_submitted" if (results.get("SPORTS_LADDER") or {}).get("submitted") else "primary_lane_already_submitted",
                "ticker": primary_ticker,
            }
        else:
            results["SPORTS"] = results["SPORTS_MULTI"]
        summary = {
            "source": source,
            "primary_ticker": primary_ticker,
            "primary_lane": primary_lane,
            "primary_submitted": bool(primary_result.get("submitted")),
            "sports_submitted": bool((results.get("SPORTS") or {}).get("submitted") or (results.get("SPORTS_LADDER") or {}).get("submitted") or (results.get("SPORTS_MULTI") or {}).get("submitted")),
            "sports_reason": (results.get("SPORTS") or {}).get("reason"),
            "sports_ladder_reason": (results.get("SPORTS_LADDER") or {}).get("reason"),
            "sports_multi_submitted_count": (results.get("SPORTS_MULTI") or {}).get("submitted_count", 0),
            "results": results,
        }
        print("[AION-FINAL-ALLOCATION-TRUTH] " + json.dumps(summary, sort_keys=True, default=str))
        return summary

