    def _build_structural_family_profile(self, family=None, category=None, market_type=None):
        family_text = str(family or "").strip().upper() or "UNKNOWN"
        category_text = str(category or "").strip().lower() or "unknown"
        market_type_text = str(market_type or "").strip().lower() or "generic"
        is_sports = bool(category_text == "sports" or self.is_sports_family(family_text))
        profile = {
            "family": family_text,
            "category": category_text,
            "market_type": market_type_text,
            "structural_edge_weight": 1.0,
            "timing_sensitivity": 0.50,
            "volatility_tolerance": 0.50,
            "sizing_bias": 1.0,
            "profile_reason": "generic",
        }
        if is_sports:
            profile.update(
                {
                    "structural_edge_weight": 1.18,
                    "timing_sensitivity": 0.76,
                    "volatility_tolerance": 0.68,
                    "sizing_bias": 1.08,
                    "profile_reason": "sports_structural",
                }
            )
            text = f"{family_text} {market_type_text}"
            if any(term in text for term in ("PROP", "STRIKE", "HR", "HIT", "RBI", "PLAYER")):
                profile.update(
                    {
                        "structural_edge_weight": 1.28,
                        "timing_sensitivity": 0.86,
                        "volatility_tolerance": 0.82,
                        "sizing_bias": 1.06,
                        "profile_reason": "sports_prop_ladder",
                    }
                )
            elif any(term in text for term in ("SPREAD", "TOTAL", "1H")):
                profile.update(
                    {
                        "structural_edge_weight": 1.22,
                        "timing_sensitivity": 0.80,
                        "volatility_tolerance": 0.72,
                        "sizing_bias": 1.10,
                        "profile_reason": "sports_spread_total",
                    }
                )
            elif any(term in text for term in ("TENNIS", "ATP")):
                profile.update(
                    {
                        "structural_edge_weight": 1.16,
                        "timing_sensitivity": 0.84,
                        "volatility_tolerance": 0.78,
                        "sizing_bias": 1.06,
                        "profile_reason": "sports_tennis",
                    }
                )
        elif family_text.startswith("KXBTC"):
            profile.update(
                {
                    "structural_edge_weight": 1.18,
                    "timing_sensitivity": 0.94,
                    "volatility_tolerance": 0.94,
                    "sizing_bias": 1.10,
                    "profile_reason": "btc_ladder_fast_repricing",
                }
            )
        elif family_text.startswith("KXETH") or "CRYPTO" in family_text:
            profile.update(
                {
                    "structural_edge_weight": 0.88,
                    "timing_sensitivity": 0.90,
                    "volatility_tolerance": 0.90,
                    "sizing_bias": 0.96,
                    "profile_reason": "crypto_fast_repricing",
                }
            )
        elif "WEATHER" in family_text or "KXHIGH" in family_text or "KXTEMP" in family_text:
            profile.update(
                {
                    "structural_edge_weight": 0.96,
                    "timing_sensitivity": 0.42,
                    "volatility_tolerance": 0.38,
                    "sizing_bias": 0.96,
                    "profile_reason": "weather_slow_repricing",
                }
            )
        try:
            stats = self._get_family_profit_memory_stats(family_text, refresh=False)
        except Exception:
            stats = {}
        if isinstance(stats, dict):
            pnl = self.to_float(stats.get("pnl") or stats.get("net_pnl") or stats.get("realized_pnl"), 0.0) or 0.0
            win_rate = self.to_float(stats.get("win_rate"), None)
            trade_count = int(self.to_float(stats.get("trade_count") or stats.get("trades") or stats.get("sample_size"), 0) or 0)
            if trade_count >= 3 and pnl > 0.0:
                profile["sizing_bias"] = min(1.18, self.to_float(profile.get("sizing_bias"), 1.0) + 0.04)
                profile["structural_edge_weight"] = min(1.38, self.to_float(profile.get("structural_edge_weight"), 1.0) + 0.06)
                profile["profile_reason"] = f"{profile['profile_reason']}+profitable_family"
            elif trade_count >= 3 and pnl < 0.0:
                profile["sizing_bias"] = max(0.86, self.to_float(profile.get("sizing_bias"), 1.0) - 0.05)
                profile["structural_edge_weight"] = max(0.82, self.to_float(profile.get("structural_edge_weight"), 1.0) - 0.04)
                profile["profile_reason"] = f"{profile['profile_reason']}+weak_family"
            if win_rate is not None and trade_count >= 5 and win_rate >= 0.58:
                profile["sizing_bias"] = min(1.22, self.to_float(profile.get("sizing_bias"), 1.0) + 0.03)
        return profile

    def _structural_related_markets(self, *, market=None, q=None, family=None, markets=None, ticker=None):
        market = market if isinstance(market, dict) else {}
        ticker = str(ticker or getattr(q, "ticker", "") or market.get("ticker", "") or "").strip()
        family = str(family or self.get_market_family(market if market else {"ticker": ticker}) or "").strip().upper()
        if not family or not markets:
            return []
        event_keys = {
            str(market.get(key) or "").strip().upper()
            for key in ("event_ticker", "eventTicker", "series_ticker", "seriesTicker")
            if str(market.get(key) or "").strip()
        }
        title = self._normalize_structural_text(
            " ".join(
                str(value or "")
                for value in (
                    market.get("title"),
                    market.get("subtitle"),
                    market.get("event_title"),
                    getattr(q, "title", None),
                    getattr(q, "market_title", None),
                )
                if str(value or "").strip()
            )
        )
        title_tokens = {token for token in title.split() if len(token) >= 3 and not token.isdigit()}
        related = []
        for candidate_market in markets or []:
            if not isinstance(candidate_market, dict):
                continue
            candidate_ticker = str(candidate_market.get("ticker") or "").strip()
            if not candidate_ticker or candidate_ticker == ticker:
                continue
            candidate_family = str(self.get_market_family(candidate_market) or "").strip().upper()
            if candidate_family != family:
                continue
            candidate_event_keys = {
                str(candidate_market.get(key) or "").strip().upper()
                for key in ("event_ticker", "eventTicker", "series_ticker", "seriesTicker")
                if str(candidate_market.get(key) or "").strip()
            }
            event_match = bool(event_keys and candidate_event_keys and event_keys.intersection(candidate_event_keys))
            candidate_title = self._normalize_structural_text(
                " ".join(
                    str(candidate_market.get(key) or "")
                    for key in ("title", "subtitle", "event_title")
                    if str(candidate_market.get(key) or "").strip()
                )
            )
            candidate_tokens = {token for token in candidate_title.split() if len(token) >= 3 and not token.isdigit()}
            overlap = len(title_tokens.intersection(candidate_tokens))
            if not event_match and overlap < 2:
                continue
            line_value = self._extract_structural_line_value(
                candidate_market.get("title"),
                candidate_market.get("subtitle"),
                candidate_market.get("ticker"),
            )
            yes_mid = self._structural_yes_mid(candidate_market)
            if yes_mid is None:
                continue
            related.append(
                {
                    "ticker": candidate_ticker,
                    "line": line_value,
                    "yes_mid": yes_mid,
                    "title_overlap": overlap,
                    "event_match": event_match,
                }
            )
        related.sort(
            key=lambda item: (
                0 if item.get("line") is None else 1,
                abs(self.to_float(item.get("line"), 0.0) or 0.0),
                item.get("ticker") or "",
            )
        )
        return related[:24]

    def _structural_market_kind(self, *, family=None, ticker=None, title=None):
        text = " ".join(str(value or "") for value in (family, ticker, title)).upper()
        if any(term in text for term in ("TOTAL", "OVER/UNDER", " OVER ", " UNDER ", "1H TOTAL")):
            return "total"
        if any(term in text for term in ("SPREAD", "MARGIN", "HANDICAP")):
            return "spread"
        if any(term in text for term in ("STRIKEOUT", " STRIKE ", " PITCHER K", " KS ", "KXMLBSTRIKE")):
            return "strikeout_ladder"
        if any(term in text for term in ("HIT", "RBI", "HOME RUN", " HR", "RUNS", "TOTAL BASE", "PLAYER PROP", "PROP")):
            return "player_prop"
        if any(term in text for term in ("LADDER", "RANGE", "ALT LINE")):
            return "ladder"
        if any(term in text for term in ("TENNIS", "ATP", "WTA", "SET", "GAME")):
            return "tennis_live"
        return "generic"

    def _structural_cross_market_peers(self, *, market=None, q=None, family=None, markets=None, ticker=None):
        market = market if isinstance(market, dict) else {}
        ticker = str(ticker or getattr(q, "ticker", "") or market.get("ticker", "") or "").strip()
        family = self._normalize_family_for_profit_memory(family, ticker=ticker, market=market, q=q)
        if not ticker or not markets:
            return []
        title = self._normalize_structural_text(
            " ".join(
                str(value or "")
                for value in (
                    market.get("title"),
                    market.get("subtitle"),
                    market.get("event_title"),
                    getattr(q, "title", None),
                    getattr(q, "market_title", None),
                )
                if str(value or "").strip()
            )
        )
        stopwords = {
            "the", "and", "for", "will", "with", "than", "over", "under", "market",
            "game", "team", "player", "total", "spread", "yes", "no",
        }
        title_tokens = {token for token in title.split() if len(token) >= 3 and token not in stopwords and not token.isdigit()}
        event_keys = {
            str(market.get(key) or "").strip().upper()
            for key in ("event_ticker", "eventTicker", "series_ticker", "seriesTicker")
            if str(market.get(key) or "").strip()
        }
        current_kind = self._structural_market_kind(family=family, ticker=ticker, title=title)
        peers = []
        for candidate_market in markets or []:
            if not isinstance(candidate_market, dict):
                continue
            candidate_ticker = str(candidate_market.get("ticker") or "").strip()
            if not candidate_ticker or candidate_ticker == ticker:
                continue
            candidate_family = self._normalize_family_for_profit_memory(
                self.get_market_family(candidate_market),
                ticker=candidate_ticker,
                market=candidate_market,
            )
            candidate_title_raw = " ".join(
                str(candidate_market.get(key) or "")
                for key in ("title", "subtitle", "event_title")
                if str(candidate_market.get(key) or "").strip()
            )
            candidate_title = self._normalize_structural_text(candidate_title_raw)
            candidate_tokens = {token for token in candidate_title.split() if len(token) >= 3 and token not in stopwords and not token.isdigit()}
            candidate_event_keys = {
                str(candidate_market.get(key) or "").strip().upper()
                for key in ("event_ticker", "eventTicker", "series_ticker", "seriesTicker")
                if str(candidate_market.get(key) or "").strip()
            }
            event_match = bool(event_keys and candidate_event_keys and event_keys.intersection(candidate_event_keys))
            overlap = len(title_tokens.intersection(candidate_tokens))
            if not event_match and overlap < 2:
                continue
            candidate_kind = self._structural_market_kind(
                family=candidate_family,
                ticker=candidate_ticker,
                title=candidate_title_raw,
            )
            if candidate_kind == current_kind and candidate_family == family:
                continue
            yes_mid = self._structural_yes_mid(candidate_market)
            if yes_mid is None:
                continue
            candidate_yes_bid = self._sports_edge_price_value(candidate_market.get("yes_bid") or candidate_market.get("yes_bid_dollars"))
            candidate_yes_ask = self._sports_edge_price_value(candidate_market.get("yes_ask") or candidate_market.get("yes_ask_dollars"))
            candidate_spread = None
            if candidate_yes_bid is not None and candidate_yes_ask is not None:
                candidate_spread = max(0.0, candidate_yes_ask - candidate_yes_bid)
            candidate_price_delta = self.to_float(
                candidate_market.get("price_delta")
                or candidate_market.get("recent_price_movement")
                or candidate_market.get("movement")
                or candidate_market.get("repricing_delta"),
                0.0,
            ) or 0.0
            candidate_velocity = self.to_float(candidate_market.get("repricing_velocity") or candidate_market.get("velocity"), 0.0) or 0.0
            peer_score = (3 if event_match else 0) + min(4, overlap)
            peers.append(
                {
                    "ticker": candidate_ticker,
                    "family": candidate_family,
                    "kind": candidate_kind,
                    "yes_mid": yes_mid,
                    "spread": candidate_spread,
                    "line": self._extract_structural_line_value(
                        candidate_market.get("title"),
                        candidate_market.get("subtitle"),
                        candidate_ticker,
                    ),
                    "price_delta": candidate_price_delta,
                    "repricing_velocity": candidate_velocity,
                    "event_match": event_match,
                    "title_overlap": overlap,
                    "peer_score": peer_score,
                }
            )
        peers.sort(key=lambda item: (item.get("peer_score") or 0, abs((self.to_float(item.get("yes_mid"), 0.5) or 0.5) - 0.5)), reverse=True)
        return peers[:32]

    def _build_cross_market_edge_context(
        self,
        *,
        market=None,
        q=None,
        family=None,
        ticker=None,
        markets=None,
        selected_side=None,
        selected_price=None,
        current_yes_mid=None,
        spread_value=None,
        selected_top_size=0.0,
        opposite_top_size=0.0,
        repricing_component=0.0,
        liquidity_component=0.0,
        family_profile=None,
    ):
        market = market if isinstance(market, dict) else {}
        family_profile = family_profile if isinstance(family_profile, dict) else {}
        ticker = str(ticker or getattr(q, "ticker", "") or market.get("ticker", "") or "").strip()
        family = self._normalize_family_for_profit_memory(family, ticker=ticker, market=market, q=q)
        selected_side = self._aion_normalize_live_side(selected_side)
        selected_price_value = self.to_float(selected_price, None)
        current_kind = self._structural_market_kind(
            family=family,
            ticker=ticker,
            title=" ".join(str(market.get(key) or "") for key in ("title", "subtitle", "event_title")),
        )
        peers = self._structural_cross_market_peers(market=market, q=q, family=family, markets=markets, ticker=ticker)
        if not peers:
            return {
                "enabled": True,
                "score": 0.0,
                "CROSS_MARKET_EDGE_SCORE": 0.0,
                "boost": 0.0,
                "probability_adjustment": 0.0,
                "size_multiplier": 1.0,
                "tags": [],
                "pattern_keys": [],
                "peer_count": 0,
                "reason": "no_cross_market_peers",
            }

        def avg_for(*kinds):
            values = [
                self.to_float(peer.get("yes_mid"), None)
                for peer in peers
                if peer.get("kind") in set(kinds) and self.to_float(peer.get("yes_mid"), None) is not None
            ]
            if not values:
                return None
            return sum(values) / len(values)

        spread_avg = avg_for("spread")
        total_avg = avg_for("total")
        prop_avg = avg_for("player_prop", "strikeout_ladder", "ladder")
        all_mids = [self.to_float(peer.get("yes_mid"), None) for peer in peers if self.to_float(peer.get("yes_mid"), None) is not None]
        peer_signal_yes = max(all_mids) if all_mids else None
        peer_signal_no = 1.0 - min(all_mids) if all_mids else None
        selected_contract_probability = selected_price_value
        if selected_contract_probability is None and current_yes_mid is not None:
            selected_contract_probability = current_yes_mid if selected_side == "yes" else 1.0 - current_yes_mid
        if selected_contract_probability is not None:
            selected_contract_probability = max(0.01, min(0.99, selected_contract_probability))
        peer_signal = peer_signal_no if selected_side == "no" else peer_signal_yes
        if peer_signal is None:
            peer_signal = 0.50
        peer_pressure = max(abs((value or 0.5) - 0.5) for value in all_mids) * 2.0 if all_mids else 0.0
        peer_velocity = max(
            abs(self.to_float(peer.get("price_delta"), 0.0) or 0.0) * 8.0
            + abs(self.to_float(peer.get("repricing_velocity"), 0.0) or 0.0) * 35.0
            for peer in peers
        ) if peers else 0.0
        spread_total_disagreement = 0.0
        if spread_avg is not None and total_avg is not None:
            spread_total_disagreement = self._clamp(abs(spread_avg - total_avg) / 0.18)
        underreaction_gap = 0.0
        if selected_contract_probability is not None:
            underreaction_gap = max(0.0, peer_signal - selected_contract_probability)
        distribution_inconsistency = self._clamp(underreaction_gap / 0.18)
        correlated_prop_divergence = 0.0
        if prop_avg is not None and current_yes_mid is not None:
            if selected_side == "no":
                correlated_prop_divergence = self._clamp(max(0.0, current_yes_mid - prop_avg) / 0.14)
            else:
                correlated_prop_divergence = self._clamp(max(0.0, prop_avg - current_yes_mid) / 0.14)
        pace_mismatch = 0.0
        if current_kind in {"player_prop", "strikeout_ladder", "ladder", "tennis_live"}:
            pace_mismatch = self._clamp((peer_pressure * 0.38) + (max(0.0, repricing_component) * 0.42) + (peer_velocity * 0.20))
        tail_compression = 0.0
        if selected_contract_probability is not None:
            tail_base = max(0.0, 0.46 - selected_contract_probability) / 0.35
            if selected_contract_probability <= 0.46 or underreaction_gap > 0.05:
                tail_compression = self._clamp((tail_base * 0.62) + (peer_pressure * 0.24) + (distribution_inconsistency * 0.14))
        repricing_sequence_lag = self._clamp(
            (max(0.0, repricing_component) * 0.48)
            + (peer_velocity * 0.24)
            + (peer_pressure * 0.18)
            + (distribution_inconsistency * 0.10)
        )
        liquidity_vacuum = self._clamp(
            (max(0.0, liquidity_component) * 0.50)
            + ((1.0 if (selected_top_size <= 2.0 and opposite_top_size >= 5.0) else 0.0) * 0.34)
            + (0.16 if spread_value is not None and spread_value <= 0.10 else 0.0)
        )
        components = {
            "spread_total_disagreement": round(spread_total_disagreement, 4),
            "live_pace_mismatch": round(pace_mismatch, 4),
            "correlated_prop_divergence": round(correlated_prop_divergence, 4),
            "tail_compression": round(tail_compression, 4),
            "distribution_inconsistency": round(distribution_inconsistency, 4),
            "repricing_sequence_lag": round(repricing_sequence_lag, 4),
            "liquidity_vacuum": round(liquidity_vacuum, 4),
        }
        family_weight = max(0.80, min(1.45, self.to_float(family_profile.get("structural_edge_weight"), 1.0) or 1.0))
        raw_score = (
            spread_total_disagreement * 13.0
            + pace_mismatch * 15.0
            + correlated_prop_divergence * 15.0
            + tail_compression * 15.0
            + distribution_inconsistency * 18.0
            + repricing_sequence_lag * 14.0
            + liquidity_vacuum * 10.0
        ) * family_weight
        score = round(max(0.0, min(100.0, raw_score)), 4)
        tags = []
        if spread_total_disagreement >= 0.32:
            tags.append("CROSS_MARKET_SPREAD_TOTAL_DISAGREEMENT")
        if pace_mismatch >= 0.35:
            tags.append("CROSS_MARKET_LIVE_PACE_MISMATCH")
        if correlated_prop_divergence >= 0.32:
            tags.append("CROSS_MARKET_CORRELATED_PROP_DIVERGENCE")
        if tail_compression >= 0.35:
            tags.append("CROSS_MARKET_TAIL_COMPRESSION")
        if distribution_inconsistency >= 0.34:
            tags.append("CROSS_MARKET_DISTRIBUTION_INCONSISTENCY")
        if repricing_sequence_lag >= 0.34:
            tags.append("CROSS_MARKET_REPRICING_SEQUENCE_LAG")
        if liquidity_vacuum >= 0.38:
            tags.append("CROSS_MARKET_LIQUIDITY_VACUUM")
        boost = 0.0
        if score >= 25.0:
            boost = min(AION_CROSS_MARKET_EDGE_MAX_RANK_BOOST, ((score - 20.0) / 80.0) * AION_CROSS_MARKET_EDGE_MAX_RANK_BOOST)
        probability_adjustment = 0.0
        if score >= 45.0:
            probability_adjustment = min(
                AION_CROSS_MARKET_EDGE_MAX_PROBABILITY_ADJUSTMENT,
                0.010 + ((score - 45.0) / 55.0) * (AION_CROSS_MARKET_EDGE_MAX_PROBABILITY_ADJUSTMENT - 0.010),
            )
        size_multiplier = 1.0
        if score >= 82.0:
            size_multiplier = min(AION_CROSS_MARKET_EDGE_MAX_SIZE_MULTIPLIER, 1.58 * self.to_float(family_profile.get("sizing_bias"), 1.0))
        elif score >= 65.0:
            size_multiplier = min(AION_CROSS_MARKET_EDGE_MAX_SIZE_MULTIPLIER, 1.34 * self.to_float(family_profile.get("sizing_bias"), 1.0))
        elif score >= 42.0:
            size_multiplier = min(AION_CROSS_MARKET_EDGE_MAX_SIZE_MULTIPLIER, 1.12 * self.to_float(family_profile.get("sizing_bias"), 1.0))
        elif score < 20.0:
            size_multiplier = 0.82
        odds_bucket = self._aion_distilled_odds_bucket(selected_contract_probability)
        cross_bucket = "cross_elite" if score >= 82.0 else "cross_strong" if score >= 65.0 else "cross_present" if score >= 35.0 else "cross_weak"
        pattern_keys = []
        for tag in tags[:8]:
            pattern_keys.append(f"{family}|{tag}")
            pattern_keys.append(f"{current_kind}|{tag}")
        if odds_bucket:
            pattern_keys.append(f"{family}|{current_kind}|{odds_bucket}|{cross_bucket}")
        return {
            "enabled": True,
            "ticker": ticker,
            "family": family,
            "market_kind": current_kind,
            "score": score,
            "cross_market_edge_score": score,
            "CROSS_MARKET_EDGE_SCORE": score,
            "boost": round(max(0.0, boost), 4),
            "probability_adjustment": round(max(0.0, probability_adjustment), 6),
            "size_multiplier": round(max(0.65, min(AION_CROSS_MARKET_EDGE_MAX_SIZE_MULTIPLIER, size_multiplier)), 4),
            "components": components,
            "tags": tags,
            "pattern_keys": list(dict.fromkeys(pattern_keys))[:16],
            "cross_market_bucket": cross_bucket,
            "peer_count": len(peers),
            "peer_kinds": sorted({str(peer.get("kind") or "unknown") for peer in peers}),
            "peer_pressure": round(peer_pressure, 4),
            "peer_velocity": round(peer_velocity, 4),
            "spread_avg_yes_mid": round(spread_avg, 6) if spread_avg is not None else None,
            "total_avg_yes_mid": round(total_avg, 6) if total_avg is not None else None,
            "prop_avg_yes_mid": round(prop_avg, 6) if prop_avg is not None else None,
            "underreaction_gap": round(underreaction_gap, 6),
            "reason": "+".join(tags) if tags else "cross_market_baseline",
        }

    def _build_elite_edge_confidence_context(
        self,
        *,
        structural_edge_score=0.0,
        cross_market_score=0.0,
        structural_tags=None,
        cross_market_context=None,
        memory_signal=None,
        family_profile=None,
        spread_component=0.0,
        liquidity_component=0.0,
        repricing_component=0.0,
        live_state_score=0.0,
        quality_snapshot=None,
        selected_top_size=0.0,
        opposite_top_size=0.0,
    ):
        if not AION_ELITE_EDGE_ENABLED:
            return {
                "enabled": False,
                "ELITE_EDGE_CONFIDENCE": 0.0,
                "rank_boost": 0.0,
                "size_multiplier": 1.0,
                "kelly_max_multiplier": None,
                "tier": "disabled",
                "tags": [],
            }
        structural_tags = structural_tags if isinstance(structural_tags, list) else []
        cross_market_context = cross_market_context if isinstance(cross_market_context, dict) else {}
        memory_signal = memory_signal if isinstance(memory_signal, dict) else {}
        family_profile = family_profile if isinstance(family_profile, dict) else {}
        quality_snapshot = quality_snapshot if isinstance(quality_snapshot, dict) else {}
        structural_component = self._clamp((self.to_float(structural_edge_score, 0.0) or 0.0) / 100.0)
        cross_component = self._clamp((self.to_float(cross_market_score, 0.0) or 0.0) / 100.0)
        memory_components = [
            component for component in (memory_signal.get("components") or [])
            if isinstance(component, dict)
            and str(component.get("label") or "") in {"structural_tag", "structural_pattern", "cross_market_bucket"}
        ]
        weighted_bias = 0.0
        weighted_count = 0.0
        for component in memory_components:
            bias = self.to_float(component.get("bias"), 0.0) or 0.0
            weight = self.to_float(component.get("weight"), 1.0) or 1.0
            weighted_bias += bias * weight
            weighted_count += abs(weight)
        memory_bias = (weighted_bias / weighted_count) if weighted_count > 0.0 else 0.0
        structural_memory_component = self._clamp(0.48 + max(-0.32, min(0.42, memory_bias)))
        signal_size_multiplier = self.to_float(memory_signal.get("sizing_confidence_multiplier"), 1.0) or 1.0
        if signal_size_multiplier > 1.02:
            structural_memory_component = min(1.0, structural_memory_component + (signal_size_multiplier - 1.0) * 1.35)
        elif signal_size_multiplier < 0.98:
            structural_memory_component = max(0.0, structural_memory_component - (1.0 - signal_size_multiplier) * 1.10)
        family_bias = self.to_float(family_profile.get("sizing_bias"), 1.0) or 1.0
        family_weight = self.to_float(family_profile.get("structural_edge_weight"), 1.0) or 1.0
        family_component = self._clamp(0.50 + ((family_bias - 1.0) * 1.25) + ((family_weight - 1.0) * 0.70))
        fill_quality_raw = self.to_float(
            self._sports_edge_read_value([quality_snapshot], "fill_quality_score", "execution_quality_score", "market_quality_score"),
            None,
        )
        fill_quality_component = self._clamp(fill_quality_raw / 100.0) if fill_quality_raw is not None and fill_quality_raw > 1.0 else self._clamp(fill_quality_raw if fill_quality_raw is not None else 0.50)
        liquidity_quality_component = self._clamp(
            (self.to_float(spread_component, 0.0) or 0.0) * 0.50
            + (self.to_float(liquidity_component, 0.0) or 0.0) * 0.30
            + (0.20 if (self.to_float(selected_top_size, 0.0) or 0.0) > 0.0 and (self.to_float(opposite_top_size, 0.0) or 0.0) > 0.0 else 0.0)
        )
        repricing_reliability_component = self._clamp(
            (self.to_float(repricing_component, 0.0) or 0.0) * 0.62
            + (self.to_float(cross_market_context.get("peer_velocity"), 0.0) or 0.0) * 0.18
            + (self.to_float(cross_market_context.get("peer_pressure"), 0.0) or 0.0) * 0.20
        )
        live_state_component = self._clamp(self.to_float(live_state_score, 0.0) or 0.0)
        cross_cluster_component = self._clamp(
            cross_component * 0.74
            + min(1.0, (self.to_float(cross_market_context.get("peer_count"), 0.0) or 0.0) / 8.0) * 0.16
            + (0.10 if len(cross_market_context.get("tags") or []) >= 2 else 0.0)
        )
        confidence = (
            structural_component * 19.0
            + cross_cluster_component * 18.0
            + structural_memory_component * 19.0
            + family_component * 10.0
            + fill_quality_component * 8.0
            + liquidity_quality_component * 8.0
            + repricing_reliability_component * 9.0
            + live_state_component * 9.0
        )
        if structural_component < 0.45 and cross_component < 0.42:
            confidence *= 0.62
        if memory_bias < -0.18:
            confidence *= 0.82
        confidence = round(max(0.0, min(100.0, confidence)), 4)
        tags = []
        if structural_component >= 0.78:
            tags.append("ELITE_STRUCTURAL_PERSISTENCE")
        if cross_cluster_component >= 0.62:
            tags.append("ELITE_CROSS_MARKET_CLUSTER")
        if structural_memory_component >= 0.62 and memory_components:
            tags.append("ELITE_STRUCTURAL_MEMORY_CONFIRMED")
        if family_component >= 0.60:
            tags.append("ELITE_FAMILY_SPECIALIZATION")
        if fill_quality_component >= 0.70:
            tags.append("ELITE_FILL_QUALITY")
        if liquidity_quality_component >= 0.62:
            tags.append("ELITE_LIQUIDITY_QUALITY")
        if repricing_reliability_component >= 0.55:
            tags.append("ELITE_REPRICING_RELIABLE")
        if live_state_component >= 0.65:
            tags.append("ELITE_LIVE_STATE_ALIGNMENT")
        tier = "weak"
        size_multiplier = 0.72
        rank_boost = 0.0
        kelly_max_multiplier = None
        if confidence >= 88.0:
            tier = "elite"
            size_multiplier = min(AION_ELITE_EDGE_MAX_SIZE_MULTIPLIER, 12.0)
            rank_boost = AION_ELITE_EDGE_MAX_RANK_BOOST
            kelly_max_multiplier = min(18.0, AION_ELITE_EDGE_MAX_KELLY_MULTIPLIER)
            tags.append("ELITE_CONCENTRATION_READY")
        elif confidence >= 75.0:
            tier = "strong"
            size_multiplier = min(AION_ELITE_EDGE_MAX_SIZE_MULTIPLIER, 7.5)
            rank_boost = AION_ELITE_EDGE_MAX_RANK_BOOST * 0.74
            kelly_max_multiplier = min(14.0, AION_ELITE_EDGE_MAX_KELLY_MULTIPLIER)
            tags.append("ELITE_CONCENTRATION_READY")
        elif confidence >= 60.0:
            tier = "promising"
            size_multiplier = min(AION_ELITE_EDGE_MAX_SIZE_MULTIPLIER, 3.5)
            rank_boost = AION_ELITE_EDGE_MAX_RANK_BOOST * 0.38
            kelly_max_multiplier = min(8.0, AION_ELITE_EDGE_MAX_KELLY_MULTIPLIER)
        elif confidence >= 42.0:
            tier = "standard"
            size_multiplier = 1.18
            rank_boost = AION_ELITE_EDGE_MAX_RANK_BOOST * 0.14
        return {
            "enabled": True,
            "ELITE_EDGE_CONFIDENCE": confidence,
            "elite_edge_confidence": confidence,
            "tier": tier,
            "rank_boost": round(max(0.0, rank_boost), 4),
            "size_multiplier": round(max(0.55, min(AION_ELITE_EDGE_MAX_SIZE_MULTIPLIER, size_multiplier)), 4),
            "kelly_max_multiplier": None if kelly_max_multiplier is None else round(max(1.0, kelly_max_multiplier), 4),
            "components": {
                "structural_persistence": round(structural_component, 4),
                "cross_market_agreement": round(cross_cluster_component, 4),
                "structural_memory_success": round(structural_memory_component, 4),
                "family_profitability": round(family_component, 4),
                "fill_quality": round(fill_quality_component, 4),
                "liquidity_quality": round(liquidity_quality_component, 4),
                "repricing_reliability": round(repricing_reliability_component, 4),
                "live_state_alignment": round(live_state_component, 4),
            },
            "structural_memory_bias": round(memory_bias, 4),
            "structural_memory_component_count": len(memory_components),
            "tags": list(dict.fromkeys(tags)),
        }

    def _get_structural_edge_rank_adjustment(self, *args, **kwargs):
        return _call_sports_live_intelligence("_get_structural_edge_rank_adjustment", self, *args, **kwargs)

    def _is_sports_edge_candidate(self, *, market=None, q=None, family=None, ticker=None, item=None, category=None):
        market = market if isinstance(market, dict) else {}
        if isinstance(item, dict):
            q = q or item.get("q") or item.get("quote")
            ticker = ticker or item.get("ticker")
            family = family or item.get("family")
            category = category or item.get("category")
        elif isinstance(item, (list, tuple)):
            q = q or (item[1] if len(item) > 1 else None)
            family = family or (item[3] if len(item) > 3 else None)
        ticker = str(ticker or getattr(q, "ticker", "") or market.get("ticker", "") or "").strip()
        family = self._normalize_family_for_profit_memory(family, ticker=ticker, market=market, q=q)
        category = str(category or self.get_market_discovery_category(market or family) or "").strip().lower()
        if category == "sports" or self.is_sports_family(family, ticker=ticker):
            return True, family, ticker, category or "sports"
        sports_text = " ".join(
            str(value or "").lower()
            for value in (
                market.get("title"),
                market.get("subtitle"),
                market.get("event_title"),
                getattr(q, "title", None),
                getattr(q, "market_title", None),
                ticker,
                family,
            )
            if str(value or "").strip()
        )
        sports_terms = (
            "nba", "mlb", "nfl", "nhl", "ncaab", "ncaaf", "basketball",
            "baseball", "football", "hockey", "spread", "total", "1h",
            "first half", "strikeout", "player prop",
        )
        if any(term in sports_text for term in sports_terms):
            return True, family, ticker, "sports"
        return False, family, ticker, category or "unknown"

