    def _attach_ev_score_to_candidate(
        self,
        item=None,
        *,
        market=None,
        q=None,
        spread=None,
        family=None,
        expectancy_summary=None,
        quality_snapshot=None,
        family_profit_memory_adjustment=0.0,
        orderbook_imbalance_context=None,
        structural_edge_context=None,
        dynamic_memory_adjustment=0.0,
        adaptive_confidence_summary=None,
        source="ranking",
    ):
        if candidate_quality_compute_candidate_ev is None:
            return {}
        item = item if item is not None else {}
        market = market if isinstance(market, dict) else {}
        expectancy_summary = expectancy_summary if isinstance(expectancy_summary, dict) else {}
        quality_snapshot = quality_snapshot if isinstance(quality_snapshot, dict) else {}
        orderbook_imbalance_context = orderbook_imbalance_context if isinstance(orderbook_imbalance_context, dict) else {}
        structural_edge_context = structural_edge_context if isinstance(structural_edge_context, dict) else {}
        adaptive_confidence_summary = adaptive_confidence_summary if isinstance(adaptive_confidence_summary, dict) else {}
        if isinstance(item, dict):
            q = q or item.get("q") or item.get("quote")
            spread = spread if spread is not None else item.get("spread")
            family = family or item.get("family")
            if not expectancy_summary and isinstance(item.get("expectancy_summary"), dict):
                expectancy_summary = item.get("expectancy_summary") or {}
            if not quality_snapshot and isinstance(item.get("quality_snapshot"), dict):
                quality_snapshot = item.get("quality_snapshot") or {}
        elif isinstance(item, (list, tuple)):
            q = q or (item[1] if len(item) > 1 else None)
            spread = spread if spread is not None else (item[2] if len(item) > 2 else None)
            family = family or (item[3] if len(item) > 3 else None)
        ticker = str(
            (item.get("ticker") if isinstance(item, dict) else "")
            or getattr(q, "ticker", "")
            or market.get("ticker", "")
            or ""
        ).strip()
        family = self._normalize_family_for_profit_memory(family, ticker=ticker, market=market, q=q)
        if not structural_edge_context:
            try:
                structural_edge_context = self._get_structural_edge_rank_adjustment(
                    item,
                    market=market,
                    q=q,
                    spread=spread,
                    family=family,
                    expectancy_summary=expectancy_summary,
                    quality_snapshot=quality_snapshot,
                    source=f"{source}:ev",
                    log=True,
                )
            except Exception:
                structural_edge_context = {}
        memory_profile = {}
        try:
            memory_profile = dict((getattr(self, "market_memory_profiles", {}) or {}).get(ticker, {}) or {})
        except Exception:
            memory_profile = {}
        try:
            family_profit_memory_stats = self._get_family_profit_memory_stats(family, refresh=False)
        except Exception:
            family_profit_memory_stats = {}
        selected_side = (
            expectancy_summary.get("selected_side")
            or quality_snapshot.get("selected_side")
            or (item.get("selected_side") if isinstance(item, dict) else None)
            or getattr(q, "selected_side", None)
            or getattr(q, "side", None)
        )
        selected_price = (
            expectancy_summary.get("selected_price")
            or expectancy_summary.get("selected_price_dollars")
            or quality_snapshot.get("selected_price")
            or quality_snapshot.get("selected_price_dollars")
            or (item.get("selected_price") if isinstance(item, dict) else None)
            or getattr(q, "selected_price", None)
        )
        ev_candidate = {
            "ticker": ticker or None,
            "family": family,
            "q": q,
            "side": selected_side,
            "selected_side": selected_side,
            "selected_price": selected_price,
            "spread": spread,
            "yes_bid": getattr(q, "yes_bid", None) if q is not None else market.get("yes_bid"),
            "yes_ask": getattr(q, "yes_ask", None) if q is not None else market.get("yes_ask"),
            "no_bid": getattr(q, "no_bid", None) if q is not None else market.get("no_bid"),
            "no_ask": getattr(q, "no_ask", None) if q is not None else market.get("no_ask"),
            "probability_estimate": (
                expectancy_summary.get("probability_estimate")
                or quality_snapshot.get("probability_estimate")
                or (item.get("probability_estimate") if isinstance(item, dict) else None)
            ),
            "implied_probability": (
                expectancy_summary.get("implied_probability")
                or quality_snapshot.get("implied_probability")
                or (item.get("implied_probability") if isinstance(item, dict) else None)
            ),
            "confidence_score": (
                expectancy_summary.get("confidence_score")
                or quality_snapshot.get("confidence_score")
                or quality_snapshot.get("profitability_score")
                or (item.get("confidence_score") if isinstance(item, dict) else None)
            ),
            "probability_confidence": expectancy_summary.get("probability_confidence") or quality_snapshot.get("probability_confidence"),
            "family_profit_memory_adjustment": family_profit_memory_adjustment,
            "family_profit_memory_stats": family_profit_memory_stats,
            "dynamic_memory_adjustment": dynamic_memory_adjustment,
            "orderbook_imbalance_adjustment": (orderbook_imbalance_context or {}).get("adjustment"),
            "orderbook_imbalance": orderbook_imbalance_context,
            "structural_edge_context": structural_edge_context,
            "structural_edge_score": structural_edge_context.get("structural_edge_score"),
            "STRUCTURAL_EDGE_SCORE": structural_edge_context.get("STRUCTURAL_EDGE_SCORE"),
            "cross_market_edge_context": structural_edge_context.get("cross_market_edge_context") or {},
            "cross_market_edge_score": structural_edge_context.get("cross_market_edge_score"),
            "CROSS_MARKET_EDGE_SCORE": structural_edge_context.get("CROSS_MARKET_EDGE_SCORE"),
            "cross_market_size_multiplier": structural_edge_context.get("cross_market_size_multiplier"),
            "elite_edge_context": structural_edge_context.get("elite_edge_context") or {},
            "elite_edge_confidence": structural_edge_context.get("elite_edge_confidence"),
            "ELITE_EDGE_CONFIDENCE": structural_edge_context.get("ELITE_EDGE_CONFIDENCE"),
            "elite_edge_size_multiplier": structural_edge_context.get("elite_edge_size_multiplier"),
            "elite_edge_kelly_max_multiplier": structural_edge_context.get("elite_edge_kelly_max_multiplier"),
            "elite_edge_concentration_tier": structural_edge_context.get("elite_edge_concentration_tier"),
            "structural_edge_probability_adjustment": structural_edge_context.get("probability_adjustment"),
            "structural_edge_size_multiplier": structural_edge_context.get("size_multiplier"),
            "structural_edge_rank_boost": structural_edge_context.get("boost"),
            "structural_edge_tags": list(structural_edge_context.get("tags") or []),
            "structural_pattern_keys": list(structural_edge_context.get("structural_pattern_keys") or []),
            "structural_memory_size_multiplier": structural_edge_context.get("structural_memory_size_multiplier"),
            "family_profile": structural_edge_context.get("family_profile") or {},
            "live_state_context": structural_edge_context.get("live_state") or {},
            "memory_profile": memory_profile,
            "adaptive_confidence_summary": adaptive_confidence_summary,
            "expectancy_summary": expectancy_summary,
            "quality_snapshot": quality_snapshot,
            "source": source,
        }
        ev_context = candidate_quality_compute_candidate_ev(ev_candidate)
        sports_edge_context = self._get_sports_edge_rank_adjustment(
            item,
            market=market,
            q=q,
            spread=spread,
            family=family,
            source=source,
            log=True,
            expectancy_summary=expectancy_summary,
            quality_snapshot=quality_snapshot,
        )
        if sports_edge_context.get("is_sports"):
            ev_context["sports_edge_context"] = sports_edge_context
            ev_context["sports_edge_tags"] = list(sports_edge_context.get("tags") or [])
            ev_context["sports_edge_rank_boost"] = sports_edge_context.get("boost", 0.0)
            ev_context["sports_edge_score_at_entry"] = sports_edge_context.get("score_at_entry")
            self._apply_sports_edge_sizing_hint(
                ev_context,
                item=item,
                market=market,
                q=q,
                spread=spread,
                family=family,
                source=source,
            )
        ev_fields = (
            "market_implied_probability",
            "raw_probability",
            "bayesian_probability",
            "bayesian_delta",
            "bayesian_sample_size",
            "bayesian_posterior_mean",
            "bayesian_reason",
            "bayesian_alpha",
            "bayesian_beta",
            "bayesian_signal_bucket",
            "bayesian_family_key",
            "calibration_input_probability",
            "calibrated_probability",
            "calibration_delta",
            "calibration_sample_size",
            "calibration_reason",
            "calibration_confidence_bucket",
            "calibration_family_key",
            "calibration_reliability_weight",
            "calibration_observed_probability",
            "estimated_win_probability",
            "expected_value",
            "expected_roi",
            "ev_edge",
            "ev_score",
            "ev_selected_price",
            "ev_tier",
            "ev_reason",
            "ev_sizing_multiplier",
            "ev_action",
            "sports_edge_context",
            "sports_edge_tags",
            "sports_edge_rank_boost",
            "sports_edge_score_at_entry",
            "sports_edge_size_multiplier",
            "structural_edge_context",
            "structural_edge_score",
            "STRUCTURAL_EDGE_SCORE",
            "cross_market_edge_context",
            "cross_market_edge_score",
            "CROSS_MARKET_EDGE_SCORE",
            "cross_market_size_multiplier",
            "elite_edge_context",
            "elite_edge_confidence",
            "ELITE_EDGE_CONFIDENCE",
            "elite_edge_size_multiplier",
            "elite_edge_kelly_max_multiplier",
            "elite_edge_concentration_tier",
            "structural_edge_probability_adjustment",
            "structural_edge_size_multiplier",
            "structural_edge_rank_boost",
            "structural_edge_tags",
            "structural_pattern_keys",
            "structural_memory_size_multiplier",
            "family_profile",
            "live_state_context",
            "conviction_size_multiplier",
        )
        for target in (item if isinstance(item, dict) else None, expectancy_summary, quality_snapshot):
            if isinstance(target, dict):
                for field in ev_fields:
                    target[field] = ev_context.get(field)
        if q is not None:
            for field in ev_fields:
                try:
                    setattr(q, field, ev_context.get(field))
                except Exception:
                    pass
        return ev_context

