    def _record_live_session_outcome(self, realized_value, now_ts=None):
        now_ts = float(now_ts or time.time())
        self.live_recent_session_outcomes.append({"ts": now_ts, "pnl": float(realized_value or 0.0)})
        self.live_recent_session_outcomes = [
            item for item in list(self.live_recent_session_outcomes or [])
            if now_ts - float((item or {}).get("ts", 0.0) or 0.0) <= 6 * 3600
        ]

    def _get_live_session_streaks(self):
        profit_streak = 0
        loss_streak = 0
        for item in reversed(list(self.live_recent_session_outcomes or [])):
            pnl_value = float((item or {}).get("pnl", 0.0) or 0.0)
            if pnl_value > 0:
                if loss_streak > 0:
                    break
                profit_streak += 1
            elif pnl_value < 0:
                if profit_streak > 0:
                    break
                loss_streak += 1
            else:
                break
        return profit_streak, loss_streak

    def _get_live_session_mode(self):
        wins_today = int(self.live_perf_wins_today or 0)
        losses_today = int(self.live_perf_losses_today or 0)
        realized_pnl_today = float(self.live_realized_pnl_today or 0.0)
        profit_streak, loss_streak = self._get_live_session_streaks()
        mode = "neutral"
        reason = "flat_session"
        if not KALSHI_SESSION_PROTECTION_ENABLED:
            reason = "feature_disabled"
        elif realized_pnl_today <= KALSHI_DEFENSIVE_MODE_PNL or loss_streak >= 2 or (losses_today >= wins_today + 2 and losses_today >= 3):
            mode = "defensive"
            reason = "drawdown_or_loss_streak"
        elif realized_pnl_today >= KALSHI_PROTECTED_MODE_PNL:
            mode = "protected"
            reason = "protecting_session_gains"
        elif realized_pnl_today > 0 or profit_streak >= 2:
            mode = "aggressive"
            reason = "positive_session_flow"
        log_marker = (mode, round(realized_pnl_today, 4), wins_today, losses_today, profit_streak, loss_streak)
        if self.live_session_mode_log_marker != log_marker:
            print(
                f"[LIVE-SESSION-MODE] mode={mode} realized_pnl_today={round(realized_pnl_today, 4)} "
                f"wins_today={wins_today} losses_today={losses_today} "
                f"profit_streak={profit_streak} loss_streak={loss_streak} reason={reason}"
            )
            if mode == "protected":
                print(
                    f"[LIVE-SESSION-PROTECTED] realized_pnl_today={round(realized_pnl_today, 4)} "
                    f"threshold={KALSHI_PROTECTED_MODE_PNL}"
                )
            elif mode == "defensive":
                print(
                    f"[LIVE-SESSION-DEFENSIVE] realized_pnl_today={round(realized_pnl_today, 4)} "
                    f"threshold={KALSHI_DEFENSIVE_MODE_PNL}"
                )
            elif mode == "aggressive":
                print(
                    f"[LIVE-SESSION-AGGRESSIVE] realized_pnl_today={round(realized_pnl_today, 4)} "
                    f"profit_streak={profit_streak}"
                )
            self.live_session_mode_log_marker = log_marker
            self.live_session_mode = mode
        return {
            "mode": mode,
            "reason": reason,
            "realized_pnl_today": realized_pnl_today,
            "wins_today": wins_today,
            "losses_today": losses_today,
            "profit_streak": profit_streak,
            "loss_streak": loss_streak,
        }

    def _get_live_session_entry_adjustment(self, adaptive_entry=False, borderline=False):
        session_state = self._get_live_session_mode()
        mode = session_state.get("mode", "neutral")
        if not KALSHI_SESSION_PROTECTION_ENABLED:
            return {"mode": mode, "score_penalty": 0.0, "adaptive_block": False, "reason": "feature_disabled"}
        score_penalty = 0.0
        adaptive_block = False
        reason = "neutral"
        if mode == "protected":
            score_penalty = PHASE5_BUY_SCORE_THRESHOLD * KALSHI_PROTECTED_MODE_ENTRY_PENALTY
            if adaptive_entry and borderline:
                adaptive_block = True
                reason = "protected_mode_blocks_borderline_adaptive"
            else:
                reason = "protected_mode_penalty"
        elif mode == "defensive":
            score_penalty = PHASE5_BUY_SCORE_THRESHOLD * KALSHI_DEFENSIVE_MODE_ENTRY_PENALTY
            if adaptive_entry or borderline:
                adaptive_block = True
                reason = "defensive_mode_blocks_adaptive_or_borderline"
            else:
                reason = "defensive_mode_penalty"
        elif mode == "aggressive":
            reason = "normal_operation"
        print(
            f"[LIVE-SESSION-ENTRY-ADJUSTMENT] mode={mode} adaptive_entry={'yes' if adaptive_entry else 'no'} "
            f"borderline={'yes' if borderline else 'no'} score_penalty={round(score_penalty, 4)} "
            f"adaptive_block={'yes' if adaptive_block else 'no'} reason={reason}"
        )
        return {
            "mode": mode,
            "score_penalty": float(score_penalty),
            "adaptive_block": adaptive_block,
            "reason": reason,
        }

    def _get_family_performance_weight(self, family):
        family = self._normalize_family_for_profit_memory(family)
        self._get_family_profit_memory_adjustment(family, log=False, source="legacy_decision_hook")
        return 0.0

    def _prune_post_loss_cooldowns(self, now_ts=None):
        now_ts = float(now_ts or time.time())
        for ticker, event in list((self.live_post_loss_ticker_cooldowns or {}).items()):
            expires_at = float((event or {}).get("expires_at", 0.0) or 0.0)
            if expires_at and expires_at <= now_ts:
                print(
                    f"[LIVE-POST-LOSS-COOLDOWN-EXPIRED] scope=ticker ticker={ticker} "
                    f"family={(event or {}).get('family')} reason={(event or {}).get('reason')}"
                )
                self.live_post_loss_ticker_cooldowns.pop(ticker, None)
        for family, event in list((self.live_post_loss_family_cooldowns or {}).items()):
            expires_at = float((event or {}).get("expires_at", 0.0) or 0.0)
            if expires_at and expires_at <= now_ts:
                print(
                    f"[LIVE-POST-LOSS-COOLDOWN-EXPIRED] scope=family family={family} "
                    f"reason={(event or {}).get('reason')}"
                )
                self.live_post_loss_family_cooldowns.pop(family, None)
        recent_window = max(1800, KALSHI_POST_LOSS_TICKER_COOLDOWN_SECONDS)
        self.live_recent_negative_exit_events = [
            event for event in list(self.live_recent_negative_exit_events or [])
            if now_ts - float((event or {}).get("ts", 0.0) or 0.0) <= recent_window
        ]

    def _prune_degenerate_family_cooldowns(self, now_ts=None):
        now_ts = float(now_ts or time.time())
        window_seconds = float(KALSHI_DEGENERATE_FAMILY_WINDOW_SECONDS)
        history_container = getattr(self, "live_degenerate_family_reject_history", {}) or {}
        for family, state in list(history_container.items()):
            recent_timestamps = [
                float(ts)
                for ts in list((state or {}).get("recent_timestamps", []))
                if now_ts - float(ts or 0.0) <= window_seconds
            ]
            if recent_timestamps:
                state = dict(state or {})
                state["recent_timestamps"] = recent_timestamps
                history_container[family] = state
            else:
                history_container.pop(family, None)
        cooldown_container = getattr(self, "live_degenerate_family_cooldowns", {}) or {}
        for family, event in list(cooldown_container.items()):
            expires_at = float((event or {}).get("expires_at", 0.0) or 0.0)
            if expires_at and expires_at <= now_ts:
                print(
                    f"[AION-DEGENERATE-FAMILY-COOLDOWN-EXPIRED] family={family} "
                    f"reason={(event or {}).get('reason')} cooldown_until={round(expires_at, 3)}"
                )
                cooldown_container.pop(family, None)

    def _get_degenerate_family_penalty_state(self, family, now_ts=None):
        now_ts = float(now_ts or time.time())
        family = str(family or "UNKNOWN").strip().upper() or "UNKNOWN"
        self._prune_degenerate_family_cooldowns(now_ts=now_ts)
        history = dict((self.live_degenerate_family_reject_history or {}).get(family, {}) or {})
        recent_timestamps = [
            float(ts)
            for ts in list(history.get("recent_timestamps", []))
            if now_ts - float(ts or 0.0) <= float(KALSHI_DEGENERATE_FAMILY_WINDOW_SECONDS)
        ]
        recent_rejects = len(recent_timestamps)
        cooldown_event = dict((self.live_degenerate_family_cooldowns or {}).get(family, {}) or {})
        cooldown_expires_at = float(cooldown_event.get("expires_at", 0.0) or 0.0)
        cooldown_remaining_seconds = max(0.0, cooldown_expires_at - now_ts)
        cooldown_active = cooldown_remaining_seconds > 0.0
        penalty = 0.0
        if recent_rejects > 0:
            penalty += float(recent_rejects) * float(KALSHI_DEGENERATE_FAMILY_BASE_PENALTY)
        if recent_rejects >= int(KALSHI_DEGENERATE_FAMILY_MIN_REJECTIONS):
            penalty += 18.0 + max(0.0, float(recent_rejects) - float(KALSHI_DEGENERATE_FAMILY_MIN_REJECTIONS)) * 4.0
        if cooldown_active:
            penalty += float(KALSHI_DEGENERATE_FAMILY_ACTIVE_COOLDOWN_PENALTY)
        penalty += min(20.0, cooldown_remaining_seconds / 30.0) if cooldown_active else 0.0
        return {
            "family": family,
            "recent_rejects": recent_rejects,
            "cooldown_active": cooldown_active,
            "cooldown_remaining_seconds": int(max(0.0, cooldown_remaining_seconds)),
            "cooldown_reason": str(cooldown_event.get("reason") or "degenerate_family_cooldown"),
            "cooldown_until": round(cooldown_expires_at, 3) if cooldown_expires_at else 0.0,
            "penalty": round(penalty, 4),
            "window_seconds": int(KALSHI_DEGENERATE_FAMILY_WINDOW_SECONDS),
            "trigger_rejections": int(KALSHI_DEGENERATE_FAMILY_MIN_REJECTIONS),
        }

    def _record_degenerate_family_reject(self, family, ticker, reason, now_ts=None):
        now_ts = float(now_ts or time.time())
        family = str(family or "UNKNOWN").strip().upper() or "UNKNOWN"
        ticker = str(ticker or "").strip().upper()
        reason = str(reason or "degenerate_book").strip() or "degenerate_book"
        self._prune_degenerate_family_cooldowns(now_ts=now_ts)
        history = dict((self.live_degenerate_family_reject_history or {}).get(family, {}) or {})
        recent_timestamps = [
            float(ts)
            for ts in list(history.get("recent_timestamps", []))
            if now_ts - float(ts or 0.0) <= float(KALSHI_DEGENERATE_FAMILY_WINDOW_SECONDS)
        ]
        recent_timestamps.append(now_ts)
        history["recent_timestamps"] = recent_timestamps
        history["last_ticker"] = ticker
        history["last_reason"] = reason
        history["last_ts"] = now_ts
        self.live_degenerate_family_reject_history[family] = history
        family_state = self._get_degenerate_family_penalty_state(family, now_ts=now_ts)
        print(
            "[AION-DEGENERATE-FAMILY-PENALTY] "
            + json.dumps(
                {
                    "family": family,
                    "ticker": ticker,
                    "reason": reason,
                    "recent_rejects": family_state.get("recent_rejects", 0),
                    "penalty": family_state.get("penalty", 0.0),
                    "cooldown_active": family_state.get("cooldown_active", False),
                    "cooldown_remaining_seconds": family_state.get("cooldown_remaining_seconds", 0),
                    "window_seconds": family_state.get("window_seconds", 0),
                    "trigger_rejections": family_state.get("trigger_rejections", 0),
                },
                sort_keys=True,
                default=str,
            )
        )
        if family_state.get("recent_rejects", 0) >= int(KALSHI_DEGENERATE_FAMILY_MIN_REJECTIONS):
            cooldown_until = now_ts + float(KALSHI_DEGENERATE_FAMILY_COOLDOWN_SECONDS)
            current_cooldown_until = float((self.live_degenerate_family_cooldowns or {}).get(family, {}).get("expires_at", 0.0) or 0.0)
            if cooldown_until > current_cooldown_until:
                self.live_degenerate_family_cooldowns[family] = {
                    "family": family,
                    "ticker": ticker,
                    "reason": "repeated_degenerate_book",
                    "recent_rejects": family_state.get("recent_rejects", 0),
                    "expires_at": cooldown_until,
                }
                print(
                    "[AION-DEGENERATE-FAMILY-COOLDOWN] "
                    + json.dumps(
                        {
                            "family": family,
                            "ticker": ticker,
                            "reason": "repeated_degenerate_book",
                            "recent_rejects": family_state.get("recent_rejects", 0),
                            "cooldown_seconds": int(KALSHI_DEGENERATE_FAMILY_COOLDOWN_SECONDS),
                            "cooldown_until": round(cooldown_until, 3),
                        },
                        sort_keys=True,
                        default=str,
                    )
                )
                print(
                    "[AION-SCAN-CONTINUE-AFTER-DEGENERATE] "
                    + json.dumps(
                        {
                            "family": family,
                            "ticker": ticker,
                            "reason": "repeated_degenerate_book",
                            "next_action": "continue_scan",
                            "cooldown_applied": True,
                        },
                        sort_keys=True,
                        default=str,
                    )
                )
        return family_state

