    def _read_field(self, source, *names, default=None):
        for name in names:
            if isinstance(source, dict):
                value = source.get(name)
            else:
                value = getattr(source, name, None)
            if value not in (None, ""):
                return value
        return default

    def extract_order_execution_summary(self, order=None):
        order = order if isinstance(order, dict) else {}
        root = order.get("order") if isinstance(order.get("order"), dict) else order
        ticker = str(root.get("ticker") or root.get("market_ticker") or "").strip()
        side = str(root.get("side") or root.get("outcome_side") or root.get("purchased_side") or "").strip().lower() or None
        price = (
            root.get("price")
            if root.get("price") is not None
            else root.get("yes_price_dollars")
            if root.get("yes_price_dollars") is not None
            else root.get("no_price_dollars")
            if root.get("no_price_dollars") is not None
            else root.get("yes_price")
            if root.get("yes_price") is not None
            else root.get("no_price")
        )
        filled_count = (
            root.get("filled_count")
            if root.get("filled_count") is not None
            else root.get("fill_count")
            if root.get("fill_count") is not None
            else root.get("filled_count_fp")
            if root.get("filled_count_fp") is not None
            else root.get("fill_count_fp")
            if root.get("fill_count_fp") is not None
            else root.get("filled_quantity")
        )
        initial_count = (
            root.get("initial_count")
            if root.get("initial_count") is not None
            else root.get("initial_count_fp")
            if root.get("initial_count_fp") is not None
            else root.get("count")
            if root.get("count") is not None
            else root.get("count_fp")
        )
        remaining_count = (
            root.get("remaining_count")
            if root.get("remaining_count") is not None
            else root.get("remaining_count_fp")
        )
        status = str(root.get("status") or root.get("state") or "").strip().lower()
        count = filled_count
        if count is None and status in {"executed", "filled", "closed", "settled"}:
            count = initial_count
        if count is None and not status:
            count = initial_count
        if filled_count is None and remaining_count is not None and initial_count is not None:
            try:
                count = max(0.0, float(initial_count) - float(remaining_count))
            except (TypeError, ValueError):
                pass
        action = str(root.get("action") or root.get("type") or "").strip().lower() or None
        if not side and root.get("yes_price") is not None:
            side = "yes"
        if not side and root.get("no_price") is not None:
            side = "no"
        if side in {"buy_yes", "yes_buy"}:
            side = "yes"
        elif side in {"buy_no", "no_buy"}:
            side = "no"
        normalized_price = self.normalize_contract_price(price, ticker=ticker, source="extract_order_execution_summary")
        filled_count_value = self.to_float(count, None)
        initial_count_value = self.to_float(initial_count, None)
        remaining_count_value = self.to_float(remaining_count, None)
        raw_keys = sorted(str(key) for key in root.keys())
        if any(key in root for key in ("fill_count_fp", "initial_count_fp", "remaining_count_fp", "position_fp")):
            try:
                print(
                    "[AION-API-SCHEMA-AUDIT] "
                    + json.dumps(
                        {
                            "parser": "order",
                            "ticker": ticker,
                            "keys": raw_keys[:40],
                            "status": status or None,
                            "filled_count": filled_count_value,
                            "initial_count": initial_count_value,
                            "remaining_count": remaining_count_value,
                        },
                        sort_keys=True,
                        default=str,
                    )
                )
            except Exception:
                pass
        return {
            "order_id": root.get("order_id") or root.get("id"),
            "ticker": ticker,
            "side": side,
            "action": action,
            "price": normalized_price,
            "filled_count": filled_count_value,
            "initial_count": initial_count_value,
            "remaining_count": remaining_count_value,
            "status": status or root.get("status"),
            "raw": root,
        }

    def extract_position_summary(self, position=None):
        position = position if isinstance(position, dict) else {}
        ticker = str(position.get("ticker") or position.get("market_ticker") or "").strip()
        raw_count = (
            position.get("count")
            if position.get("count") is not None
            else position.get("position")
            if position.get("position") is not None
            else position.get("position_fp")
            if position.get("position_fp") is not None
            else position.get("count_fp")
            if position.get("count_fp") is not None
            else position.get("yes_count")
            if position.get("yes_count") is not None
            else position.get("no_count")
        )
        count = self.to_float(raw_count, 0.0) or 0.0
        side = str(position.get("side") or position.get("outcome_side") or "").strip().lower()
        if side not in {"yes", "no"}:
            side = "no" if position.get("no_count") not in (None, "", 0, 0.0) or count < 0 else "yes"
        avg_price = (
            position.get("avg_price")
            if position.get("avg_price") is not None
            else position.get("average_price")
            if position.get("average_price") is not None
            else position.get("entry_price")
        )
        normalized_avg_price = self.normalize_contract_price(avg_price, ticker=ticker, source="extract_position_summary")
        market_exposure = self.to_float(position.get("market_exposure_dollars"), None)
        if market_exposure is None:
            market_exposure_cents = self.to_float(position.get("market_exposure_cents"), None)
            if market_exposure_cents is not None:
                market_exposure = market_exposure_cents / 100.0
        if market_exposure is None:
            market_exposure = self.to_float(position.get("market_exposure"), None)
            if market_exposure is not None and market_exposure > 1.0:
                market_exposure = market_exposure / 100.0
        if normalized_avg_price is None:
            if market_exposure is not None and abs(count) > 0:
                normalized_avg_price = round(float(market_exposure) / abs(float(count)), 6)
        realized_pnl = self.to_float(
            position.get("realized_pnl_dollars")
            if position.get("realized_pnl_dollars") is not None
            else position.get("pnl_dollars")
            if position.get("pnl_dollars") is not None
            else position.get("realized_pnl"),
            None,
        )
        fees_paid = self.to_float(
            position.get("fees_paid_dollars")
            if position.get("fees_paid_dollars") is not None
            else position.get("fees_dollars"),
            None,
        )
        total_traded = self.to_float(
            position.get("total_traded_dollars")
            if position.get("total_traded_dollars") is not None
            else position.get("volume_dollars"),
            None,
        )
        status = "open" if abs(count) > 0 else "closed"
        return {
            "ticker": ticker,
            "side": side,
            "count": abs(count),
            "avg_price": normalized_avg_price,
            "market_exposure_dollars": None if market_exposure is None else round(float(market_exposure), 6),
            "realized_pnl": None if realized_pnl is None else round(float(realized_pnl), 6),
            "fees_paid_dollars": None if fees_paid is None else round(float(fees_paid), 6),
            "total_traded_dollars": None if total_traded is None else round(float(total_traded), 6),
            "status": status,
            "updated_ts": time.time(),
            "raw": position,
        }

    def _load_local_live_positions(self):
        state = self.load_live_position_state()
        rows = []
        for ticker, entry in (state or {}).items():
            if not isinstance(entry, dict):
                continue
            row = dict(entry)
            row["ticker"] = str(row.get("ticker") or ticker).strip()
            row["status"] = str(row.get("status") or "open").strip().lower() or "open"
            rows.append(row)
        self.live_positions = rows
        return rows

    def reconcile_live_positions(self):
        result = self._live_request_json("GET", "/trade-api/v2/portfolio/positions", timeout=15)
        if not result.get("ok"):
            fallback = self._load_local_live_positions()
            print(
                "[LIVE-POSITIONS-FALLBACK] "
                + json.dumps(
                    {
                        "reason": result.get("reason"),
                        "status_code": result.get("status_code"),
                        "open_positions": len(self._get_open_live_positions()),
                        "source": "local_state",
                    },
                    sort_keys=True,
                    default=str,
                )
            )
            return {"ok": False, "reason": result.get("reason"), "positions": fallback}
        body = result.get("body") if isinstance(result.get("body"), dict) else {}
        raw_positions = (
            body.get("market_positions")
            or body.get("positions")
            or body.get("event_positions")
            or body.get("data")
            or []
        )
        if isinstance(raw_positions, dict):
            raw_positions = list(raw_positions.values())
        normalized = [
            self.extract_position_summary(row)
            for row in (raw_positions or [])
            if isinstance(row, dict)
        ]
        try:
            raw_position_keys = sorted(
                {
                    str(key)
                    for row in (raw_positions or [])
                    if isinstance(row, dict)
                    for key in row.keys()
                }
            )
            schema_signature = "|".join(raw_position_keys)
            if schema_signature and getattr(self, "_last_live_position_schema_signature", None) != schema_signature:
                self._last_live_position_schema_signature = schema_signature
                print(
                    "[AION-API-SCHEMA-AUDIT] "
                    + json.dumps(
                        {
                            "endpoint": "/trade-api/v2/portfolio/positions",
                            "body_keys": sorted(str(key) for key in body.keys())[:40],
                            "position_keys": raw_position_keys[:60],
                            "raw_position_count": len(raw_positions or []),
                            "normalized_count": len(normalized),
                        },
                        sort_keys=True,
                        default=str,
                    )
                )
        except Exception:
            pass
        previous_state = self.load_live_position_state()
        normalized_by_ticker = {
            str(row.get("ticker") or "").strip(): row
            for row in normalized
            if isinstance(row, dict) and str(row.get("ticker") or "").strip()
        }
        active_tickers = {
            ticker
            for ticker, row in normalized_by_ticker.items()
            if str(row.get("status", "open") or "open").strip().lower() == "open"
        }
        for ticker, entry in (previous_state or {}).items():
            ticker = str(ticker or "").strip()
            if not ticker or ticker in active_tickers or not isinstance(entry, dict):
                continue
            closed_summary = normalized_by_ticker.get(ticker, {})
            entry_context = entry.get("entry_context") if isinstance(entry.get("entry_context"), dict) else {}
            entry_price = self._sports_memory_price(entry.get("entry_price") or entry.get("avg_price"))
            exit_price = self._sports_memory_price(
                entry.get("exit_price")
                or entry.get("exit_pending_price")
                or closed_summary.get("avg_price")
                or closed_summary.get("exit_price")
            )
            count = self.to_float(entry.get("count") or closed_summary.get("count"), None)
            api_realized_pnl = self.to_float(closed_summary.get("realized_pnl"), None)
            realized_pnl = self.to_float(
                api_realized_pnl
                if api_realized_pnl is not None
                else entry.get("realized_pnl")
                or entry.get("pnl_dollars")
                or entry.get("unrealized_pnl_at_exit"),
                None,
            )
            if realized_pnl is None and entry_price is not None and exit_price is not None and count is not None:
                realized_pnl = round((exit_price - entry_price) * abs(float(count)), 6)
            original_cost = None
            settled_payout = None
            if entry_price is not None and count is not None:
                original_cost = round(float(entry_price) * abs(float(count)), 6)
                if realized_pnl is not None:
                    settled_payout = round(float(original_cost) + float(realized_pnl), 6)
            if api_realized_pnl is not None:
                try:
                    print(
                        "[AION-SETTLEMENT-PNL-RECONCILE] "
                        + json.dumps(
                            {
                                "ticker": ticker,
                                "realized_pnl": realized_pnl,
                                "original_cost_dollars": original_cost,
                                "settled_payout_dollars": settled_payout,
                                "source": "kalshi_position_realized_pnl",
                            },
                            sort_keys=True,
                            default=str,
                        )
                    )
                except Exception:
                    pass
            hold_seconds = self.to_float(entry.get("hold_seconds"), None)
            if hold_seconds is None and self.to_float(entry.get("entry_ts"), None) is not None:
                hold_seconds = round(max(0.0, time.time() - float(entry.get("entry_ts"))), 3)
            self.append_aion_learning_archive_event(
                "trade_closed",
                position={**entry, **closed_summary, "ticker": ticker},
                extra={
                    "ticker": ticker,
                    "family": entry.get("family") or self.get_market_family({"ticker": ticker}),
                    "side": entry.get("side") or closed_summary.get("side"),
                    "price": exit_price,
                    "entry_price": entry_price,
                    "exit_price": exit_price,
                    "contracts": count,
                    "count": count,
                    "pnl_dollars": realized_pnl,
                    "realized_pnl": realized_pnl,
                    "original_cost_dollars": original_cost,
                    "settled_payout_dollars": settled_payout,
                    "fees_paid_dollars": closed_summary.get("fees_paid_dollars"),
                    "total_traded_dollars": closed_summary.get("total_traded_dollars"),
                    "hold_seconds": hold_seconds,
                    "sports_memory_context": entry_context.get("sports_memory_context") if isinstance(entry_context, dict) else {},
                    "sports_memory_dimensions": entry_context.get("sports_memory_dimensions") if isinstance(entry_context, dict) else {},
                    "sports_memory_regime": entry_context.get("sports_memory_regime") if isinstance(entry_context, dict) else None,
                    "sports_memory_rank_adjustment": entry_context.get("sports_memory_rank_adjustment") if isinstance(entry_context, dict) else None,
                    "sports_memory_size_multiplier": entry_context.get("sports_memory_size_multiplier") if isinstance(entry_context, dict) else None,
                    "sports_regime_context": entry_context.get("sports_regime_context") if isinstance(entry_context, dict) else {},
                    "sports_regime": entry_context.get("sports_regime") if isinstance(entry_context, dict) else None,
                    "sports_regime_type": entry_context.get("sports_regime_type") if isinstance(entry_context, dict) else None,
                    "sports_momentum_classification": entry_context.get("sports_momentum_classification") if isinstance(entry_context, dict) else None,
                    "sports_regime_rank_adjustment": entry_context.get("sports_regime_rank_adjustment") if isinstance(entry_context, dict) else None,
                    "sports_regime_size_multiplier": entry_context.get("sports_regime_size_multiplier") if isinstance(entry_context, dict) else None,
                    "game_thesis_context": entry_context.get("game_thesis_context") if isinstance(entry_context, dict) else {},
                    "game_id": entry_context.get("game_id") if isinstance(entry_context, dict) else None,
                    "game_thesis_type": entry_context.get("game_thesis_type") if isinstance(entry_context, dict) else None,
                    "game_thesis_confidence": entry_context.get("game_thesis_confidence") if isinstance(entry_context, dict) else None,
                    "game_thesis_rank_boost": entry_context.get("game_thesis_rank_boost") if isinstance(entry_context, dict) else None,
                    "game_thesis_size_multiplier": entry_context.get("game_thesis_size_multiplier") if isinstance(entry_context, dict) else None,
                    "sports_ladder_context": entry_context.get("sports_ladder_context") if isinstance(entry_context, dict) else {},
                    "sports_ladder_plan_id": entry_context.get("sports_ladder_plan_id") if isinstance(entry_context, dict) else None,
                    "sports_ladder_role": entry_context.get("sports_ladder_role") if isinstance(entry_context, dict) else None,
                    "sports_ladder_leg_type": entry_context.get("sports_ladder_leg_type") if isinstance(entry_context, dict) else None,
                    "sports_ladder_score": entry_context.get("sports_ladder_score") if isinstance(entry_context, dict) else None,
                    "sports_ladder_size_cap": entry_context.get("sports_ladder_size_cap") if isinstance(entry_context, dict) else None,
                    "sports_edge_context": entry_context.get("sports_edge_context") if isinstance(entry_context, dict) else {},
                    "sports_tags": entry_context.get("sports_tags") if isinstance(entry_context, dict) else [],
                    "exit_reason": "position_reconcile_closed",
                    "result": closed_summary.get("status") or "closed",
                    "close_timestamp_utc": datetime.now(timezone.utc).isoformat(),
                },
            )
        self.live_positions = [
            row for row in normalized
            if str(row.get("ticker") or "").strip()
            and str(row.get("status", "open") or "open").strip().lower() == "open"
        ]
        for row in self.live_positions:
            self.upsert_live_entry_metadata_from_position(row)
        self.prune_live_position_state(active_tickers=[row.get("ticker") for row in self.live_positions])
        print(
            "[LIVE-POSITIONS-API] "
            + json.dumps(
                {
                    "ok": True,
                    "open_positions": len(self.live_positions),
                    "path": result.get("path"),
                    "status_code": result.get("status_code"),
                },
                sort_keys=True,
                default=str,
            )
        )
        return {"ok": True, "positions": self.live_positions, "source": "api"}

