    def place_live_order(self, payload):
        return kalshi_execution_module.place_live_order(self, payload)

    def submit_live_order(self, q, size=None, lane=None, payload_override=None):
        payload_override = payload_override if isinstance(payload_override, dict) else payload_override
        payload_ticker = (payload_override or {}).get("ticker") if isinstance(payload_override, dict) else None
        ticker = str(payload_ticker or getattr(q, "ticker", "") or "").strip()
        family = self.get_market_family({"ticker": ticker}) if ticker else str(getattr(q, "family", "") or "UNKNOWN")
        resolved_lane = str(lane or "").strip().upper()
        if not resolved_lane:
            resolved_lane = self._candidate_execution_lane(
                family=family,
                ticker=ticker,
                market=payload_override if isinstance(payload_override, dict) else {"ticker": ticker, "series_ticker": family},
                q=q,
            )
        if self._sports_only_execution_blocked(
            family=family,
            ticker=ticker,
            market=payload_override if isinstance(payload_override, dict) else {"ticker": ticker, "series_ticker": family},
            q=q,
            lane=resolved_lane,
            reason=self._sports_only_block_reason(family=family, ticker=ticker, q=q, lane=resolved_lane),
            source="submit_live_order",
        ):
            return {
                "submitted": False,
                "reason": self._sports_only_block_reason(family=family, ticker=ticker, q=q, lane=resolved_lane),
                "payload": payload_override if isinstance(payload_override, dict) else None,
            }
        if self._sports_only_mode_enabled():
            self._emit_sports_only_execution_log(
                "AION-SPORTS-ONLY-SUBMIT",
                ticker=ticker,
                family=family,
                lane=resolved_lane,
                reason="sports_submit_allowed",
                market=payload_override if isinstance(payload_override, dict) else {"ticker": ticker, "series_ticker": family},
                q=q,
                category="sports",
                source="submit_live_order",
            )
        return kalshi_execution_module.submit_live_order(
            self,
            q,
            size=size,
            lane=lane,
            payload_override=payload_override,
            default_live_order_side=DEFAULT_LIVE_ORDER_SIDE,
            max_live_trades_per_day=MAX_LIVE_TRADES_PER_DAY,
            max_simultaneous_live_positions=MAX_SIMULTANEOUS_LIVE_POSITIONS,
            max_sports_live_positions=MAX_SPORTS_LIVE_POSITIONS,
            live_order_rate_limit=LIVE_ORDER_RATE_LIMIT,
        )

    def cancel_live_order(self, order_id):
        order_id = str(order_id or "").strip()
        if not order_id:
            print("[LIVE-CANCEL] reason=missing_order_id")
            return {"ok": False, "reason": "missing_order_id"}
        result = self._live_request_json("DELETE", f"/trade-api/v2/portfolio/orders/{order_id}", timeout=15)
        print(
            "[LIVE-CANCEL] "
            + json.dumps(
                {
                    "ok": bool(result.get("ok")),
                    "reason": result.get("reason"),
                    "status_code": result.get("status_code"),
                    "order_id": order_id,
                },
                sort_keys=True,
                default=str,
            )
        )
        return result

    def run_live_monitor_positions_pass(self, allow_real_exits=False, quotes_by_ticker=None):
        open_positions = list(self._get_open_live_positions())
        decisions = []
        submitted = 0
        flip_reentries_submitted = 0
        for position in open_positions:
            decision = self._evaluate_dynamic_live_exit(position, quotes_by_ticker=quotes_by_ticker)
            position_flip_decision = self._evaluate_position_flip(
                position,
                base_decision=decision,
                quotes_by_ticker=quotes_by_ticker,
            )
            if position_flip_decision.get("action") == "exit":
                decision = position_flip_decision
            result = {"submitted": False, "reason": "hold"}
            reentry_result = {"submitted": False, "reason": "not_attempted"}
            if decision.get("action") == "exit":
                if allow_real_exits:
                    result = self.submit_live_exit_order(position, decision)
                    if decision.get("position_flip"):
                        cooldowns = getattr(self, "position_flip_cooldowns", None)
                        if not isinstance(cooldowns, dict):
                            self.position_flip_cooldowns = {}
                            cooldowns = self.position_flip_cooldowns
                        cooldowns[decision.get("ticker")] = time.time() + float(AION_POSITION_FLIP_COOLDOWN_SECONDS or 120)
                        self._emit_position_flip_log(
                            "AION-POSITION-FLIP-EXIT",
                            {
                                "ticker": decision.get("ticker"),
                                "side": decision.get("side"),
                                "opposite_side": (decision.get("position_flip") or {}).get("opposite_side"),
                                "submitted": bool(result.get("submitted")),
                                "exit_reason": result.get("reason"),
                                "unrealized_pnl": decision.get("unrealized_pnl"),
                                "edge_delta": (decision.get("position_flip") or {}).get("edge_delta"),
                            },
                            cooldown_key=f"flip-exit:{decision.get('ticker')}",
                            cooldown_seconds=5.0,
                        )
                    if result.get("submitted"):
                        submitted += 1
                        if decision.get("position_flip"):
                            reentry_result = self._maybe_reenter_position_flip(position, decision, result)
                            if reentry_result.get("submitted"):
                                flip_reentries_submitted += 1
                else:
                    result = {"submitted": False, "reason": "monitor_only", "payload": None}
                    print(
                        "[LIVE-EXIT] "
                        + json.dumps(
                            {
                                "ticker": decision.get("ticker"),
                                "submitted": False,
                                "reason": "monitor_only",
                                "pnl": decision.get("unrealized_pnl"),
                            },
                            sort_keys=True,
                            default=str,
                        )
                    )
            decisions.append(
                {
                    "ticker": decision.get("ticker"),
                    "action": decision.get("action"),
                    "reason": decision.get("reason"),
                    "submitted": bool(result.get("submitted")),
                    "submit_reason": result.get("reason"),
                    "position_flip": bool(decision.get("position_flip")),
                    "reentry_submitted": bool(reentry_result.get("submitted")),
                    "reentry_reason": reentry_result.get("reason"),
                }
            )
        post_exit_reconcile = None
        if allow_real_exits and submitted > 0:
            try:
                post_exit_reconcile = self.reconcile_live_positions()
            except Exception as exc:
                post_exit_reconcile = {"ok": False, "reason": exc.__class__.__name__}
            print(
                "[LIVE-EXIT-RECONCILE] "
                + json.dumps(
                    {
                        "exit_orders_submitted": submitted,
                        "ok": bool((post_exit_reconcile or {}).get("ok")),
                        "open_positions": len(self._get_open_live_positions()),
                        "reason": (post_exit_reconcile or {}).get("reason"),
                    },
                    sort_keys=True,
                    default=str,
                )
            )
        return {
            "ok": True,
            "open_positions": len(open_positions),
            "allow_real_exits": bool(allow_real_exits),
            "exit_orders_submitted": submitted,
            "flip_reentries_submitted": flip_reentries_submitted,
            "post_exit_reconcile": post_exit_reconcile,
            "decisions": decisions,
        }

    def run_live_monitor_positions_once(self):
        self.reconcile_live_positions()
        return self.run_live_monitor_positions_pass(allow_real_exits=False)

    def manage_live_positions(self):
        self.reconcile_live_positions()
        return self.run_live_monitor_positions_pass(allow_real_exits=True)

